    private EngineRunResult HumanSlashResponseCore(
        bool useSlash,
        int? requestedSlashCardId,
        CardKind? requestedResponseCardKind,
        bool advanceToHumanBoundary) =>
        _pendingJijiang is not null
            ? HumanJijiangResponseCore(
                useSlash,
                requestedSlashCardId,
                requestedResponseCardKind,
                advanceToHumanBoundary)
            : _pendingDecision?.Kind == DecisionKind.Ganglie
            ? HumanGanglieCore(
                useGanglie: false,
                advanceToHumanBoundary: advanceToHumanBoundary)
            : _pendingDecision?.Kind == DecisionKind.GangliePunish
            ? HumanGangliePunishmentFallbackCore(advanceToHumanBoundary)
            : _pendingDecision?.Kind is DecisionKind.Guicai or DecisionKind.Guidao
            ? HumanGuicaiCore(
                useGuicai: false,
                requestedCardId: null,
                advanceToHumanBoundary: advanceToHumanBoundary)
            : _pendingDecision?.Kind == DecisionKind.Nullification
            ? HumanNullificationCore(
                useNullification: false,
                requestedNullificationCardId: null,
                advanceToHumanBoundary: advanceToHumanBoundary)
            : _pendingDecision?.Kind == DecisionKind.FireAttackReveal
            ? HumanFireAttackCardCore(
                _pendingDecision.ValidCardIds.First(),
                advanceToHumanBoundary)
            : _pendingDecision?.Kind == DecisionKind.FireAttackDiscard
            ? _pendingDecision.ValidCardIds.Count > 0
                ? HumanFireAttackCardCore(_pendingDecision.ValidCardIds.First(), advanceToHumanBoundary)
                : HumanFireAttackSkipCore(advanceToHumanBoundary)
            : _pendingDecision?.Kind == DecisionKind.Yuanhu
            ? HumanYuanhuCore(
                selectedCardId: null,
                advanceToHumanBoundary: advanceToHumanBoundary)
            : _pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack }
            ? HumanGroupResponseCore(
                useResponse: useSlash,
                useBagua: false,
                requestedResponseCardId: requestedSlashCardId,
                requestedResponseCardKind: requestedResponseCardKind,
                advanceToHumanBoundary: advanceToHumanBoundary)
            : HumanDuelResponseCore(
                useSlash,
                requestedSlashCardId,
                requestedResponseCardKind,
                advanceToHumanBoundary);

    private EngineRunResult HumanZhangbaSlashResponseCore(
        IReadOnlyList<int> requestedCardIds,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.RespondSlash);
        var responder = _players[_pendingDecision!.PlayerSeat];
        var pair = FindZhangbaSlashPair(responder, requestedCardIds) ??
            throw new InvalidOperationException("The responding player has no matching Zhangba Slash pair.");

        if (_pendingJijiang is { } jijiang)
        {
            ResolveJijiangZhangbaCandidateResponse(jijiang, responder, pair);
        }
        else if (_pendingBorrowedSword is { AwaitingSlashChoice: true } borrowedSword)
        {
            ResolveBorrowedSwordZhangbaSlashChoice(borrowedSword, pair);
        }
        else if (_pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack } group)
        {
            PopResponseWindow(group.ResolutionId);
            SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            ClearPendingDecision();
            ResolveGroupZhangbaResponse(group, responder, pair);
        }
        else
        {
            var duel = _pendingDuel ??
                throw new InvalidOperationException("There is no Slash response continuation.");
            PopResponseWindow(duel.ResolutionId);
            SetCardUseStep(duel.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            ClearPendingDecision();
            ResolveDuelZhangbaResponse(duel, responder, pair);
        }

        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanProgramViewAsSlashResponseCore(
        IReadOnlyList<int> requestedCardIds,
        CardConversionSource source,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.RespondSlash);
        var responder = _players[_pendingDecision!.PlayerSeat];
        var forResponse = _pendingBorrowedSword is null &&
                          _pendingJijiang is not
                          {
                              IsActiveUse: true
                          } and not
                          {
                              IsBorrowedSwordUse: true
                          } and not
                          {
                              IsQinglongCrescentBladeUse: true
                          };
        var selection = FindProgramMultiCardViewAsSelection(
            responder, requestedCardIds, CardKind.Slash, forResponse, source) ??
            throw new InvalidOperationException("The responding player has no matching configured Slash conversion.");

        if (_pendingJijiang is { } jijiang)
        {
            ResolveJijiangProgramMultiCardCandidateResponse(jijiang, responder, selection);
        }
        else if (_pendingBorrowedSword is { AwaitingSlashChoice: true } borrowedSword)
        {
            ResolveBorrowedSwordProgramMultiCardSlashChoice(borrowedSword, selection);
        }
        else if (_pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack } group)
        {
            PopResponseWindow(group.ResolutionId);
            SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            ClearPendingDecision();
            ResolveGroupProgramMultiCardResponse(group, responder, selection);
        }
        else
        {
            var duel = _pendingDuel ??
                throw new InvalidOperationException("There is no Slash response continuation.");
            PopResponseWindow(duel.ResolutionId);
            SetCardUseStep(duel.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            ClearPendingDecision();
            ResolveDuelProgramMultiCardResponse(duel, responder, selection);
        }

        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanBorrowedSwordResponseCore(
        bool useSlash,
        int? requestedSlashCardId,
        CardKind? requestedEffectiveKind,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.RespondSlash);
        var pending = _pendingBorrowedSword ??
            throw new InvalidOperationException("There is no Borrowed Sword awaiting a response.");
        var owner = _players[pending.WeaponOwnerSeat];
        if (!pending.AwaitingSlashChoice || owner.Seat != _options.HumanSeat)
        {
            throw new InvalidOperationException("The current Borrowed Sword responder is not the human seat.");
        }

        var slash = useSlash
            ? GetBorrowedSwordSlashCards(owner, _players[pending.SlashTargetSeat])
                .SingleOrDefault(card => card.Id == requestedSlashCardId)
            : null;
        if (useSlash && slash is null)
        {
            throw new InvalidOperationException("The responding player has no matching legal Slash.");
        }

        if (slash is not null)
        {
            ResolveBorrowedSwordSlashChoice(pending, slash, requestedEffectiveKind);
        }
        else
        {
            CompleteBorrowedSwordWithoutSlash(pending, transferWeapon: true);
        }

        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanBorrowedSwordJijiangCore(bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.RespondSlash);
        var pending = _pendingBorrowedSword ??
            throw new InvalidOperationException("There is no Borrowed Sword awaiting Jijiang.");
        if (!pending.AwaitingSlashChoice ||
            _pendingDecision?.Choices.All(choice =>
                choice.Parameters.GetValueOrDefault("response") != "jijiang-request") != false)
        {
            throw new InvalidOperationException("Jijiang is not available in the current Borrowed Sword response.");
        }

        BeginBorrowedSwordJijiangRequest(pending);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanGanglieCore(
        bool useGanglie,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.Ganglie);
        var pending = _pendingDamageSkill ??
            throw new InvalidOperationException("There is no Ganglie trigger awaiting a response.");
        if (pending.OwnerSeat != _options.HumanSeat ||
            pending.Effect != DamageSkillEffectKind.GanglieJudgment)
        {
            throw new InvalidOperationException("The current Ganglie owner is not the human seat.");
        }

        ClearPendingDecision();
        ResolveDamageSkillChoice(pending, useGanglie);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanGuicaiCore(
        bool useGuicai,
        int? requestedCardId,
        bool advanceToHumanBoundary)
    {
        if (_pendingDecision?.Kind is not (DecisionKind.Guicai or DecisionKind.Guidao))
            throw new InvalidOperationException("The current prompt is not a judgment replacement.");
        var pending = _pendingJudgment ??
            throw new InvalidOperationException("There is no Guicai judgment awaiting a response.");
        var decision = _pendingDecision ??
            throw new InvalidOperationException("There is no Guicai prompt.");
        var ownerSeat = pending.CurrentCandidateSeat;
        if (ownerSeat != _options.HumanSeat || decision.PlayerSeat != ownerSeat)
        {
            throw new InvalidOperationException("The current Guicai owner is not the human seat.");
        }

        if (useGuicai)
        {
            if (requestedCardId is not { } cardId ||
                !decision.ValidCardIds.Contains(cardId) ||
                !decision.ValidCardIds.Contains(cardId))
            {
                throw new InvalidOperationException("The requested Guicai card is not a published hand choice.");
            }
        }
        else if (requestedCardId is not null)
        {
            throw new InvalidOperationException("A skipped Guicai response cannot name a card.");
        }

        ClearPendingDecision();
        ResolveGuicaiChoice(pending, useGuicai ? requestedCardId : null);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanGangliePunishmentCore(
        GangliePunishmentKind punishment,
        IReadOnlyList<int> discardedCardIds,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.GangliePunish);
        var pending = _pendingDamageSkill ??
            throw new InvalidOperationException("There is no Ganglie punishment awaiting a response.");
        var decision = _pendingDecision ??
            throw new InvalidOperationException("There is no Ganglie punishment prompt.");
        if (pending.Effect != DamageSkillEffectKind.GanglieJudgment ||
            pending.SourceSeat != _options.HumanSeat)
        {
            throw new InvalidOperationException("The current Ganglie source is not the human seat.");
        }

        var response = punishment == GangliePunishmentKind.DiscardTwo
            ? "ganglie-discard-two"
            : "ganglie-lose-hp";
        var selected = decision.Choices.FirstOrDefault(choice =>
            choice.Parameters.GetValueOrDefault("response") == response &&
            choice.Cards.SequenceEqual(discardedCardIds));
        if (selected is null)
        {
            throw new InvalidOperationException("The selected Ganglie punishment is not a published choice.");
        }

        ClearPendingDecision();
        ResolveGangliePunishmentChoice(pending, punishment, discardedCardIds);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanGangliePunishmentFallbackCore(bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.GangliePunish);
        var choice = _pendingDecision!.Choices.FirstOrDefault(candidate =>
                         candidate.Parameters.GetValueOrDefault("response") == "ganglie-lose-hp") ??
                     _pendingDecision.Choices.First();
        var punishment = choice.Parameters.GetValueOrDefault("response") == "ganglie-discard-two"
            ? GangliePunishmentKind.DiscardTwo
            : GangliePunishmentKind.LoseHp;
        return HumanGangliePunishmentCore(
            punishment,
            choice.Cards,
            advanceToHumanBoundary);
    }


    private EngineRunResult HumanYuanhuCore(
        int? selectedCardId,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.Yuanhu);
        var pending = _pendingDamageSkill ??
            throw new InvalidOperationException("There is no Yuanhu trigger awaiting a response.");
        if (pending.OwnerSeat != _options.HumanSeat ||
            pending.Effect != DamageSkillEffectKind.RecoverDamageTarget)
        {
            throw new InvalidOperationException("The current Yuanhu owner is not the human seat.");
        }

        if (selectedCardId is { } cardId &&
            !_pendingDecision!.ValidCardIds.Contains(cardId))
        {
            throw new InvalidOperationException("The selected Yuanhu discard card is not a legal choice.");
        }

        ClearPendingDecision();
        ResolveDamageSkillChoice(
            pending,
            useSkill: selectedCardId.HasValue,
            selectedCardId,
            selectedTargetSeat: selectedCardId.HasValue ? pending.Attack.TargetSeat : null);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanDuelResponseCore(
        bool useSlash,
        int? requestedSlashCardId,
        CardKind? requestedResponseCardKind,
        bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.RespondSlash);
        var duel = _pendingDuel ??
            throw new InvalidOperationException("There is no Duel awaiting a response.");
        var responder = _players[duel.ResponderSeat];
        if (responder.Seat != _options.HumanSeat)
        {
            throw new InvalidOperationException("The current Duel responder is not the human seat.");
        }

        var selectedSlash = useSlash
            ? GetResponseCards(responder, CardKind.Slash).FirstOrDefault(card =>
                (!requestedSlashCardId.HasValue || card.Id == requestedSlashCardId.Value) &&
                (!requestedResponseCardKind.HasValue ||
                 GetEffectiveResponseKind(responder, card, CardKind.Slash) == requestedResponseCardKind.Value))
            : null;
        if (useSlash && selectedSlash is null)
        {
            throw new InvalidOperationException("The responding player has no legal Slash response card.");
        }

        PopResponseWindow(duel.ResolutionId);
        SetCardUseStep(duel.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ClearPendingDecision();
        ResolveDuelResponse(duel, responder, selectedSlash);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private EngineRunResult HumanGroupResponseCore(
        bool useResponse,
        bool useBagua,
        int? requestedResponseCardId,
        CardKind? requestedResponseCardKind,
        bool advanceToHumanBoundary)
    {
        var group = _pendingGroupCard ??
            throw new InvalidOperationException("There is no group attack awaiting a response.");
        var requiredCardKind = group.RequiredCardKind ??
            throw new InvalidOperationException("A group response attack must declare a required card kind.");
        var expectedDecision = requiredCardKind == CardKind.Dodge
            ? DecisionKind.RespondDodge
            : DecisionKind.RespondSlash;
        RequireHumanDecision(expectedDecision);
        var attack = group.CurrentAttack ??
            throw new InvalidOperationException("The group attack has no current target.");
        var responder = _players[attack.TargetSeat];
        if (responder.Seat != _options.HumanSeat)
        {
            throw new InvalidOperationException("The current group responder is not the human seat.");
        }

        if (useResponse && useBagua)
        {
            throw new InvalidOperationException("A response cannot use both a physical card and Bagua.");
        }

        var canUseBagua = requiredCardKind == CardKind.Dodge &&
                          !attack.IgnoresArmor &&
                          HasBagua(responder);
        if (useBagua && !canUseBagua)
        {
            throw new InvalidOperationException(
                "Bagua is not available for this group response under the active rules version.");
        }

        var selectedResponse = useResponse
            ? GetResponseCards(responder, requiredCardKind).FirstOrDefault(card =>
                (!requestedResponseCardId.HasValue || card.Id == requestedResponseCardId.Value) &&
                (!requestedResponseCardKind.HasValue ||
                 GetEffectiveResponseKind(responder, card, requiredCardKind) == requestedResponseCardKind.Value))
            : null;
        if (useResponse &&
            selectedResponse is null &&
            !requestedResponseCardId.HasValue &&
            !requestedResponseCardKind.HasValue &&
            canUseBagua)
        {
            // Preserve the boolean compatibility adapter for callers that only
            // know how to request a Dodge response.
            useResponse = false;
            useBagua = true;
        }

        if (useResponse && selectedResponse is null)
        {
            throw new InvalidOperationException(
                $"The responding player has no legal {requiredCardKind} response card.");
        }

        PopResponseWindow(group.ResolutionId);
        SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ClearPendingDecision();
        if (useBagua)
        {
            var judgmentResult = ResolveBaguaJudgment(attack, responder);
            if (judgmentResult is { } succeeded)
            {
                CompleteBaguaResponse(attack, succeeded);
            }
        }
        else
        {
            ResolveGroupResponse(group, responder, selectedResponse);
        }
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    /// <summary>
    /// Creates a viewer-safe snapshot. Pass revealAll only for diagnostics/tests or
    /// an explicit post-game reveal screen.
    /// </summary>
    public GameSnapshot CreateSnapshot(int viewerSeat, bool revealAll = false)
    {
        var snapshots = _players.Select(player =>
        {
            var playerHand = GetHand(player);
            var canSeeRole = !IsNationalWarMode &&
                             (revealAll ||
                              IsTeamMode ||
                              player.Role == Role.Lord ||
                              player.RoleRevealed ||
                              player.Seat == viewerSeat);
            var canSeeHand = revealAll || player.Seat == viewerSeat;
            var hand = canSeeHand
                ? playerHand.Select(ToSnapshot).ToArray()
                : [];
            var equipment = GetEquipment(player)
                .Select(ToSnapshot)
                .ToArray();
            var judgment = GetJudgment(player)
                .Select(ToJudgmentSnapshot)
                .ToArray();
            var woodenOxGrain = GetWoodenOxGrain(player);
            var buquWounds = GetBuquWounds(player);
            var authority = GetAuthority(player);
            var chunlao = _cardZones.CardsAt(CardLocation.Chunlao(player.Seat));
            var canSeeGeneral = player.GeneralSelected &&
                                (revealAll || player.GeneralRevealed || player.Seat == viewerSeat);
            var general = canSeeGeneral ? player.General : CreateHiddenGeneral();
            var canSeeSecondaryGeneral = player.SecondaryGeneralSelected &&
                                         (revealAll ||
                                          player.SecondaryGeneralRevealed ||
                                          player.Seat == viewerSeat);
            var secondaryGeneral = canSeeSecondaryGeneral ? player.SecondaryGeneral : null;
            var effectiveFactionId = GetEffectiveFactionId(player);
            var hasIdentityGodFaction = SupportsGodFactionSelection &&
                                        string.Equals(player.General.FactionId, "god", StringComparison.Ordinal) &&
                                        player.ChosenFactionId is not null;
            var canSeeFaction = effectiveFactionId is not null &&
                                (IsNationalWarMode
                                    ? revealAll || player.FactionRevealed || player.Seat == viewerSeat
                                    : hasIdentityGodFaction &&
                                      (revealAll || player.GeneralRevealed || player.Seat == viewerSeat));
            return new PlayerSnapshot(
                player.Seat,
                player.Name,
                player.IsHuman,
                canSeeRole ? player.Role : null,
                !IsNationalWarMode && (player.RoleRevealed || player.Role == Role.Lord),
                general.Id,
                general.Name,
                general.PortraitKey,
                player.Hp,
                player.MaxHp,
                player.IsAlive,
                playerHand.Count,
                hand,
                player.GeneralSelected && player.GeneralRevealed,
                player.HasAlcoholEffect)
            {
                IsFaceDown = player.IsFaceDown,
                TeamId = IsTeamMode && player.TeamRevealed ? player.TeamId : null,
                IsTeamRevealed = IsTeamMode && player.TeamRevealed,
                Equipment = Array.AsReadOnly(equipment),
                WoodenOxGrainCount = woodenOxGrain.Count,
                WoodenOxGrain = GetEquipment(player).Any(card => card.Kind == CardKind.WoodenOx) || woodenOxGrain.Count > 0
                    ? canSeeHand
                        ? Array.AsReadOnly(woodenOxGrain.Select(ToSnapshot).ToArray())
                        : Array.Empty<CardSnapshot>()
                    : null,
                IsChained = player.IsChained,
                Judgment = Array.AsReadOnly(judgment),
                BuquWounds = UsesFormalZhouTai || buquWounds.Count > 0
                    ? Array.AsReadOnly(buquWounds.Select(ToSnapshot).ToArray())
                    : null,
                AuthorityCount = authority.Count,
                AuthorityCards = Array.AsReadOnly(authority.Select(ToSnapshot).ToArray()),
                ChunlaoCount = chunlao.Count,
                ChunlaoCards = HasProgramPersistentZone(player, CardZoneKind.Chunlao) || chunlao.Count > 0
                    ? Array.AsReadOnly(chunlao.Select(ToSnapshot).ToArray())
                    : null,
                Markers = player.Markers.Count > 0
                    ? Array.AsReadOnly(player.Markers
                        .OrderBy(marker => marker.Key)
                        .Select(marker => new PlayerMarkerSnapshot(
                            marker.Key,
                            PlayerMarkerCatalog.GetDisplayName(marker.Key),
                            marker.Value))
                        .ToArray())
                    : null,
                FactionId = canSeeFaction ? effectiveFactionId : null,
                IsFactionRevealed = IsNationalWarMode
                    ? player.FactionRevealed
                    : hasIdentityGodFaction && player.GeneralRevealed,
                SecondaryGeneralId = secondaryGeneral?.Id,
                SecondaryGeneralName = secondaryGeneral?.Name,
                SecondaryPortraitKey = secondaryGeneral?.PortraitKey,
                IsSecondaryGeneralPublic = IsNationalWarMode && player.SecondaryGeneralRevealed,
                Skills = canSeeGeneral
                    ? Array.AsReadOnly(OwnedRuntimeSkills(player, general, includeAcquired: true)
                        .Select(skill => skill with
                        {
                            Description = GetVisibleSkillDescription(skill.Kind, skill.Description)
                        })
                        .ToArray())
                    : null,
                SecondarySkills = secondaryGeneral is not null
                    ? Array.AsReadOnly(OwnedRuntimeSkills(player, secondaryGeneral, includeAcquired: false)
                        .Select(skill => skill with
                        {
                            Description = GetVisibleSkillDescription(skill.Kind, skill.Description)
                        })
                        .ToArray())
                    : null,
                SkillRuntimeStates = canSeeGeneral
                    ? Array.AsReadOnly(OwnedRuntimeSkills(player, general, includeAcquired: true)
                        .Select(skill => skill.ContentId)
                        .OfType<string>()
                        .Distinct(StringComparer.Ordinal)
                        .Select(skillId => CreateProgramAwareSkillStateSnapshot(player, skillId))
                        .ToArray())
                    : null
            };
        }).ToArray();

        var visibleDecision = _pendingDecision?.PlayerSeat == viewerSeat
            ? CloneDecision(_pendingDecision)
            : null;
        var programRevealedCards = GetProgramPublicCards();
        var publicRevealedCards = _resolutionStack.LastOrDefault() is PindianFrame { Result: { } contest }
            ? _cardZones.CardsAt(CardLocation.Processing)
                .Where(card => card.Id == contest.SourceCardId || card.Id == contest.OpponentCardId)
                .Select(ToSnapshot).ToArray()
            : programRevealedCards.Count > 0
            ? programRevealedCards.ToArray()
            : _pendingGroupCard is { Effect: GroupCardEffect.PublicDraft } publicDraft
            ? publicDraft.RevealedCardIds
                .Select(cardId => _cardZones.CardsAt(CardLocation.Processing)
                    .Single(card => card.Id == cardId))
                .Select(ToSnapshot)
                .ToArray()
            : _pendingFireAttack is { RevealedCardId: not null } fireAttack
                ? [ToSnapshot(GetFireAttackRevealedCard(fireAttack))]
                : Array.Empty<CardSnapshot>();

        return new GameSnapshot(
            revealAll ? _options.Seed : null,
            _options.HumanSeat,
            _status,
            _winner,
            _turnNumber,
            _currentSeat,
            _phase,
            _cardZones.Count(CardLocation.DrawPile),
            _cardZones.Count(CardLocation.DiscardPile),
            snapshots,
            visibleDecision,
            _cardZones.Count(CardLocation.Processing),
            _revision)
        {
            WinnerTeamId = IsTeamMode ? _winnerTeamId : null,
            WinnerFactionId = IsNationalWarMode ? _winnerFactionId : null,
            ModeKind = _modeDefinition.ModeKind,
            PublicRevealedCards = Array.AsReadOnly(publicRevealedCards)
        };
    }

    /// <summary>
    /// Returns every physical card and its exact location for trusted diagnostics,
    /// invariant tests, and future replay tooling. This is intentionally not a player view.
    /// </summary>
    public IReadOnlyList<CardZoneDiagnostic> CreateCardZoneDiagnostics() =>
        _cardZones.CreateDiagnostics();

    public string SerializeState(bool revealAll = false) =>
        SnapshotJson.Serialize(CreateSnapshot(_options.HumanSeat, revealAll));

    private static void ValidateOptions(GameOptions options)
    {
        if (options.AiPolicyVersion is not (1 or 2 or 3))
        {
            throw new ArgumentOutOfRangeException(nameof(options.AiPolicyVersion),
                "Supported AI policy versions are 1, 2 and 3.");
        }

        if (options.PlayerCount is not (4 or 5 or 6 or 8))
        {
            throw new ArgumentOutOfRangeException(
                nameof(options.PlayerCount),
                "The built-in adapters currently support 4, 5, 6, or 8 players.");
        }

        if (options.HumanSeat < -1 || options.HumanSeat >= options.PlayerCount)
        {
            throw new ArgumentOutOfRangeException(
                nameof(options.HumanSeat),
                $"HumanSeat must be -1 or a seat from 0 through {options.PlayerCount - 1}.");
        }

        if (options.HumanSeat == -1 && options.HumanRole is not null)
        {
            throw new ArgumentException("HumanRole must be null when HumanSeat is -1.", nameof(options));
        }

        if (options.MaxTurns <= 0)
        {
            throw new ArgumentOutOfRangeException(nameof(options.MaxTurns));
        }
    }

    private static ContentModeDefinition ResolveModeDefinition(
        ContentRegistry? contentRegistry,
        GameOptions options)
    {
        var modeId = options.ModeId ??
            (options.PlayerCount == 4
                ? "team:standard-2v2"
                : $"identity:standard-{options.PlayerCount}");
        if (contentRegistry is not null)
        {
            if (!contentRegistry.Modes.TryGetValue(modeId, out var registeredMode))
            {
                throw new InvalidOperationException(
                    $"The supplied content registry does not contain mode '{modeId}'.");
            }

            if (options.PlayerCount < registeredMode.MinPlayers ||
                options.PlayerCount > registeredMode.MaxPlayers)
            {
                throw new InvalidOperationException(
                    $"Mode '{modeId}' does not support {options.PlayerCount} players.");
            }

            return registeredMode;
        }

        var roleCounts = options.PlayerCount switch
        {
            8 => new Dictionary<string, int>
            {
                [nameof(Role.Lord)] = 1,
                [nameof(Role.Loyalist)] = 2,
                [nameof(Role.Rebel)] = 4,
                [nameof(Role.Renegade)] = 1
            },
            5 => new Dictionary<string, int>
            {
                [nameof(Role.Lord)] = 1,
                [nameof(Role.Loyalist)] = 1,
                [nameof(Role.Rebel)] = 2,
                [nameof(Role.Renegade)] = 1
            },
            _ => throw new ArgumentOutOfRangeException(nameof(options.PlayerCount))
        };
        return new ContentModeDefinition(
            modeId,
            $"身份局（{options.PlayerCount}人兼容模式）",
            options.PlayerCount,
            options.PlayerCount,
            roleCounts);
    }

    private static void ValidateModeOptions(
        GameOptions options,
        ContentModeDefinition mode)
    {
        if (mode.ModeKind == ContentModeKind.Team)
        {
            if (options.HumanRole is not null)
            {
                throw new ArgumentException(
                    "HumanRole must be null in a public-team mode.",
                    nameof(options.HumanRole));
            }

            if (mode.TeamCounts is null || mode.TeamCounts.Count != 2 ||
                mode.TeamCounts.Values.Sum() != options.PlayerCount)
            {
                throw new InvalidOperationException(
                    $"Mode '{mode.Id}' is not supported by the two-team adapter for {options.PlayerCount} players.");
            }

            if (options.HumanSeat < 0 && options.HumanTeamId is not null)
            {
                throw new ArgumentException(
                    "HumanTeamId requires a human seat.",
                    nameof(options.HumanTeamId));
            }

            if (options.HumanTeamId is not null &&
                !mode.TeamCounts.ContainsKey(options.HumanTeamId))
            {
                throw new ArgumentException(
                    $"Team '{options.HumanTeamId}' is not defined by mode '{mode.Id}'.",
                    nameof(options.HumanTeamId));
            }
        }
        else if (mode.ModeKind == ContentModeKind.NationalWarLite)
        {
            if (options.HumanRole is not null)
            {
                throw new ArgumentException(
                    "HumanRole must be null in a national-war mode.",
                    nameof(options.HumanRole));
            }

            if (options.HumanTeamId is not null)
            {
                throw new ArgumentException(
                    "HumanTeamId is not valid in a national-war mode.",
                    nameof(options.HumanTeamId));
            }

            if (mode.FactionCounts is null ||
                mode.FactionCounts.Count < 2 ||
                mode.FactionCounts.Values.Sum() != options.PlayerCount)
            {
                throw new InvalidOperationException(
                    $"Mode '{mode.Id}' must define at least two factions totaling {options.PlayerCount} players.");
            }
        }
        else if (options.HumanTeamId is not null)
        {
            throw new ArgumentException(
                "HumanTeamId is only valid in a public-team mode.",
                nameof(options.HumanTeamId));
        }
    }

    private static List<Role> CreateIdentityRoles(ContentModeDefinition mode, int playerCount)
    {
        var roles = new List<Role>();
        foreach (var role in Enum.GetValues<Role>())
        {
            if (!mode.RoleCounts.TryGetValue(role.ToString(), out var count))
            {
                continue;
            }

            if (count < 0)
            {
                throw new InvalidOperationException($"Mode '{mode.Id}' has a negative {role} count.");
            }

            for (var index = 0; index < count; index++)
            {
                roles.Add(role);
            }
        }

        var unknownRoles = mode.RoleCounts.Keys
            .Where(key => !Enum.TryParse<Role>(key, ignoreCase: false, out _))
            .ToArray();
        if (unknownRoles.Length > 0)
        {
            throw new InvalidOperationException(
                $"Mode '{mode.Id}' contains unknown role ids: {string.Join(", ", unknownRoles)}.");
        }

        if (roles.Count != playerCount || roles.Count(role => role == Role.Lord) != 1)
        {
            throw new InvalidOperationException(
                $"Mode '{mode.Id}' does not provide exactly one valid {playerCount}-seat identity distribution.");
        }

        return roles;
    }

    private static string FormatRoleSummary(ContentModeDefinition mode)
    {
        var roleNames = new Dictionary<Role, string>
        {
            [Role.Lord] = "主公",
            [Role.Loyalist] = "忠臣",
            [Role.Rebel] = "反贼",
            [Role.Renegade] = "内奸"
        };
        return string.Join(
            "、",
            Enum.GetValues<Role>()
                .Where(role => mode.RoleCounts.GetValueOrDefault(role.ToString()) > 0)
                .Select(role => $"{mode.RoleCounts[role.ToString()]} {roleNames[role]}"));
    }

    private static string FormatTeamSummary(ContentModeDefinition mode) =>
        string.Join(
            "、",
            mode.TeamCounts!
                .OrderBy(entry => entry.Key, StringComparer.Ordinal)
                .Select(entry => $"{entry.Value} {GetTeamName(entry.Key)}"));

    private static string FormatFactionSummary(ContentModeDefinition mode) =>
        string.Join(
            "、",
            mode.FactionCounts!
                .OrderBy(entry => entry.Key, StringComparer.Ordinal)
                .Select(entry => $"{entry.Value} {GetFactionName(entry.Key)}"));

    private static string GetTeamName(string teamId) => teamId switch
    {
        "team:blue" => "青队",
        "team:red" => "赤队",
        _ => teamId
    };

    private IReadOnlyList<string> GetModeTeamIds() =>
        _modeDefinition.TeamCounts is { } teamCounts
            ? teamCounts.Keys.OrderBy(teamId => teamId, StringComparer.Ordinal).ToArray()
            : [];

    private IReadOnlyList<string> GetModeFactionIds() =>
        _modeDefinition.FactionCounts is { } factionCounts
            ? factionCounts.Keys.OrderBy(factionId => factionId, StringComparer.Ordinal).ToArray()
            : [];

    private static string GetFactionName(string factionId) => factionId switch
    {
        "wei" => "魏",
        "shu" => "蜀",
        "ambitious" => "野心家",
        "wu" => "吴",
        "qun" => "群",
        _ => factionId
    };

    private string? GetEffectiveFactionId(CharacterState player) =>
        IsNationalWarMode
            ? player.NationalFactionId
            : player.ChosenFactionId ?? player.General.FactionId;

    private bool RequiresGodFactionSelection(CharacterState player) =>
        SupportsGodFactionSelection &&
        player.GeneralSelected &&
        string.Equals(player.General.FactionId, "god", StringComparison.Ordinal) &&
        player.ChosenFactionId is null;

    private string ChooseAutomaticGodFaction(CharacterState player) =>
        GodFactionChoices[(int)(((uint)_options.Seed + (uint)player.Seat) % (uint)GodFactionChoices.Count)];

    private void AssignAutomaticGodFactions()
    {
        foreach (var player in _players.Where(RequiresGodFactionSelection).OrderBy(player => player.Seat))
        {
            player.ChosenFactionId = ChooseAutomaticGodFaction(player);
        }
    }

    private Role GetTeamRole(string teamId)
    {
        var teamIndex = GetModeTeamIds()
            .Select((candidate, index) => (candidate, index))
            .Where(item => item.candidate == teamId)
            .Select(item => item.index)
            .FirstOrDefault(-1);
        return teamIndex switch
        {
            0 => Role.TeamA,
            1 => Role.TeamB,
            _ => throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' does not define a supported team '{teamId}'.")
        };
    }

    private int GetStartingSeat()
    {
        if (IsNationalWarMode)
        {
            return 0;
        }

        if (!IsTeamMode)
        {
            return _players.Single(player => player.Role == Role.Lord).Seat;
        }

        var firstTeam = GetModeTeamIds().FirstOrDefault()
            ?? throw new InvalidOperationException($"Mode '{_modeDefinition.Id}' has no teams.");
        var seat = _players
            .Where(player => player.TeamId == firstTeam)
            .OrderBy(player => player.Seat)
            .Select(player => player.Seat)
            .FirstOrDefault(-1);
        return seat >= 0
            ? seat
            : throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' has no seat assigned to team '{firstTeam}'.");
    }

    private static IReadOnlyList<GeneralDefinition> CreateRuntimeGeneralPool(
        ContentRegistry? contentRegistry,
        ContentModeDefinition mode)
    {
        if (contentRegistry is null)
        {
            return GeneralCatalog.DemoGenerals;
        }

        var ids = mode.GeneralPoolIds ?? contentRegistry.Generals.Keys
            .OrderBy(id => id, StringComparer.Ordinal)
            .ToArray();
        return ids.Select(id =>
            {
                var definition = contentRegistry.Generals.TryGetValue(id, out var general)
                    ? general
                    : throw new InvalidOperationException(
                        $"Mode '{mode.Id}' references unknown general '{id}'.");
                var skills = definition.SkillIds
                    .Select(contentRegistry.GetSkill)
                    .ToArray();
                var skill = skills[0];
                return new GeneralDefinition(
                    definition.Id,
                    definition.Name,
                    definition.PortraitKey,
                    skill.LegacyKind ?? SkillKind.None,
                    skill.Name,
                    skill.Description,
                    definition.FactionId,
                    definition.BaseHp,
                    skills.Skip(1)
                        .Select(additional => new GeneralSkillDefinition(
                            additional.LegacyKind ?? SkillKind.None,
                            additional.Name,
                            additional.Description)
                        {
                            ContentId = additional.Id,
                            Tags = additional.Tags,
                            ExecutionForms = additional.ExecutionForms,
                            ActionForms = additional.ActionForms
                        })
                        .ToArray(),
                    definition.Gender)
                {
                    SkillContentId = skill.Id,
                    SkillTags = skill.Tags,
                    SkillExecutionForms = skill.ExecutionForms,
                    SkillActionForms = skill.ActionForms
                };
            })
            .ToArray();
    }

    private static ContentDeckRecipe? ResolveDeckDefinition(
        ContentRegistry? contentRegistry,
        string? deckId)
    {
        if (contentRegistry is null)
        {
            if (deckId is not null && deckId is not ("basic-demo" or "standard:basic-demo"))
            {
                throw new InvalidOperationException(
                    $"The legacy Core content path does not contain deck '{deckId}'.");
            }

            return null;
        }

        var requestedId = deckId ?? "standard:basic-demo";
        if (!contentRegistry.Decks.TryGetValue(requestedId, out var definition))
        {
            throw new InvalidOperationException(
                $"The supplied content registry does not contain deck '{requestedId}'.");
        }

        var hasCountRecipe = definition.Cards.Count > 0;
        var hasPhysicalRecipe = definition.PhysicalCards is { Count: > 0 };
        if (definition.InitialHandSize < 0 || definition.DrawPerTurn < 0 ||
            hasCountRecipe == hasPhysicalRecipe)
        {
            throw new InvalidOperationException("The supplied deck recipe is invalid.");
        }

        return definition;
    }

    private void SetupPlayers()
    {
        if (IsTeamMode)
        {
            SetupTeamPlayers();
            return;
        }

        if (IsNationalWarMode)
        {
            SetupNationalWarPlayers();
            return;
        }

        var availableRoles = CreateIdentityRoles(_modeDefinition, _playerCount);
        var assigned = new Role[_playerCount];

        if (_options.HumanSeat >= 0 && _options.HumanRole is { } forcedRole)
        {
            assigned[_options.HumanSeat] = forcedRole;
            if (!availableRoles.Remove(forcedRole))
            {
                throw new ArgumentException(
                    $"Mode '{_modeDefinition.Id}' does not contain a {forcedRole} seat.",
                    nameof(_options.HumanRole));
            }
            _random.Shuffle(availableRoles);
            var roleIndex = 0;
            for (var seat = 0; seat < _playerCount; seat++)
            {
                if (seat != _options.HumanSeat)
                {
                    assigned[seat] = availableRoles[roleIndex++];
                }
            }
        }
        else
        {
            _random.Shuffle(availableRoles);
            for (var seat = 0; seat < _playerCount; seat++)
            {
                assigned[seat] = availableRoles[seat];
            }
        }

        if (_generalPool.Count < _playerCount)
        {
            throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' needs {_playerCount} generals but only {_generalPool.Count} are available.");
        }

        var generals = _generalPool.ToList();
        if (!_options.UseInteractiveSetup)
        {
            _random.Shuffle(generals);
        }

        var hiddenGeneral = CreateHiddenGeneral();
        for (var seat = 0; seat < _playerCount; seat++)
        {
            var role = assigned[seat];
            var assignedGeneral = _options.UseInteractiveSetup ? hiddenGeneral : generals[seat];
            var maxHp = UsesGeneralBaseHp
                ? assignedGeneral.BaseHp + (role == Role.Lord ? 1 : 0)
                : role == Role.Lord ? 5 : 4;
            _players.Add(new CharacterState
            {
                Seat = seat,
                Name = seat == _options.HumanSeat ? "你" : $"AI {seat + 1}",
                IsHuman = seat == _options.HumanSeat,
                Role = role,
                TeamId = null,
                TeamRevealed = false,
                RoleRevealed = role == Role.Lord,
                General = assignedGeneral,
                GeneralSelected = !_options.UseInteractiveSetup,
                GeneralRevealed = !_options.UseInteractiveSetup,
                MaxHp = maxHp,
                Hp = maxHp
            });
        }

        if (_options.UseInteractiveSetup)
        {
            _availableGenerals.AddRange(generals);
            _random.Shuffle(_availableGenerals);
            _selectionOrder.AddRange(_players
                .OrderBy(player => player.Role == Role.Lord ? 0 : 1)
                .ThenBy(player => player.Seat)
                .Select(player => player.Seat));
        }
    }

    private void SetupTeamPlayers()
    {
        var teamIds = GetModeTeamIds();
        if (teamIds.Count != 2 || _modeDefinition.TeamCounts is null)
        {
            throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' requires exactly two public teams for this engine adapter.");
        }

        var availableTeams = _modeDefinition.TeamCounts
            .OrderBy(entry => entry.Key, StringComparer.Ordinal)
            .SelectMany(entry => Enumerable.Repeat(entry.Key, entry.Value))
            .ToList();
        var assignedTeams = new string[_playerCount];
        if (_options.HumanSeat >= 0 && _options.HumanTeamId is { } humanTeamId)
        {
            assignedTeams[_options.HumanSeat] = humanTeamId;
            if (!availableTeams.Remove(humanTeamId))
            {
                throw new ArgumentException(
                    $"Mode '{_modeDefinition.Id}' has no remaining seat for team '{humanTeamId}'.",
                    nameof(_options.HumanTeamId));
            }

            _random.Shuffle(availableTeams);
            var teamIndex = 0;
            for (var seat = 0; seat < _playerCount; seat++)
            {
                if (seat != _options.HumanSeat)
                {
                    assignedTeams[seat] = availableTeams[teamIndex++];
                }
            }
        }
        else
        {
            _random.Shuffle(availableTeams);
            for (var seat = 0; seat < _playerCount; seat++)
            {
                assignedTeams[seat] = availableTeams[seat];
            }
        }

        if (_generalPool.Count < _playerCount)
        {
            throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' needs {_playerCount} generals but only {_generalPool.Count} are available.");
        }

        var generals = _generalPool.ToList();
        if (!_options.UseInteractiveSetup)
        {
            _random.Shuffle(generals);
        }

        var hiddenGeneral = CreateHiddenGeneral();
        for (var seat = 0; seat < _playerCount; seat++)
        {
            var teamId = assignedTeams[seat];
            _players.Add(new CharacterState
            {
                Seat = seat,
                Name = seat == _options.HumanSeat ? "你" : $"AI {seat + 1}",
                IsHuman = seat == _options.HumanSeat,
                Role = GetTeamRole(teamId),
                TeamId = teamId,
                TeamRevealed = true,
                RoleRevealed = true,
                General = _options.UseInteractiveSetup ? hiddenGeneral : generals[seat],
                GeneralSelected = !_options.UseInteractiveSetup,
                GeneralRevealed = !_options.UseInteractiveSetup,
                MaxHp = 4,
                Hp = 4
            });
        }

        if (_options.UseInteractiveSetup)
        {
            _availableGenerals.AddRange(generals);
            _random.Shuffle(_availableGenerals);
            _selectionOrder.AddRange(_players
                .OrderBy(player => player.Seat)
                .Select(player => player.Seat));
        }
    }

    private void SetupNationalWarPlayers()
    {
        if (_modeDefinition.FactionCounts is not { Count: >= 2 } factionCounts ||
            factionCounts.Values.Sum() != _playerCount)
        {
            throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' requires at least two hidden factions totaling {_playerCount} seats.");
        }

        var availableFactions = factionCounts
            .OrderBy(entry => entry.Key, StringComparer.Ordinal)
            .SelectMany(entry => Enumerable.Repeat(entry.Key, entry.Value))
            .ToList();
        _random.Shuffle(availableFactions);

        var generals = _generalPool.ToList();
        if (!_options.UseInteractiveSetup)
        {
            _random.Shuffle(generals);
        }

        var hiddenGeneral = CreateHiddenGeneral();
        for (var seat = 0; seat < _playerCount; seat++)
        {
            var factionId = availableFactions[seat];
            var seatGenerals = generals
                .Where(general => string.Equals(general.FactionId, factionId, StringComparison.Ordinal))
                .Take(2)
                .ToArray();
            if (!_options.UseInteractiveSetup && seatGenerals.Length != 2)
            {
                throw new InvalidOperationException(
                    $"Mode '{_modeDefinition.Id}' could not reserve two generals for faction '{factionId}'.");
            }

            if (!_options.UseInteractiveSetup)
            {
                foreach (var general in seatGenerals)
                {
                    generals.Remove(general);
                }
            }

            _players.Add(new CharacterState
            {
                Seat = seat,
                Name = seat == _options.HumanSeat ? "你" : $"AI {seat + 1}",
                IsHuman = seat == _options.HumanSeat,
                // The legacy combat adapter still needs a non-null Role for
                // old AI/scoring contracts. National snapshots never expose
                // this compatibility value as an identity role.
                Role = Role.Renegade,
                TeamId = null,
                TeamRevealed = false,
                NationalFactionId = factionId,
                FactionRevealed = false,
                RoleRevealed = false,
                General = _options.UseInteractiveSetup ? hiddenGeneral : seatGenerals[0],
                GeneralSelected = !_options.UseInteractiveSetup,
                GeneralRevealed = false,
                SecondaryGeneral = _options.UseInteractiveSetup ? null : seatGenerals[1],
                SecondaryGeneralSelected = !_options.UseInteractiveSetup,
                SecondaryGeneralRevealed = false,
                MaxHp = 4,
                Hp = 4
            });
        }

        if (_options.UseInteractiveSetup)
        {
            _availableGenerals.AddRange(_generalPool);
            _random.Shuffle(_availableGenerals);
            _selectionOrder.AddRange(_players
                .OrderBy(player => player.Seat)
                .SelectMany(player => new[] { player.Seat, player.Seat }));
        }
    }

    private static IReadOnlyList<Card> CreateDeckFromRegistry(
        ContentRegistry contentRegistry,
        ContentDeckRecipe definition)
    {
        if (definition.PhysicalCards is { Count: > 0 } physicalCards)
        {
            return physicalCards.Select((entry, index) =>
            {
                var cardDefinition = contentRegistry.GetCard(entry.CardDefinitionId);
                if (cardDefinition.LegacyKind is not { } kind)
                {
                    throw new InvalidOperationException(
                        $"Card '{cardDefinition.Id}' has no legacy runtime projection for this engine.");
                }

                return new Card(index + 1, kind, entry.Suit, entry.Rank);
            }).ToArray();
        }

        var cards = new List<Card>(definition.Cards.Sum(entry => entry.Count));
        var id = 1;
        foreach (var entry in definition.Cards)
        {
            if (entry.Count <= 0)
            {
                throw new InvalidOperationException(
                    $"Deck recipe '{definition.Id}' contains a non-positive count.");
            }

            var cardDefinition = contentRegistry.GetCard(entry.CardDefinitionId);
            if (cardDefinition.LegacyKind is not { } kind)
            {
                throw new InvalidOperationException(
                    $"Card '{cardDefinition.Id}' has no legacy runtime projection for this engine.");
            }

            for (var copy = 0; copy < entry.Count; copy++)
            {
                var suit = (Suit)((id - 1) % 4);
                var rank = ((id - 1) % 13) + 1;
                cards.Add(new Card(id++, kind, suit, rank));
            }
        }

        return cards;
    }

    private void SetupDeck()
    {
        var cards = _contentRegistry is null
            ? StandardDeckCatalog.CreateBasicDemoDeck()
            : CreateDeckFromRegistry(
                _contentRegistry,
                ResolveDeckDefinition(_contentRegistry, _options.DeckId ?? _modeDefinition.DeckId)!);
        _cardZones.LoadInitialDeck(cards);
        _initialCardCount = _cardZones.TotalCards;
        if (!_options.UseInteractiveSetup)
        {
            if (UsesFormalWoodenOx && cards.Count(card => card.Kind == CardKind.WoodenOx) == 1)
            {
                _cardZones.ShuffleKeepingSingleKindAtBottom(CardLocation.DrawPile, _random, CardKind.WoodenOx);
            }
            else
            {
                _cardZones.Shuffle(CardLocation.DrawPile, _random);
            }
        }
        AssertCoreInvariants();
    }

    private void DealInitialHands()
    {
        for (var cardIndex = 0; cardIndex < _initialHandSize; cardIndex++)
        {
            foreach (var player in _players)
            {
                // The first seat of the first public team starts with one
                // fewer card in the 2v2 adapter, compensating for initiative.
                if (IsTeamMode && cardIndex == 0 && player.Seat == _currentSeat)
                {
                    continue;
                }

                DrawCards(player, 1, log: false, CardMoveReasons.InitialDeal);
            }
        }

        AssertCoreInvariants();
    }

    private void BeginTurn()
    {
        var current = _players[_currentSeat];
        if (!current.IsAlive)
        {
            _currentSeat = FindNextAliveSeat(_currentSeat);
            current = _players[_currentSeat];
        }

        if (_turnNumber >= _options.MaxTurns)
        {
            EndAsDraw($"达到最大回合数 {_options.MaxTurns}");
            return;
        }

        BeginRoundForTurn(current);
        _turnNumber++;
        ExpireOwnerTurnStartDamageModifiers(current.Seat);
        _slashCountThisTurn = 0;
        ResetCardUseDebitPhase();
        _usedOrPlayedSlashDuringPlayPhase = false;
        _shuangxiongJudgmentWasRed = null;
        _woodenOxUsedThisTurn = false;
        _shensuTwoResolvedThisTurn = false;
        _pendingShensuStage = 0;
        current.UsedPlayPhaseAlcoholThisTurn = false;
        current.AiJijiangFailedThisTurn = false;
        current.UsedActiveSkillKinds.Clear();
        _skillRuntimeState.ResetTurn();
        foreach (var character in _players)
            foreach (var grant in character.SkillGrants.Grants.Where(grant =>
                         grant.SourceId.StartsWith("turn:", StringComparison.Ordinal)))
                character.SkillGrants.RemoveGrant(grant.GrantId);
        foreach (var key in _programUses.Keys.Where(key => key.Seat == current.Seat).ToArray())
            _programUses.Remove(key);
        _phase = TurnPhase.Draw;
        AddLog(
            "TurnStarted",
            $"第 {_turnNumber} 回合：{current.Name}（{GetPublicGeneralName(current)}）行动。",
            current.Seat);
        QueueGameEvent(new TurnStartedEvent(_turnNumber, current.Seat));
        ResolveHengyeTurnStart(current);

        if (current.IsFaceDown)
        {
            current.IsFaceDown = false;
            AddLog("SkillTriggered", $"{current.Name} 将武将牌翻回正面并跳过本回合。", current.Seat);
            _phase = TurnPhase.Finished;
            AddLog("TurnEnded", $"{current.Name} 的翻面回合结束。", current.Seat);
            QueueGameEvent(new TurnEndedEvent(_turnNumber, current.Seat));
            _currentSeat = FindNextAliveSeat(_currentSeat);
            _phase = TurnPhase.NotStarted;
            PublishState();
            return;
        }

        _pendingTurnDelayedEffects = DelayedTurnEffects.None;
        if (TryBeginTurnStartProgramWindow(current))
        {
            return;
        }

        BeginNormalTurnStartAfterProgramBindings(current);
    }

    private void BeginTurnStartAfterProgramLifecycle(CharacterState current)
    {
        if (UsesFormalLuoshenAndQingguo && HasRuntimeSkill(current, SkillKind.Luoshen))
        {
            BeginLuoshenChoice(current, isRepeat: false);
            return;
        }

        BeginTurnStartAfterLuoshen(current);
    }

    private void BeginTurnStartAfterLuoshen(CharacterState current)
    {
        if (UsesFormalGuanxing && HasRuntimeSkill(current, SkillKind.Guanxing))
        {
            BeginGuanxingChoice(current);
            return;
        }

        if (UsesFormalXiahouYuan && HasRuntimeSkill(current, SkillKind.Shensu))
        {
            BeginShensuChoice(current, stage: 1);
            return;
        }

        BeginDelayedJudgmentOrTurnStart(current);
    }

    private void BeginLuoshenChoice(CharacterState current, bool isRepeat)
    {
        _pendingLuoshen = new LuoshenResolution(current.Seat, isRepeat);
        _pendingDecision = new PendingDecision(
            DecisionKind.Luoshen,
            current.Seat,
            isRepeat
                ? "【洛神】的黑色判定牌已获得，是否再次进行判定？"
                : "准备阶段开始，是否发动【洛神】进行判定？",
            [],
            [])
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            TargetSeat = current.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId($"luoshen.use.turn-{_turnNumber}.seat-{current.Seat}.{(isRepeat ? "repeat" : "initial")}"),
                    isRepeat ? "继续发动【洛神】，再次进行判定。" : "发动【洛神】，进行判定。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "luoshen-use" }),
                new PromptChoice(
                    new ChoiceId($"luoshen.skip.turn-{_turnNumber}.seat-{current.Seat}.{(isRepeat ? "repeat" : "initial")}"),
                    isRepeat ? "停止发动【洛神】，继续准备阶段。" : "不发动【洛神】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "luoshen-skip" })
            ]
        };
        _status = current.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        PublishState();
    }

    private void ResolveLuoshenChoice(bool useSkill)
    {
        var pending = _pendingLuoshen ??
            throw new InvalidOperationException("There is no Luoshen choice to resolve.");
        var current = _players[pending.PlayerSeat];
        _pendingLuoshen = null;
        ClearPendingDecision();
        QueueGameEvent(new LuoshenChoiceResolvedEvent(current.Seat, useSkill, pending.IsRepeat));
        AddLog(
            useSkill ? "SkillTriggered" : "SkillSkipped",
            useSkill
                ? $"{current.Name} 发动【洛神】，进行判定。"
                : pending.IsRepeat
                    ? $"{current.Name} 停止发动【洛神】。"
                    : $"{current.Name} 未发动【洛神】。",
            current.Seat);
        if (!useSkill)
        {
            BeginTurnStartAfterLuoshen(current);
            return;
        }

        _ = BeginJudgment(
            attack: null,
            targetSeat: current.Seat,
            reason: JudgmentReasons.Luoshen,
            parentFrameId: 0,
            sourceCard: null,
            continuation: JudgmentContinuationKind.Luoshen,
            damageSkill: null,
            sourceSeat: current.Seat);
    }

    private void BeginGuanxingChoice(CharacterState current)
    {
        _pendingGuanxing = new GuanxingResolution(
            current.Seat,
            GuanxingStage.Offer,
            [],
            [],
            []);
        _pendingDecision = new PendingDecision(
            DecisionKind.Guanxing,
            current.Seat,
            "是否发动【观星】，观看并重新排列牌堆顶的牌？",
            [],
            [])
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            TargetSeat = current.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId($"guanxing.use.turn-{_turnNumber}.seat-{current.Seat}"),
                    "发动【观星】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "guanxing-use" }),
                new PromptChoice(
                    new ChoiceId($"guanxing.skip.turn-{_turnNumber}.seat-{current.Seat}"),
                    "不发动【观星】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "guanxing-skip" })
            ]
        };
        _status = current.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        PublishState();
    }

    private void ResolveGuanxingChoice(PromptChoice choice)
    {
        var pending = _pendingGuanxing ??
            throw new InvalidOperationException("There is no Guanxing choice to resolve.");
        var current = _players[pending.PlayerSeat];
        var action = choice.Parameters.GetValueOrDefault("action");

        if (pending.Stage == GuanxingStage.Offer)
        {
            if (action == "guanxing-skip")
            {
                CompleteGuanxing(current, used: false);
                return;
            }

            if (action != "guanxing-use")
            {
                throw new InvalidOperationException("The Guanxing offer has an unsupported choice.");
            }

            _ = EnsureDrawPile();
            var viewedCount = Math.Min(
                Math.Min(5, _players.Count(player => player.IsAlive)),
                _cardZones.Count(CardLocation.DrawPile));
            var viewedTopFirst = _cardZones.CardsAt(CardLocation.DrawPile)
                .TakeLast(viewedCount)
                .Reverse()
                .Select(card => card.Id)
                .ToArray();
            if (viewedTopFirst.Length == 0)
            {
                _pendingGuanxing = pending with
                {
                    Stage = GuanxingStage.SelectingTop,
                    ViewedCardIds = viewedTopFirst
                };
                CompleteGuanxing(current, used: true);
                return;
            }

            pending = pending with
            {
                Stage = GuanxingStage.SelectingTop,
                ViewedCardIds = viewedTopFirst
            };
            _pendingGuanxing = pending;
            PublishGuanxingOrderingPrompt(current, pending);
            return;
        }

        var selectedIds = pending.TopCardIds.Concat(pending.BottomCardIds).ToHashSet();
        var remaining = pending.ViewedCardIds.Where(id => !selectedIds.Contains(id)).ToArray();
        if (pending.Stage == GuanxingStage.SelectingTop)
        {
            if (action == "guanxing-finish-top")
            {
                if (remaining.Length == 0)
                {
                    CompleteGuanxing(current, used: true);
                    return;
                }

                pending = pending with { Stage = GuanxingStage.SelectingBottom };
                _pendingGuanxing = pending;
                PublishGuanxingOrderingPrompt(current, pending);
                return;
            }

            if (action != "guanxing-top" || choice.Cards.Count != 1 || !remaining.Contains(choice.Cards[0]))
            {
                throw new InvalidOperationException("The selected Guanxing top card is no longer available.");
            }

            pending = pending with { TopCardIds = [.. pending.TopCardIds, choice.Cards[0]] };
        }
        else
        {
            if (action != "guanxing-bottom" || choice.Cards.Count != 1 || !remaining.Contains(choice.Cards[0]))
            {
                throw new InvalidOperationException("The selected Guanxing bottom card is no longer available.");
            }

            pending = pending with { BottomCardIds = [.. pending.BottomCardIds, choice.Cards[0]] };
        }

        _pendingGuanxing = pending;
        selectedIds = pending.TopCardIds.Concat(pending.BottomCardIds).ToHashSet();
        if (pending.ViewedCardIds.All(selectedIds.Contains))
        {
            CompleteGuanxing(current, used: true);
            return;
        }

        PublishGuanxingOrderingPrompt(current, pending);
    }

    private void PublishGuanxingOrderingPrompt(CharacterState current, GuanxingResolution pending)
    {
        var selectedIds = pending.TopCardIds.Concat(pending.BottomCardIds).ToHashSet();
        var remainingCards = pending.ViewedCardIds
            .Where(id => !selectedIds.Contains(id))
            .Select(id => _cardZones.CardsAt(CardLocation.DrawPile).Single(card => card.Id == id))
            .ToArray();
        var selectingTop = pending.Stage == GuanxingStage.SelectingTop;
        var desiredTopCount = GetAiGuanxingTopCount(current, pending.ViewedCardIds.Count);
        var slotPurpose = selectingTop
            ? GetGuanxingTopSlotPurpose(current, pending.TopCardIds.Count)
            : "bottom";
        var choices = remainingCards
            .Select(card => new PromptChoice(
                new ChoiceId($"guanxing.{(selectingTop ? "top" : "bottom")}.turn-{_turnNumber}.card-{card.Id}.slot-{(selectingTop ? pending.TopCardIds.Count : pending.BottomCardIds.Count)}"),
                selectingTop
                    ? $"将{GetSuitName(card.Suit)}【{card.DisplayName}】（{card.RankText}）置于牌堆顶第 {pending.TopCardIds.Count + 1} 张。"
                    : $"将{GetSuitName(card.Suit)}【{card.DisplayName}】（{card.RankText}）置于牌堆底第 {pending.BottomCardIds.Count + 1} 张（由底向上）。",
                [card.Id],
                [],
                new Dictionary<string, string>
                {
                    ["action"] = selectingTop ? "guanxing-top" : "guanxing-bottom",
                    ["stage"] = selectingTop ? "top" : "bottom",
                    ["card-kind"] = card.Kind.ToString(),
                    ["suit"] = card.Suit.ToString(),
                    ["rank"] = card.Rank.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["top-selected"] = pending.TopCardIds.Count.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["desired-top-count"] = desiredTopCount.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["slot-purpose"] = slotPurpose
                }))
            .ToList();
        if (selectingTop)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"guanxing.finish-top.turn-{_turnNumber}.count-{pending.TopCardIds.Count}"),
                pending.TopCardIds.Count == 0
                    ? "不在牌堆顶保留牌，其余牌改为置于牌堆底。"
                    : "牌堆顶排序完成，其余牌改为置于牌堆底。",
                [],
                [],
                new Dictionary<string, string>
                {
                    ["action"] = "guanxing-finish-top",
                    ["stage"] = "top",
                    ["top-selected"] = pending.TopCardIds.Count.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["desired-top-count"] = desiredTopCount.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["slot-purpose"] = slotPurpose
                }));
        }

        _pendingDecision = new PendingDecision(
            DecisionKind.Guanxing,
            current.Seat,
            selectingTop
                ? $"【观星】已观看 {pending.ViewedCardIds.Count} 张牌：依次选择牌堆顶顺序，第一张将最先被摸取；也可结束牌堆顶排序。"
                : $"【观星】牌堆顶已保留 {pending.TopCardIds.Count} 张：依次选择其余牌的牌堆底顺序，第一张置于最底层。",
            remainingCards.Select(card => card.Id).ToArray(),
            [])
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            TargetSeat = current.Seat,
            Choices = choices.AsReadOnly()
        };
        _status = current.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private int GetAiGuanxingTopCount(CharacterState current, int viewedCount)
    {
        var judgmentCount = GetJudgment(current).Count(card =>
            IsDelayedCard(GetJudgmentEffectiveCardKind(card)));
        return Math.Min(viewedCount, judgmentCount + Math.Max(0, GetTurnDrawCount(current)));
    }

    private string GetGuanxingTopSlotPurpose(CharacterState current, int topIndex)
    {
        var delayedCards = GetJudgment(current)
            .Where(card => IsDelayedCard(GetJudgmentEffectiveCardKind(card)))
            .ToArray();
        return topIndex < delayedCards.Length
            ? $"judgment-{GetJudgmentEffectiveCardKind(delayedCards[topIndex])}"
            : "draw";
    }

    private void CompleteGuanxing(CharacterState current, bool used)
    {
        var pending = _pendingGuanxing ??
            throw new InvalidOperationException("There is no Guanxing resolution to complete.");
        if (used)
        {
            _cardZones.ReorderDrawPileTop(
                pending.ViewedCardIds,
                pending.TopCardIds,
                pending.BottomCardIds);
        }

        QueueGameEvent(new GuanxingResolvedEvent(
            current.Seat,
            used,
            pending.ViewedCardIds.Count,
            pending.TopCardIds.Count,
            pending.BottomCardIds.Count));
        AddLog(
            "SkillTriggered",
            used
                ? $"{current.Name} 发动【观星】，观看 {pending.ViewedCardIds.Count} 张牌，将 {pending.TopCardIds.Count} 张置于牌堆顶、{pending.BottomCardIds.Count} 张置于牌堆底。"
                : $"{current.Name} 未发动【观星】。",
            current.Seat);
        _pendingGuanxing = null;
        ClearPendingDecision();
        BeginDelayedJudgmentOrTurnStart(current);
    }

    private void BeginDelayedJudgmentOrTurnStart(CharacterState current, int? excludedCardId = null)
    {
        var delayedCard = GetJudgment(current)
            .FirstOrDefault(card =>
                IsDelayedCard(GetJudgmentEffectiveCardKind(card)) &&
                card.Id != excludedCardId);
        if (delayedCard is not null)
        {
            var effectiveKind = GetJudgmentEffectiveCardKind(delayedCard);
            var delayedJudgment = GetDelayedJudgmentInfo(effectiveKind);
            var judgment = BeginJudgment(
                attack: null,
                targetSeat: current.Seat,
                reason: delayedJudgment.Reason,
                parentFrameId: 0,
                sourceCard: effectiveKind,
                continuation: delayedJudgment.Continuation,
                damageSkill: null,
                delayedCard: delayedCard,
                sourceSeat: current.Seat);
            if (judgment is null)
            {
                PublishState();
            }

            return;
        }

        CompleteTurnStart(current, _pendingTurnDelayedEffects);
    }

    private void CompleteTurnStart(CharacterState current, DelayedTurnEffects delayedEffects)
    {
        if (delayedEffects.HasFlag(DelayedTurnEffects.SkipDrawPhase))
        {
            AddLog("DelayedCardEffect", $"{current.Name} 因【兵粮寸断】跳过摸牌阶段。", current.Seat);
        }
        else if (UsesFormalShuangxiong && HasRuntimeSkill(current, SkillKind.Shuangxiong))
        {
            BeginShuangxiongDrawChoice(current, delayedEffects);
            return;
        }
        else if (TryBeginDrawPhaseProgramWindow(
                     current,
                     delayedEffects.HasFlag(DelayedTurnEffects.SkipPlayPhase)))
        {
            return;
        }
        else
        {
            DrawCards(current, GetTurnDrawCount(current), log: true);
        }

        CompleteTurnStartAfterDraw(current, delayedEffects);
    }

    private int GetTurnDrawCount(CharacterState current)
        => ToLegacyRuleValue(EvaluateDrawCount(current));

    private void BeginShuangxiongDrawChoice(CharacterState current, DelayedTurnEffects delayedEffects)
    {
        _pendingShuangxiongDraw = new ShuangxiongDrawResolution(current.Seat, delayedEffects);
        _pendingDecision = new PendingDecision(DecisionKind.Shuangxiong, current.Seat,
            "是否发动【双雄】，放弃通常摸牌并进行一次判定？", [], [])
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            Choices =
            [
                new PromptChoice(new ChoiceId("shuangxiong.use"), "发动【双雄】：判定并获得判定牌。", [], [],
                    new Dictionary<string, string> { ["action"] = "shuangxiong-use" }),
                new PromptChoice(new ChoiceId("shuangxiong.skip"), "不发动【双雄】，按通常数量摸牌。", [], [],
                    new Dictionary<string, string> { ["action"] = "shuangxiong-skip" })
            ]
        };
        _status = current.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        PublishState();
    }

    private void ResolveShuangxiongDrawChoice(bool useSkill)
    {
        var pending = _pendingShuangxiongDraw ?? throw new InvalidOperationException("There is no Shuangxiong draw choice.");
        var current = _players[pending.PlayerSeat];
        ClearPendingDecision();
        if (!useSkill)
        {
            DrawCards(current, GetTurnDrawCount(current), log: true);
            _pendingShuangxiongDraw = null;
            CompleteTurnStartAfterDraw(current, pending.DelayedEffects);
            return;
        }
        AddLog("SkillTriggered", $"{current.Name} 发动【双雄】，以判定替代摸牌。", current.Seat);
        BeginJudgment(null, current.Seat, JudgmentReasons.Shuangxiong, 0, null,
            JudgmentContinuationKind.Shuangxiong, null, sourceSeat: current.Seat);
    }

    private void CompleteDrawPhaseAfterProgramWindow(
        CharacterState current,
        bool skipPlayPhaseAfterDraw,
        bool normalDrawReplaced,
        int normalDrawAdjustment,
        int? frozenBaseDrawCount = null)
    {
        if (!normalDrawReplaced)
            DrawCards(current, Math.Max(0, checked((frozenBaseDrawCount ?? GetTurnDrawCount(current)) +
                normalDrawAdjustment)), log: true);
        CompleteTurnStartAfterDraw(
            current,
            skipPlayPhaseAfterDraw ? DelayedTurnEffects.SkipPlayPhase : DelayedTurnEffects.None);
    }

    private void CompleteTurnStartAfterDraw(CharacterState current, DelayedTurnEffects delayedEffects)
    {

        if (delayedEffects.HasFlag(DelayedTurnEffects.SkipPlayPhase))
        {
            BeginDiscardPhase();
            AddLog("DelayedCardEffect", $"{current.Name} 因【乐不思蜀】跳过出牌阶段。", current.Seat);
        }
        else if (UsesFormalXiahouYuan && HasRuntimeSkill(current, SkillKind.Shensu) &&
                 !_shensuTwoResolvedThisTurn && GetEquipment(current).Count > 0)
        {
            BeginShensuChoice(current, stage: 2);
        }
        else
        {
            EnterPlayPhase(current);
        }
        PublishState();
    }

    private void EnterPlayPhase(CharacterState current)
    {
        // Play-phase limits are distinct from turn-wide effects. Dangxian can
        // create two Play phases in one turn, so Slash count and phase-limited
        // actions reset here while Alcohol's once-per-turn flag remains intact.
        _slashCountThisTurn = 0;
        ResetCardUseDebitPhase();
        _woodenOxUsedThisTurn = false;
        current.AiJijiangFailedThisTurn = false;
        current.UsedActiveSkillKinds.Clear();
        ResetProgramContributionUsesForPlayPhase(current.Seat);
        foreach (var key in _programPhaseUses.Keys.Where(key => key.Seat == current.Seat).ToArray())
            _programPhaseUses.Remove(key);
        _skillRuntimeState.ResetPhase();
        _phase = TurnPhase.Play;
        AddLog("PhaseChanged", $"{current.Name} 进入出牌阶段。", current.Seat);
        QueueGameEvent(new PhaseChangedEvent(_phase, current.Seat));
    }

    private void BeginShensuChoice(CharacterState current, int stage)
    {
        var targets = _players.Where(target =>
            target.IsAlive &&
            target.Seat != current.Seat &&
            !IsDirectedCardTargetProhibited(current.Seat, target.Seat, CardKind.Slash) &&
            !IsSlashProhibited(target)).ToArray();
        var choices = new List<PromptChoice>();
        if (stage == 1)
        {
            foreach (var target in targets)
                choices.Add(new PromptChoice(new ChoiceId($"shensu.1.target-{target.Seat}"),
                    $"发动【神速】：跳过判定阶段和摸牌阶段，视为对 {target.Name} 使用无距离限制的【杀】。", [], [target.Seat],
                    new Dictionary<string, string> { ["action"] = "shensu-use", ["stage"] = "1" }));
        }
        else
        {
            foreach (var equipment in GetEquipment(current))
                foreach (var target in targets)
                    choices.Add(new PromptChoice(new ChoiceId($"shensu.2.card-{equipment.Id}.target-{target.Seat}"),
                        $"发动【神速】：弃置装备【{equipment.DisplayName}】并跳过出牌阶段，视为对 {target.Name} 使用无距离限制的【杀】。",
                        [equipment.Id], [target.Seat],
                        new Dictionary<string, string> { ["action"] = "shensu-use", ["stage"] = "2" }));
        }
        choices.Add(new PromptChoice(new ChoiceId($"shensu.{stage}.skip"), "不发动【神速】。", [], [],
            new Dictionary<string, string> { ["action"] = "shensu-skip", ["stage"] = stage.ToString(System.Globalization.CultureInfo.InvariantCulture) }));
        _pendingShensuStage = stage;
        _pendingDecision = new PendingDecision(DecisionKind.Shensu, current.Seat,
            stage == 1 ? "是否发动【神速】跳过判定与摸牌阶段？" : "是否发动【神速】弃置装备并跳过出牌阶段？", [], targets.Select(target => target.Seat).ToArray())
        { PromptId = CreatePromptId(), IsPrivate = true, Choices = choices.AsReadOnly() };
        _status = current.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        PublishState();
    }

    private void ResolveShensuChoice(int? equipmentCardId, int? targetSeat)
    {
        if (_pendingDecision is not { Kind: DecisionKind.Shensu, PlayerSeat: var playerSeat } || playerSeat != _currentSeat || _pendingShensuStage is not (1 or 2))
            throw new InvalidOperationException("There is no Shensu phase choice to resolve.");
        var player = _players[playerSeat];
        var stage = _pendingShensuStage;
        ClearPendingDecision();
        if (targetSeat is null)
        {
            _pendingShensuStage = 0;
            AddLog("SkillSkipped", $"{player.Name} 未发动【神速】第 {stage} 项。", player.Seat);
            if (stage == 1) BeginDelayedJudgmentOrTurnStart(player);
            else { _shensuTwoResolvedThisTurn = true; EnterPlayPhase(player); }
            return;
        }
        var target = _players[targetSeat.Value];
        if (!target.IsAlive || target.Seat == player.Seat || IsSlashProhibited(target))
            throw new InvalidOperationException("The selected Shensu target is no longer legal.");
        if (stage == 2)
        {
            var equipment = GetEquipment(player).SingleOrDefault(card => card.Id == equipmentCardId) ??
                throw new InvalidOperationException("Shensu's second option requires one current equipment card.");
            MoveCard(equipment, CardLocation.Equipment(player.Seat), CardLocation.DiscardPile, CardMoveReasons.ShensuDiscard);
            _shensuTwoResolvedThisTurn = true;
        }
        else if (equipmentCardId is not null)
        {
            throw new InvalidOperationException("Shensu's first option has no card cost.");
        }
        BeginShensuSlash(player, target, stage, equipmentCardId);
    }

    private void BeginShensuSlash(CharacterState source, CharacterState target, int stage, int? equipmentCardId)
    {
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new CardUseFrame(frameId, source.Seat, 0, CardKind.Slash,
            Array.AsReadOnly(new[] { target.Seat }), PhysicalCardIds: Array.AsReadOnly(Array.Empty<int>())));
        QueueGameEvent(new CardUseDeclaredEvent(frameId, 0, CardKind.Slash, source.Seat));
        QueueGameEvent(new TargetsConfirmedEvent(frameId, Array.AsReadOnly(new[] { target.Seat })));
        var attack = new AttackResolution(frameId, source.Seat, target.Seat, card: null,
            playedCardKind: CardKind.Slash);
        _pendingAttack = attack;
        AddLog("SkillTriggered", $"{source.Name} 发动【神速】第 {stage} 项，视为对 {target.Name} 使用无距离限制的【杀】。", source.Seat, target.Seat);
        QueueGameEvent(new ShensuUsedEvent(frameId, source.Seat, target.Seat, stage, stage == 2 ? equipmentCardId : null));
        QueueGameEvent(new CardUsedEvent(0, CardKind.Slash, source.Seat, target.Seat));
        ContinueSlashAfterLiegong(attack);
    }

    private static bool IsDelayedCard(CardKind kind) =>
        kind is CardKind.Indulgence or CardKind.SupplyShortage or CardKind.Lightning;

    private static bool IsOrdinaryTrick(CardKind kind) =>
        CardCatalog.Get(kind).CategoryName == "锦囊牌" && !IsDelayedCard(kind);

    private CardKind GetJudgmentEffectiveCardKind(Card card) =>
        _judgmentEffectiveCardKinds.GetValueOrDefault(card.Id, card.Kind);

    private bool HasJudgmentEffectiveCard(CharacterState player, CardKind kind) =>
        GetJudgment(player).Any(card => GetJudgmentEffectiveCardKind(card) == kind);

    private static bool IsDelayedJudgmentContinuation(JudgmentContinuationKind continuation) =>
        continuation is JudgmentContinuationKind.Indulgence or
            JudgmentContinuationKind.SupplyShortage or
            JudgmentContinuationKind.Lightning;

    private static (string Reason, JudgmentContinuationKind Continuation) GetDelayedJudgmentInfo(
        CardKind kind) => kind switch
        {
            CardKind.Indulgence => (JudgmentReasons.Indulgence, JudgmentContinuationKind.Indulgence),
            CardKind.SupplyShortage => (JudgmentReasons.SupplyShortage, JudgmentContinuationKind.SupplyShortage),
            CardKind.Lightning => (JudgmentReasons.Lightning, JudgmentContinuationKind.Lightning),
            _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "The card is not a delayed judgment card.")
        };

    private static DelayedTurnEffects GetDelayedTurnEffects(CardKind kind) => kind switch
    {
        CardKind.Indulgence => DelayedTurnEffects.SkipPlayPhase,
        CardKind.SupplyShortage => DelayedTurnEffects.SkipDrawPhase,
        CardKind.Lightning => DelayedTurnEffects.None,
        _ => throw new ArgumentOutOfRangeException(nameof(kind), kind, "The card is not a delayed turn card.")
    };

    private void RunOneSetupStep()
    {
        if (_selectionIndex >= _selectionOrder.Count)
        {
            var factionPlayer = _players
                .Where(RequiresGodFactionSelection)
                .OrderBy(player => player.Seat)
                .FirstOrDefault();
            if (factionPlayer is not null)
            {
                QueueGameEvent(new GodFactionSelectionRequestedEvent(
                    factionPlayer.Seat,
                    GodFactionChoices));
                if (factionPlayer.IsHuman)
                {
                    RequestHumanGodFactionSelection(factionPlayer);
                }
                else
                {
                    ApplyGodFactionSelection(factionPlayer, ChooseAutomaticGodFaction(factionPlayer));
                    PublishState();
                }
                return;
            }

            CompleteSetup();
            return;
        }

        var seat = _selectionOrder[_selectionIndex];
        var player = _players[seat];
        var candidates = GetAvailableGeneralCandidates(player);
        if (candidates.Count == 0)
        {
            throw new InvalidOperationException(
                $"Mode '{_modeDefinition.Id}' ran out of generals during setup.");
        }

        QueueGameEvent(new GeneralSelectionRequestedEvent(
            player.Seat,
            candidates.Select(general => general.Id).ToArray()));

        if (player.IsHuman)
        {
            RequestHumanGeneralSelection(player, candidates);
            return;
        }

        var view = CreateSnapshot(player.Seat);
        var (general, thought) = _aiBrains[player.Seat].ChooseGeneral(
            view,
            view.Players.Single(snapshot => snapshot.Seat == player.Seat).Role ?? Role.Renegade,
            candidates,
            ++_thoughtSequence);
        AddGeneralThought(thought);
        ApplyGeneralSelection(player, general);
        PublishState();
    }

    private void RequestHumanGodFactionSelection(CharacterState player)
    {
        var choices = GodFactionChoices
            .Select(factionId => new PromptChoice(
                new ChoiceId($"setup.god-faction.{factionId}"),
                $"选择{GetFactionName(factionId)}势力",
                [],
                [],
                new Dictionary<string, string>
                {
                    ["action"] = "select-god-faction",
                    ["faction-id"] = factionId
                }))
            .ToArray();
        _pendingDecision = new PendingDecision(
            DecisionKind.SelectFaction,
            player.Seat,
            $"{player.General.Name}为神势力武将。请选择本局归属的魏、蜀、吴、群势力；该选择会影响主公技等势力判定，但不会改写武将的印刷势力。",
            [],
            [])
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            IsPrivate = true
        };
        _status = EngineStatus.AwaitingHumanFactionSelection;
        PublishState();
    }

    private void ApplyGodFactionSelection(CharacterState player, string factionId)
    {
        if (!RequiresGodFactionSelection(player))
        {
            throw new InvalidOperationException(
                $"Seat {player.Seat} does not currently require a god-faction choice.");
        }
        if (!GodFactionChoices.Contains(factionId, StringComparer.Ordinal))
        {
            throw new InvalidOperationException($"Faction '{factionId}' is not a legal god-faction choice.");
        }

        player.ChosenFactionId = factionId;
        ClearPendingDecision();
        _status = EngineStatus.Running;
        AddLog(
            "GodFactionSelected",
            $"{player.Name} 为神势力武将 {player.General.Name} 选择了{GetFactionName(factionId)}势力。",
            player.Seat);
        QueueGameEvent(new GodFactionSelectedEvent(player.Seat, factionId));
    }

    private EngineRunResult HumanSelectGodFactionCore(string factionId, bool advanceToHumanBoundary)
    {
        RequireHumanDecision(DecisionKind.SelectFaction);
        var pending = _pendingDecision ??
            throw new InvalidOperationException("There is no god-faction selection prompt.");
        ApplyGodFactionSelection(_players[pending.PlayerSeat], factionId);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private IReadOnlyList<GeneralDefinition> GetAvailableGeneralCandidates(CharacterState player) =>
        _availableGenerals
            .Where(general => !IsNationalWarMode ||
                              string.Equals(general.FactionId, player.NationalFactionId, StringComparison.Ordinal))
            .Take(Math.Min(_modeDefinition.GeneralCandidateCount, _availableGenerals.Count))
            .ToArray();

    private void RequestHumanGeneralSelection(
        CharacterState player,
        IReadOnlyList<GeneralDefinition> candidates)
    {
        var choices = candidates.Select(general =>
        {
            var factionSuffix = IsNationalWarMode
                ? $" · {GetFactionName(general.FactionId ?? string.Empty)}"
                : string.Empty;
            var choice = new PromptChoice(
                new ChoiceId($"setup.general.{general.Id}"),
                $"选择 {general.Name}（{general.SkillSummary}{factionSuffix}）",
                [],
                [],
                new Dictionary<string, string>
                {
                    ["action"] = "select-general",
                    ["general-id"] = general.Id,
                    ["faction-id"] = general.FactionId ?? string.Empty
                });
            choice = choice with { ContentIds = [general.Id] };
            if (!IsNationalWarMode && UsesGeneralBaseHp)
            {
                var identityMaxHp = general.BaseHp + (player.Role == Role.Lord ? 1 : 0);
                choice = choice with
                {
                    Parameters = new Dictionary<string, string>(choice.Parameters, StringComparer.Ordinal)
                    {
                        ["base-hp"] = general.BaseHp.ToString(System.Globalization.CultureInfo.InvariantCulture),
                        ["identity-max-hp"] = identityMaxHp.ToString(System.Globalization.CultureInfo.InvariantCulture),
                        ["health-preview"] = player.Role == Role.Lord
                            ? $"主公体力上限为基础 {general.BaseHp} + 1 = {identityMaxHp}。"
                            : $"身份模式体力上限为 {identityMaxHp}。"
                    }
                };
            }
            choice = WithNationalHealthPreview(choice, player, general);
            return choice;
        }).ToArray();

        _pendingDecision = new PendingDecision(
            DecisionKind.SelectGeneral,
            player.Seat,
            IsNationalWarMode
                ? player.GeneralSelected
                    ? $"主将 {player.General.Name}（基础体力 {player.General.BaseHp}）· 请选择副将，卡片显示组合后的体力上限。"
                    : $"请选择你的第 {(player.GeneralSelected ? "二" : "一")} 名同势力武将。候选仅对你可见，明置前势力不会公开。"
                : "请选择你的武将。候选仅对你可见，所有人完成后才会公开结果。",
            [],
            [])
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            ValidContentIds = candidates.Select(general => general.Id).ToArray()
        };
        _status = EngineStatus.AwaitingHumanGeneralSelection;
        PublishState();
    }

    private void ApplyGeneralSelection(CharacterState player, GeneralDefinition general)
    {
        if (!_availableGenerals.Remove(general))
        {
            throw new InvalidOperationException(
                $"General '{general.Id}' is not available for seat {player.Seat}.");
        }

        if (IsNationalWarMode)
        {
            if (string.IsNullOrWhiteSpace(general.FactionId) ||
                !string.Equals(general.FactionId, player.NationalFactionId, StringComparison.Ordinal))
            {
                throw new InvalidOperationException(
                    $"General '{general.Id}' does not belong to seat {player.Seat}'s assigned faction.");
            }

            if (!player.GeneralSelected)
            {
                player.General = general;
                player.GeneralSelected = true;
                QueueGameEvent(new GeneralSelectedEvent(player.Seat, general.Id));
            }
            else if (!player.SecondaryGeneralSelected)
            {
                player.SecondaryGeneral = general;
                player.SecondaryGeneralSelected = true;
                QueueGameEvent(new SecondaryGeneralSelectedEvent(player.Seat, general.Id));
            }
            else
            {
                throw new InvalidOperationException($"Seat {player.Seat} already selected both generals.");
            }
        }
        else
        {
            player.General = general;
            player.GeneralSelected = true;
            player.GeneralRevealed = false;
            if (UsesGeneralBaseHp)
            {
                player.MaxHp = general.BaseHp + (player.Role == Role.Lord ? 1 : 0);
                player.Hp = player.MaxHp;
            }
            AddLog("GeneralSelected", $"座位 {player.Seat + 1} 完成私有选将。", player.Seat);
            QueueGameEvent(new GeneralSelectedEvent(player.Seat, general.Id));
        }
        _selectionIndex++;
        ClearPendingDecision();
    }

    private void CompleteSetup()
    {
        if (_setupComplete)
        {
            return;
        }

        if (_selectionIndex != _selectionOrder.Count ||
            _players.Any(player => !player.GeneralSelected ||
                                  IsNationalWarMode && !player.SecondaryGeneralSelected ||
                                  RequiresGodFactionSelection(player)))
        {
            throw new InvalidOperationException("Setup cannot complete before every seat selects a general.");
        }

        InitializeNationalHealth();
        _cardZones.Shuffle(CardLocation.DrawPile, _random);
        DealInitialHands();
        foreach (var player in _players.Where(player => !IsNationalWarMode))
        {
            player.GeneralRevealed = true;
        }
        InitializeStructuredConversionSkills();

        _setupComplete = true;
        _status = EngineStatus.Running;
        AddLog(
            "SetupCompleted",
            IsNationalWarMode
                ? "国战选将完成，双将与势力保持暗置；出牌阶段或杀响应时可按需明置一名武将。"
                : $"选将完成并公开：{string.Join("、", _players.OrderBy(player => player.Seat).Select(player => player.General.Name))}。",
            _currentSeat);
        QueueGameEvent(new GameStartedEvent(_playerCount, _modeDefinition.Id));
        QueueGameEvent(new SetupCompletedEvent(_players.Count, _modeDefinition.Id));
        PublishState();
    }

    private void RunOneEngineStep()
    {
        if (_pendingDecision is { Kind: DecisionKind.ProgramTrigger } programTriggerDecision)
        {
            if (!_players[programTriggerDecision.PlayerSeat].IsHuman)
                ResolvePendingAiProgramTrigger();
            return;
        }

        if (_pendingDecision?.SkillPrompt is not null)
        {
            if (IsAiPindianPending()) ResolvePendingAiPindian();
            return;
        }

        if (_resolutionStack.LastOrDefault() is ProgramJudgmentTriggerWindowFrame &&
            _pendingDecision is null)
        {
            ContinueProgramJudgmentWindow();
            return;
        }

        if (_pendingDecision is
            {
                Kind: DecisionKind.ProgramJudgmentTrigger
            })
        {
            if (IsAiProgramJudgmentPending()) ResolvePendingAiProgramJudgment();
            return;
        }

        if (IsAiProgramJudgmentReplacementPending())
        {
            ResolvePendingAiProgramJudgmentReplacement();
            return;
        }


        if (IsAiTianxiangPending())
        {
            ResolvePendingAiTianxiang();
            return;
        }

        if (IsAiLiuliPending())
        {
            ResolvePendingAiLiuli();
            return;
        }

        if (IsAiGuanxingPending())
        {
            ResolvePendingAiGuanxing();
            return;
        }

        if (IsAiLuoshenPending())
        {
            ResolvePendingAiLuoshen();
            return;
        }

        if (IsAiJizhiPending())
        {
            ResolvePendingAiJizhi();
            return;
        }

        if (IsAiTieqiPending())
        {
            ResolvePendingAiTieqi();
            return;
        }

        if (IsAiLiegongPending())
        {
            ResolvePendingAiLiegong();
            return;
        }


        if (IsAiYingboPending())
        {
            ResolvePendingAiYingbo();
            return;
        }

        if (IsAiFanjianPending())
        {
            ResolvePendingAiFanjian();
            return;
        }

        if (IsAiTianduPending())
        {
            ResolvePendingAiTiandu();
            return;
        }

        if (IsAiKejiPending())
        {
            ResolvePendingAiKeji();
            return;
        }

        if (IsAiShensuPending())
        {
            ResolvePendingAiShensu();
            return;
        }

        if (IsAiYaowuPending())
        {
            ResolvePendingAiYaowu();
            return;
        }

        if (IsAiShuangxiongPending())
        {
            ResolvePendingAiShuangxiong();
            return;
        }

        if (_pendingDying is not null)
        {
            RunOneDyingStep();
            return;
        }

        if (IsAiTargetCardSelectionPending())
        {
            ResolvePendingAiTargetCardSelection();
            return;
        }

        if (IsAiFireAttackPending())
        {
            ResolvePendingAiFireAttack();
            return;
        }

        if (IsAiDamageSkillPending())
        {
            ResolvePendingAiDamageSkill();
            return;
        }

        if (IsAiJudgmentPending())
        {
            ResolvePendingAiJudgment();
            return;
        }

        if (_pendingDamageTrigger is not null)
        {
            RunOneDamageTriggerStep();
            return;
        }

        if (IsAiNullificationPending())
        {
            ResolvePendingAiNullification();
            return;
        }

        if (IsAiResponsePending())
        {
            ResolvePendingAiResponse();
            return;
        }

        if (IsAiHarvestPending())
        {
            ResolvePendingAiHarvest();
            return;
        }

        if (_pendingGroupCard is { Effect: GroupCardEffect.Recovery })
        {
            RunOneGroupRecoveryStep();
            return;
        }

        if (!_setupComplete)
        {
            RunOneSetupStep();
            return;
        }

        if (_resolutionStack.LastOrDefault() is ProgramSkillFrame programFrame)
        {
            ContinueProgramSkill(programFrame.Id);
            PublishState();
            return;
        }

        if (_phase is TurnPhase.NotStarted or TurnPhase.Finished)
        {
            BeginTurn();
            return;
        }

        if (_phase == TurnPhase.Play)
        {
            var current = _players[_currentSeat];
            if (!current.IsAlive)
            {
                EndTurn();
                return;
            }

            if (current.IsHuman)
            {
                RequestHumanPlay();
                return;
            }

            RunOneAiPlayDecision(current);
            return;
        }

        if (_phase == TurnPhase.Discard)
        {
            var current = _players[_currentSeat];
            if (_options.UseInteractiveDiscard && current.IsHuman && current.IsAlive &&
                GetHand(current).Count > GetHandLimit(current))
            {
                RequestHumanDiscard(current);
                return;
            }

            AutoDiscard(current);
            EndTurn();
            return;
        }

        throw new InvalidOperationException(
            $"No continuation for phase {_phase}; seed {_options.Seed}, turn {_turnNumber}, seat {_currentSeat}, " +
            $"general {_players[_currentSeat].General.Id}, winner {_winner}, " +
            $"frames [{string.Join(", ", _resolutionStack.Select(frame => $"{frame.Kind}:{frame.Id}"))}], " +
            $"decision {_pendingDecision?.Kind}.");
    }

    private void RunOneAiPlayDecision(CharacterState player)
    {
        var legalActions = BuildLegalActions(player);
        var view = CreateSnapshot(player.Seat);
        var (action, thought) = _aiBrains[player.Seat].ChoosePlay(view, legalActions, ++_thoughtSequence);
        AddThought(thought);

        if (action.Kind == LegalActionKind.EndPlay)
        {
            CompleteCurrentPlayPhase();
            PublishState();
            return;
        }

        var activeSkillCards = action.Kind is LegalActionKind.UseSkill or LegalActionKind.UseEquipmentEffect or LegalActionKind.UseProgramSkill
            ? _aiBrains[player.Seat].ChooseActiveSkillCards(view, action)
            : [];
        var activeSkillTargets = action.Kind is LegalActionKind.UseSkill or LegalActionKind.UseEquipmentEffect or LegalActionKind.UseProgramSkill
            ? _aiBrains[player.Seat].ChooseActiveSkillTargets(view, action)
            : [];
        ExecuteAction(player, action, activeSkillCards, activeSkillTargets);
        PublishState();
    }

    private void ExecuteActiveSkill(
        CharacterState actor,
        LegalAction action,
        IReadOnlyList<int>? selectedCardIds = null,
        IReadOnlyList<int>? selectedTargetSeats = null)
    {
        var skillKind = action.Skill ??
            throw new InvalidOperationException("An active-skill action must identify its skill.");
        var skill = ActiveActionCatalog.Find(skillKind) ??
            throw new InvalidOperationException($"Skill {skillKind} does not expose an active effect.");
        var selection = ActiveActionCatalog.Selection(skillKind);
        var cardIds = selectedCardIds?.ToArray() ?? [];
        var targetSeats = selectedTargetSeats?.ToArray() ?? [];
        var context = CreateActiveSkillContext(
            actor,
            skillKind,
            cardIds.Length,
            targetSeats.Length);
        if (!skill.CanUse(context))
        {
            throw new InvalidOperationException($"Skill {skillKind} cannot be used in the current context.");
        }

        var effect = skill.GetEffect(context);
        var selectionError = ValidateActiveSkillSelection(
            actor,
            skillKind,
            effect,
            cardIds,
            targetSeats,
            GetActiveSkillValidTargetSeats(actor, skillKind));
        if (selectionError is not null)
        {
            throw new InvalidOperationException(selectionError.Message);
        }

        if (!ActiveActionExecutor.IsSupported(effect.Kind))
        {
            throw new InvalidOperationException($"Skill {skillKind} returned an invalid or unsupported active effect.");
        }

        if (ActiveActionExecutor.TryExecuteImmediate(skill, effect, actor.Seat, cardIds, this))
        {
            return;
        }

        if (effect.Kind == ActiveSkillEffectKind.DiscardAndDraw)
        {
            effect = effect with { DrawCount = cardIds.Length };
        }

        var recordedCardIds = cardIds.Length == 0
            ? null
            : Array.AsReadOnly(cardIds);
        var recordedTargetSeats = targetSeats.Length == 0
            ? null
            : Array.AsReadOnly(targetSeats);

        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new ActiveSkillFrame(
            frameId,
            actor.Seat,
            skillKind,
            effect.Kind,
            effect.HpCost,
            effect.DrawCount,
            CardIds: recordedCardIds,
            TargetSeats: recordedTargetSeats,
            RecoveryAmount: effect.RecoveryAmount));
        QueueGameEvent(new ActiveSkillRequestedEvent(
            frameId,
            actor.Seat,
            skillKind,
            recordedCardIds,
            recordedTargetSeats));
        SetActiveSkillFrameStep(frameId, ResolutionFrameStep.ResolvingEffect);

        if (ActiveActionExecutor.TryExecute(new ActiveActionInvocation(
                frameId, actor.Seat, skill, selection, effect, cardIds, targetSeats), this))
        {
            return;
        }

        throw new InvalidOperationException($"Unsupported active effect {effect.Kind}.");
    }

    private void ExecuteAction(
        CharacterState actor,
        LegalAction action,
        IReadOnlyList<int>? activeSkillCardIds = null,
        IReadOnlyList<int>? activeSkillTargetSeats = null)
    {
        SelectUseConversion(action);
        if (action.Kind == LegalActionKind.UseProgramSkill)
        {
            ExecuteProgramSkill(actor, action, activeSkillCardIds ?? [], activeSkillTargetSeats ?? []);
            return;
        }
        if (action.Kind == LegalActionKind.RevealGeneral)
        {
            RevealNationalGeneral(
                actor,
                action.GeneralSlot ??
                throw new InvalidOperationException("A general reveal action must identify its slot."));
            return;
        }

        if (action.Kind == LegalActionKind.UseSkill)
        {
            ExecuteActiveSkill(actor, action, activeSkillCardIds, activeSkillTargetSeats);
            return;
        }

        if (action.Kind == LegalActionKind.UseEquipmentEffect)
        {
            var cardIds = activeSkillCardIds?.Distinct().ToArray() ?? [];
            var targets = activeSkillTargetSeats?.Distinct().ToArray() ?? [];
            if (cardIds.Length < action.MinCardCount || cardIds.Length > action.MaxCardCount ||
                targets.Length < action.MinTargetCount || targets.Length > action.MaxTargetCount ||
                cardIds.Any(cardId => !action.SelectableCardIds.Contains(cardId)) ||
                targets.Any(target => !action.SelectableTargetSeats.Contains(target)))
            {
                throw new InvalidOperationException("The equipment-effect selection is invalid.");
            }

            if (action.EquipmentKind == CardKind.WoodenOx)
            {
                ResolveWoodenOx(actor, cardIds[0], targets.SingleOrDefault(-1));
            }
            else
            {
                var cards = cardIds.Select(cardId =>
                    GetPlayableCards(actor).Single(card => card.Id == cardId)).ToArray();
                ResolveZhangbaSlash(actor, _players[targets[0]], cards);
            }
            return;
        }

        var card = FindOwnedPlayableCard(actor, action.CardId) ??
            throw new InvalidOperationException("The chosen card is no longer in the actor's playable zones.");

        switch (action.Kind)
        {
            case LegalActionKind.Recast:
                ResolveRecast(actor, card, action.PlayedCardKind);
                break;
            case LegalActionKind.Slash:
                if (action.TargetSeat is null)
                {
                    throw new InvalidOperationException("Slash requires a target.");
                }

                if (action.TargetSeats.Count > 1)
                {
                    ResolveFangtianHalberdSlash(
                        actor,
                        action.TargetSeats.Select(seat => _players[seat]).ToArray(),
                        card,
                        action.PlayedCardKind ?? card.Kind,
                        action.ConversionSource,
                        action.AdditionalConversionSources,
                        action.CardKindModifierSkill,
                        action.TargetCountModifierSkill);
                }
                else
                {
                    ResolveSlash(
                        actor,
                        _players[action.TargetSeat.Value],
                        card,
                        action.PlayedCardKind ?? card.Kind,
                        action.ConversionSource,
                        action.AdditionalConversionSources,
                        action.CardKindModifierSkill,
                        action.TargetCountModifierSkill);
                }
                break;
            case LegalActionKind.Peach:
                ResolvePeach(actor, card);
                break;
            case LegalActionKind.Duel:
                if (action.TargetSeat is null)
                {
                    throw new InvalidOperationException("Duel requires a target.");
                }

                ResolveDuel(actor, _players[action.TargetSeat.Value], card, action.PlayedCardKind);
                break;
            case LegalActionKind.DrawTwo:
                ResolveDrawTwo(actor, card);
                break;
            case LegalActionKind.Alcohol:
                ResolveAlcohol(actor, card);
                break;
            case LegalActionKind.Equip:
                ResolveEquip(actor, card);
                break;
            case LegalActionKind.BarbarianAssault:
                ResolveGroupCard(actor, card, LegalActionKind.BarbarianAssault, CardKind.Slash);
                break;
            case LegalActionKind.ArrowBarrage:
                ResolveGroupCard(actor, card, LegalActionKind.ArrowBarrage, CardKind.Dodge);
                break;
            case LegalActionKind.PeachGarden:
                ResolvePeachGarden(actor, card);
                break;
            case LegalActionKind.FiveGrains:
                ResolveFiveGrains(actor, card);
                break;
            case LegalActionKind.IronChain:
                if (action.TargetSeats.Count is < 1 or > 2)
                {
                    throw new InvalidOperationException("IronChain requires one or two targets.");
                }

                ResolveIronChain(actor, card, action.TargetSeats, action.PlayedCardKind);
                break;
            case LegalActionKind.Indulgence:
            case LegalActionKind.SupplyShortage:
            case LegalActionKind.Lightning:
                if (action.TargetSeat is null)
                {
                    throw new InvalidOperationException($"{action.Kind} requires a target.");
                }

                ResolveDelayedCard(
                    actor,
                    _players[action.TargetSeat.Value],
                    card,
                    action.Kind,
                    action.PlayedCardKind);
                break;
            case LegalActionKind.Dismantlement:
                if (action.TargetSeat is null)
                {
                    throw new InvalidOperationException("Dismantlement requires a target.");
                }

                ResolveDismantlement(
                    actor,
                    _players[action.TargetSeat.Value],
                    card,
                    action.TargetCardId,
                    action.PlayedCardKind);
                break;
            case LegalActionKind.Snatch:
                if (action.TargetSeat is null)
                {
                    throw new InvalidOperationException("Snatch requires a target.");
                }

                ResolveSnatch(
                    actor,
                    _players[action.TargetSeat.Value],
                    card,
                    action.TargetCardId);
                break;
            case LegalActionKind.FireAttack:
                if (action.TargetSeat is null)
                {
                    throw new InvalidOperationException("FireAttack requires a target.");
                }

                ResolveFireAttack(actor, _players[action.TargetSeat.Value], card, action.PlayedCardKind);
                break;
            case LegalActionKind.BorrowedSword:
                if (action.TargetSeats.Count != 2)
                {
                    throw new InvalidOperationException("Borrowed Sword requires an ordered weapon owner and Slash target.");
                }

                ResolveBorrowedSword(
                    actor,
                    _players[action.TargetSeats[0]],
                    _players[action.TargetSeats[1]],
                    card);
                break;
            default:
                throw new InvalidOperationException($"Unsupported action {action.Kind}.");
        }
    }

    private void RevealNationalGeneral(CharacterState actor, GeneralSelectionSlot slot)
    {
        if (!IsNationalWarMode)
        {
            throw new InvalidOperationException("General reveal is only available in national-war lite mode.");
        }

        var general = slot switch
        {
            GeneralSelectionSlot.Primary => actor.GeneralSelected && !actor.GeneralRevealed
                ? actor.General
                : null,
            GeneralSelectionSlot.Secondary => actor.SecondaryGeneralSelected &&
                                              !actor.SecondaryGeneralRevealed
                ? actor.SecondaryGeneral
                : null,
            _ => null
        };
        if (general is null)
        {
            throw new InvalidOperationException("The selected national general is already public or unavailable.");
        }

        if (slot == GeneralSelectionSlot.Primary)
        {
            actor.GeneralRevealed = true;
        }
        else
        {
            actor.SecondaryGeneralRevealed = true;
        }

        var firstFactionReveal = !actor.FactionRevealed;
        actor.FactionRevealed = true;
        QueueGameEvent(new NationalGeneralRevealedEvent(actor.Seat, slot, general.Id));
        if (firstFactionReveal)
        {
            QueueGameEvent(new NationalFactionRevealedEvent(actor.Seat, actor.NationalFactionId!));
        }

        AddLog(
            "NationalGeneralRevealed",
            $"{actor.Name} 明置{GetFactionName(actor.NationalFactionId!)}势力的【{general.Name}】。",
            actor.Seat);
    }

    private void RevealNationalInformation(CharacterState player)
    {
        if (!IsNationalWarMode || player.NationalFactionId is null)
        {
            return;
        }

        if (player.GeneralSelected && !player.GeneralRevealed)
        {
            player.GeneralRevealed = true;
            QueueGameEvent(new NationalGeneralRevealedEvent(
                player.Seat,
                GeneralSelectionSlot.Primary,
                player.General.Id));
        }

        if (player.SecondaryGeneralSelected &&
            player.SecondaryGeneral is { } secondary &&
            !player.SecondaryGeneralRevealed)
        {
            player.SecondaryGeneralRevealed = true;
            QueueGameEvent(new NationalGeneralRevealedEvent(
                player.Seat,
                GeneralSelectionSlot.Secondary,
                secondary.Id));
        }

        if (!player.FactionRevealed)
        {
            player.FactionRevealed = true;
            QueueGameEvent(new NationalFactionRevealedEvent(player.Seat, player.NationalFactionId));
        }
    }

    private void ResolveEquip(CharacterState source, Card equipment)
    {
        var definition = EquipmentCatalog.Get(equipment.Kind);
        var stillLegal = BuildLegalActions(source).Any(action =>
            action.Kind == LegalActionKind.Equip &&
            action.CardId == equipment.Id &&
            action.TargetSeat is null);
        if (!stillLegal)
        {
            throw new InvalidOperationException("The equipment card became illegal before resolution.");
        }

        var resolutionId = BeginCardUse(equipment, source.Seat, []);
        MoveCard(
            equipment,
            FindOwnedCardLocation(source, equipment),
            CardLocation.Processing,
            CardMoveReasons.EquipmentUse);
        SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);

        var replaced = GetEquipment(source)
            .SingleOrDefault(card => EquipmentCatalog.Get(card.Kind).Slot == definition.Slot);
        if (replaced is not null)
        {
            MoveCard(
                replaced,
                CardLocation.Equipment(source.Seat),
                CardLocation.DiscardPile,
                CardMoveReasons.EquipmentReplace);
        }

        MoveCard(
            equipment,
            CardLocation.Processing,
            CardLocation.Equipment(source.Seat),
            CardMoveReasons.EquipmentEnter);
        QueueGameEvent(new EquipmentChangedEvent(
            resolutionId,
            source.Seat,
            definition.Slot,
            equipment.Id,
            equipment.Kind,
            replaced?.Id));
        AddLog(
            "EquipmentChanged",
            replaced is null
                ? $"{source.Name} 装备【{definition.DisplayName}】。"
                : $"{source.Name} 装备【{definition.DisplayName}】，替换并弃置原有{EquipmentCatalog.GetSlotName(definition.Slot)}。",
            source.Seat);
        FinishCardUse(resolutionId, equipment);
    }

    private void BeginJizhiOrNullificationWindow(
        long resolutionId,
        Card effectCard,
        int sourceSeat,
        IReadOnlyList<int> targetSeats,
        LegalActionKind actionKind,
        int? targetCardId = null,
        CardKind? requiredCardKind = null,
        CardKind? playedCardKind = null)
    {
        var effectiveCardKind = playedCardKind ?? effectCard.Kind;
        var pending = new JizhiResolution(
            sourceSeat,
            resolutionId,
            effectCard,
            effectiveCardKind,
            targetSeats,
            actionKind,
            targetCardId,
            requiredCardKind,
            activeNullification: null);
        if (TryBeginProgramCardUseBeforeTargetEffects(pending))
        {
            return;
        }
        ContinueJizhiOrNullificationAfterTargetTriggers(pending);
    }

    private void ContinueJizhiOrNullificationAfterTargetTriggers(JizhiResolution pending)
    {
        if (TryBeginJizhiChoice(pending))
        {
            return;
        }

        BeginNullificationWindow(
            pending.ResolutionId,
            pending.Card,
            pending.PlayerSeat,
            pending.TargetSeats,
            pending.ActionKind,
            pending.TargetCardId,
            pending.RequiredCardKind,
            pending.EffectiveCardKind);
    }

    private bool TryBeginJizhiChoice(JizhiResolution pending)
    {
        var owner = _players[pending.PlayerSeat];
        if (!UsesFormalJizhi ||
            !owner.IsAlive ||
            !HasRuntimeSkill(owner, SkillKind.Jizhi) ||
            !IsOrdinaryTrick(pending.EffectiveCardKind))
        {
            return false;
        }

        if (_pendingJizhi is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Jizhi choices at once.");
        }

        _pendingJizhi = pending;
        _pendingDecision = new PendingDecision(
            DecisionKind.Jizhi,
            owner.Seat,
            $"你使用了【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】，是否发动【集智】摸一张牌？",
            [],
            [],
            SourceSeat: owner.Seat,
            IncomingCard: pending.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            TargetSeat = owner.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId($"jizhi.use.card-{pending.Card.Id}.resolution-{pending.ResolutionId}"),
                    "发动【集智】，摸一张牌。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "jizhi-use" }),
                new PromptChoice(
                    new ChoiceId($"jizhi.skip.card-{pending.Card.Id}.resolution-{pending.ResolutionId}"),
                    "不发动【集智】，继续结算此牌。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "jizhi-skip" })
            ]
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private void ResolveJizhiChoice(bool useSkill)
    {
        var pending = _pendingJizhi ??
            throw new InvalidOperationException("There is no Jizhi choice to resolve.");
        var owner = _players[pending.PlayerSeat];
        _pendingJizhi = null;
        ClearPendingDecision();
        var drawnCardIds = useSkill
            ? DrawCards(owner, 1, log: false, CardMoveReasons.JizhiDraw)
            : [];
        QueueGameEvent(new DrawSkillResolvedEvent(
            owner.Seat,
            SkillKind.Jizhi,
            useSkill,
            drawnCardIds.Count));
        AddLog(
            useSkill ? "SkillTriggered" : "SkillSkipped",
            useSkill
                ? drawnCardIds.Count == 1
                    ? $"{owner.Name} 发动【集智】，摸一张牌。"
                    : $"{owner.Name} 发动【集智】，但牌堆中没有可摸的牌。"
                : $"{owner.Name} 未发动【集智】。",
            owner.Seat);

        if (pending.ActiveNullification is { } activeNullification)
        {
            ContinueNullificationWindow(activeNullification);
            return;
        }

        BeginNullificationWindow(
            pending.ResolutionId,
            pending.Card,
            pending.PlayerSeat,
            pending.TargetSeats,
            pending.ActionKind,
            pending.TargetCardId,
            pending.RequiredCardKind,
            pending.EffectiveCardKind);
    }

    private void BeginNullificationWindow(
        long resolutionId,
        Card effectCard,
        int sourceSeat,
        IReadOnlyList<int> targetSeats,
        LegalActionKind actionKind,
        int? targetCardId = null,
        CardKind? requiredCardKind = null,
        CardKind? playedCardKind = null)
    {
        if (IsYingboUnrespondable(resolutionId))
        {
            SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
            ResolveNullifiableEffect(new NullificationResolution(
                resolutionId,
                0,
                effectCard,
                sourceSeat,
                targetSeats,
                actionKind,
                targetCardId,
                requiredCardKind,
                playedCardKind ?? effectCard.Kind));
            return;
        }

        if (_pendingNullification is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Nullification windows at once.");
        }

        var candidates = BuildNullificationCandidateSeats(sourceSeat);
        var pending = new NullificationResolution(
            resolutionId,
            ++_resolutionSequence,
            effectCard,
            sourceSeat,
            targetSeats,
            actionKind,
            targetCardId,
            requiredCardKind,
            playedCardKind ?? effectCard.Kind)
        {
            CandidateSeats = candidates
        };
        _pendingNullification = pending;
        SetCardUseStep(resolutionId, ResolutionFrameStep.AwaitingResponse);
        _resolutionStack.Add(new NullificationWindowFrame(
            pending.FrameId,
            resolutionId,
            sourceSeat,
            Array.AsReadOnly(targetSeats.ToArray()),
            effectCard.Id,
            pending.EffectiveCardKind,
            actionKind,
            targetCardId,
            requiredCardKind,
            candidates));
        ContinueNullificationWindow(pending);
    }

    private IReadOnlyList<int> BuildNullificationCandidateSeats(int startAfterSeat)
    {
        return Enumerable.Range(1, _playerCount)
            .Select(offset => _players[(startAfterSeat + offset) % _playerCount])
            .Where(player => player.IsAlive)
            .Select(player => player.Seat)
            .ToArray();
    }

    private void ContinueNullificationWindow(NullificationResolution pending)
    {
        if (!ReferenceEquals(_pendingNullification, pending) ||
            _resolutionStack.LastOrDefault() is not NullificationWindowFrame frame ||
            frame.Id != pending.FrameId)
        {
            throw new InvalidOperationException("The Nullification window is not the current resolution frame.");
        }

        while (pending.CandidateIndex < pending.CandidateSeats.Count)
        {
            var responder = _players[pending.CandidateSeats[pending.CandidateIndex]];
            var cards = GetNullificationCards(responder);
            if (cards.Count == 0)
            {
                pending.CandidateIndex++;
                UpdateNullificationWindowFrame(pending, ResolutionFrameStep.AwaitingResponse);
                continue;
            }

            var effectName = CardCatalog.Get(pending.EffectiveCardKind).DisplayName;
            _pendingDecision = new PendingDecision(
                DecisionKind.Nullification,
                responder.Seat,
                pending.EffectNullified
                    ? $"上一张【无懈可击】使【{effectName}】暂时失效，是否继续使用【无懈可击】？"
                    : $"{_players[pending.SourceSeat].Name} 使用了【{effectName}】，是否使用【无懈可击】？",
                cards.Select(card => card.Id).ToArray(),
                [],
                pending.SourceSeat,
                pending.EffectiveCardKind)
            {
                PromptId = CreatePromptId(),
                Choices = CreateNullificationChoices(pending, cards),
                TargetSeat = pending.TargetSeat,
                RequiredCardKind = CardKind.Nullification
            };
            QueueGameEvent(new NullificationRequestedEvent(
                pending.ResolutionId,
                pending.EffectCard.Id,
                pending.EffectiveCardKind,
                pending.SourceSeat,
                responder.Seat,
                pending.EffectNullified,
                pending.ChainDepth));
            AddLog(
                "NullificationRequested",
                pending.EffectNullified
                    ? $"{responder.Name} 可以继续使用【无懈可击】恢复【{effectName}】效果。"
                    : $"{responder.Name} 可以使用【无懈可击】响应【{effectName}】。",
                pending.SourceSeat,
                responder.Seat);
            UpdateNullificationWindowFrame(pending, ResolutionFrameStep.AwaitingResponse);
            _status = responder.IsHuman
                ? EngineStatus.AwaitingHumanResponse
                : EngineStatus.Running;
            return;
        }

        FinishNullificationWindow(pending);
    }

    private static IReadOnlyList<PromptChoice> CreateNullificationChoices(
        NullificationResolution pending,
        IReadOnlyList<Card> cards)
    {
        var effectName = CardCatalog.Get(pending.EffectiveCardKind).DisplayName;
        var choices = cards
            .Select(card => new PromptChoice(
                new ChoiceId($"nullification.card-{card.Id}.depth-{pending.ChainDepth}"),
                pending.EffectNullified
                    ? $"使用【无懈可击】恢复【{effectName}】效果。"
                    : $"使用【无懈可击】使【{effectName}】失效。",
                [card.Id],
                [],
                new Dictionary<string, string>
                {
                    ["response"] = "nullification",
                    ["effect-card-id"] = pending.EffectCard.Id.ToString(
                        System.Globalization.CultureInfo.InvariantCulture),
                    ["chain-depth"] = pending.ChainDepth.ToString(
                        System.Globalization.CultureInfo.InvariantCulture)
                }))
            .ToList();
        choices.Add(new PromptChoice(
            new ChoiceId($"nullification.pass.depth-{pending.ChainDepth}"),
            "不使用【无懈可击】。",
            [],
            [],
            new Dictionary<string, string>
            {
                ["response"] = "pass"
            }));
        return choices;
    }

    private IReadOnlyList<Card> GetNullificationCards(CharacterState responder) =>
        GetPlayableCards(responder).Where(card =>
            !IsCardUseForbidden(responder.Seat, CardKind.Nullification, CardActionType.Use) &&
            !IsTurnHandCardRestricted(responder, card) &&
            !HasProgramCardIdentity(responder, card) &&
            (card.Kind == CardKind.Nullification ||
            UsesFormalWolong && HasRuntimeSkill(responder, SkillKind.Kanpo) &&
            GetHand(responder).Any(handCard => handCard.Id == card.Id) &&
            !IsRedSuit(card.Suit))).ToArray();

    private void ResolveNullificationChoice(
        NullificationResolution pending,
        CharacterState responder,
        Card? selectedCard)
    {
        if (!ReferenceEquals(_pendingNullification, pending) ||
            pending.CandidateIndex >= pending.CandidateSeats.Count ||
            pending.CandidateSeats[pending.CandidateIndex] != responder.Seat)
        {
            throw new InvalidOperationException("The Nullification response is not for the current responder.");
        }

        if (selectedCard is null)
        {
            pending.CandidateIndex++;
            UpdateNullificationWindowFrame(pending, ResolutionFrameStep.AwaitingResponse);
            ContinueNullificationWindow(pending);
            return;
        }

        var card = GetNullificationCards(responder).SingleOrDefault(candidate =>
            candidate.Id == selectedCard.Id);
        if (card is null)
        {
            throw new InvalidOperationException("The selected Nullification card is not in the responder's hand.");
        }

        MoveCard(
            card,
            FindOwnedCardLocation(responder, card),
            CardLocation.Processing,
            CardMoveReasons.Nullification);
        MoveCard(
            card,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.NullificationFinished);
        pending.EffectNullified = !pending.EffectNullified;
        pending.ChainDepth++;
        pending.CandidateSeats = BuildNullificationCandidateSeats(responder.Seat);
        pending.CandidateIndex = 0;
        UpdateNullificationWindowFrame(pending, ResolutionFrameStep.AwaitingResponse);
        QueueGameEvent(new CardRespondedEvent(
            card.Id,
            responder.Seat,
            pending.SourceSeat,
            CardKind.Nullification));
        QueueGameEvent(new NullificationRespondedEvent(
            pending.ResolutionId,
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            responder.Seat,
            card.Id,
            pending.EffectNullified,
            pending.ChainDepth));
        AddLog(
            "NullificationResponded",
            pending.EffectNullified
                ? $"{responder.Name} 使用【无懈可击】，使【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】失效。"
                : $"{responder.Name} 使用【无懈可击】，使【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】恢复。",
            responder.Seat,
            pending.SourceSeat);
        var jizhi = new JizhiResolution(
            responder.Seat,
            pending.ResolutionId,
            card,
            CardKind.Nullification,
            pending.TargetSeats,
            pending.ActionKind,
            pending.TargetCardId,
            pending.RequiredCardKind,
            pending);
        if (TryBeginJizhiChoice(jizhi))
        {
            return;
        }

        ContinueNullificationWindow(pending);
    }

    private void FinishNullificationWindow(NullificationResolution pending)
    {
        if (!ReferenceEquals(_pendingNullification, pending) ||
            _resolutionStack.LastOrDefault() is not NullificationWindowFrame frame ||
            frame.Id != pending.FrameId)
        {
            throw new InvalidOperationException("The Nullification window cannot finish from its current frame.");
        }

        UpdateNullificationWindowFrame(pending, ResolutionFrameStep.Completed);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.NullificationWindow);
        QueueGameEvent(new NullificationResolvedEvent(
            pending.ResolutionId,
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            pending.EffectNullified,
            pending.ChainDepth));
        _pendingNullification = null;
        ClearPendingDecision();
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        if (pending.EffectNullified)
        {
            foreach (var physicalCard in GetCardUsePhysicalCards(pending.ResolutionId))
            {
                MoveCard(
                    physicalCard,
                    CardLocation.Processing,
                    CardLocation.DiscardPile,
                    CardMoveReasons.UseFinished);
            }
            AddLog(
                "CardEffect",
                $"【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】的效果被无懈。",
                pending.SourceSeat);
            FinishCardUse(pending.ResolutionId, pending.EffectCard, pending.EffectiveCardKind);
            return;
        }

        ResolveNullifiableEffect(pending);
    }

    private void ResolveNullifiableEffect(NullificationResolution pending)
    {
        if (pending.TargetSeats.Count == 1 &&
            IsCardEffectIneffective(pending.ResolutionId, pending.TargetSeats[0]))
        {
            CompleteIneffectiveTrickTarget(pending, pending.TargetSeats[0]);
            return;
        }

        switch (pending.ActionKind)
        {
            case LegalActionKind.DrawTwo:
                ResolveDrawTwoEffect(pending);
                break;
            case LegalActionKind.BarbarianAssault:
            case LegalActionKind.ArrowBarrage:
                ResolveGroupCardEffect(pending);
                break;
            case LegalActionKind.PeachGarden:
                ResolvePeachGardenEffect(pending);
                break;
            case LegalActionKind.FiveGrains:
                ResolveFiveGrainsEffect(pending);
                break;
            case LegalActionKind.Dismantlement:
            case LegalActionKind.Snatch:
                ResolveTargetCardEffect(pending);
                break;
            case LegalActionKind.FireAttack:
                ResolveFireAttackEffect(pending);
                break;
            case LegalActionKind.BorrowedSword:
                ResolveBorrowedSwordEffect(pending);
                break;
            case LegalActionKind.Duel:
                ResolveDuelEffect(pending);
                break;
            case LegalActionKind.IronChain:
                ResolveIronChainEffect(pending);
                break;
            case LegalActionKind.Indulgence:
            case LegalActionKind.SupplyShortage:
            case LegalActionKind.Lightning:
                ResolveDelayedCardEffect(pending);
                break;
            default:
                throw new InvalidOperationException(
                    $"Card kind {pending.EffectiveCardKind} cannot continue after Nullification.");
        }
    }

    private void ResolveDrawTwoEffect(NullificationResolution pending)
    {
        var source = _players[pending.SourceSeat];
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        DrawCards(source, 2, log: true);
        MoveCard(
            pending.EffectCard,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.UseFinished);
        FinishCardUse(pending.ResolutionId, pending.EffectCard);
        AddLog("CardEffect", $"{source.Name} 使用【无中生有】，摸两张牌。", source.Seat);
    }

    private void ResolveGroupCardEffect(NullificationResolution pending)
    {
        var source = _players[pending.SourceSeat];
        var requiredCardKind = pending.RequiredCardKind ??
            throw new InvalidOperationException("A group card must retain its response card kind.");
        var physicalCards = GetCardUsePhysicalCards(pending.ResolutionId);
        var effectiveCard = pending.EffectiveCardKind == pending.EffectCard.Kind
            ? pending.EffectCard
            : pending.EffectCard with { Kind = pending.EffectiveCardKind };
        var group = new GroupCardResolution(
            pending.ResolutionId,
            source.Seat,
            effectiveCard,
            pending.TargetSeats,
            GroupCardEffect.ResponseAttack,
            requiredCardKind,
            physicalCards);
        if (UsesFormalMengHuo && effectiveCard.Kind == CardKind.BarbarianAssault)
        {
            var mengHuo = _players.FirstOrDefault(player =>
                player.IsAlive && HasRuntimeSkill(player, SkillKind.Huoshou));
            if (mengHuo is not null)
            {
                group.DamageSourceSeat = mengHuo.Seat;
                QueueGameEvent(new HuoshouAttributedEvent(group.ResolutionId, source.Seat, mengHuo.Seat));
            }
        }
        _pendingGroupCard = group;
        AddLog(
            "CardUsed",
            $"{source.Name} 使用【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】，依次攻击 {pending.TargetSeats.Count} 名角色。",
            source.Seat);
        QueueGameEvent(new GroupCardUsedEvent(
            pending.ResolutionId,
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            source.Seat,
            pending.TargetSeats));
        NotifyAiOfGroupAttack(source, pending.TargetSeats);
        BeginGroupAttackResponse(group);
    }

    private void ResolvePeachGardenEffect(NullificationResolution pending)
    {
        var source = _players[pending.SourceSeat];
        var effectiveCard = pending.EffectiveCardKind == pending.EffectCard.Kind
            ? pending.EffectCard
            : pending.EffectCard with { Kind = pending.EffectiveCardKind };
        var group = new GroupCardResolution(
            pending.ResolutionId,
            source.Seat,
            effectiveCard,
            pending.TargetSeats,
            GroupCardEffect.Recovery,
            requiredCardKind: null,
            GetCardUsePhysicalCards(pending.ResolutionId));
        _pendingGroupCard = group;
        AddLog(
            "CardUsed",
            $"{source.Name} 使用【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】，使 {pending.TargetSeats.Count} 名存活角色依次回复体力。",
            source.Seat);
        QueueGameEvent(new GroupCardUsedEvent(
            pending.ResolutionId,
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            source.Seat,
            pending.TargetSeats));
    }

    private void ResolveFiveGrainsEffect(NullificationResolution pending)
    {
        var source = _players[pending.SourceSeat];
        var effectiveCard = pending.EffectiveCardKind == pending.EffectCard.Kind
            ? pending.EffectCard
            : pending.EffectCard with { Kind = pending.EffectiveCardKind };
        var group = new GroupCardResolution(
            pending.ResolutionId,
            source.Seat,
            effectiveCard,
            pending.TargetSeats,
            GroupCardEffect.PublicDraft,
            requiredCardKind: null,
            GetCardUsePhysicalCards(pending.ResolutionId));
        _pendingGroupCard = group;
        foreach (var _ in pending.TargetSeats)
        {
            var revealed = DrawOneToProcessing(CardMoveReasons.Reveal) ??
                throw new InvalidOperationException("FiveGrains could not reveal the promised card count.");
            group.RevealedCardIds.Add(revealed.Id);
        }

        AddLog(
            "CardUsed",
            $"{source.Name} 使用【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】，公开展示 {group.RevealedCardIds.Count} 张牌并依次选取。",
            source.Seat);
        QueueGameEvent(new GroupCardUsedEvent(
            pending.ResolutionId,
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            source.Seat,
            pending.TargetSeats));
        QueueGameEvent(new CardsRevealedEvent(
            pending.ResolutionId,
            group.RevealedCardIds
                .Select(cardId => _cardZones.CardsAt(CardLocation.Processing).Single(card => card.Id == cardId))
                .Select(ToSnapshot)
                .ToArray()));
        if (group.TargetSeats.Count == 0)
        {
            FinishFiveGrains(group);
        }
        else
        {
            BeginHarvestSelection(group);
        }
    }

    private void ResolveTargetCardEffect(NullificationResolution pending)
    {
        var targetSeat = pending.TargetSeat ??
            throw new InvalidOperationException("A target-card effect must retain one target.");
        var target = _players[targetSeat];
        Card targetCard;
        CardLocation targetCardFromZone;
        if (pending.TargetCardId is { } requestedTargetCardId)
        {
            var publicTarget = FindPublicTargetCard(target, requestedTargetCardId);
            if (publicTarget is null)
            {
                SkipUnavailableTargetCardEffect(pending, target, CardEffectSkipReason.PublicTargetMissing);
                return;
            }
            targetCard = publicTarget.Value.Card;
            targetCardFromZone = publicTarget.Value.Location;
        }
        else
        {
            var targetHand = GetHand(target);
            if (targetHand.Count == 0)
            {
                SkipUnavailableTargetCardEffect(pending, target, CardEffectSkipReason.TargetHandEmpty);
                return;
            }

            BeginTargetCardSelection(pending, target, targetHand.Count);
            return;
        }

        ApplyTargetCardEffect(
            pending.ResolutionId,
            pending.EffectCard,
            pending.EffectiveCardKind,
            pending.SourceSeat,
            target.Seat,
            pending.ActionKind,
            targetCard,
            targetCardFromZone);
    }

    private void BeginTargetCardSelection(
        NullificationResolution pending,
        CharacterState target,
        int candidateCount)
    {
        if (_pendingTargetCardSelection is not null)
        {
            throw new InvalidOperationException("The engine cannot open two hidden target-card selections at once.");
        }

        var source = _players[pending.SourceSeat];
        var candidateSlots = Enumerable.Range(0, candidateCount).ToArray();
        var selection = new TargetCardSelectionResolution(
            pending.ResolutionId,
            ++_resolutionSequence,
            pending.EffectCard,
            pending.EffectiveCardKind,
            source.Seat,
            target.Seat,
            pending.ActionKind,
            candidateCount);
        _pendingTargetCardSelection = selection;
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        _resolutionStack.Add(new TargetCardSelectionFrame(
            selection.FrameId,
            pending.ResolutionId,
            source.Seat,
            target.Seat,
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            pending.ActionKind,
            Array.AsReadOnly(candidateSlots)));
        _pendingDecision = new PendingDecision(
            DecisionKind.SelectTargetCard,
            source.Seat,
            $"{source.Name} 使用【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】，请选择 {target.Name} 的一张暗牌。",
            [],
            [target.Seat],
            source.Seat,
            pending.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices = Array.AsReadOnly(candidateSlots
                .Select(slot => new PromptChoice(
                    new ChoiceId($"target-card.slot-{slot}.resolution-{pending.ResolutionId}"),
                    $"选择 {target.Name} 的一张暗牌（牌位 {slot + 1}）",
                    [],
                    [target.Seat],
                    new Dictionary<string, string>
                    {
                        ["action"] = "target-card-slot",
                        ["slot-index"] = slot.ToString(
                            System.Globalization.CultureInfo.InvariantCulture)
                    }))
                .ToArray()),
            IsPrivate = true,
            TargetSeat = target.Seat
        };
        QueueGameEvent(new TargetCardSelectionRequestedEvent(
            pending.ResolutionId,
            source.Seat,
            target.Seat,
            pending.ActionKind,
            candidateCount));
        AddLog(
            "TargetCardSelectionRequested",
            $"{source.Name} 对 {target.Name} 的手牌进行不透明牌位选择。",
            source.Seat,
            target.Seat);
        _status = source.IsHuman
            ? EngineStatus.AwaitingHumanCardSelection
            : EngineStatus.Running;
    }

    private void ResolveTargetCardSelection(
        TargetCardSelectionResolution pending,
        int slot)
    {
        if (!ReferenceEquals(_pendingTargetCardSelection, pending) ||
            _resolutionStack.LastOrDefault() is not TargetCardSelectionFrame frame ||
            frame.Id != pending.FrameId)
        {
            throw new InvalidOperationException("The hidden target-card selection is not the current resolution frame.");
        }

        var target = _players[pending.TargetSeat];
        var targetHand = GetHand(target);
        if (targetHand.Count != pending.CandidateCount ||
            slot < 0 ||
            slot >= pending.CandidateCount)
        {
            throw new InvalidOperationException(
                "The target hand changed while the hidden target-card selection was pending.");
        }

        var targetCard = targetHand[slot];
        UpdateTargetCardSelectionFrame(pending, ResolutionFrameStep.Completed);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.TargetCardSelection);
        _pendingTargetCardSelection = null;
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ApplyTargetCardEffect(
            pending.ResolutionId,
            pending.EffectCard,
            pending.EffectiveCardKind,
            pending.SourceSeat,
            pending.TargetSeat,
            pending.ActionKind,
            targetCard,
            CardLocation.Hand(target.Seat));
    }

    private void ApplyTargetCardEffect(
        long resolutionId,
        Card effectCard,
        CardKind effectiveCardKind,
        int sourceSeat,
        int targetSeat,
        LegalActionKind actionKind,
        Card targetCard,
        CardLocation targetCardFromZone)
    {
        var source = _players[sourceSeat];
        var target = _players[targetSeat];
        var targetMoveReason = GetTargetCardMoveReason(actionKind, targetCardFromZone.Zone);
        var publicTargetKind = targetCardFromZone.Zone == CardZoneKind.Judgment
            ? GetJudgmentEffectiveCardKind(targetCard)
            : targetCard.Kind;
        MoveCard(
            targetCard,
            targetCardFromZone,
            CardLocation.Processing,
            targetMoveReason);

        if (actionKind == LegalActionKind.Dismantlement)
        {
            QueueGameEvent(new TargetCardDiscardedEvent(
                resolutionId,
                source.Seat,
                target.Seat,
                targetCardFromZone.Zone,
                IsPublicTargetZone(targetCardFromZone.Zone) ? targetCard.Id : null,
                IsPublicTargetZone(targetCardFromZone.Zone) ? publicTargetKind : null));
            MoveCard(
                targetCard,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                GetTargetCardFinishedMoveReason(actionKind, targetCardFromZone.Zone));
        }
        else
        {
            QueueGameEvent(new TargetCardTakenEvent(
                resolutionId,
                source.Seat,
                target.Seat,
                targetCardFromZone.Zone,
                IsPublicTargetZone(targetCardFromZone.Zone) ? targetCard.Id : null,
                IsPublicTargetZone(targetCardFromZone.Zone) ? publicTargetKind : null));
            MoveCard(
                targetCard,
                CardLocation.Processing,
                CardLocation.Hand(source.Seat),
                GetTargetCardFinishedMoveReason(actionKind, targetCardFromZone.Zone));
        }

        MoveCard(
            effectCard,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.UseFinished);
        FinishCardUse(resolutionId, effectCard, effectiveCardKind);

        var displayName = CardCatalog.Get(effectiveCardKind).DisplayName;
        var targetDescription = targetCardFromZone.Zone switch
        {
            CardZoneKind.Equipment => $"装备【{targetCard.DisplayName}】",
            CardZoneKind.Judgment => $"判定区【{CardCatalog.Get(publicTargetKind).DisplayName}】",
            _ => "一张手牌"
        };
        var outcome = actionKind == LegalActionKind.Dismantlement
            ? $"弃置 {target.Name} 的{targetDescription}"
            : $"获得 {target.Name} 的{targetDescription}";
        AddLog(
            "CardEffect",
            IsPublicTargetZone(targetCardFromZone.Zone)
                ? $"{source.Name} 使用【{displayName}】，{outcome}。"
                : $"{source.Name} 使用【{displayName}】，{outcome}（牌面不公开）。",
            source.Seat,
            target.Seat);
    }

    private void ResolveFireAttackEffect(NullificationResolution pending)
    {
        var source = _players[pending.SourceSeat];
        var targetSeat = pending.TargetSeat ??
            throw new InvalidOperationException("FireAttack must retain one target.");
        if (GetHand(_players[targetSeat]).Count == 0)
        {
            SkipUnavailableTargetCardEffect(pending, _players[targetSeat], CardEffectSkipReason.TargetHandEmpty);
            return;
        }
        var pendingFireAttack = new FireAttackResolution(
            pending.ResolutionId,
            source.Seat,
            targetSeat,
            pending.EffectCard,
            pending.EffectiveCardKind);
        _pendingFireAttack = pendingFireAttack;
        AddLog(
            "CardUsed",
            $"{source.Name} 对 {_players[targetSeat].Name} 使用【火攻】，等待目标展示一张手牌。",
            source.Seat,
            targetSeat);
        QueueGameEvent(new CardUsedEvent(
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            source.Seat,
            targetSeat));
        NotifyAiOfFireAttack(source, _players[targetSeat]);
        BeginFireAttackReveal(pendingFireAttack);
    }

    private void ResolveBorrowedSwordEffect(NullificationResolution pending)
    {
        if (pending.TargetSeats.Count != 2)
        {
            throw new InvalidOperationException("Borrowed Sword must retain its ordered two targets.");
        }

        var ineffectiveTarget = pending.TargetSeats.FirstOrDefault(
            targetSeat => IsCardEffectIneffective(pending.ResolutionId, targetSeat),
            -1);
        if (ineffectiveTarget >= 0)
        {
            CompleteIneffectiveTrickTarget(pending, ineffectiveTarget);
            return;
        }

        var resolution = new BorrowedSwordResolution(
            pending.ResolutionId,
            pending.SourceSeat,
            pending.TargetSeats[0],
            pending.TargetSeats[1],
            pending.EffectCard);
        _pendingBorrowedSword = resolution;
        AddLog(
            "CardUsed",
            $"{_players[resolution.SourceSeat].Name} 对 {_players[resolution.WeaponOwnerSeat].Name} 使用【借刀杀人】，指定其攻击 {_players[resolution.SlashTargetSeat].Name}。",
            resolution.SourceSeat,
            resolution.WeaponOwnerSeat);
        BeginBorrowedSwordSlashChoice(resolution, includeJijiang: true);
    }

    private void SkipUnavailableTargetCardEffect(NullificationResolution pending, CharacterState target, CardEffectSkipReason reason)
    {
        QueueGameEvent(new CardEffectSkippedEvent(pending.ResolutionId, pending.SourceSeat, target.Seat, pending.EffectiveCardKind, reason));
        MoveCard(pending.EffectCard, CardLocation.Processing, CardLocation.DiscardPile, CardMoveReasons.UseFinished);
        FinishCardUse(pending.ResolutionId, pending.EffectCard, pending.EffectiveCardKind);
        var explanation = reason == CardEffectSkipReason.TargetHandEmpty ? "已没有手牌" : "所选的公开牌已不在原处";
        AddLog("CardEffect", $"【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】结算时，{target.Name}{explanation}，本次效果跳过。", pending.SourceSeat, target.Seat);
    }

    private void ResolveDuelEffect(NullificationResolution pending)
    {
        var source = _players[pending.SourceSeat];
        var targetSeat = pending.TargetSeat ??
            throw new InvalidOperationException("Duel must retain one target.");
        var target = _players[targetSeat];
        var attack = new AttackResolution(
            pending.ResolutionId,
            source.Seat,
            target.Seat,
            pending.EffectCard,
            playedCardKind: pending.EffectiveCardKind,
            physicalCards: GetCardUsePhysicalCards(pending.ResolutionId));
        _pendingAttack = attack;
        var duel = new DuelResolution(attack);
        _pendingDuel = duel;
        AddLog("CardUsed", $"{source.Name} 对 {target.Name} 使用【决斗】。", source.Seat, target.Seat);
        QueueGameEvent(new CardUsedEvent(
            pending.EffectCard.Id,
            pending.EffectiveCardKind,
            source.Seat,
            target.Seat));
        NotifyAiOfDuel(source, target);
        BeginDuelResponse(duel);
    }

    private void ResolveIronChainEffect(NullificationResolution pending)
    {
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        var changes = new List<string>(pending.TargetSeats.Count);
        foreach (var targetSeat in pending.TargetSeats)
        {
            var target = _players[targetSeat];
            if (!target.IsAlive || IsCardEffectIneffective(pending.ResolutionId, targetSeat))
            {
                continue;
            }

            target.IsChained = !target.IsChained;
            changes.Add($"{target.Name}{(target.IsChained ? "横置" : "重置")}");
            QueueGameEvent(new IronChainStateChangedEvent(
                pending.ResolutionId,
                pending.SourceSeat,
                target.Seat,
                target.IsChained));
        }

        QueueGameEvent(new IronChainResolvedEvent(
            pending.ResolutionId,
            pending.SourceSeat,
            pending.TargetSeats));
        var source = _players[pending.SourceSeat];
        AddLog(
            "CardEffect",
            changes.Count == 0
                ? $"{source.Name} 使用【铁索连环】，但目标已无存活角色。"
                : $"{source.Name} 使用【铁索连环】，" + string.Join("、", changes) + "。",
            source.Seat);
        MoveCard(
            pending.EffectCard,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.IronChainFinished);
        FinishCardUse(pending.ResolutionId, pending.EffectCard);
    }

    private void ResolveDrawTwo(CharacterState source, Card drawTwo)
    {
        var stillLegal = BuildLegalActions(source).Any(action =>
            action.Kind == LegalActionKind.DrawTwo &&
            action.CardId == drawTwo.Id &&
            action.TargetSeat is null);
        if (!stillLegal)
        {
            throw new InvalidOperationException("DrawTwo became illegal before resolution.");
        }

        var resolutionId = BeginCardUse(drawTwo, source.Seat, []);
        MoveCard(
            drawTwo,
            FindOwnedCardLocation(source, drawTwo),
            CardLocation.Processing,
            CardMoveReasons.Use);
        BeginJizhiOrNullificationWindow(
            resolutionId,
            drawTwo,
            source.Seat,
            [],
            LegalActionKind.DrawTwo);
    }

    private void ResolveAlcohol(CharacterState source, Card alcohol)
    {
        var stillLegal = BuildLegalActions(source).Any(action =>
            action.Kind == LegalActionKind.Alcohol &&
            action.CardId == alcohol.Id &&
            action.TargetSeat is null);
        if (!stillLegal)
        {
            throw new InvalidOperationException("Alcohol became illegal before resolution.");
        }

        var resolutionId = BeginCardUse(alcohol, source.Seat, []);
        MoveCard(
            alcohol,
            FindOwnedCardLocation(source, alcohol),
            CardLocation.Processing,
            CardMoveReasons.Use);
        SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
        source.HasAlcoholEffect = true;
        source.UsedPlayPhaseAlcoholThisTurn = true;
