            borrowedSword,
            source.Seat,
            targets,
            LegalActionKind.BorrowedSword);
    }

    private void BeginFireAttackReveal(FireAttackResolution pending)
    {
        if (!ReferenceEquals(_pendingFireAttack, pending) || pending.RevealedCardId is not null)
        {
            throw new InvalidOperationException("The FireAttack reveal is not the current resolution.");
        }

        var target = _players[pending.TargetSeat];
        var hand = GetHand(target);
        if (hand.Count == 0)
        {
            throw new InvalidOperationException("FireAttack cannot request a reveal from an empty hand.");
        }

        _pendingDecision = new PendingDecision(
            DecisionKind.FireAttackReveal,
            target.Seat,
            $"{_players[pending.SourceSeat].Name} 对你使用了【火攻】，请选择一张手牌展示。",
            hand.Select(card => card.Id).ToArray(),
            [],
            pending.SourceSeat,
            pending.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices = hand
                .Select(card => new PromptChoice(
                    new ChoiceId($"fire-attack.reveal.card-{card.Id}"),
                    $"展示【{card.DisplayName}】（{card.RankText}）",
                    [card.Id],
                    [],
                    new Dictionary<string, string>
                    {
                        ["response"] = "fire-attack-reveal",
                        ["action"] = "reveal-card"
                    }))
                .ToArray(),
            TargetSeat = target.Seat
        };
        _status = target.IsHuman
            ? EngineStatus.AwaitingHumanCardSelection
            : EngineStatus.Running;
    }

    private void ResolveFireAttackReveal(
        FireAttackResolution pending,
        int cardId)
    {
        if (!ReferenceEquals(_pendingFireAttack, pending) || pending.RevealedCardId is not null)
        {
            throw new InvalidOperationException("The FireAttack reveal is not the current resolution.");
        }

        var target = _players[pending.TargetSeat];
        var revealed = GetHand(target).SingleOrDefault(card => card.Id == cardId) ??
            throw new InvalidOperationException("The selected FireAttack reveal card is not in the target hand.");
        pending.RevealedCardId = revealed.Id;
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        QueueGameEvent(new FireAttackCardRevealedEvent(
            pending.ResolutionId,
            pending.SourceSeat,
            pending.TargetSeat,
            revealed.Id,
            revealed.Kind,
            revealed.Suit));
        AddLog(
            "CardRevealed",
            $"{target.Name} 展示了【{revealed.DisplayName}】（{revealed.Suit}），等待攻击者弃置同花色手牌。",
            target.Seat,
            pending.SourceSeat);
        BeginFireAttackDiscard(pending, revealed);
    }

    private void BeginFireAttackDiscard(
        FireAttackResolution pending,
        Card revealed)
    {
        if (!ReferenceEquals(_pendingFireAttack, pending) || pending.RevealedCardId != revealed.Id)
        {
            throw new InvalidOperationException("The FireAttack discard is not the current resolution.");
        }

        var source = _players[pending.SourceSeat];
        var matchingCards = GetHand(source)
            .Where(card => card.Suit == revealed.Suit)
            .ToArray();
        if (matchingCards.Length == 0)
        {
            ResolveFireAttackDiscard(pending, selectedCardId: null);
            return;
        }

        _pendingDecision = new PendingDecision(
            DecisionKind.FireAttackDiscard,
            source.Seat,
            $"目标展示了【{revealed.DisplayName}】（{revealed.Suit}），请选择一张同花色手牌弃置，或放弃造成火焰伤害。",
            matchingCards.Select(card => card.Id).ToArray(),
            [],
            source.Seat,
            pending.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices = matchingCards
                .Select(card => new PromptChoice(
                    new ChoiceId($"fire-attack.discard.card-{card.Id}"),
                    $"弃置【{card.DisplayName}】（{card.RankText}），造成 1 点火焰伤害。",
                    [card.Id],
                    [],
                    new Dictionary<string, string>
                    {
                        ["response"] = "fire-attack-discard",
                        ["action"] = "discard-same-suit"
                    }))
                .Append(new PromptChoice(
                    new ChoiceId("fire-attack.skip"),
                    "不弃置同花色牌，火攻不造成伤害。",
                    [],
                    [],
                    new Dictionary<string, string>
                    {
                        ["response"] = "fire-attack-skip",
                        ["action"] = "skip-fire-attack"
                    }))
                .ToArray(),
            TargetSeat = pending.TargetSeat
        };
        _status = source.IsHuman
            ? EngineStatus.AwaitingHumanCardSelection
            : EngineStatus.Running;
    }

    private void ResolveFireAttackDiscard(
        FireAttackResolution pending,
        int? selectedCardId)
    {
        if (!ReferenceEquals(_pendingFireAttack, pending) || pending.RevealedCardId is null)
        {
            throw new InvalidOperationException("The FireAttack discard is not the current resolution.");
        }

        var source = _players[pending.SourceSeat];
        var target = _players[pending.TargetSeat];
        var revealed = GetFireAttackRevealedCard(pending);
        var matchingDiscard = selectedCardId is { } cardId
            ? GetHand(source).SingleOrDefault(card => card.Id == cardId)
            : null;
        if (selectedCardId is not null &&
            (matchingDiscard is null || matchingDiscard.Suit != revealed.Suit))
        {
            throw new InvalidOperationException("FireAttack requires a same-suit source discard card.");
        }

        if (matchingDiscard is null)
        {
            QueueGameEvent(new FireAttackResolvedEvent(
                pending.ResolutionId,
                source.Seat,
                target.Seat,
                revealed.Id,
                revealed.Suit,
                MatchingDiscardCardId: null,
                CausedDamage: false));
            AddLog(
                "CardEffect",
                $"{source.Name} 未弃置同花色牌，{target.Name} 的【火攻】未造成伤害。",
                source.Seat,
                target.Seat);
            MoveCard(
                pending.Card,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.UseFinished);
            FinishCardUse(pending.ResolutionId, pending.Card, pending.EffectiveCardKind);
            _pendingFireAttack = null;
            return;
        }

        MoveCard(
            matchingDiscard,
            CardLocation.Hand(source.Seat),
            CardLocation.Processing,
            CardMoveReasons.FireAttackDiscard);
        MoveCard(
            matchingDiscard,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.FireAttackDiscardFinished);
        QueueGameEvent(new FireAttackResolvedEvent(
            pending.ResolutionId,
            source.Seat,
            target.Seat,
            revealed.Id,
            revealed.Suit,
            matchingDiscard.Id,
            CausedDamage: true));
        AddLog(
            "CardEffect",
            $"{source.Name} 弃置【{matchingDiscard.DisplayName}】，{target.Name} 受到 1 点火焰伤害。",
            source.Seat,
            target.Seat);

        _pendingFireAttack = null;
        var attack = new AttackResolution(
            pending.ResolutionId,
            source.Seat,
            target.Seat,
            pending.Card,
            damageAmount: 1,
            playedCardKind: CardKind.FireAttack,
            physicalCards: GetCardUsePhysicalCards(pending.ResolutionId));
        _pendingAttack = attack;
        if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private Card GetFireAttackRevealedCard(FireAttackResolution pending)
    {
        var revealedCardId = pending.RevealedCardId ??
            throw new InvalidOperationException("FireAttack has no revealed card.");
        var location = (CardLocation.Hand(pending.TargetSeat)
);
        return _cardZones.CardsAt(location).Single(card => card.Id == revealedCardId);
    }

    private void BeginHarvestSelection(GroupCardResolution group)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) || group.Effect != GroupCardEffect.PublicDraft)
        {
            throw new InvalidOperationException("The FiveGrains draft is not the current card resolution.");
        }

        while (group.TargetIndex < group.TargetSeats.Count &&
               (!_players[group.TargetSeats[group.TargetIndex]].IsAlive ||
                IsCardEffectIneffective(group.ResolutionId, group.TargetSeats[group.TargetIndex])))
        {
            group.TargetIndex++;
            SetCardUseTargetIndex(group.ResolutionId, group.TargetIndex);
        }

        if (group.TargetIndex >= group.TargetSeats.Count)
        {
            FinishFiveGrains(group);
            return;
        }

        var picker = _players[group.TargetSeats[group.TargetIndex]];
        var processing = _cardZones.CardsAt(CardLocation.Processing);
        var revealed = group.RevealedCardIds
            .Select(cardId => processing.Single(card => card.Id == cardId))
            .ToArray();
        if (revealed.Length == 0)
        {
            throw new InvalidOperationException("A FiveGrains picker cannot choose from an empty reveal.");
        }

        _pendingDecision = new PendingDecision(
            DecisionKind.SelectHarvestCard,
            picker.Seat,
            $"{_players[group.SourceSeat].Name} 使用了【五谷丰登】，请选择一张公开牌。",
            group.RevealedCardIds.ToArray(),
            [],
            group.SourceSeat,
            group.Card.Kind)
        {
            PromptId = CreatePromptId(),
            Choices = revealed
                .Select(card => new PromptChoice(
                    new ChoiceId($"harvest.card-{card.Id}"),
                    $"选择公开牌【{card.DisplayName}】（{card.RankText}）",
                    [card.Id],
                    [],
                    new Dictionary<string, string>
                    {
                        ["action"] = "harvest-pick"
                    }))
                .ToArray()
        };
        _status = picker.IsHuman
            ? EngineStatus.AwaitingHumanCardSelection
            : EngineStatus.Running;
    }

    private void ResolveHarvestSelection(
        GroupCardResolution group,
        CharacterState picker,
        int cardId)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) || group.Effect != GroupCardEffect.PublicDraft)
        {
            throw new InvalidOperationException("The FiveGrains draft is not the current card resolution.");
        }

        if (group.TargetIndex >= group.TargetSeats.Count ||
            group.TargetSeats[group.TargetIndex] != picker.Seat)
        {
            throw new InvalidOperationException("The selected FiveGrains picker is not current.");
        }

        if (!group.RevealedCardIds.Contains(cardId))
        {
            throw new InvalidOperationException("The selected card is not in the public FiveGrains reveal.");
        }

        var card = _cardZones.CardsAt(CardLocation.Processing)
            .Single(candidate => candidate.Id == cardId);
        MoveCard(
            card,
            CardLocation.Processing,
            CardLocation.Hand(picker.Seat),
            CardMoveReasons.HarvestPick);
        group.RevealedCardIds.Remove(cardId);
        AddLog(
            "CardSelected",
            $"{picker.Name} 从五谷丰登的公开牌中选择了【{card.DisplayName}】。",
            picker.Seat);
        QueueGameEvent(new HarvestCardSelectedEvent(group.ResolutionId, picker.Seat, cardId));

        group.TargetIndex++;
        SetCardUseTargetIndex(group.ResolutionId, group.TargetIndex);
        if (group.TargetIndex >= group.TargetSeats.Count)
        {
            FinishFiveGrains(group);
        }
        else
        {
            BeginHarvestSelection(group);
        }
    }

    private void FinishFiveGrains(GroupCardResolution group)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) || group.Effect != GroupCardEffect.PublicDraft)
        {
            throw new InvalidOperationException("The FiveGrains draft is not the current card resolution.");
        }

        if (_pendingDying is not null || _pendingAttack is not null ||
            group.TargetIndex < group.TargetSeats.Count)
        {
            throw new InvalidOperationException("FiveGrains cannot finish while a picker or child resolution is pending.");
        }

        foreach (var cardId in group.RevealedCardIds.ToArray())
        {
            var card = _cardZones.CardsAt(CardLocation.Processing)
                .Single(candidate => candidate.Id == cardId);
            MoveCard(
                card,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.HarvestDiscard);
        }
        group.RevealedCardIds.Clear();

        var cardLocation = _cardZones.GetLocation(group.Card.Id);
        if (cardLocation == CardLocation.Processing)
        {
            MoveCard(
                group.Card,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.UseFinished);
        }
        else if (cardLocation != CardLocation.DiscardPile)
        {
            throw new InvalidOperationException(
                $"A resolved {group.Card.Kind} left Processing through an unsupported destination: {cardLocation}.");
        }

        SetCardUseTargetIndex(group.ResolutionId, group.TargetSeats.Count);
        FinishCardUse(group.ResolutionId, group.Card);
        _pendingGroupCard = null;
        _pendingAttack = null;
        _pendingDuel = null;
        _pendingDecision = null;

        if (_winner != Winner.None && _status != EngineStatus.Completed)
        {
            CompleteGame();
        }
    }

    private void RunOneGroupRecoveryStep()
    {
        var group = _pendingGroupCard ??
            throw new InvalidOperationException("A group recovery step has no pending card.");
        if (group.Effect != GroupCardEffect.Recovery)
        {
            throw new InvalidOperationException("The pending group card is not a recovery effect.");
        }

        if (group.TargetIndex >= group.TargetSeats.Count)
        {
            FinishGroupRecovery(group);
            PublishState();
            return;
        }

        var target = _players[group.TargetSeats[group.TargetIndex]];
        if (target.IsAlive &&
            !IsCardEffectIneffective(group.ResolutionId, target.Seat) &&
            target.Hp < target.MaxHp)
        {
            var recoveryFrameId = BeginRecovery(
                group.ResolutionId,
                group.SourceSeat,
                target.Seat,
                1);
            try
            {
                target.Hp++;
                AddLog(
                    "Recovered",
                    $"{target.Name} 因【桃园结义】回复至 {target.Hp}/{target.MaxHp} 点体力。",
                    group.SourceSeat,
                    target.Seat);
                QueueGameEvent(new RecoveryAppliedEvent(
                    group.SourceSeat,
                    target.Seat,
                    1,
                    target.Hp));
            }
            finally
            {
                PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
            }
        }

        group.TargetIndex++;
        SetCardUseTargetIndex(group.ResolutionId, group.TargetIndex);
        if (group.TargetIndex >= group.TargetSeats.Count)
        {
            FinishGroupRecovery(group);
        }

        PublishState();
    }

    private void BeginGroupAttackResponse(GroupCardResolution group)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) || group.Effect != GroupCardEffect.ResponseAttack)
        {
            throw new InvalidOperationException("The group attack is not the current card resolution.");
        }

        if (_winner != Winner.None)
        {
            FinishGroupAttack(group);
            return;
        }

        if (group.TargetIndex >= group.TargetSeats.Count)
        {
            FinishGroupAttack(group);
            return;
        }

        var targetSeat = group.TargetSeats[group.TargetIndex];
        var target = _players[targetSeat];
        if (!target.IsAlive || IsCardEffectIneffective(group.ResolutionId, targetSeat))
        {
            group.TargetIndex++;
            SetCardUseTargetIndex(group.ResolutionId, group.TargetIndex);
            BeginGroupAttackResponse(group);
            return;
        }

        var attack = new AttackResolution(
            group.ResolutionId,
            group.DamageSourceSeat,
            target.Seat,
            group.Card,
            playedCardKind: group.Card.Kind,
            physicalCards: group.PhysicalCards,
            ignoresArmor: HasDirectedCardArmorBypass(group.ResolutionId, target.Seat));
        group.CurrentAttack = attack;
        _pendingAttack = attack;
        if (UsesFormalTengjia && !attack.IgnoresArmor && HasTengjia(target) &&
            group.Card.Kind is CardKind.BarbarianAssault or CardKind.ArrowBarrage)
        {
            AddLog("ArmorEffect", $"{target.Name} 的【藤甲】令【{CardCatalog.Get(group.Card.Kind).DisplayName}】对其无效。", target.Seat, group.SourceSeat);
            QueueGameEvent(new ArmorEffectAppliedEvent(
                group.ResolutionId, CardKind.Tengjia, group.SourceSeat, target.Seat, group.Card.Kind));
            SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            CompleteAttack(attack);
            return;
        }
        if (IsYingboUnrespondable(group.ResolutionId))
        {
            SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            ResolveGroupResponse(group, target, selectedResponse: null);
            return;
        }
        var requiredCardKind = group.RequiredCardKind ??
            throw new InvalidOperationException("A group response attack must declare a required card kind.");
        var responseCards = GetResponseCards(target, requiredCardKind);
        var zhangbaPairs = requiredCardKind == CardKind.Slash
            ? GetZhangbaSlashPairs(target)
            : [];
        var programMultiCardResponses = requiredCardKind == CardKind.Slash
            ? GetProgramMultiCardViewAsSelections(target, CardKind.Slash, forResponse: true)
            : [];
        var hasBagua = requiredCardKind == CardKind.Dodge &&
                       !attack.IgnoresArmor &&
                       HasBagua(target);
        var canRequestHujia = requiredCardKind == CardKind.Dodge && CanRequestHujia(target, attack);
        var canRequestJijiang = requiredCardKind == CardKind.Slash && CanRequestJijiangResponse(target, attack);
        if (responseCards.Count == 0 && zhangbaPairs.Count == 0 && programMultiCardResponses.Count == 0 &&
            !hasBagua && !canRequestHujia && !canRequestJijiang)
        {
            SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            ResolveGroupResponse(group, target, selectedResponse: null);
            return;
        }

        PushResponseWindow(
            group.ResolutionId,
            group.SourceSeat,
            target.Seat,
            group.Card.Kind,
            requiredCardKind);
        var incomingName = CardCatalog.Get(group.Card.Kind).DisplayName;
        var requiredName = CardCatalog.Get(requiredCardKind).DisplayName;
        var decisionKind = requiredCardKind == CardKind.Dodge
            ? DecisionKind.RespondDodge
            : DecisionKind.RespondSlash;
        _pendingDecision = new PendingDecision(
            decisionKind,
            target.Seat,
            $"{_players[group.SourceSeat].Name} 使用了【{incomingName}】，是否打出【{requiredName}】？",
            responseCards.Select(card => card.Id)
                .Concat(zhangbaPairs.SelectMany(pair => pair.Select(card => card.Id)))
                .Concat(programMultiCardResponses.SelectMany(item => item.Cards.Select(card => card.Id)))
                .Distinct()
                .ToArray(),
            [],
            group.SourceSeat,
            group.Card.Kind)
        {
            PromptId = CreatePromptId(),
            Choices = CreateResponseChoices(
                responseCards,
                requiredCardKind,
                group.Card.Kind,
                card => GetEffectiveResponseKind(target, card, requiredCardKind),
                includeBagua: hasBagua,
                includeHujia: canRequestHujia,
                includeJijiang: canRequestJijiang,
                responder: target),
            RequiredCardKind = requiredCardKind
        };
        QueueGameEvent(new ResponseRequestedEvent(
            group.SourceSeat,
            target.Seat,
            group.Card.Kind,
            requiredCardKind));
        _status = target.IsHuman
            ? EngineStatus.AwaitingHumanResponse
            : EngineStatus.Running;
    }

    private Card? GetWeapon(CharacterState player) =>
        GetEquipment(player).SingleOrDefault(card =>
            EquipmentCatalog.Get(card.Kind).Slot == EquipmentSlot.Weapon);

    private bool IsLegalBorrowedSwordSlashTarget(
        CharacterState weaponOwner,
        CharacterState target,
        CardKind? effectiveKind = null) =>
        effectiveKind is { } kind
            ? target.IsAlive && target.Seat != weaponOwner.Seat &&
              !IsCardUseForbidden(weaponOwner.Seat, kind, CardActionType.Use) &&
              (HasCardDistanceExemption(weaponOwner, target, kind) ||
               GetCombatDistance(weaponOwner.Seat, target.Seat) <= GetAttackRange(weaponOwner.Seat)) &&
              !IsDirectedCardTargetProhibited(weaponOwner.Seat, target.Seat, kind) &&
              !IsSlashProhibited(target)
            : SlashKinds.Any(candidate => IsLegalBorrowedSwordSlashTarget(weaponOwner, target, candidate));

    private IReadOnlyList<Card> GetBorrowedSwordSlashCards(
        CharacterState weaponOwner,
        CharacterState slashTarget)
    {
        if (!IsLegalBorrowedSwordSlashTarget(weaponOwner, slashTarget))
        {
            return [];
        }

        return GetSlashUseCards(weaponOwner)
            .Where(card =>
            {
                var baseKind = IsSlashCard(card.Kind) ? card.Kind : CardKind.Slash;
                if (!GetSlashUseVariants(weaponOwner, baseKind).Any(variant =>
                        IsLegalBorrowedSwordSlashTarget(weaponOwner, slashTarget, variant.EffectiveKind)))
                    return false;
                var location = _cardZones.GetLocation(card.Id);
                if (location != CardLocation.Equipment(weaponOwner.Seat) ||
                    EquipmentCatalog.Get(card.Kind).Slot != EquipmentSlot.Weapon)
                {
                    return true;
                }

                // When Wusheng spends the equipped weapon itself, that weapon
                // cannot also provide the range needed for the forced Slash.
                return GetCombatDistance(weaponOwner.Seat, slashTarget.Seat) <= 1;
            })
            .ToArray();
    }

    private bool CanRequestBorrowedSwordJijiang(BorrowedSwordResolution pending)
    {
        var owner = _players[pending.WeaponOwnerSeat];
        return UsesFormalJijiang &&
               !pending.JijiangAttempted &&
               owner.IsAlive &&
               owner.Role == Role.Lord &&
               HasRuntimeSkill(owner, SkillKind.Jijiang) &&
               IsLegalBorrowedSwordSlashTarget(owner, _players[pending.SlashTargetSeat]) &&
               GetJijiangCandidateSeats(owner.Seat).Count > 0;
    }

    private void BeginBorrowedSwordSlashChoice(
        BorrowedSwordResolution pending,
        bool includeJijiang)
    {
        if (!ReferenceEquals(_pendingBorrowedSword, pending) || pending.ActiveAttack is not null)
        {
            throw new InvalidOperationException("Borrowed Sword is not awaiting its forced Slash choice.");
        }

        var source = _players[pending.SourceSeat];
        var weaponOwner = _players[pending.WeaponOwnerSeat];
        var slashTarget = _players[pending.SlashTargetSeat];
        var weapon = GetWeapon(weaponOwner);
        if (!weaponOwner.IsAlive || weapon is null)
        {
            CompleteBorrowedSwordWithoutSlash(pending, transferWeapon: false);
            return;
        }

        if (!IsLegalBorrowedSwordSlashTarget(weaponOwner, slashTarget))
        {
            CompleteBorrowedSwordWithoutSlash(pending, transferWeapon: true);
            return;
        }

        var slashes = GetBorrowedSwordSlashCards(weaponOwner, slashTarget);
        var zhangbaPairs = GetZhangbaSlashPairs(weaponOwner);
        var programMultiCardUses = GetProgramMultiCardViewAsSelections(
            weaponOwner, CardKind.Slash, forResponse: false);
        var canRequestJijiang = includeJijiang && CanRequestBorrowedSwordJijiang(pending);
        if (slashes.Count == 0 && zhangbaPairs.Count == 0 && programMultiCardUses.Count == 0 && !canRequestJijiang)
        {
            CompleteBorrowedSwordWithoutSlash(pending, transferWeapon: true);
            return;
        }

        PushResponseWindow(
            pending.ResolutionId,
            source.Seat,
            weaponOwner.Seat,
            CardKind.BorrowedSword,
            CardKind.Slash);
        var choices = slashes.SelectMany(card =>
        {
            var baseEffectiveKind = IsSlashCard(card.Kind) ? card.Kind : CardKind.Slash;
            return GetSlashUseKinds(weaponOwner, baseEffectiveKind)
                .Where(effectiveKind => effectiveKind == baseEffectiveKind ||
                                        IsNativeResponseCard(card, CardKind.Slash))
                .SelectMany(effectiveKind =>
            {
                var usesZhuqueFan = effectiveKind != baseEffectiveKind;
                var cardDescription = usesZhuqueFan
                    ? $"发动【朱雀羽扇】，将【杀】改为【火杀】使用"
                    : IsNativeResponseCard(card, CardKind.Slash)
                        ? $"使用【{CardCatalog.Get(effectiveKind).DisplayName}】"
                        : $"将【{card.DisplayName}】当作【杀】使用";
                var suffix = usesZhuqueFan ? ".as-FireSlash" : string.Empty;
                return CreateConversionChoiceVariants(
                    weaponOwner, card, baseEffectiveKind, forResponse: false,
                    $"borrowed-sword.slash.card-{card.Id}{suffix}",
                    $"{cardDescription}攻击 {slashTarget.Name}。",
                    [card.Id],
                    [slashTarget.Seat],
                    new Dictionary<string, string>
                    {
                        ["response"] = "borrowed-sword-slash",
                        ["response-card-kind"] = effectiveKind.ToString(),
                        ["target-seat"] = slashTarget.Seat.ToString(
                            System.Globalization.CultureInfo.InvariantCulture)
                    });
            });
        }).ToList();
        foreach (var pair in zhangbaPairs)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"borrowed-sword.zhangba-slash.cards-{pair[0].Id}-{pair[1].Id}"),
                $"发动【丈八蛇矛】，将两张手牌当【杀】攻击 {slashTarget.Name}。",
                [pair[0].Id, pair[1].Id],
                [slashTarget.Seat],
                new Dictionary<string, string>
                {
                    ["response"] = "zhangba-slash",
                    ["response-card-kind"] = CardKind.Slash.ToString(),
                    ["equipment"] = CardKind.ZhangbaSerpentSpear.ToString(),
                    ["target-seat"] = slashTarget.Seat.ToString(
                        System.Globalization.CultureInfo.InvariantCulture)
                }));
        }
        foreach (var selection in programMultiCardUses)
        {
            var cardIds = selection.Cards.Select(card => card.Id).ToArray();
            var parameters = new Dictionary<string, string>
            {
                ["response"] = "program-view-as-slash",
                ["response-card-kind"] = CardKind.Slash.ToString(),
                ["target-seat"] = slashTarget.Seat.ToString(
                    System.Globalization.CultureInfo.InvariantCulture)
            };
            AddConversionParameters(parameters, selection.Source);
            choices.Add(new PromptChoice(
                new ChoiceId($"borrowed-sword.program-view-as-slash.{selection.Source.SkillId.Length}:" +
                             $"{selection.Source.SkillId}.{selection.Source.BindingId}.cards-{string.Join('-', cardIds)}"),
                $"发动【{ProgramConversionName(selection.Source)}】，将 {cardIds.Length} 张手牌当【杀】攻击 {slashTarget.Name}。",
                cardIds,
                [slashTarget.Seat],
                parameters));
        }
        if (canRequestJijiang)
        {
            choices.Add(new PromptChoice(
                new ChoiceId("borrowed-sword.jijiang"),
                $"发动主公技【激将】，请求其他蜀势力角色提供【杀】攻击 {slashTarget.Name}。",
                [],
                [slashTarget.Seat],
                new Dictionary<string, string>
                {
                    ["response"] = "jijiang-request",
                    ["skill"] = SkillKind.Jijiang.ToString()
                }));
        }

        choices.Add(new PromptChoice(
            new ChoiceId("borrowed-sword.give-weapon"),
            $"不使用【杀】，将【{weapon.DisplayName}】交给 {source.Name}。",
            [],
            [source.Seat],
            new Dictionary<string, string>
            {
                ["response"] = "borrowed-sword-give-weapon",
                ["weapon-card-id"] = weapon.Id.ToString(
                    System.Globalization.CultureInfo.InvariantCulture)
            }));

        _pendingDecision = new PendingDecision(
            DecisionKind.RespondSlash,
            weaponOwner.Seat,
            $"{source.Name} 对你使用【借刀杀人】：请对 {slashTarget.Name} 使用【杀】，否则交出武器。",
            slashes.Select(card => card.Id)
                .Concat(zhangbaPairs.SelectMany(pair => pair.Select(card => card.Id)))
                .Concat(programMultiCardUses.SelectMany(item => item.Cards.Select(card => card.Id)))
                .Distinct()
                .ToArray(),
            [slashTarget.Seat],
            source.Seat,
            CardKind.BorrowedSword)
        {
            PromptId = CreatePromptId(),
            TargetSeat = slashTarget.Seat,
            RequiredCardKind = CardKind.Slash,
            Choices = choices
        };
        pending.AwaitingSlashChoice = true;
        _status = weaponOwner.IsHuman
            ? EngineStatus.AwaitingHumanResponse
            : EngineStatus.Running;
        QueueGameEvent(new ResponseRequestedEvent(
            source.Seat,
            weaponOwner.Seat,
            CardKind.BorrowedSword,
            CardKind.Slash));
    }

    private void ResolveBorrowedSwordSlashChoice(
        BorrowedSwordResolution pending,
        Card slash,
        CardKind? requestedEffectiveKind = null)
    {
        var weaponOwner = _players[pending.WeaponOwnerSeat];
        var slashTarget = _players[pending.SlashTargetSeat];
        var selected = GetBorrowedSwordSlashCards(weaponOwner, slashTarget)
            .SingleOrDefault(card => card.Id == slash.Id) ??
            throw new InvalidOperationException("The selected Borrowed Sword Slash is no longer legal.");
        var baseEffectiveKind = IsSlashCard(selected.Kind) ? selected.Kind : CardKind.Slash;
        var effectiveKind = requestedEffectiveKind ?? baseEffectiveKind;
        var usesZhuqueFan = IsZhuqueFanConversion(
            weaponOwner,
            baseEffectiveKind,
            effectiveKind);
        if (effectiveKind != baseEffectiveKind && !usesZhuqueFan)
        {
            throw new InvalidOperationException("The selected Borrowed Sword Slash conversion is no longer legal.");
        }
        if (!IsLegalBorrowedSwordSlashTarget(weaponOwner, slashTarget, effectiveKind))
        {
            throw new InvalidOperationException("The selected Borrowed Sword Slash target is no longer legal.");
        }

        PopResponseWindow(pending.ResolutionId);
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ClearPendingDecision();
        pending.AwaitingSlashChoice = false;
        pending.SlashCardId = selected.Id;
        pending.EffectiveSlashKind = effectiveKind;
        ResolveSlashCore(
            weaponOwner,
            slashTarget,
            selected,
            effectiveKind,
            weaponOwner.Seat,
            borrowedSword: pending,
            usesZhuqueFan: usesZhuqueFan);
    }

    private void ResolveBorrowedSwordZhangbaSlashChoice(
        BorrowedSwordResolution pending,
        IReadOnlyList<Card> pair)
    {
        var weaponOwner = _players[pending.WeaponOwnerSeat];
        var slashTarget = _players[pending.SlashTargetSeat];
        if (!ReferenceEquals(_pendingBorrowedSword, pending) ||
            !pending.AwaitingSlashChoice ||
            !IsLegalBorrowedSwordSlashTarget(weaponOwner, slashTarget) ||
            FindZhangbaSlashPair(weaponOwner, pair.Select(card => card.Id).ToArray()) is null)
        {
            throw new InvalidOperationException("The selected Borrowed Sword Zhangba Slash is no longer legal.");
        }

        PopResponseWindow(pending.ResolutionId);
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ClearPendingDecision();
        pending.AwaitingSlashChoice = false;
        pending.SlashCardId = pair[0].Id;
        pending.EffectiveSlashKind = CardKind.Slash;
        ResolveSlashCore(
            weaponOwner,
            slashTarget,
            pair[0],
            CardKind.Slash,
            weaponOwner.Seat,
            borrowedSword: pending,
            physicalCards: pair);
    }

    private void ResolveBorrowedSwordProgramMultiCardSlashChoice(
        BorrowedSwordResolution pending,
        ProgramMultiCardViewAsSelection selection)
    {
        var weaponOwner = _players[pending.WeaponOwnerSeat];
        var slashTarget = _players[pending.SlashTargetSeat];
        if (!ReferenceEquals(_pendingBorrowedSword, pending) ||
            !pending.AwaitingSlashChoice ||
            !IsLegalBorrowedSwordSlashTarget(weaponOwner, slashTarget) ||
            FindProgramMultiCardViewAsSelection(
                weaponOwner,
                selection.Cards.Select(card => card.Id).ToArray(),
                CardKind.Slash,
                forResponse: false,
                selection.Source) is null)
        {
            throw new InvalidOperationException("The selected Borrowed Sword configured Slash is no longer legal.");
        }

        PopResponseWindow(pending.ResolutionId);
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ClearPendingDecision();
        pending.AwaitingSlashChoice = false;
        pending.SlashCardId = selection.Cards[0].Id;
        pending.EffectiveSlashKind = CardKind.Slash;
        ResolveProgramMultiCardSlash(
            weaponOwner,
            slashTarget,
            selection,
            borrowedSword: pending,
            enforceOwnTurnSlashLimit: false);
    }

    private void CompleteBorrowedSwordWithoutSlash(
        BorrowedSwordResolution pending,
        bool transferWeapon)
    {
        if (!ReferenceEquals(_pendingBorrowedSword, pending) || pending.ActiveAttack is not null)
        {
            throw new InvalidOperationException("Borrowed Sword fallback is not current.");
        }

        if (_resolutionStack.LastOrDefault() is ResponseWindowFrame response &&
            response.ParentFrameId == pending.ResolutionId)
        {
            PopResponseWindow(pending.ResolutionId);
        }

        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        ClearPendingDecision();
        pending.AwaitingSlashChoice = false;
        var source = _players[pending.SourceSeat];
        var weaponOwner = _players[pending.WeaponOwnerSeat];
        var weapon = transferWeapon ? GetWeapon(weaponOwner) : null;
        if (weapon is not null)
        {
            MoveCard(
                weapon,
                CardLocation.Equipment(weaponOwner.Seat),
                CardLocation.Processing,
                CardMoveReasons.BorrowedSwordGive);
            MoveCard(
                weapon,
                CardLocation.Processing,
                CardLocation.Hand(source.Seat),
                CardMoveReasons.BorrowedSwordGive);
            AddLog(
                "CardEffect",
                $"{weaponOwner.Name} 未使用【杀】，将【{weapon.DisplayName}】交给 {source.Name}。",
                weaponOwner.Seat,
                source.Seat);
        }
        else
        {
            AddLog(
                "CardEffect",
                $"{weaponOwner.Name} 已没有可交出的武器，【借刀杀人】结束。",
                pending.SourceSeat,
                weaponOwner.Seat);
        }

        QueueGameEvent(new BorrowedSwordResolvedEvent(
            pending.ResolutionId,
            pending.SourceSeat,
            pending.WeaponOwnerSeat,
            pending.SlashTargetSeat,
            UsedSlash: false,
            TransferredWeaponCardId: weapon?.Id,
            TransferredWeaponKind: weapon?.Kind));
        FinishBorrowedSword(pending);
    }

    private void CompleteBorrowedSwordAfterSlash(BorrowedSwordResolution pending)
    {
        if (!ReferenceEquals(_pendingBorrowedSword, pending) ||
            pending.ActiveAttack is null ||
            pending.SlashCardId is null ||
            pending.EffectiveSlashKind is null)
        {
            throw new InvalidOperationException("Borrowed Sword Slash completion is not current.");
        }

        QueueGameEvent(new BorrowedSwordResolvedEvent(
            pending.ResolutionId,
            pending.SourceSeat,
            pending.WeaponOwnerSeat,
            pending.SlashTargetSeat,
            UsedSlash: true,
            SlashCardId: pending.SlashCardId,
            EffectiveSlashKind: pending.EffectiveSlashKind));
        AddLog(
            "CardEffect",
            $"{_players[pending.WeaponOwnerSeat].Name} 已按【借刀杀人】要求对 {_players[pending.SlashTargetSeat].Name} 使用【{CardCatalog.Get(pending.EffectiveSlashKind.Value).DisplayName}】。",
            pending.WeaponOwnerSeat,
            pending.SlashTargetSeat);
        FinishBorrowedSword(pending);
    }

    private void FinishBorrowedSword(BorrowedSwordResolution pending)
    {
        SetCardUseTargetIndex(pending.ResolutionId, 2);
        MoveCard(
            pending.Card,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.UseFinished);
        FinishCardUse(pending.ResolutionId, pending.Card, CardKind.BorrowedSword);
        _pendingBorrowedSword = null;
        if (_pendingJijiang?.BorrowedSword == pending)
        {
            _pendingJijiang = null;
        }

        if (_winner != Winner.None && _status != EngineStatus.Completed)
        {
            CompleteGame();
        }
    }

    private void ResolveSlash(
        CharacterState source,
        CharacterState target,
        Card slash,
        CardKind playedCardKind,
        CardConversionSource? conversionSource = null,
        IReadOnlyList<CardConversionSource>? additionalConversionSources = null,
        SkillKind? cardKindModifierSkill = null,
        SkillKind? targetCountModifierSkill = null)
    {
        var stillLegal = BuildLegalActions(source).Any(action =>
            action.Kind == LegalActionKind.Slash &&
            action.CardId == slash.Id &&
            action.TargetSeat == target.Seat &&
            (action.PlayedCardKind ?? slash.Kind) == playedCardKind &&
            action.ConversionSource == conversionSource &&
            ConversionSourcesEqual(action.AdditionalConversionSources, additionalConversionSources) &&
            action.CardKindModifierSkill == cardKindModifierSkill &&
            action.TargetCountModifierSkill == targetCountModifierSkill);
        if (!stillLegal)
        {
            throw new InvalidOperationException("Slash became illegal before resolution.");
        }

        ResolveSlashCore(
            source,
            target,
            slash,
            playedCardKind,
            source.Seat,
            usesZhuqueFan: playedCardKind == CardKind.FireSlash &&
                           (additionalConversionSources is null || additionalConversionSources.Count == 0) &&
                           !IsDirectProgramFireSlashConversion(source, slash, conversionSource) &&
                           (slash.Kind == CardKind.Slash ||
                            GetProgramCardIdentityMatches(source, slash).Any(match =>
                                match.Identity.OutputKind == CardKind.Slash)),
            conversionSource: conversionSource,
            additionalConversionSources: additionalConversionSources,
            cardKindModifierSkill: cardKindModifierSkill,
            targetCountModifierSkill: targetCountModifierSkill);
    }

    private void ResolveFangtianHalberdSlash(
        CharacterState source,
        IReadOnlyList<CharacterState> targets,
        Card slash,
        CardKind playedCardKind,
        CardConversionSource? conversionSource = null,
        IReadOnlyList<CardConversionSource>? additionalConversionSources = null,
        SkillKind? cardKindModifierSkill = null,
        SkillKind? targetCountModifierSkill = null)
    {
        var targetSeats = targets.Select(target => target.Seat).ToArray();
        var stillLegal = targetSeats.Length is >= 2 and <= 5 &&
            BuildLegalActions(source).Any(action =>
                action.Kind == LegalActionKind.Slash &&
                action.CardId == slash.Id &&
                action.TargetSeats.SequenceEqual(targetSeats) &&
                (action.PlayedCardKind ?? slash.Kind) == playedCardKind &&
                action.ConversionSource == conversionSource &&
                ConversionSourcesEqual(action.AdditionalConversionSources, additionalConversionSources) &&
                action.CardKindModifierSkill == cardKindModifierSkill &&
                action.TargetCountModifierSkill == targetCountModifierSkill);
        var usesFangtian = UsesFormalFangtianHalberd &&
            GetHand(source).Count == 1 && GetHand(source)[0].Id == slash.Id &&
            GetEquipment(source).Any(card => card.Kind == CardKind.FangtianHalberd);
        var usesProgramTargetCount = UsesProgramCardTargetCount(
            source, slash, playedCardKind, targetSeats.Length);
        if (!stillLegal || (!usesFangtian && !usesProgramTargetCount))
        {
            throw new InvalidOperationException("Fangtian Halberd Slash became illegal before resolution.");
        }

        var ignoresArmor = HasArmorBypass(source);
        var resolutionId = BeginCardUse(
            slash,
            source.Seat,
            targetSeats,
            playedCardKind,
            ignoresArmor,
            conversionSource: conversionSource,
            additionalConversionSources: additionalConversionSources,
            cardKindModifierSkill: cardKindModifierSkill);
        var nuzhan = GetNuzhanModifiers(resolutionId, source);
        MoveCard(
            slash,
            FindOwnedCardLocation(source, slash),
            CardLocation.Processing,
            CardMoveReasons.Use);
        var countedTowardSlashLimit =
            !nuzhan.IgnoresSlashLimit && _phase == TurnPhase.Play && source.Seat == _currentSeat;
        if (countedTowardSlashLimit)
        {
            RecordSlashUseDebit(resolutionId, source.Seat);
        }
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(source.Seat, playedCardKind);
        var damageAmount = (source.HasAlcoholEffect ? 2 : 1) + nuzhan.DamageBonus;
        source.HasAlcoholEffect = false;

        var pending = new FangtianHalberdResolution(
            resolutionId,
            source.Seat,
            slash,
            playedCardKind,
            ignoresArmor,
            damageAmount,
            targetSeats,
            usesFangtian,
            countedTowardSlashLimit,
            conversionSource,
            cardKindModifierSkill,
            targetCountModifierSkill);
        _pendingFangtianHalberd = pending;
        if (usesFangtian)
        {
            QueueGameEvent(new FangtianHalberdUsedEvent(
                resolutionId,
                source.Seat,
                slash.Id,
                playedCardKind,
                Array.AsReadOnly(targetSeats)));
        }
        var usesZhuqueFan = playedCardKind == CardKind.FireSlash &&
                            (additionalConversionSources is null || additionalConversionSources.Count == 0) &&
                            !IsDirectProgramFireSlashConversion(source, slash, conversionSource) &&
                            (slash.Kind == CardKind.Slash ||
                             GetProgramCardIdentityMatches(source, slash).Any(match =>
                                 match.Identity.OutputKind == CardKind.Slash));
        if (usesZhuqueFan)
        {
            QueueGameEvent(new ZhuqueFanConvertedEvent(
                resolutionId,
                source.Seat,
                Array.AsReadOnly(new[] { slash.Id }),
                Array.AsReadOnly(targetSeats)));
        }
        if (usesProgramTargetCount)
        {
            var targetCountRule = EvaluateCardTargetCount(source, playedCardKind);
            QueueGameEvent(new ProgramCardTargetCountAppliedEvent(
                resolutionId,
                source.Seat,
                playedCardKind,
                Array.AsReadOnly(targetSeats),
                Array.AsReadOnly(targetCountRule.Value.Contributions
                    .Select(contribution => contribution.SourceId)
                    .ToArray())));
        }
        QueueGameEvent(new CardUsedEvent(
            slash.Id,
            playedCardKind,
            source.Seat,
            targetSeats[0],
            IgnoresArmor: ignoresArmor));
        var slashName = CardCatalog.Get(playedCardKind).DisplayName;
        AddLog(
            usesFangtian && !usesProgramTargetCount ? "EquipmentEffect" : "SkillTriggered",
            $"{source.Name} 以【{slashName}】指定 {string.Join("、", targets.Select(target => target.Name))}。",
            source.Seat,
            targetSeats[0]);
        foreach (var target in targets)
        {
            NotifyAiOfSlash(source, target);
        }

        BeginNextFangtianHalberdTarget(pending);
    }

    private void BeginNextFangtianHalberdTarget(FangtianHalberdResolution pending)
    {
        if (!ReferenceEquals(_pendingFangtianHalberd, pending))
        {
            throw new InvalidOperationException("The Fangtian Halberd continuation is no longer current.");
        }

        while (pending.TargetIndex < pending.TargetSeats.Count &&
               !_players[GetFangtianEffectiveTarget(pending, pending.TargetIndex)].IsAlive)
        {
            pending.TargetIndex++;
        }

        if (pending.TargetIndex >= pending.TargetSeats.Count)
        {
            throw new InvalidOperationException("A Fangtian Halberd use must finish through its final target attack.");
        }

        SetCardUseTargetIndex(pending.ResolutionId, pending.TargetIndex);
        SetCardUseStep(pending.ResolutionId, ResolutionFrameStep.Declared);
        var targetSeat = GetFangtianEffectiveTarget(pending, pending.TargetIndex);
        var targetIgnoresArmor = pending.IgnoresArmor ||
            HasCardArmorBypass(_players[pending.SourceSeat], _players[targetSeat], pending.EffectiveCardKind);
        var attack = new AttackResolution(
            pending.ResolutionId,
            pending.SourceSeat,
            targetSeat,
            pending.Card,
            pending.DamageAmount,
            pending.EffectiveCardKind,
            targetIgnoresArmor,
            conversionSource: pending.ConversionSource,
            cardKindModifierSkill: pending.CardKindModifierSkill,
            targetCountModifierSkill: pending.TargetCountModifierSkill);
        if (_acceptedProgramUses.Contains(pending.ResolutionId) &&
            _preparedProgramTargets.TryGetValue(pending.ResolutionId, out var prepared))
            attack = prepared[pending.TargetIndex];
        pending.CurrentAttack = attack;
        _pendingAttack = attack;
        AddLog(
            "CardEffect",
            $"【{(pending.UsesFangtian ? "方天画戟" : "天义")}】的【{CardCatalog.Get(pending.EffectiveCardKind).DisplayName}】开始结算 {_players[targetSeat].Name}。",
            pending.SourceSeat,
            targetSeat);
        var committedAction = _resolutionStack.OfType<CardUseFrame>()
            .Single(frame => frame.Id == attack.ResolutionId).Action;
        if (committedAction is not null && _committedProgramUses.Add(attack.ResolutionId) &&
            TryBeginProgramCardWindow(attack, committedAction, SkillProgramTriggerWindow.CardUseCommitted,
                committedAction.TargetSeats, ProgramCardContinuation.CommittedSlash))
        {
            PublishState();
            return;
        }
        BeginSlashTargetResolution(attack);
    }

    private void ResolveZhangbaSlash(
        CharacterState source,
        CharacterState target,
        IReadOnlyList<Card> physicalCards)
    {
        if (!CanUseZhangbaSerpentSpear(source) ||
            physicalCards.Count != 2 ||
            physicalCards.Select(card => card.Id).Distinct().Count() != 2 ||
            physicalCards.Any(card => !IsOwnedPlayableLocation(source, _cardZones.GetLocation(card.Id))) ||
            !CanUseVirtualSlashTarget(source, target))
        {
            throw new InvalidOperationException("Zhangba Serpent Spear became illegal before resolution.");
        }

        ResolveSlashCore(
            source,
            target,
            physicalCards[0],
            CardKind.Slash,
            source.Seat,
            physicalCards: physicalCards);
    }

    private bool TryBeginLiegongChoice(AttackResolution attack)
    {
        var owner = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var attackRange = GetAttackRange(owner.Seat);
        var targetHandCount = GetHand(target).Count;
        var targetHandAtLeastSourceHp = targetHandCount >= owner.Hp;
        var targetHandAtMostAttackRange = targetHandCount <= attackRange;
        if (!UsesFormalLiegong ||
            _phase != TurnPhase.Play ||
            _currentSeat != owner.Seat ||
            !owner.IsAlive ||
            !target.IsAlive ||
            !HasRuntimeSkill(owner, SkillKind.Liegong) ||
            (!targetHandAtLeastSourceHp && !targetHandAtMostAttackRange))
        {
            return false;
        }

        if (_pendingLiegong is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Liegong choices at once.");
        }

        var conditions = string.Join("；", new[]
        {
            targetHandAtLeastSourceHp
                ? $"其手牌数 {targetHandCount} 不小于你的体力值 {owner.Hp}"
                : null,
            targetHandAtMostAttackRange
                ? $"其手牌数 {targetHandCount} 不大于你的攻击范围 {attackRange}"
                : null
        }.Where(item => item is not null));
        _pendingLiegong = new LiegongResolution(attack);
        _pendingDecision = new PendingDecision(
            DecisionKind.Liegong,
            owner.Seat,
            $"你对 {target.Name} 使用了【{CardCatalog.Get(attack.EffectiveCardKind ?? CardKind.Slash).DisplayName}】；{conditions}，是否发动【烈弓】？",
            [],
            [],
            SourceSeat: owner.Seat,
            IncomingCard: attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId($"liegong.use.resolution-{attack.ResolutionId}.target-{target.Seat}"),
                    "发动【烈弓】，令目标不能使用【闪】响应此【杀】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "liegong-use" }),
                new PromptChoice(
                    new ChoiceId($"liegong.skip.resolution-{attack.ResolutionId}.target-{target.Seat}"),
                    "不发动【烈弓】，继续普通响应。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "liegong-skip" })
            ]
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private void ResolveLiegongChoice(bool useSkill)
    {
        var pending = _pendingLiegong ??
            throw new InvalidOperationException("There is no Liegong choice to resolve.");
        var attack = pending.Attack;
        var owner = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        _pendingLiegong = null;
        ClearPendingDecision();
        attack.ResolveLiegong(useSkill);
        QueueGameEvent(new LiegongChoiceResolvedEvent(owner.Seat, target.Seat, useSkill));
        AddLog(
            useSkill ? "SkillTriggered" : "SkillSkipped",
            useSkill
                ? $"{owner.Name} 对 {target.Name} 发动【烈弓】，其不能使用【闪】响应此【杀】。"
                : $"{owner.Name} 未对 {target.Name} 发动【烈弓】。",
            owner.Seat,
            target.Seat);
        ContinueSlashAfterLiegong(attack);
    }

    private bool TryBeginTieqiChoice(AttackResolution attack)
    {
        var owner = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!UsesFormalTieqi ||
            !owner.IsAlive ||
            !target.IsAlive ||
            !HasRuntimeSkill(owner, SkillKind.Tieqi))
        {
            return false;
        }

        if (_pendingTieqi is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Tieqi choices at once.");
        }

        _pendingTieqi = new TieqiResolution(attack);
        _pendingDecision = new PendingDecision(
            DecisionKind.Tieqi,
            owner.Seat,
            $"你对 {target.Name} 使用了【{CardCatalog.Get(attack.EffectiveCardKind ?? CardKind.Slash).DisplayName}】，是否发动【铁骑】进行判定？",
            [],
            [],
            SourceSeat: owner.Seat,
            IncomingCard: attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId($"tieqi.use.resolution-{attack.ResolutionId}.target-{target.Seat}"),
                    "发动【铁骑】，进行判定。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "tieqi-use" }),
                new PromptChoice(
                    new ChoiceId($"tieqi.skip.resolution-{attack.ResolutionId}.target-{target.Seat}"),
                    "不发动【铁骑】，继续询问【闪】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "tieqi-skip" })
            ]
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private void ResolveTieqiChoice(bool useSkill)
    {
        var pending = _pendingTieqi ??
            throw new InvalidOperationException("There is no Tieqi choice to resolve.");
        var attack = pending.Attack;
        var owner = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        _pendingTieqi = null;
        ClearPendingDecision();
        QueueGameEvent(new TieqiChoiceResolvedEvent(owner.Seat, target.Seat, useSkill));
        AddLog(
            useSkill ? "SkillTriggered" : "SkillSkipped",
            useSkill
                ? $"{owner.Name} 对 {target.Name} 发动【铁骑】，进行判定。"
                : $"{owner.Name} 未对 {target.Name} 发动【铁骑】。",
            owner.Seat,
            target.Seat);

        if (!useSkill)
        {
            ContinueSlashAfterTieqi(attack);
            return;
        }

        var result = BeginJudgment(
            attack,
            owner.Seat,
            JudgmentReasons.Tieqi,
            attack.ResolutionId,
            attack.EffectiveCardKind,
            JudgmentContinuationKind.Tieqi,
            damageSkill: null,
            sourceSeat: owner.Seat);
        if (result is { } succeeded)
        {
            CompleteTieqiJudgment(attack, succeeded);
        }
    }

    private void CompleteTieqiJudgment(AttackResolution attack, bool succeeded)
    {
        if (!ReferenceEquals(_pendingAttack, attack))
        {
            throw new InvalidOperationException("The Tieqi judgment does not own the current Slash.");
        }

        attack.ResolveTieqi(succeeded);
        ContinueSlashAfterTieqi(attack);
    }

    private void ResolveSlashCore(
        CharacterState source,
        CharacterState target,
        Card slash,
        CardKind playedCardKind,
        int physicalOwnerSeat,
        JijiangResolution? activeJijiang = null,
        BorrowedSwordResolution? borrowedSword = null,
        IReadOnlyList<Card>? physicalCards = null,
        bool countsTowardSlashLimit = true,
        bool usesZhuqueFan = false,
        CardConversionSource? conversionSource = null,
        IReadOnlyList<CardConversionSource>? additionalConversionSources = null,
        SkillKind? cardKindModifierSkill = null,
        SkillKind? targetCountModifierSkill = null)
    {
        var slashCards = physicalCards?.ToArray() ?? [slash];
        if (slashCards.Length == 0 || slashCards[0].Id != slash.Id)
        {
            throw new InvalidOperationException("A Slash use must retain its primary physical card.");
        }
        if (usesZhuqueFan &&
            (!HasZhuqueFan(source) || playedCardKind != CardKind.FireSlash))
        {
            throw new InvalidOperationException("Zhuque Fan is no longer available for this Fire Slash conversion.");
        }
        var ignoresArmor = HasCardArmorBypass(source, target, playedCardKind);
        var resolutionId = BeginCardUse(
            slash,
            source.Seat,
            [target.Seat],
            playedCardKind,
            ignoresArmor,
            slashCards.Select(card => card.Id).ToArray(),
            conversionSource,
            additionalConversionSources,
            cardKindModifierSkill);
        var nuzhan = GetNuzhanModifiers(resolutionId, source);
        if (usesZhuqueFan)
        {
            QueueGameEvent(new ZhuqueFanConvertedEvent(
                resolutionId,
                source.Seat,
                Array.AsReadOnly(slashCards.Select(card => card.Id).ToArray()),
                Array.AsReadOnly(new[] { target.Seat })));
            AddLog(
                "EquipmentEffect",
                $"{source.Name} 发动【朱雀羽扇】，将本次普通【杀】改为【火杀】使用。",
                source.Seat,
                target.Seat);
        }
        foreach (var physicalCard in slashCards)
        {
            MoveCard(
                physicalCard,
                FindOwnedCardLocation(_players[physicalOwnerSeat], physicalCard),
                CardLocation.Processing,
                CardMoveReasons.Use);
        }
        var countedTowardSlashLimit = countsTowardSlashLimit && !nuzhan.IgnoresSlashLimit &&
                                     _phase == TurnPhase.Play && source.Seat == _currentSeat;
        if (countedTowardSlashLimit)
        {
            RecordSlashUseDebit(resolutionId, source.Seat);
        }
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(source.Seat, playedCardKind);
        var damageAmount = (source.HasAlcoholEffect ? 2 : 1) + nuzhan.DamageBonus;
        source.HasAlcoholEffect = false;
        var attack = new AttackResolution(
            resolutionId,
            source.Seat,
            target.Seat,
            slash,
            damageAmount,
            playedCardKind,
            ignoresArmor,
            physicalCards: slashCards,
            conversionSource: conversionSource,
            cardKindModifierSkill: cardKindModifierSkill,
            targetCountModifierSkill: targetCountModifierSkill);
        if (activeJijiang is not null)
        {
            activeJijiang.ActiveAttack = attack;
        }
        if (borrowedSword is not null)
        {
            borrowedSword.ActiveAttack = attack;
        }
        _pendingAttack = attack;
        var slashName = CardCatalog.Get(playedCardKind).DisplayName;
        var useDescription = conversionSource is not null && slashCards.Length > 1
            ? $"发动【{ProgramConversionName(conversionSource)}】，将 {slashCards.Length} 张手牌当作【杀】使用"
            : slashCards.Length == 2
            ? "发动【丈八蛇矛】，将两张手牌当作【杀】使用"
            : playedCardKind == slash.Kind
            ? $"使用【{slashName}】"
            : $"将【{CardCatalog.Get(slash.Kind).DisplayName}】当作【{slashName}】使用";
        AddLog("CardUsed", $"{source.Name} 对 {target.Name}{useDescription}。", source.Seat, target.Seat);
        QueueGameEvent(new CardUsedEvent(
            slash.Id,
            playedCardKind,
            source.Seat,
            target.Seat,
            IgnoresArmor: ignoresArmor));
        if (conversionSource is not null && slashCards.Length > 1)
        {
            QueueGameEvent(new ProgramViewAsConvertedEvent(
                resolutionId,
                conversionSource.SkillId,
                conversionSource.BindingId,
                source.Seat,
                Array.AsReadOnly(slashCards.Select(card => card.Id).ToArray()),
                playedCardKind,
                IsUse: true,
                [target.Seat]));
        }
        else if (slashCards.Length == 2)
        {
            QueueGameEvent(new ZhangbaSerpentSpearConvertedEvent(
                resolutionId,
                source.Seat,
                Array.AsReadOnly(slashCards.Select(card => card.Id).ToArray()),
                IsUse: true,
                target.Seat));
        }
        NotifyAiOfSlash(source, target);

        var committedAction = _resolutionStack.OfType<CardUseFrame>()
            .Single(frame => frame.Id == attack.ResolutionId).Action;
        if (committedAction is not null && _committedProgramUses.Add(attack.ResolutionId) &&
            TryBeginProgramCardWindow(attack, committedAction, SkillProgramTriggerWindow.CardUseCommitted,
                committedAction.TargetSeats, ProgramCardContinuation.CommittedSlash))
        {
            PublishState();
            return;
        }
        BeginSlashTargetResolution(attack);
    }

    private void BeginSlashTargetResolution(AttackResolution attack)
    {
        if (TryBeginLiuliChoice(attack))
        {
            PublishState();
            return;
        }

        if (PrepareProgramSlashTargets(attack)) return;
        ContinueSlashAfterFinalizedTargets(attack);
    }

    private void ContinueSlashAfterFinalizedTargets(AttackResolution attack)
    {
        if (TryBeginProgramCardUseBeforeTargetEffects(attack))
        {
            PublishState();
            return;
        }

        ContinueSlashAfterProgramTargetEffects(attack);
    }

    private void ContinueSlashAfterProgramTargetEffects(AttackResolution attack)
    {
        if (IsCardEffectIneffective(attack.ResolutionId, attack.TargetSeat))
        {
            SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            CompleteAttack(attack);
            return;
        }

        if (TryBeginLiegongChoice(attack))
        {
            PublishState();
            return;
        }

        ContinueSlashAfterLiegong(attack);
    }

    private bool TryBeginLiuliChoice(AttackResolution attack)
    {
        if (!UsesFormalDaQiao || attack.LiuliResolved)
        {
            return false;
        }

        var target = _players[attack.TargetSeat];
        attack.MarkLiuliResolved();
        if (!HasRuntimeSkill(target, SkillKind.Liuli))
        {
            return false;
        }

        var cards = GetHand(target).Concat(GetEquipment(target)).OrderBy(card => card.Id).ToArray();
        var targets = _players.Where(candidate =>
                candidate.IsAlive &&
                candidate.Seat != target.Seat &&
                candidate.Seat != attack.SourceSeat &&
                (_pendingFangtianHalberd is null ||
                 !((_resolutionStack.OfType<CardUseFrame>().Single(frame => frame.Id == attack.ResolutionId).TargetSeats
)).Contains(candidate.Seat)) &&
                 (HasCardDistanceExemption(_players[attack.SourceSeat], candidate,
                      attack.EffectiveCardKind ?? CardKind.Slash) ||
                  GetCombatDistance(target.Seat, candidate.Seat) <= GetAttackRange(target.Seat)) &&
                 !IsDirectedCardTargetProhibited(attack.SourceSeat, candidate.Seat,
                     attack.EffectiveCardKind ?? CardKind.Slash) &&
                 !IsSlashProhibited(candidate))
            .OrderBy(candidate => candidate.Seat)
            .ToArray();
        if (cards.Length == 0 || targets.Length == 0)
        {
            return false;
        }

        var choices = cards.SelectMany(card => targets.Select(newTarget => new PromptChoice(
                new ChoiceId($"liuli-{card.Id}-{newTarget.Seat}"),
                $"弃置【{CardCatalog.Get(card.Kind).DisplayName}】，将此杀转移给 {newTarget.Name}",
                [card.Id],
                [newTarget.Seat],
                new Dictionary<string, string> { ["action"] = "liuli-use" })))
            .Append(new PromptChoice(
                new ChoiceId("liuli-skip"),
                "不发动【流离】",
                [],
                [],
                new Dictionary<string, string> { ["action"] = "liuli-skip" }))
            .ToArray();
        _pendingDecision = new PendingDecision(
            DecisionKind.Liuli,
            target.Seat,
            $"{_players[attack.SourceSeat].Name} 对你使用了【杀】，是否发动【流离】？",
            cards.Select(card => card.Id).ToArray(),
            targets.Select(candidate => candidate.Seat).ToArray(),
            attack.SourceSeat,
            attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices = choices
        };
        PushResponseWindow(
            attack.ResolutionId,
            attack.SourceSeat,
            target.Seat,
            attack.EffectiveCardKind ?? CardKind.Slash,
            CardKind.Dodge);
        _status = target.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private EngineRunResult ResolveLiuliChoice(
        AttackResolution attack,
        int? discardedCardId,
        int? newTargetSeat,
        bool advanceToHumanBoundary)
    {
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.Liuli } decision)
        {
            throw new InvalidOperationException("流离窗口已失效。");
        }

        var owner = _players[decision.PlayerSeat];
        PopResponseWindow(attack.ResolutionId);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.Declared);
        ClearPendingDecision();
        if (discardedCardId is { } cardId && newTargetSeat is { } redirectedSeat)
        {
            var card = GetHand(owner).SingleOrDefault(candidate => candidate.Id == cardId);
            var from = CardLocation.Hand(owner.Seat);
            if (card is null)
            {
                card = GetEquipment(owner).Single(candidate => candidate.Id == cardId);
                from = CardLocation.Equipment(owner.Seat);
            }
            MoveCard(card, from, CardLocation.Processing, CardMoveReasons.LiuliDiscard);
            MoveCard(card, CardLocation.Processing, CardLocation.DiscardPile, CardMoveReasons.LiuliDiscard);
            var originalTargetSeat = attack.TargetSeat;
            attack.SetDamageParticipants(attack.SourceSeat, redirectedSeat);
            attack.SetIgnoresArmor(
                HasArmorBypass(_players[attack.SourceSeat]) ||
                HasCardArmorBypass(_players[attack.SourceSeat], _players[redirectedSeat],
                    attack.EffectiveCardKind ?? CardKind.Slash));
            RedirectCardUseTarget(attack.ResolutionId, originalTargetSeat, redirectedSeat);
            QueueGameEvent(new LiuliRedirectedEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                originalTargetSeat,
                redirectedSeat,
                card.Id));
            AddLog("SkillTriggered",
                $"{owner.Name} 发动【流离】，弃置【{CardCatalog.Get(card.Kind).DisplayName}】，将【杀】转移给 {_players[redirectedSeat].Name}。",
                owner.Seat,
                redirectedSeat);
        }

        BeginSlashTargetResolution(attack);
        PublishState();
        return advanceToHumanBoundary ? AdvanceToHumanBoundary() : BuildResult();
    }

    private bool IsAiLiuliPending() =>
        _pendingDecision is { Kind: DecisionKind.Liuli } decision &&
        decision.PlayerSeat != _options.HumanSeat;

    private void ResolvePendingAiLiuli()
    {
        var decision = _pendingDecision ?? throw new InvalidOperationException("AI 流离窗口不存在。");
        var use = decision.Choices.FirstOrDefault(choice =>
            choice.Parameters.GetValueOrDefault("action") == "liuli-use");
        ResolveLiuliChoice(
            _pendingAttack ?? throw new InvalidOperationException("AI 流离缺少杀结算。"),
            use?.Cards.SingleOrDefault(),
            use?.Targets.SingleOrDefault(),
            advanceToHumanBoundary: false);
    }

    private void ContinueSlashAfterLiegong(AttackResolution attack)
    {
        if (!ReferenceEquals(_pendingAttack, attack))
        {
            throw new InvalidOperationException("The Liegong continuation does not own the current Slash.");
        }

        if (TryBeginTieqiChoice(attack))
        {
            PublishState();
            return;
        }

        ContinueSlashAfterTieqi(attack);
    }

    private void ContinueSlashAfterTieqi(AttackResolution attack)
    {
        if (!ReferenceEquals(_pendingAttack, attack))
        {
            throw new InvalidOperationException("The Tieqi continuation does not own the current Slash.");
        }

        if (TryBeginCixiongDoubleSwordsChoice(attack))
        {
            return;
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var slash = attack.Card;
        var playedCardKind = attack.EffectiveCardKind ?? slash?.Kind ??
            throw new InvalidOperationException("A Slash continuation must retain an effective card kind.");
        var ignoresArmor = attack.IgnoresArmor;
        var resolutionId = attack.ResolutionId;
        var slashName = CardCatalog.Get(playedCardKind).DisplayName;

        if (attack.SuccessfulDodgeResponses == 0)
        {
            attack.SetRequiredDodgeResponses(GetRequiredResponseCount(
                source,
                source.Seat,
                target.Seat,
                playedCardKind,
                CardKind.Dodge));
        }

        if (!ignoresArmor &&
            !attack.IsTwoCardVirtualSlash &&
            slash?.Suit is Suit.Spade or Suit.Club &&
            HasBlackSlashBarrier(target))
        {
            AddLog(
                "ArmorEffect",
                $"{target.Name} 的【仁王盾】令这次黑色【{slashName}】无效。",
                target.Seat,
                source.Seat);
            QueueGameEvent(new ArmorEffectAppliedEvent(
                resolutionId,
                CardKind.RenwangShield,
                source.Seat,
                target.Seat,
                playedCardKind));
            SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
            CompleteAttack(attack);
            return;
        }

        if (UsesFormalYuJin &&
            HasRuntimeSkill(target, SkillKind.Yizhong) &&
            CanYizhongNullify(attack.PhysicalCards, HasArmor(target)))
        {
            AddLog(
                "SkillTriggered",
                $"{target.Name} 的【毅重】令这次黑色【{slashName}】无效。",
                target.Seat,
                source.Seat);
            QueueGameEvent(new YizhongNullifiedEvent(
                resolutionId,
                source.Seat,
                target.Seat,
                playedCardKind));
            SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
            CompleteAttack(attack);
            return;
        }

        if (UsesFormalTengjia &&
            !ignoresArmor &&
            playedCardKind == CardKind.Slash &&
            HasTengjia(target))
        {
            AddLog("ArmorEffect", $"{target.Name} 的【藤甲】令这次普通【杀】无效。", target.Seat, source.Seat);
            QueueGameEvent(new ArmorEffectAppliedEvent(
                resolutionId, CardKind.Tengjia, source.Seat, target.Seat, playedCardKind));
            SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
            CompleteAttack(attack);
            return;
        }

        if (IsYingboUnrespondable(resolutionId))
        {
            SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
            if (!ApplyAttackDamage(attack))
            {
                CompleteAttack(attack);
            }
            return;
        }

        if (attack.ProhibitsDodge)
        {
            var prohibitingSkills = string.Join("、", new[]
            {
                attack.LiegongProhibitsDodge ? "【烈弓】" : null,
                attack.TieqiProhibitsDodge ? "【铁骑】" : null
            }.Where(item => item is not null));
            AddLog(
                "SkillTriggered",
                $"{source.Name} 的{prohibitingSkills}令 {target.Name} 不能使用【闪】响应此【{slashName}】。",
                source.Seat,
                target.Seat);
            SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
            if (!ApplyAttackDamage(attack))
            {
                CompleteAttack(attack);
            }
            return;
        }

        var dodges = GetResponseCards(target, CardKind.Dodge);
        var hasBagua = !ignoresArmor && HasBagua(target);
        var dodge = dodges.FirstOrDefault();
        var canRequestHujia = CanRequestHujia(target, attack);
        var responseOrdinal = attack.SuccessfulDodgeResponses + 1;
        var responsePrompt = attack.RequiredDodgeResponses > 1
            ? $"{source.Name} 的【无双】要求你打出第 {responseOrdinal} 张【闪】，是否响应？"
            : $"{source.Name} 对你使用了【{slashName}】，是否打出【闪】？";
        if ((dodges.Count > 0 || hasBagua || canRequestHujia) && target.IsHuman)
        {
            PushResponseWindow(
                resolutionId,
                source.Seat,
                target.Seat,
                playedCardKind,
                CardKind.Dodge);
            _pendingDecision = new PendingDecision(
                DecisionKind.RespondDodge,
                target.Seat,
                responsePrompt,
                dodges.Select(card => card.Id).ToArray(),
                [],
                source.Seat,
                playedCardKind)
            {
                PromptId = CreatePromptId(),
                Choices = CreateResponseChoices(
                    dodges,
                    CardKind.Dodge,
                    playedCardKind,
                    card => GetEffectiveResponseKind(target, card, CardKind.Dodge),
                    includeBagua: hasBagua,
                    includeHujia: canRequestHujia,
                    responder: target),
                RequiredCardKind = CardKind.Dodge
            };
            _status = EngineStatus.AwaitingHumanResponse;
            QueueGameEvent(new ResponseRequestedEvent(
                source.Seat,
                target.Seat,
                playedCardKind,
                CardKind.Dodge));
            PublishState();
            return;
        }

        if (dodge is not null || hasBagua || canRequestHujia)
        {
            // Choosing to respond is a separate continuation. Advance() consumes it
            // immediately, while AdvanceOneStep() exposes it as the next AI decision.
            PushResponseWindow(
                resolutionId,
                source.Seat,
                target.Seat,
                playedCardKind,
                CardKind.Dodge);
            _pendingDecision = new PendingDecision(
                DecisionKind.RespondDodge,
                target.Seat,
                attack.RequiredDodgeResponses > 1
                    ? $"{source.Name} 的【无双】要求 {target.Name} 打出第 {responseOrdinal} 张【闪】，AI 将选择是否响应。"
                    : $"{source.Name} 对 {target.Name} 使用了【{slashName}】，AI 将选择是否打出【闪】。",
                dodges.Select(card => card.Id).ToArray(),
                [],
                source.Seat,
                playedCardKind)
            {
                PromptId = CreatePromptId(),
                Choices = CreateResponseChoices(
                    dodges,
                    CardKind.Dodge,
                    playedCardKind,
                    card => GetEffectiveResponseKind(target, card, CardKind.Dodge),
                    includeBagua: hasBagua,
                    includeHujia: canRequestHujia,
                    responder: target),
                RequiredCardKind = CardKind.Dodge
            };
            QueueGameEvent(new ResponseRequestedEvent(
                source.Seat,
                target.Seat,
                playedCardKind,
                CardKind.Dodge));
            return;
        }

        SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
        if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private bool TryBeginCixiongDoubleSwordsChoice(AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!UsesFormalCixiongDoubleSwords ||
            attack.CixiongDoubleSwordsResolved ||
            !source.IsAlive ||
            !target.IsAlive ||
            source.Gender == target.Gender ||
            GetEquipment(source).All(card => card.Kind != CardKind.CixiongDoubleSwords))
        {
            return false;
        }

        if (_pendingCixiongDoubleSwords is not null)
        {
            throw new InvalidOperationException("Only one Cixiong Double Swords choice may be active.");
        }

        _pendingCixiongDoubleSwords = new CixiongDoubleSwordsResolution(attack);
        _pendingDecision = new PendingDecision(
            DecisionKind.CixiongDoubleSwords,
            source.Seat,
            $"你对异性角色 {target.Name} 使用了【杀】，是否发动【雌雄双股剑】？",
            [],
            [],
            source.Seat,
            attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            TargetSeat = target.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId("cixiong.activate"),
                    $"发动【雌雄双股剑】，令 {target.Name} 弃一张手牌或令你摸一张牌。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "cixiong-use" }),
                new PromptChoice(
                    new ChoiceId("cixiong.skip"),
                    "不发动【雌雄双股剑】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "cixiong-skip" })
            ]
        };
        _status = source.IsHuman
            ? EngineStatus.AwaitingHumanResponse
            : EngineStatus.Running;
        return true;
    }

    private void ResolveCixiongDoubleSwordsChoice(PromptChoice selected)
    {
        var pending = _pendingCixiongDoubleSwords ??
            throw new InvalidOperationException("There is no Cixiong Double Swords choice to resolve.");
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.CixiongDoubleSwords } decision ||
            !selected.Parameters.TryGetValue("action", out var action))
        {
            throw new InvalidOperationException("The Cixiong Double Swords continuation is inconsistent.");
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (pending.Stage == CixiongDoubleSwordsStage.SourceActivation)
        {
            if (decision.PlayerSeat != source.Seat || action is not ("cixiong-use" or "cixiong-skip"))
            {
                throw new InvalidOperationException("The Cixiong activation choice is not current.");
            }

            if (action == "cixiong-skip")
            {
                CompleteCixiongDoubleSwords(
                    pending,
                    activated: false,
                    targetDiscarded: false,
                    discardedCardId: null,
                    sourceDrawCount: 0);
                return;
            }

            pending.Stage = CixiongDoubleSwordsStage.TargetChoice;
            var hand = GetHand(target).OrderBy(card => card.Id).ToArray();
            var choices = hand.Select(card => new PromptChoice(
                    new ChoiceId($"cixiong.discard.card-{card.Id}"),
                    $"弃置【{card.DisplayName}】（{card.RankText}）。",
                    [card.Id],
                    [],
                    new Dictionary<string, string> { ["action"] = "cixiong-discard" }))
                .Append(new PromptChoice(
                    new ChoiceId("cixiong.allow-draw"),
                    $"令 {source.Name} 摸一张牌。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "cixiong-draw" }))
                .ToArray();
            _pendingDecision = new PendingDecision(
                DecisionKind.CixiongDoubleSwords,
                target.Seat,
                $"{source.Name} 发动【雌雄双股剑】，请选择弃置一张手牌，或令其摸一张牌。",
                hand.Select(card => card.Id).ToArray(),
                [],
                source.Seat,
                attack.EffectiveCardKind)
            {
                PromptId = CreatePromptId(),
                TargetSeat = target.Seat,
                Choices = choices
            };
            _status = target.IsHuman
                ? EngineStatus.AwaitingHumanResponse
                : EngineStatus.Running;
            return;
        }

        if (decision.PlayerSeat != target.Seat ||
            pending.Stage != CixiongDoubleSwordsStage.TargetChoice)
        {
            throw new InvalidOperationException("The Cixiong target choice is not current.");
        }

        if (action == "cixiong-discard")
        {
            if (selected.Cards.Count != 1)
            {
                throw new InvalidOperationException("Cixiong requires exactly one discarded hand card.");
            }
            var card = GetHand(target).SingleOrDefault(candidate => candidate.Id == selected.Cards[0]) ??
                throw new InvalidOperationException("The selected Cixiong discard is no longer in hand.");
            MoveCard(
                card,
                CardLocation.Hand(target.Seat),
                CardLocation.DiscardPile,
                CardMoveReasons.CixiongDiscard);
            CompleteCixiongDoubleSwords(
                pending,
                activated: true,
                targetDiscarded: true,
                discardedCardId: card.Id,
                sourceDrawCount: 0);
            return;
        }

        if (action != "cixiong-draw" || selected.Cards.Count != 0)
        {
            throw new InvalidOperationException("The Cixiong target choice is invalid.");
        }
        var drawn = DrawCards(source, 1, log: true, CardMoveReasons.CixiongDraw);
        CompleteCixiongDoubleSwords(
            pending,
            activated: true,
            targetDiscarded: false,
            discardedCardId: null,
            sourceDrawCount: drawn.Count);
    }

    private void CompleteCixiongDoubleSwords(
        CixiongDoubleSwordsResolution pending,
        bool activated,
        bool targetDiscarded,
        int? discardedCardId,
        int sourceDrawCount)
    {
        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        attack.MarkCixiongDoubleSwordsResolved();
        _pendingCixiongDoubleSwords = null;
        ClearPendingDecision();
        QueueGameEvent(new CixiongDoubleSwordsResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            activated,
            targetDiscarded,
            discardedCardId,
            sourceDrawCount));
        AddLog(
            activated ? "EquipmentEffect" : "EquipmentSkipped",
            !activated
                ? $"{source.Name} 未发动【雌雄双股剑】。"
                : targetDiscarded
                    ? $"{source.Name} 发动【雌雄双股剑】，{target.Name} 弃置了一张手牌。"
                    : $"{source.Name} 发动【雌雄双股剑】并摸了一张牌。",
            source.Seat,
            target.Seat);
        ContinueSlashAfterTieqi(attack);
    }

    private void ResolveDuel(CharacterState source, CharacterState target, Card duel, CardKind? playedCardKind = null)
    {
        var stillLegal = BuildLegalActions(source).Any(action =>
            action.Kind == LegalActionKind.Duel &&
            action.CardId == duel.Id &&
            action.TargetSeat == target.Seat &&
            action.PlayedCardKind == playedCardKind);
        if (!stillLegal)
        {
            throw new InvalidOperationException("Duel became illegal before resolution.");
        }

        var resolutionId = BeginCardUse(duel, source.Seat, [target.Seat], playedCardKind);
        MoveCard(
            duel,
            FindOwnedCardLocation(source, duel),
            CardLocation.Processing,
            CardMoveReasons.Use);
        BeginJizhiOrNullificationWindow(
            resolutionId,
            duel,
            source.Seat,
            [target.Seat],
            LegalActionKind.Duel,
            playedCardKind: playedCardKind);
    }

    private void BeginDuelResponse(DuelResolution duel)
    {
        if (!ReferenceEquals(_pendingDuel, duel))
        {
            throw new InvalidOperationException("The Duel response is not the current card resolution.");
        }

        var responder = _players[duel.ResponderSeat];
        var opponent = _players[duel.OpponentSeat];
        if (IsYingboUnrespondable(duel.ResolutionId))
        {
            SetCardUseStep(duel.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            _pendingDecision = null;
            ResolveDuelResponse(duel, responder, selectedSlash: null);
            return;
        }

        var requiredSlashResponses = GetRequiredResponseCount(
            opponent,
            opponent.Seat,
            responder.Seat,
            CardKind.Duel,
            CardKind.Slash);
        var responseOrdinal = duel.SuccessfulSlashResponses + 1;
        var slashes = GetResponseCards(responder, CardKind.Slash);
        var zhangbaPairs = GetZhangbaSlashPairs(responder);
        var programMultiCardResponses = GetProgramMultiCardViewAsSelections(
            responder, CardKind.Slash, forResponse: true);
        var canRequestJijiang = CanRequestJijiangResponse(responder, duel.Attack);
        if (slashes.Count == 0 && zhangbaPairs.Count == 0 && programMultiCardResponses.Count == 0 && !canRequestJijiang)
        {
            if (_pendingAttack is null)
            {
                throw new InvalidOperationException("A Duel response has no active damage source.");
            }
            SetCardUseStep(duel.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            _pendingDecision = null;
            ResolveDuelResponse(duel, responder, selectedSlash: null);
            return;
        }

        PushResponseWindow(
            duel.ResolutionId,
            duel.OpponentSeat,
            responder.Seat,
            CardKind.Duel,
            CardKind.Slash);
        _pendingDecision = new PendingDecision(
            DecisionKind.RespondSlash,
            responder.Seat,
            requiredSlashResponses > 1
                ? $"{opponent.Name} 的【无双】要求你打出第 {responseOrdinal} 张【杀】响应【决斗】，是否响应？"
                : $"{opponent.Name} 对你使用了【决斗】，是否打出【杀】？",
            slashes.Select(card => card.Id)
                .Concat(zhangbaPairs.SelectMany(pair => pair.Select(card => card.Id)))
                .Concat(programMultiCardResponses.SelectMany(item => item.Cards.Select(card => card.Id)))
                .Distinct()
                .ToArray(),
            [],
            duel.OpponentSeat,
            CardKind.Duel)
        {
            PromptId = CreatePromptId(),
            Choices = CreateResponseChoices(
                slashes,
                CardKind.Slash,
                effectiveCardKindSelector: card =>
                    GetEffectiveResponseKind(responder, card, CardKind.Slash),
                includeJijiang: canRequestJijiang,
                responder: responder),
            RequiredCardKind = CardKind.Slash
        };
        QueueGameEvent(new ResponseRequestedEvent(
            duel.OpponentSeat,
            responder.Seat,
            CardKind.Duel,
            CardKind.Slash));
        _status = responder.IsHuman
            ? EngineStatus.AwaitingHumanResponse
            : EngineStatus.Running;
    }

    private void ResolveDuelResponse(
        DuelResolution duel,
        CharacterState responder,
        Card? selectedSlash)
    {
        if (!ReferenceEquals(_pendingDuel, duel) || responder.Seat != duel.ResponderSeat)
        {
            throw new InvalidOperationException("The Duel response does not belong to the current responder.");
        }

        if (selectedSlash is { } slash)
        {
            var responseCardKind = GetEffectiveResponseKind(
                responder,
                slash,
                CardKind.Slash);
            var responseConversion = GetSelectedResponseConversion(responder, slash, responseCardKind);
            var responseFrom = FindOwnedCardLocation(responder, slash);
            MoveCard(
                slash,
                responseFrom,
                CardLocation.Processing,
                CardMoveReasons.Respond);
            var responseName = CardCatalog.Get(responseCardKind).DisplayName;
            var responseDescription = IsNativeResponseCard(slash, CardKind.Slash)
                ? $"打出【{responseName}】"
                : $"将【{slash.DisplayName}】当作【{responseName}】";
            AddLog(
                "CardResponded",
                $"{responder.Name} {responseDescription}应战【决斗】。",
                responder.Seat,
                duel.OpponentSeat);
            QueueGameEvent(new CardRespondedEvent(
                slash.Id,
                responder.Seat,
                duel.OpponentSeat,
                responseCardKind));
            MarkSlashUsedOrPlayedDuringCurrentPlayPhase(responder.Seat, responseCardKind);
            QueueGameEvent(new DuelResponseEvent(
                duel.ResolutionId,
                responder.Seat,
                UsedSlash: true,
                SlashCardId: slash.Id,
                ResponseCardKind: responseCardKind));
            var responseCost = new CardActionCost(slash.Id, slash.Kind, responseFrom);
            if (TryBeginCardResponsePrograms(
                    duel.Attack,
                    responder,
                    responder,
                    requesterSeat: null,
                    duel.OpponentSeat,
                    responseCardKind,
                    [responseCost],
                    ProgramCardContinuation.DuelSlash,
                    responseConversion))
            {
                return;
            }
            MoveCard(
                slash,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.ResponseFinished);
            ContinueDuelAfterSuccessfulSlash(duel, responder.Seat);
            return;
        }

        QueueGameEvent(new DuelResponseEvent(
            duel.ResolutionId,
            responder.Seat,
            UsedSlash: false,
            SlashCardId: null));
        var attack = _pendingAttack ??
            throw new InvalidOperationException("A failed Duel response has no active damage source.");
        {
            attack.SetDamageParticipants(
                sourceSeat: duel.OpponentSeat,
                targetSeat: responder.Seat);
        }
        if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private void ResolveDuelZhangbaResponse(
        DuelResolution duel,
        CharacterState responder,
        IReadOnlyList<Card> pair)
    {
        if (!ReferenceEquals(_pendingDuel, duel) || responder.Seat != duel.ResponderSeat)
        {
            throw new InvalidOperationException("The Zhangba Duel response does not belong to the current responder.");
        }

        MoveZhangbaResponseCards(responder, pair, duel.ResolutionId, duel.OpponentSeat);
        AddLog(
            "CardResponded",
            $"{responder.Name} 发动【丈八蛇矛】，将两张手牌当【杀】应战【决斗】。",
            responder.Seat,
            duel.OpponentSeat);
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(responder.Seat, CardKind.Slash);
        QueueGameEvent(new DuelResponseEvent(
            duel.ResolutionId,
            responder.Seat,
            UsedSlash: true,
            SlashCardId: pair[0].Id,
            ResponseCardKind: CardKind.Slash));
        FinishZhangbaResponseCards(pair);
        ContinueDuelAfterSuccessfulSlash(duel, responder.Seat);
    }

    private void ContinueDuelAfterSuccessfulSlash(DuelResolution duel, int responderSeat)
    {
        var skillOwner = _players[duel.OpponentSeat];
        var requiredSlashResponses = GetRequiredResponseCount(
            skillOwner,
            skillOwner.Seat,
            responderSeat,
            CardKind.Duel,
            CardKind.Slash);
        var completedResponseSet = duel.RegisterSlashResponse(requiredSlashResponses);
        if (requiredSlashResponses > 1)
        {
            QueueGameEvent(new RequiredResponseProgressEvent(
                duel.ResolutionId,
                skillOwner.Seat,
                responderSeat,
                CardKind.Duel,
                CardKind.Slash,
                completedResponseSet ? requiredSlashResponses : duel.SuccessfulSlashResponses,
                requiredSlashResponses));
        }

        BeginDuelResponse(duel);
    }

    private void ResolveGroupResponse(
        GroupCardResolution group,
        CharacterState responder,
        Card? selectedResponse)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) ||
            group.Effect != GroupCardEffect.ResponseAttack ||
            group.CurrentAttack is not { } attack ||
            responder.Seat != attack.TargetSeat)
        {
            throw new InvalidOperationException(
                "The group attack response does not belong to the current target.");
        }

        var requiredCardKind = group.RequiredCardKind ??
            throw new InvalidOperationException("A group response attack must declare a required card kind.");

        if (selectedResponse is { } responseCard)
        {
            var responseCardKind = GetEffectiveResponseKind(
                responder,
                responseCard,
                requiredCardKind);
            var responseConversion = GetSelectedResponseConversion(responder, responseCard, responseCardKind);
            var responseFrom = FindOwnedCardLocation(responder, responseCard);

            MoveCard(
                responseCard,
                responseFrom,
                CardLocation.Processing,
                CardMoveReasons.Respond);
            var incomingName = CardCatalog.Get(group.Card.Kind).DisplayName;
            var responseName = CardCatalog.Get(responseCardKind).DisplayName;
            var responseDescription = IsNativeResponseCard(responseCard, requiredCardKind)
                ? $"打出【{responseName}】"
                : $"将【{responseCard.DisplayName}】当作【{responseName}】";
            AddLog(
                "CardResponded",
                $"{responder.Name} {responseDescription}响应【{incomingName}】。",
                responder.Seat,
                group.SourceSeat);
            QueueGameEvent(new CardRespondedEvent(
                responseCard.Id,
                responder.Seat,
                group.SourceSeat,
                responseCardKind));
            MarkSlashUsedOrPlayedDuringCurrentPlayPhase(responder.Seat, responseCardKind);
            QueueGameEvent(new GroupResponseEvent(
                group.ResolutionId,
                group.Card.Kind,
                requiredCardKind,
                responder.Seat,
                UsedResponse: true,
                ResponseCardId: responseCard.Id,
                ResponseCardKind: responseCardKind));
            var responseCost = new CardActionCost(responseCard.Id, responseCard.Kind, responseFrom);
            if (TryBeginCardResponsePrograms(
                    attack,
                    responder,
                    responder,
                    requesterSeat: null,
                    group.SourceSeat,
                    responseCardKind,
                    [responseCost],
                    ProgramCardContinuation.GroupResponse,
                    responseConversion))
            {
                return;
            }
            MoveCard(
                responseCard,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.ResponseFinished);
            CompleteAttack(attack);
            return;
        }

        QueueGameEvent(new GroupResponseEvent(
            group.ResolutionId,
            group.Card.Kind,
            requiredCardKind,
            responder.Seat,
            UsedResponse: false,
            ResponseCardId: null));
        if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private void ResolveGroupZhangbaResponse(
        GroupCardResolution group,
        CharacterState responder,
        IReadOnlyList<Card> pair)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) ||
            group.Effect != GroupCardEffect.ResponseAttack ||
            group.RequiredCardKind != CardKind.Slash ||
            group.CurrentAttack is not { } attack ||
            responder.Seat != attack.TargetSeat)
        {
            throw new InvalidOperationException("The Zhangba group response is not current.");
        }

        MoveZhangbaResponseCards(responder, pair, group.ResolutionId, group.SourceSeat);
        AddLog(
            "CardResponded",
            $"{responder.Name} 发动【丈八蛇矛】，将两张手牌当【杀】响应【{group.Card.DisplayName}】。",
            responder.Seat,
            group.SourceSeat);
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(responder.Seat, CardKind.Slash);
        QueueGameEvent(new GroupResponseEvent(
            group.ResolutionId,
            group.Card.Kind,
            CardKind.Slash,
            responder.Seat,
            UsedResponse: true,
            ResponseCardId: pair[0].Id,
            ResponseCardKind: CardKind.Slash));
        FinishZhangbaResponseCards(pair);
        CompleteAttack(attack);
    }

    private void MoveZhangbaResponseCards(
        CharacterState responder,
        IReadOnlyList<Card> pair,
        long resolutionId,
        int responseTargetSeat)
    {
        if (FindZhangbaSlashPair(responder, pair.Select(card => card.Id).ToArray()) is null)
        {
            throw new InvalidOperationException("The Zhangba Slash pair is no longer legal.");
        }

        foreach (var card in pair)
        {
            MoveCard(
                card,
                FindOwnedCardLocation(responder, card),
                CardLocation.Processing,
                CardMoveReasons.Respond);
            QueueGameEvent(new CardRespondedEvent(
                card.Id,
                responder.Seat,
                responseTargetSeat,
                CardKind.Slash));
        }
        QueueGameEvent(new ZhangbaSerpentSpearConvertedEvent(
            resolutionId,
            responder.Seat,
            Array.AsReadOnly(pair.Select(card => card.Id).ToArray()),
            IsUse: false,
            responseTargetSeat));
    }

    private void FinishZhangbaResponseCards(IReadOnlyList<Card> pair)
    {
        foreach (var card in pair)
        {
            MoveCard(
                card,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.ResponseFinished);
        }
    }

    private void BeginHujiaRequest(AttackResolution attack)
    {
        var owner = _players[attack.TargetSeat];
        if (!CanRequestHujia(owner, attack) || _pendingHujia is not null)
        {
            throw new InvalidOperationException("Hujia is not available for the current Dodge response.");
        }

        var candidateSeats = GetHujiaCandidateSeats(owner.Seat);
        attack.MarkHujiaAttempted();
        _pendingHujia = new HujiaResolution(attack, owner.Seat, candidateSeats);
        ClearPendingDecision();
        _status = EngineStatus.Running;
        QueueGameEvent(new HujiaRequestedEvent(attack.ResolutionId, owner.Seat, candidateSeats));
        AddLog(
            "SkillTriggered",
            $"{owner.Name} 发动主公技【护驾】，依次询问其他魏势力角色是否替其打出【闪】。",
            owner.Seat,
            attack.SourceSeat);
        AdvanceHujiaCandidate();
    }

    private void AdvanceHujiaCandidate()
    {
        var pending = _pendingHujia ??
            throw new InvalidOperationException("There is no active Hujia request.");
        if (!ReferenceEquals(_pendingAttack, pending.Attack))
        {
            throw new InvalidOperationException("The Hujia request no longer belongs to the active attack.");
        }

        while (pending.CandidateIndex < pending.CandidateSeats.Count)
        {
            var provider = _players[pending.CurrentCandidateSeat];
            var responseCards = provider.IsAlive &&
                                string.Equals(GetEffectiveFactionId(provider), "wei", StringComparison.Ordinal)
                ? GetResponseCards(provider, CardKind.Dodge)
                : [];
            var hasBagua = provider.IsAlive &&
                           HasBagua(provider);
            if (responseCards.Count == 0 && !hasBagua)
            {
                pending.CandidateIndex++;
                continue;
            }

            _pendingDecision = new PendingDecision(
                DecisionKind.RespondDodge,
                provider.Seat,
                $"{_players[pending.OwnerSeat].Name} 发动了【护驾】，是否替其打出【闪】？",
                responseCards.Select(card => card.Id).ToArray(),
                [],
                pending.Attack.SourceSeat,
                pending.Attack.EffectiveCardKind)
            {
                PromptId = CreatePromptId(),
                TargetSeat = pending.OwnerSeat,
                RequiredCardKind = CardKind.Dodge,
                Choices = CreateHujiaResponseChoices(provider, pending, responseCards, hasBagua)
            };
            _status = provider.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
            return;
        }

        var attack = pending.Attack;
        var ownerSeat = pending.OwnerSeat;
        _pendingHujia = null;
        QueueGameEvent(new HujiaResolvedEvent(
            attack.ResolutionId,
            ownerSeat,
            Succeeded: false,
            ProviderSeat: null,
            ResponseCardId: null));
        AddLog(
            "SkillResolved",
            $"没有魏势力角色响应 {_players[ownerSeat].Name} 的【护驾】。",
            ownerSeat,
            attack.SourceSeat);
        PublishOwnerDodgeDecision(attack);
    }

    private IReadOnlyList<PromptChoice> CreateHujiaResponseChoices(
        CharacterState provider,
        HujiaResolution pending,
        IReadOnlyList<Card> responseCards,
        bool includeBagua)
    {
        var choices = responseCards.SelectMany(card =>
        {
            var responseCardKind = GetEffectiveResponseKind(provider, card, CardKind.Dodge);
            var responseDescription = IsNativeResponseCard(card, CardKind.Dodge)
                ? "打出【闪】"
                : $"将【{card.DisplayName}】当作【闪】";
            return CreateConversionChoiceVariants(
                provider, card, responseCardKind, forResponse: true,
                $"hujia.dodge.card-{card.Id}",
                $"{responseDescription}，替 {_players[pending.OwnerSeat].Name} 响应【护驾】。",
                [card.Id],
                [pending.OwnerSeat],
                new Dictionary<string, string>
                {
                    ["response"] = "hujia-dodge",
                    ["response-card-kind"] = responseCardKind.ToString(),
                    ["skill"] = SkillKind.Hujia.ToString()
                });
        }).ToList();
        if (includeBagua)
        {
            choices.Add(new PromptChoice(
                new ChoiceId("hujia.bagua"),
                "发动【八卦阵】判定；若为红色，视为替护驾发起者打出【闪】。",
                [],
                [pending.OwnerSeat],
                new Dictionary<string, string>
                {
                    ["response"] = "hujia-bagua",
                    ["skill"] = SkillKind.Hujia.ToString(),
                    ["equipment"] = CardKind.BaguaFormation.ToString()
                }));
        }

        choices.Add(new PromptChoice(
            new ChoiceId("hujia.decline"),
            "不响应【护驾】。",
            [],
            [pending.OwnerSeat],
            new Dictionary<string, string>
            {
                ["response"] = "hujia-decline",
                ["skill"] = SkillKind.Hujia.ToString()
            }));
        return choices;
    }

    private void ResolveHujiaCandidateResponse(
        HujiaResolution pending,
        bool useDodge,
        bool useBagua,
        int? requestedCardId)
    {
        if (!ReferenceEquals(_pendingHujia, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack) ||
            _pendingDecision is not { Kind: DecisionKind.RespondDodge } decision ||
            decision.PlayerSeat != pending.CurrentCandidateSeat ||
            useDodge && useBagua)
        {
            throw new InvalidOperationException("The Hujia response is not the current continuation.");
        }

        var provider = _players[pending.CurrentCandidateSeat];
        var selectedDodge = useDodge
            ? GetResponseCards(provider, CardKind.Dodge)
                .FirstOrDefault(card => card.Id == requestedCardId)
            : null;
        if (useDodge && selectedDodge is null)
        {
            throw new InvalidOperationException("The Hujia responder has no matching Dodge response card.");
        }

        if (useBagua && (!HasBagua(provider)))
        {
            throw new InvalidOperationException("The Hujia responder cannot use Bagua in this response window.");
        }

        ClearPendingDecision();
        _status = EngineStatus.Running;
        if (selectedDodge is not null)
        {
            CompleteHujiaResponse(pending, provider, selectedDodge, usedBagua: false);
            return;
        }

        if (useBagua)
        {
            var judgmentResult = BeginJudgment(
                pending.Attack,
                provider.Seat,
                JudgmentReasons.BaguaDefense,
                pending.Attack.ResolutionId,
                pending.Attack.EffectiveCardKind,
                JudgmentContinuationKind.HujiaBagua,
                damageSkill: null);
            if (judgmentResult is { } succeeded)
            {
                CompleteHujiaBaguaResponse(pending.Attack, succeeded);
            }
            return;
        }

        AddLog(
            "SkillSkipped",
            $"{provider.Name} 选择不响应 {_players[pending.OwnerSeat].Name} 的【护驾】。",
            provider.Seat,
            pending.OwnerSeat);
        pending.CandidateIndex++;
        AdvanceHujiaCandidate();
    }

    private void CompleteHujiaResponse(
        HujiaResolution pending,
        CharacterState provider,
        Card? selectedDodge,
        bool usedBagua)
    {
        var attack = pending.Attack;
        var owner = _players[pending.OwnerSeat];
        if (!ReferenceEquals(_pendingHujia, pending) ||
            !ReferenceEquals(_pendingAttack, attack) ||
            provider.Seat != pending.CurrentCandidateSeat)
        {
            throw new InvalidOperationException("The completed Hujia response is not current.");
        }

        PopResponseWindow(attack.ResolutionId);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingHujia = null;
        ClearPendingDecision();
        CardKind? responseCardKind = null;
        CardConversionSource? responseConversion = null;
        CardLocation? responseFrom = null;
        if (selectedDodge is not null)
        {
            responseCardKind = GetEffectiveResponseKind(provider, selectedDodge, CardKind.Dodge);
            responseConversion = GetSelectedResponseConversion(provider, selectedDodge, responseCardKind.Value);
            responseFrom = FindOwnedCardLocation(provider, selectedDodge);
            MoveCard(
                selectedDodge,
                responseFrom.Value,
                CardLocation.Processing,
                CardMoveReasons.Respond);
        }

        AddLog(
            "CardResponded",
            usedBagua
                ? $"{provider.Name} 发动【八卦阵】响应【护驾】，视为 {owner.Name} 打出【闪】。"
                : $"{provider.Name} 响应【护驾】，替 {owner.Name} 打出【闪】。",
            provider.Seat,
            owner.Seat);
        QueueGameEvent(new HujiaResolvedEvent(
            attack.ResolutionId,
            owner.Seat,
            Succeeded: true,
            provider.Seat,
            selectedDodge?.Id,
            usedBagua));
        if (selectedDodge is not null)
        {
            QueueGameEvent(new CardRespondedEvent(
                selectedDodge.Id,
                owner.Seat,
                attack.SourceSeat,
                responseCardKind ?? CardKind.Dodge));
        }

        if (_pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack } group &&
            ReferenceEquals(group.CurrentAttack, attack))
        {
            QueueGameEvent(new GroupResponseEvent(
                group.ResolutionId,
                group.Card.Kind,
                CardKind.Dodge,
                owner.Seat,
                UsedResponse: true,
                ResponseCardId: selectedDodge?.Id,
                ResponseCardKind: CardKind.Dodge));
        }

        if (selectedDodge is not null)
        {
            var responseCost = new CardActionCost(selectedDodge.Id, selectedDodge.Kind, responseFrom!.Value);
            if (TryBeginCardResponsePrograms(
                    attack,
                    owner,
                    provider,
                    requesterSeat: owner.Seat,
                    attack.SourceSeat,
                    responseCardKind ?? CardKind.Dodge,
                    [responseCost],
                    ProgramCardContinuation.HujiaDodge,
                    responseConversion))
            {
                return;
            }
            MoveCard(
                selectedDodge,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.ResponseFinished);
        }
        else if (usedBagua && TryBeginCardResponsePrograms(
                     attack,
                     owner,
                     provider,
                     requesterSeat: owner.Seat,
                     attack.SourceSeat,
                     CardKind.Dodge,
                     [],
                     ProgramCardContinuation.HujiaDodge))
        {
            return;
        }

        CompleteSuccessfulDodgeResponse(attack);
    }

    private void CompleteSuccessfulDodgeResponse(AttackResolution attack)
    {
        if (TryBeginLeijiChoice(attack))
        {
            return;
        }

        FinishSuccessfulDodgeResponse(attack);
    }

    private void FinishSuccessfulDodgeResponse(AttackResolution attack)
    {
        var completed = attack.RegisterDodgeResponse();
        if (attack.RequiredDodgeResponses > 1)
        {
            QueueGameEvent(new RequiredResponseProgressEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                attack.TargetSeat,
                RequireAttackCardKind(attack),
                CardKind.Dodge,
                attack.SuccessfulDodgeResponses,
                attack.RequiredDodgeResponses));
        }

        if (completed)
        {
            if (TryBeginMengjinChoice(attack))
            {
                return;
            }

            if (TryBeginQinglongCrescentBladeChoice(attack))
            {
                return;
            }

            if (TryBeginStoneAxeChoice(attack))
            {
                return;
            }

            CompleteAttack(attack);
            return;
        }

        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        ContinueSlashAfterTieqi(attack);
    }

    private bool TryBeginLeijiChoice(AttackResolution attack)
    {
        var owner = _players[attack.TargetSeat];
        var targetSeats = _players
            .Where(player => player.IsAlive && player.Seat != owner.Seat)
            .Select(player => player.Seat)
            .ToArray();
        if (!owner.IsAlive || !HasRuntimeSkill(owner, SkillKind.Leiji) || targetSeats.Length == 0)
        {
            return false;
        }

        if (_pendingLeiji is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Leiji choices at once.");
        }

        var pending = new LeijiResolution(attack, owner.Seat);
        _pendingLeiji = pending;
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        var choices = targetSeats.Select(targetSeat => new PromptChoice(
                new ChoiceId($"leiji.target-{targetSeat}"),
                $"发动【雷击】，令 {_players[targetSeat].Name} 进行判定。",
                [],
                [targetSeat],
                new Dictionary<string, string> { ["action"] = "leiji-target" }))
            .Append(new PromptChoice(
                new ChoiceId("leiji.skip"),
                "不发动【雷击】。",
                [],
                [],
                new Dictionary<string, string> { ["action"] = "leiji-skip" }))
            .ToArray();
        _pendingDecision = new PendingDecision(
            DecisionKind.Leiji,
            owner.Seat,
            $"{owner.Name} 使用或打出【闪】，是否发动【雷击】？",
            [],
            targetSeats,
            SourceSeat: owner.Seat,
            IncomingCard: CardKind.Dodge)
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            TargetSeat = owner.Seat,
            IsPrivate = true
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private void ResolveLeijiChoice(LeijiResolution pending, int? targetSeat)
    {
        if (!ReferenceEquals(_pendingLeiji, pending) ||
            !ReferenceEquals(_pendingAttack, pending.OriginalAttack))
        {
            throw new InvalidOperationException("The Leiji choice has no current Dodge continuation.");
        }

        ClearPendingDecision();
        if (targetSeat is null)
        {
            AddLog("SkillSkipped", $"{_players[pending.OwnerSeat].Name} 未发动【雷击】。", pending.OwnerSeat);
            _pendingLeiji = null;
            FinishSuccessfulDodgeResponse(pending.OriginalAttack);
            return;
        }

        if (targetSeat == pending.OwnerSeat || !_players[targetSeat.Value].IsAlive)
        {
            throw new InvalidOperationException("Leiji requires another living target.");
        }

        pending.TargetSeat = targetSeat.Value;
        AddLog("SkillTriggered",
            $"{_players[pending.OwnerSeat].Name} 发动【雷击】，令 {_players[targetSeat.Value].Name} 进行判定。",
            pending.OwnerSeat, targetSeat.Value);
        BeginJudgment(
            attack: pending.OriginalAttack,
            targetSeat.Value,
            JudgmentReasons.Leiji,
            pending.OriginalAttack.ResolutionId,
            CardKind.Dodge,
            JudgmentContinuationKind.Leiji,
            damageSkill: null,
            sourceSeat: pending.OwnerSeat);
    }

    private int GetMengjinTargetCardCount(CharacterState target) =>
        GetHand(target).Count + GetEquipment(target).Count;

    private bool TryBeginMengjinChoice(AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!UsesFormalPangDe ||
            attack.EffectiveCardKind is not (CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash) ||
            !source.IsAlive ||
            !target.IsAlive ||
            !HasRuntimeSkill(source, SkillKind.Mengjin) ||
            GetMengjinTargetCardCount(target) == 0)
        {
            return false;
        }

        if (_pendingMengjin is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Mengjin choices at once.");
        }

        _pendingMengjin = new MengjinResolution(attack);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        PublishMengjinChoice(_pendingMengjin);
        return true;
    }

    private void PublishMengjinChoice(MengjinResolution pending)
    {
        if (!ReferenceEquals(_pendingMengjin, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack))
        {
            throw new InvalidOperationException("The Mengjin choice has no current Slash continuation.");
        }

        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var hand = GetHand(target);
        var equipment = GetEquipment(target);
        if (hand.Count + equipment.Count == 0)
        {
            FinishMengjin(pending, discarded: null);
            return;
        }

        var choices = new List<PromptChoice>();
        for (var slot = 0; slot < hand.Count; slot++)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"mengjin.hand-slot-{slot}.resolution-{attack.ResolutionId}"),
                $"发动【猛进】，弃置 {target.Name} 的第 {slot + 1} 个暗手牌位。",
                [],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["action"] = "mengjin-discard",
                    ["target-zone"] = "hand",
                    ["slot-index"] = slot.ToString(System.Globalization.CultureInfo.InvariantCulture)
                }));
        }
        foreach (var card in equipment)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"mengjin.equipment-{card.Id}.resolution-{attack.ResolutionId}"),
                $"发动【猛进】，弃置 {target.Name} 装备区的【{card.DisplayName}】。",
                [card.Id],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["action"] = "mengjin-discard",
                    ["target-zone"] = "equipment"
                }));
        }
        choices.Add(new PromptChoice(
            new ChoiceId($"mengjin.skip.resolution-{attack.ResolutionId}"),
            "不发动【猛进】，结束此【杀】的结算。",
            [],
            [],
            new Dictionary<string, string> { ["action"] = "mengjin-skip" }));

        _pendingDecision = new PendingDecision(
            DecisionKind.Mengjin,
            source.Seat,
            $"你的【{CardCatalog.Get(RequireAttackCardKind(attack)).DisplayName}】已被 {target.Name} 的【闪】抵消，是否发动【猛进】弃置其一张手牌或装备？",
            equipment.Select(card => card.Id).ToArray(),
            [target.Seat],
            SourceSeat: source.Seat,
            IncomingCard: attack.EffectiveCardKind)
        {
            PromptId = source.IsHuman ? CreatePromptId() : default,
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices = choices
        };
        _status = source.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private void ResolveMengjinChoice(PromptChoice selected)
    {
        var pending = _pendingMengjin ??
            throw new InvalidOperationException("There is no Mengjin choice to resolve.");
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.Mengjin } decision ||
            decision.PlayerSeat != attack.SourceSeat)
        {
            throw new InvalidOperationException("The Mengjin choice is not the current Slash continuation.");
        }

        var target = _players[attack.TargetSeat];
        var action = selected.Parameters.GetValueOrDefault("action");
        Card? discarded = null;
        if (action == "mengjin-discard" && selected.Targets.SequenceEqual([target.Seat]))
        {
            var targetZone = selected.Parameters.GetValueOrDefault("target-zone");
            if (targetZone == "hand" &&
                selected.Cards.Count == 0 &&
                selected.Parameters.TryGetValue("slot-index", out var slotText) &&
                int.TryParse(slotText, System.Globalization.NumberStyles.None,
                    System.Globalization.CultureInfo.InvariantCulture, out var slot) &&
                slot >= 0 && slot < GetHand(target).Count)
            {
                discarded = GetHand(target)[slot];
            }
            else if (targetZone == "equipment" &&
                     selected.Cards.Count == 1 &&
                     GetEquipment(target).SingleOrDefault(card => card.Id == selected.Cards[0]) is { } equipment)
            {
                discarded = equipment;
            }
            else
            {
                throw new InvalidOperationException("The selected Mengjin target card is no longer available.");
            }
        }
        else if (action != "mengjin-skip" || selected.Cards.Count != 0 || selected.Targets.Count != 0)
        {
            throw new InvalidOperationException("The Mengjin choice is malformed.");
        }

        FinishMengjin(pending, discarded);
    }

    private void FinishMengjin(MengjinResolution pending, Card? discarded)
    {
        if (!ReferenceEquals(_pendingMengjin, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack))
        {
            throw new InvalidOperationException("The completed Mengjin continuation is invalid.");
        }

        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        _pendingMengjin = null;
        ClearPendingDecision();
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        if (discarded is not null)
        {
            MoveCard(discarded, FindOwnedCardLocation(target, discarded), CardLocation.DiscardPile,
                CardMoveReasons.MengjinDiscard);
        }
        QueueGameEvent(new MengjinResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            Used: discarded is not null,
            DiscardedCardId: discarded?.Id));
        AddLog(
            discarded is null ? "SkillSkipped" : "SkillTriggered",
            discarded is null
                ? $"{source.Name} 未发动【猛进】，结束对 {target.Name} 的【杀】结算。"
                : $"{source.Name} 发动【猛进】，弃置 {target.Name} 的【{discarded.DisplayName}】。",
            source.Seat,
            target.Seat);

        if (TryBeginQinglongCrescentBladeChoice(attack)) return;
        if (TryBeginStoneAxeChoice(attack)) return;
        CompleteAttack(attack);
    }

    private bool CanUseQinglongCrescentBladeTarget(
        CharacterState source,
        CharacterState target,
        CardKind? effectiveKind = null) =>
        source.IsAlive &&
        target.IsAlive &&
        source.Seat != target.Seat &&
        GetEquipment(source).Any(card => card.Kind == CardKind.QinglongCrescentBlade) &&
        (effectiveKind is { } kind
            ? !IsCardUseForbidden(source.Seat, kind, CardActionType.Use) &&
              (HasCardDistanceExemption(source, target, kind) ||
               GetCombatDistance(source.Seat, target.Seat) <= GetAttackRange(source.Seat)) &&
              !IsDirectedCardTargetProhibited(source.Seat, target.Seat, kind) &&
              !IsSlashProhibited(target)
            : SlashKinds.Any(candidate => CanUseQinglongCrescentBladeTarget(source, target, candidate)));

    private IReadOnlyList<Card> GetQinglongCrescentBladeSlashCards(
        CharacterState source,
        CharacterState target) =>
        CanUseQinglongCrescentBladeTarget(source, target)
            ? GetSlashUseCards(source).Where(card =>
                GetSlashUseVariants(source, IsSlashCard(card.Kind) ? card.Kind : CardKind.Slash)
                    .Any(variant => CanUseQinglongCrescentBladeTarget(
                        source, target, variant.EffectiveKind))).ToArray()
            : [];

    private bool CanRequestQinglongCrescentBladeJijiang(
        QinglongCrescentBladeResolution pending)
    {
        var source = _players[pending.Attack.SourceSeat];
        var target = _players[pending.Attack.TargetSeat];
        return UsesFormalJijiang &&
               _pendingJijiang is null &&
               !pending.JijiangAttempted &&
               source.Role == Role.Lord &&
               HasRuntimeSkill(source, SkillKind.Jijiang) &&
               CanUseQinglongCrescentBladeTarget(source, target) &&
               GetJijiangCandidateSeats(source.Seat).Count > 0;
    }

    private bool TryBeginQinglongCrescentBladeChoice(AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var effectiveKind = RequireAttackCardKind(attack);
        if (!UsesFormalQinglongCrescentBlade ||
            effectiveKind is not (CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash))
        {
            return false;
        }

        if (_pendingQinglongCrescentBlade is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Qinglong Crescent Blade choices at once.");
        }

        var pending = new QinglongCrescentBladeResolution(attack);
        var slashes = GetQinglongCrescentBladeSlashCards(source, target);
        if (slashes.Count == 0 && !CanRequestQinglongCrescentBladeJijiang(pending))
        {
            return false;
        }

        _pendingQinglongCrescentBlade = pending;
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        PublishQinglongCrescentBladeChoice(pending, includeJijiang: true);
        return true;
    }

    private void PublishQinglongCrescentBladeChoice(
        QinglongCrescentBladeResolution pending,
        bool includeJijiang)
    {
        if (!ReferenceEquals(_pendingQinglongCrescentBlade, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack))
        {
            throw new InvalidOperationException("The Qinglong Crescent Blade choice has no current Slash continuation.");
        }

        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var effectiveKind = RequireAttackCardKind(attack);
        var slashes = GetQinglongCrescentBladeSlashCards(source, target);
        var choices = slashes.SelectMany(card =>
        {
            var followupKind = IsSlashCard(card.Kind) ? card.Kind : CardKind.Slash;
            var cardDescription = IsSlashCard(card.Kind)
                ? $"使用【{CardCatalog.Get(card.Kind).DisplayName}】"
                : $"将【{card.DisplayName}】当作【杀】使用";
            return CreateConversionChoiceVariants(
                source, card, followupKind, forResponse: false,
                $"qinglong.slash.resolution-{attack.ResolutionId}.card-{card.Id}",
                $"{cardDescription}，继续攻击 {target.Name}。",
                [card.Id],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["action"] = "qinglong-slash",
                    ["response-card-kind"] = followupKind.ToString()
                });
        }).ToList();
        if (includeJijiang && CanRequestQinglongCrescentBladeJijiang(pending))
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"qinglong.jijiang.resolution-{attack.ResolutionId}"),
                $"发动【激将】，请求其他蜀势力角色为你对 {target.Name} 提供一张【杀】。",
                [],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["action"] = "qinglong-jijiang",
                    ["skill"] = SkillKind.Jijiang.ToString()
                }));
        }
        choices.Add(new PromptChoice(
            new ChoiceId($"qinglong.skip.resolution-{attack.ResolutionId}"),
            "不发动【青龙偃月刀】，此【杀】被【闪】抵消。",
            [],
            [],
            new Dictionary<string, string> { ["action"] = "qinglong-skip" }));

        _pendingDecision = new PendingDecision(
            DecisionKind.QinglongCrescentBlade,
            source.Seat,
            $"{target.Name} 已用【闪】抵消你的【{CardCatalog.Get(effectiveKind).DisplayName}】，是否发动【青龙偃月刀】对其再使用一张【杀】？",
            slashes.Select(card => card.Id).ToArray(),
            [target.Seat],
            SourceSeat: source.Seat,
            IncomingCard: effectiveKind)
        {
            PromptId = source.IsHuman ? CreatePromptId() : default,
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices = choices
        };
        _status = source.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private void ResolveQinglongCrescentBladeChoice(PromptChoice selected)
    {
        var pending = _pendingQinglongCrescentBlade ??
            throw new InvalidOperationException("There is no Qinglong Crescent Blade choice to resolve.");
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.QinglongCrescentBlade } decision ||
            decision.PlayerSeat != attack.SourceSeat)
        {
            throw new InvalidOperationException("The Qinglong Crescent Blade choice is not the current Slash continuation.");
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var action = selected.Parameters.GetValueOrDefault("action");
        var usesSlash = action == "qinglong-slash";
        var requestsJijiang = action == "qinglong-jijiang";
        Card? slash = null;
        CardKind? effectiveSlashKind = null;
        if (usesSlash)
        {
            if (!CanUseQinglongCrescentBladeTarget(source, target) ||
                selected.Cards.Count != 1 ||
                !selected.Targets.SequenceEqual([target.Seat]))
            {
                throw new InvalidOperationException("Qinglong Crescent Blade must retain its source, weapon and same target.");
            }

            slash = GetQinglongCrescentBladeSlashCards(source, target)
                .SingleOrDefault(card => card.Id == selected.Cards[0]) ??
                throw new InvalidOperationException("The selected Qinglong Crescent Blade Slash is no longer available.");
            effectiveSlashKind = IsSlashCard(slash.Kind) ? slash.Kind : CardKind.Slash;
            if (!CanUseQinglongCrescentBladeTarget(source, target, effectiveSlashKind))
                throw new InvalidOperationException(
                    "The selected Qinglong Crescent Blade Slash kind is prohibited for its target.");
        }
        else if (requestsJijiang)
        {
            if (selected.Cards.Count != 0 ||
                !selected.Targets.SequenceEqual([target.Seat]) ||
                !CanRequestQinglongCrescentBladeJijiang(pending))
            {
                throw new InvalidOperationException("Qinglong Crescent Blade Jijiang is no longer available.");
            }

            BeginQinglongCrescentBladeJijiangRequest(pending);
            return;
        }
        else if (action != "qinglong-skip" || selected.Cards.Count != 0 || selected.Targets.Count != 0)
        {
            throw new InvalidOperationException("The Qinglong Crescent Blade choice is malformed.");
        }

        if (usesSlash)
        {
            BeginQinglongCrescentBladeFollowup(
                pending,
                slash!,
                effectiveSlashKind!.Value,
                source.Seat,
                [slash!]);
            return;
        }

        _pendingQinglongCrescentBlade = null;
        ClearPendingDecision();
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new QinglongCrescentBladeResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            Used: false,
            SlashCardIds: [],
            EffectiveSlashKind: null));
        AddLog(
            "EquipmentSkipped",
            $"{source.Name} 未发动【青龙偃月刀】，对 {target.Name} 的【杀】被【闪】抵消。",
            source.Seat,
            target.Seat);

        CompleteAttack(attack);
    }

    private void BeginQinglongCrescentBladeFollowup(
        QinglongCrescentBladeResolution pending,
        Card slash,
        CardKind effectiveSlashKind,
        int physicalOwnerSeat,
        IReadOnlyList<Card> physicalCards,
        JijiangResolution? jijiang = null,
        CardConversionSource? conversionSource = null)
    {
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingQinglongCrescentBlade, pending) ||
            !ReferenceEquals(_pendingAttack, attack))
        {
            throw new InvalidOperationException("The Qinglong Crescent Blade follow-up is not current.");
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        _pendingQinglongCrescentBlade = null;
        ClearPendingDecision();
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new QinglongCrescentBladeResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            Used: true,
            Array.AsReadOnly(physicalCards.Select(card => card.Id).ToArray()),
            effectiveSlashKind));
        AddLog(
            "EquipmentEffect",
            $"{source.Name} 发动【青龙偃月刀】，对 {target.Name} 再使用一张【{CardCatalog.Get(effectiveSlashKind).DisplayName}】。",
            source.Seat,
            target.Seat);

        CompleteAttack(attack);
        ResolveSlashCore(
            source,
            target,
            slash,
            effectiveSlashKind,
            physicalOwnerSeat,
            activeJijiang: jijiang,
            physicalCards: physicalCards,
            countsTowardSlashLimit: false,
            conversionSource: conversionSource);
    }

    private bool TryBeginStoneAxeChoice(AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var effectiveKind = RequireAttackCardKind(attack);
        var discardableCards = GetStoneAxeDiscardCards(source);
        if (!UsesFormalStoneAxe ||
            effectiveKind is not (CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash) ||
            !source.IsAlive ||
            !target.IsAlive ||
            GetEquipment(source).All(card => card.Kind != CardKind.StoneAxe) ||
            discardableCards.Count < 2)
        {
            return false;
        }

        if (_pendingStoneAxe is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Stone Axe choices at once.");
        }

        var choices = new List<PromptChoice>();
        for (var first = 0; first < discardableCards.Count - 1; first++)
        {
            for (var second = first + 1; second < discardableCards.Count; second++)
            {
                var firstCard = discardableCards[first];
                var secondCard = discardableCards[second];
                choices.Add(new PromptChoice(
                    new ChoiceId($"stone-axe.use.resolution-{attack.ResolutionId}.cards-{firstCard.Id}-{secondCard.Id}"),
                    $"弃置{DescribeStoneAxeCost(source, firstCard)}与{DescribeStoneAxeCost(source, secondCard)}，令此【{CardCatalog.Get(effectiveKind).DisplayName}】仍造成伤害。",
                    [firstCard.Id, secondCard.Id],
                    [],
                    new Dictionary<string, string> { ["action"] = "stone-axe-use" }));
            }
        }

        choices.Add(new PromptChoice(
            new ChoiceId($"stone-axe.skip.resolution-{attack.ResolutionId}"),
            "不发动【贯石斧】，此【杀】被【闪】抵消。",
            [],
            [],
            new Dictionary<string, string> { ["action"] = "stone-axe-skip" }));

        _pendingStoneAxe = new StoneAxeResolution(
            attack,
            discardableCards.Select(card => card.Id).ToArray());
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        _pendingDecision = new PendingDecision(
            DecisionKind.StoneAxe,
            source.Seat,
            $"{target.Name} 已用【闪】抵消你的【{CardCatalog.Get(effectiveKind).DisplayName}】，是否弃置两张牌发动【贯石斧】？",
            discardableCards.Select(card => card.Id).ToArray(),
            [],
            SourceSeat: source.Seat,
            IncomingCard: effectiveKind)
        {
            PromptId = source.IsHuman ? CreatePromptId() : default,
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices = choices
        };
        _status = source.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private IReadOnlyList<Card> GetStoneAxeDiscardCards(CharacterState source) =>
        GetHand(source).Concat(GetEquipment(source)).ToArray();

    private string DescribeStoneAxeCost(CharacterState source, Card card)
    {
        var zone = _cardZones.GetLocation(card.Id) == CardLocation.Equipment(source.Seat)
            ? "装备区"
            : "手牌";
        return $"【{card.DisplayName}】（{zone}）";
    }

    private void ResolveStoneAxeChoice(IReadOnlyList<int> discardedCardIds)
    {
        var pending = _pendingStoneAxe ??
            throw new InvalidOperationException("There is no Stone Axe choice to resolve.");
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.StoneAxe } decision ||
            decision.PlayerSeat != attack.SourceSeat)
        {
            throw new InvalidOperationException("The Stone Axe choice is not the current Slash continuation.");
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var distinctIds = discardedCardIds.Distinct().ToArray();
        var useStoneAxe = distinctIds.Length > 0;
        if (useStoneAxe &&
            (distinctIds.Length != 2 ||
             distinctIds.Any(id => !pending.CandidateCardIds.Contains(id))))
        {
            throw new InvalidOperationException("Stone Axe requires two distinct cards from the published candidate set.");
        }

        var currentCards = GetStoneAxeDiscardCards(source);
        var selectedCards = distinctIds
            .Select(id => currentCards.SingleOrDefault(card => card.Id == id) ??
                throw new InvalidOperationException("A selected Stone Axe cost card is no longer owned by its source."))
            .ToArray();
        _pendingStoneAxe = null;
        ClearPendingDecision();
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);

        if (useStoneAxe)
        {
            foreach (var card in selectedCards)
            {
                MoveCard(
                    card,
                    _cardZones.GetLocation(card.Id),
                    CardLocation.Processing,
                    CardMoveReasons.StoneAxeDiscard);
            }
            foreach (var card in selectedCards)
            {
                MoveCard(
                    card,
                    CardLocation.Processing,
                    CardLocation.DiscardPile,
                    CardMoveReasons.StoneAxeDiscard);
            }
        }

        QueueGameEvent(new StoneAxeResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            useStoneAxe,
            Array.AsReadOnly(distinctIds)));
        AddLog(
            useStoneAxe ? "EquipmentEffect" : "EquipmentSkipped",
            useStoneAxe
                ? $"{source.Name} 弃置两张牌发动【贯石斧】，令对 {target.Name} 的【杀】仍造成伤害。"
                : $"{source.Name} 未发动【贯石斧】，对 {target.Name} 的【杀】被【闪】抵消。",
            source.Seat,
            target.Seat);

        if (useStoneAxe)
        {
            if (!ApplyAttackDamage(attack))
            {
                CompleteAttack(attack);
            }
            return;
        }

        CompleteAttack(attack);
    }

    private void CompleteHujiaBaguaResponse(AttackResolution attack, bool succeeded)
    {
        var pending = _pendingHujia ??
            throw new InvalidOperationException("A Hujia Bagua judgment has no Hujia continuation.");
        if (!ReferenceEquals(pending.Attack, attack))
        {
            throw new InvalidOperationException("The Hujia Bagua judgment belongs to another attack.");
        }

        var provider = _players[pending.CurrentCandidateSeat];
        if (succeeded)
        {
            CompleteHujiaResponse(pending, provider, selectedDodge: null, usedBagua: true);
            return;
        }

        AddLog(
            "SkillResolved",
            $"{provider.Name} 以【八卦阵】响应【护驾】，但判定失败。",
            provider.Seat,
            pending.OwnerSeat);
        pending.CandidateIndex++;
        AdvanceHujiaCandidate();
    }

    private void PublishOwnerDodgeDecision(AttackResolution attack)
    {
        var owner = _players[attack.TargetSeat];
        var dodges = GetResponseCards(owner, CardKind.Dodge);
        var hasBagua = !attack.IgnoresArmor && HasBagua(owner);
        _pendingDecision = new PendingDecision(
            DecisionKind.RespondDodge,
            owner.Seat,
            "【护驾】无人响应，是否由你自己打出【闪】？",
            dodges.Select(card => card.Id).ToArray(),
            [],
            attack.SourceSeat,
            attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            RequiredCardKind = CardKind.Dodge,
            Choices = CreateResponseChoices(
                dodges,
                CardKind.Dodge,
                attack.EffectiveCardKind,
                card => GetEffectiveResponseKind(owner, card, CardKind.Dodge),
                includeBagua: hasBagua,
                includeHujia: false,
                responder: owner)
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private void BeginJijiangResponseRequest(AttackResolution attack)
    {
        if (_pendingJijiang is not null)
        {
            throw new InvalidOperationException("Another Jijiang request is already active.");
        }

        JijiangPurpose purpose;
        CharacterState owner;
        if (_pendingDuel is { } duel && ReferenceEquals(duel.Attack, attack))
        {
            purpose = JijiangPurpose.DuelResponse;
            owner = _players[duel.ResponderSeat];
            if (!CanRequestJijiangResponse(owner, attack))
            {
                throw new InvalidOperationException("Jijiang is not available for this Duel response.");
            }
            duel.JijiangAttempted = true;
        }
        else if (_pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack, RequiredCardKind: CardKind.Slash } group &&
                 ReferenceEquals(group.CurrentAttack, attack))
        {
            purpose = JijiangPurpose.GroupResponse;
            owner = _players[attack.TargetSeat];
            if (!CanRequestJijiangResponse(owner, attack))
            {
                throw new InvalidOperationException("Jijiang is not available for this group response.");
            }
            attack.MarkJijiangAttempted();
        }
        else
        {
            throw new InvalidOperationException("Jijiang requires a Duel or Barbarian Assault Slash response.");
        }

        var candidateSeats = GetJijiangCandidateSeats(owner.Seat);
        _pendingJijiang = new JijiangResolution(
            attack.ResolutionId,
            purpose,
            owner.Seat,
            candidateSeats,
            responseAttack: attack);
        ClearPendingDecision();
        _status = EngineStatus.Running;
        QueueGameEvent(new JijiangRequestedEvent(
            attack.ResolutionId,
            owner.Seat,
            candidateSeats,
            IsActiveUse: false));
        AddLog(
            "SkillTriggered",
            $"{owner.Name} 发动主公技【激将】，依次询问其他蜀势力角色是否替其打出【杀】。",
            owner.Seat,
            attack.SourceSeat);
        AdvanceJijiangCandidate();
    }

    private void BeginBorrowedSwordJijiangRequest(BorrowedSwordResolution borrowedSword)
    {
        if (_pendingJijiang is not null ||
            !ReferenceEquals(_pendingBorrowedSword, borrowedSword) ||
            !borrowedSword.AwaitingSlashChoice ||
            !CanRequestBorrowedSwordJijiang(borrowedSword))
        {
            throw new InvalidOperationException("Jijiang is not available for this Borrowed Sword use.");
        }

        var owner = _players[borrowedSword.WeaponOwnerSeat];
        var candidateSeats = GetJijiangCandidateSeats(owner.Seat);
        borrowedSword.JijiangAttempted = true;
        borrowedSword.AwaitingSlashChoice = false;
        _pendingJijiang = new JijiangResolution(
            borrowedSword.ResolutionId,
            JijiangPurpose.BorrowedSwordUse,
            owner.Seat,
            candidateSeats,
            targetSeat: borrowedSword.SlashTargetSeat,
            borrowedSword: borrowedSword);
        ClearPendingDecision();
        _status = EngineStatus.Running;
        QueueGameEvent(new JijiangRequestedEvent(
            borrowedSword.ResolutionId,
            owner.Seat,
            candidateSeats,
            IsActiveUse: true,
            borrowedSword.SlashTargetSeat));
        AddLog(
            "SkillTriggered",
            $"{owner.Name} 在【借刀杀人】结算中发动主公技【激将】，请求其他蜀势力角色为其对 {_players[borrowedSword.SlashTargetSeat].Name} 提供【杀】。",
            owner.Seat,
            borrowedSword.SlashTargetSeat);
        AdvanceJijiangCandidate();
    }

    private void BeginQinglongCrescentBladeJijiangRequest(
        QinglongCrescentBladeResolution qinglong)
    {
        if (_pendingJijiang is not null ||
            !ReferenceEquals(_pendingQinglongCrescentBlade, qinglong) ||
            !CanRequestQinglongCrescentBladeJijiang(qinglong))
        {
            throw new InvalidOperationException("Jijiang is not available for this Qinglong Crescent Blade use.");
        }

        var attack = qinglong.Attack;
        var owner = _players[attack.SourceSeat];
        var candidateSeats = GetJijiangCandidateSeats(owner.Seat);
        qinglong.JijiangAttempted = true;
        _pendingJijiang = new JijiangResolution(
            attack.ResolutionId,
            JijiangPurpose.QinglongCrescentBladeUse,
            owner.Seat,
            candidateSeats,
            targetSeat: attack.TargetSeat,
            qinglongCrescentBlade: qinglong);
        ClearPendingDecision();
        _status = EngineStatus.Running;
        QueueGameEvent(new JijiangRequestedEvent(
            attack.ResolutionId,
            owner.Seat,
            candidateSeats,
            IsActiveUse: true,
            attack.TargetSeat));
        AddLog(
            "SkillTriggered",
            $"{owner.Name} 在【青龙偃月刀】结算中发动主公技【激将】，请求其他蜀势力角色为其对 {_players[attack.TargetSeat].Name} 提供【杀】。",
            owner.Seat,
            attack.TargetSeat);
        AdvanceJijiangCandidate();
    }

    private void AdvanceJijiangCandidate()
    {
        var pending = _pendingJijiang ??
            throw new InvalidOperationException("There is no active Jijiang request.");
        if (!pending.AwaitingProviders)
        {
            throw new InvalidOperationException("The Jijiang provider cursor has already completed.");
        }

        while (pending.CandidateIndex < pending.CandidateSeats.Count)
        {
            var provider = _players[pending.CurrentCandidateSeat];
            var slashes = provider.IsAlive &&
                          string.Equals(GetEffectiveFactionId(provider), "shu", StringComparison.Ordinal)
                ? GetJijiangSlashCards(pending, provider)
                : [];
            var zhangbaPairs = provider.IsAlive &&
                               string.Equals(GetEffectiveFactionId(provider), "shu", StringComparison.Ordinal)
                ? GetZhangbaSlashPairs(provider)
                : [];
            var isResponse = !pending.IsActiveUse && !pending.IsBorrowedSwordUse &&
                             !pending.IsQinglongCrescentBladeUse;
            var programMultiCardConversions = provider.IsAlive &&
                                              string.Equals(GetEffectiveFactionId(provider), "shu", StringComparison.Ordinal)
                ? GetProgramMultiCardViewAsSelections(provider, CardKind.Slash, isResponse)
                : [];
            if (slashes.Count == 0 && zhangbaPairs.Count == 0 && programMultiCardConversions.Count == 0)
            {
                pending.CandidateIndex++;
                continue;
            }

            _pendingDecision = new PendingDecision(
                DecisionKind.RespondSlash,
                provider.Seat,
                $"{_players[pending.OwnerSeat].Name} 发动了【激将】，是否替其打出【杀】？",
                slashes.Select(card => card.Id)
                    .Concat(zhangbaPairs.SelectMany(pair => pair.Select(card => card.Id)))
                    .Concat(programMultiCardConversions.SelectMany(item => item.Cards.Select(card => card.Id)))
                    .Distinct()
                    .ToArray(),
                [],
                SourceSeat: pending.OwnerSeat,
                IncomingCard: CardKind.Slash)
            {
                PromptId = CreatePromptId(),
                TargetSeat = pending.OwnerSeat,
                RequiredCardKind = CardKind.Slash,
                Choices = CreateJijiangResponseChoices(provider, pending, slashes)
            };
            _status = provider.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
            return;
        }

        CompleteJijiangFailure(pending);
    }

    private IReadOnlyList<PromptChoice> CreateJijiangResponseChoices(
        CharacterState provider,
        JijiangResolution pending,
        IReadOnlyList<Card> slashes)
    {
        var responseTargets = pending.TargetSeat is { } responseTargetSeat
            ? new[] { responseTargetSeat }
            : new[] { pending.OwnerSeat };
        var isResponse = !pending.IsActiveUse && !pending.IsBorrowedSwordUse &&
                         !pending.IsQinglongCrescentBladeUse;
        var choices = slashes.SelectMany(card =>
        {
            var effectiveKind = GetJijiangEffectiveSlashKind(pending, provider, card);
            var description = IsNativeResponseCard(card, CardKind.Slash)
                ? $"打出【{CardCatalog.Get(effectiveKind).DisplayName}】"
                : $"将【{card.DisplayName}】当作【杀】";
            return CreateConversionChoiceVariants(
                provider, card, effectiveKind, isResponse,
                $"jijiang.slash.card-{card.Id}",
                $"{description}，替 {_players[pending.OwnerSeat].Name} 响应【激将】。",
                [card.Id],
                responseTargets,
                new Dictionary<string, string>
                {
                    ["response"] = "jijiang-slash",
                    ["response-card-kind"] = effectiveKind.ToString(),
                    ["skill"] = SkillKind.Jijiang.ToString()
                });
        }).ToList();
        foreach (var pair in GetZhangbaSlashPairs(provider))
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"jijiang.zhangba-slash.cards-{pair[0].Id}-{pair[1].Id}"),
                $"发动【丈八蛇矛】，将两张手牌当【杀】替 {_players[pending.OwnerSeat].Name} 响应【激将】。",
                [pair[0].Id, pair[1].Id],
                responseTargets,
                new Dictionary<string, string>
                {
                    ["response"] = "zhangba-slash",
                    ["response-card-kind"] = CardKind.Slash.ToString(),
                    ["skill"] = SkillKind.Jijiang.ToString(),
                    ["equipment"] = CardKind.ZhangbaSerpentSpear.ToString()
                }));
        }
        foreach (var selection in GetProgramMultiCardViewAsSelections(
                     provider, CardKind.Slash, isResponse))
        {
            var cardIds = selection.Cards.Select(card => card.Id).ToArray();
            var parameters = new Dictionary<string, string>
            {
                ["response"] = "program-view-as-slash",
                ["response-card-kind"] = CardKind.Slash.ToString(),
                ["skill"] = SkillKind.Jijiang.ToString()
            };
            AddConversionParameters(parameters, selection.Source);
            choices.Add(new PromptChoice(
                new ChoiceId($"jijiang.program-view-as-slash.{selection.Source.SkillId.Length}:" +
                             $"{selection.Source.SkillId}.{selection.Source.BindingId}.cards-{string.Join('-', cardIds)}"),
                $"发动【{ProgramConversionName(selection.Source)}】，将 {cardIds.Length} 张手牌当【杀】替 {_players[pending.OwnerSeat].Name} 响应【激将】。",
                cardIds,
                responseTargets,
                parameters));
        }
        choices.Add(new PromptChoice(
            new ChoiceId("jijiang.decline"),
            "不响应【激将】。",
            [],
            responseTargets,
            new Dictionary<string, string>
            {
                ["response"] = "jijiang-decline",
                ["skill"] = SkillKind.Jijiang.ToString()
            }));
        return choices;
    }

    private void ResolveJijiangCandidateResponse(
        JijiangResolution pending,
        bool useSlash,
        int? requestedCardId,
        CardKind? requestedEffectiveKind = null)
    {
        if (!ReferenceEquals(_pendingJijiang, pending) ||
            !pending.AwaitingProviders ||
            _pendingDecision is not { Kind: DecisionKind.RespondSlash } decision ||
            decision.PlayerSeat != pending.CurrentCandidateSeat)
        {
            throw new InvalidOperationException("The Jijiang response is not the current continuation.");
        }

        var provider = _players[pending.CurrentCandidateSeat];
        var selectedSlash = useSlash
            ? GetJijiangSlashCards(pending, provider)
                .FirstOrDefault(card => card.Id == requestedCardId)
            : null;
        if (useSlash && selectedSlash is null)
        {
            throw new InvalidOperationException("The Jijiang responder has no matching Slash response card.");
        }

        ClearPendingDecision();
        _status = EngineStatus.Running;
        if (selectedSlash is not null)
        {
            var baseEffectiveKind = GetJijiangEffectiveSlashKind(pending, provider, selectedSlash);
            var effectiveKind = requestedEffectiveKind ?? baseEffectiveKind;
            if (effectiveKind != baseEffectiveKind)
            {
                throw new InvalidOperationException("A Jijiang provider cannot choose the owner's weapon conversion.");
            }

            if (TryBeginJijiangZhuqueFanChoice(
                    pending,
                    provider,
                    [selectedSlash],
                    baseEffectiveKind))
            {
                return;
            }

            if (pending.IsBorrowedSwordUse)
            {
                BeginBorrowedSwordJijiangSlash(
                    pending,
                    provider,
                    [selectedSlash],
                    effectiveKind,
                    usesZhuqueFan: false);
            }
            else if (pending.IsQinglongCrescentBladeUse)
            {
                BeginQinglongCrescentBladeJijiangSlash(
                    pending,
                    provider,
                    [selectedSlash],
                    effectiveKind,
                    usesZhuqueFan: false);
            }
            else if (pending.IsActiveUse)
            {
                BeginProvidedJijiangSlash(
                    pending,
                    provider,
                    [selectedSlash],
                    effectiveKind,
                    usesZhuqueFan: false);
            }
            else
            {
                CompleteJijiangResponse(pending, provider, selectedSlash);
            }
            return;
        }

        AddLog(
            "SkillSkipped",
            $"{provider.Name} 选择不响应 {_players[pending.OwnerSeat].Name} 的【激将】。",
            provider.Seat,
            pending.OwnerSeat);
        pending.CandidateIndex++;
        AdvanceJijiangCandidate();
    }

    private void ResolveJijiangZhangbaCandidateResponse(
        JijiangResolution pending,
        CharacterState provider,
        IReadOnlyList<Card> pair)
    {
        if (!ReferenceEquals(_pendingJijiang, pending) ||
            !pending.AwaitingProviders ||
            provider.Seat != pending.CurrentCandidateSeat ||
            FindZhangbaSlashPair(provider, pair.Select(card => card.Id).ToArray()) is null)
        {
            throw new InvalidOperationException("The Zhangba Jijiang response is not current.");
        }

        var owner = _players[pending.OwnerSeat];
        if (TryBeginJijiangZhuqueFanChoice(
                pending,
                provider,
                pair,
                CardKind.Slash))
        {
            return;
        }

        if (pending.IsBorrowedSwordUse)
        {
            ClearPendingDecision();
            BeginBorrowedSwordJijiangSlash(
                pending,
                provider,
                pair,
                CardKind.Slash,
                usesZhuqueFan: false);
            return;
        }

        if (pending.IsQinglongCrescentBladeUse)
        {
            ClearPendingDecision();
            BeginQinglongCrescentBladeJijiangSlash(
                pending,
                provider,
                pair,
                CardKind.Slash,
                usesZhuqueFan: false);
            return;
        }

        if (pending.IsActiveUse)
        {
            ClearPendingDecision();
            BeginProvidedJijiangSlash(
                pending,
                provider,
                pair,
                CardKind.Slash,
                usesZhuqueFan: false);
            return;
        }

        var attack = pending.ResponseAttack ??
            throw new InvalidOperationException("A response Jijiang has no attack continuation.");
        var duel = pending.Purpose == JijiangPurpose.DuelResponse
            ? _pendingDuel ?? throw new InvalidOperationException("A Duel Jijiang response has no Duel continuation.")
            : null;
        var responseOpponentSeat = duel?.OpponentSeat ?? attack.SourceSeat;
        PopResponseWindow(attack.ResolutionId);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingJijiang = null;
        ClearPendingDecision();
        MoveZhangbaResponseCards(provider, pair, pending.ResolutionId, responseOpponentSeat);
        QueueGameEvent(new JijiangResolvedEvent(
            pending.ResolutionId,
            owner.Seat,
            Succeeded: true,
            provider.Seat,
            pair[0].Id,
            CardKind.Slash,
            IsActiveUse: false));
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(owner.Seat, CardKind.Slash);
        FinishZhangbaResponseCards(pair);

        if (pending.Purpose == JijiangPurpose.DuelResponse)
        {
            QueueGameEvent(new DuelResponseEvent(
                duel!.ResolutionId,
                owner.Seat,
                UsedSlash: true,
                SlashCardId: pair[0].Id,
                ResponseCardKind: CardKind.Slash));
            ContinueDuelAfterSuccessfulSlash(duel, owner.Seat);
            return;
        }

        var group = _pendingGroupCard ??
            throw new InvalidOperationException("A group Jijiang response has no group continuation.");
        QueueGameEvent(new GroupResponseEvent(
            group.ResolutionId,
            group.Card.Kind,
            CardKind.Slash,
            owner.Seat,
            UsedResponse: true,
            ResponseCardId: pair[0].Id,
            ResponseCardKind: CardKind.Slash));
        CompleteAttack(attack);
    }

    private void ResolveJijiangProgramMultiCardCandidateResponse(
        JijiangResolution pending,
        CharacterState provider,
        ProgramMultiCardViewAsSelection selection)
    {
        if (!ReferenceEquals(_pendingJijiang, pending) ||
            !pending.AwaitingProviders ||
            provider.Seat != pending.CurrentCandidateSeat ||
            FindProgramMultiCardViewAsSelection(
                provider,
                selection.Cards.Select(card => card.Id).ToArray(),
                CardKind.Slash,
                forResponse: !pending.IsActiveUse && !pending.IsBorrowedSwordUse &&
                             !pending.IsQinglongCrescentBladeUse,
                selection.Source) is null)
        {
            throw new InvalidOperationException("The configured Jijiang conversion is not current.");
        }

        var owner = _players[pending.OwnerSeat];
        var conversion = selection.Source;
        if (pending.IsBorrowedSwordUse)
        {
            ClearPendingDecision();
            BeginBorrowedSwordJijiangSlash(
                pending,
                provider,
                selection.Cards,
                CardKind.Slash,
                usesZhuqueFan: false,
                conversionSource: conversion);
            return;
        }

        if (pending.IsQinglongCrescentBladeUse)
        {
            ClearPendingDecision();
            BeginQinglongCrescentBladeJijiangSlash(
                pending,
                provider,
                selection.Cards,
                CardKind.Slash,
                usesZhuqueFan: false,
                conversionSource: conversion);
            return;
        }

        if (pending.IsActiveUse)
        {
            ClearPendingDecision();
            BeginProvidedJijiangSlash(
                pending,
                provider,
                selection.Cards,
                CardKind.Slash,
                usesZhuqueFan: false,
                conversionSource: conversion);
            return;
        }

        var attack = pending.ResponseAttack ??
            throw new InvalidOperationException("A response Jijiang has no attack continuation.");
        var duel = pending.Purpose == JijiangPurpose.DuelResponse
            ? _pendingDuel ?? throw new InvalidOperationException("A Duel Jijiang response has no Duel continuation.")
            : null;
        var responseOpponentSeat = duel?.OpponentSeat ?? attack.SourceSeat;
        PopResponseWindow(attack.ResolutionId);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingJijiang = null;
        ClearPendingDecision();
        MoveProgramMultiCardResponse(
            provider,
            selection,
            pending.ResolutionId,
            responseOpponentSeat,
            owner.Seat);
        QueueGameEvent(new JijiangResolvedEvent(
            pending.ResolutionId,
            owner.Seat,
            Succeeded: true,
            provider.Seat,
            selection.Cards[0].Id,
            CardKind.Slash,
            IsActiveUse: false));
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(owner.Seat, CardKind.Slash);
        FinishProgramMultiCardResponse(selection);

        if (pending.Purpose == JijiangPurpose.DuelResponse)
        {
            QueueGameEvent(new DuelResponseEvent(
                duel!.ResolutionId,
                owner.Seat,
                UsedSlash: true,
                SlashCardId: selection.Cards[0].Id,
                ResponseCardKind: CardKind.Slash));
            ContinueDuelAfterSuccessfulSlash(duel, owner.Seat);
            return;
        }

        var group = _pendingGroupCard ??
            throw new InvalidOperationException("A group Jijiang response has no group continuation.");
        QueueGameEvent(new GroupResponseEvent(
            group.ResolutionId,
            group.Card.Kind,
            CardKind.Slash,
            owner.Seat,
            UsedResponse: true,
            ResponseCardId: selection.Cards[0].Id,
            ResponseCardKind: CardKind.Slash));
        CompleteAttack(attack);
    }

    private void CompleteJijiangFailure(JijiangResolution pending)
    {
        if (!ReferenceEquals(_pendingJijiang, pending))
        {
            throw new InvalidOperationException("The failed Jijiang request is not current.");
        }

        _pendingJijiang = null;
        QueueGameEvent(new JijiangResolvedEvent(
            pending.ResolutionId,
            pending.OwnerSeat,
            Succeeded: false,
            ProviderSeat: null,
            SlashCardId: null,
            EffectiveSlashKind: null,
            pending.IsActiveUse || pending.IsBorrowedSwordUse || pending.IsQinglongCrescentBladeUse,
            pending.TargetSeat));
        AddLog(
            "SkillResolved",
            $"没有蜀势力角色响应 {_players[pending.OwnerSeat].Name} 的【激将】。",
            pending.OwnerSeat,
            pending.TargetSeat);

        if (pending.IsBorrowedSwordUse)
        {
            var borrowedSword = pending.BorrowedSword ??
                throw new InvalidOperationException("A Borrowed Sword Jijiang failure has no parent resolution.");
            if (_resolutionStack.LastOrDefault() is ResponseWindowFrame response &&
                response.ParentFrameId == borrowedSword.ResolutionId)
            {
                PopResponseWindow(borrowedSword.ResolutionId);
            }

            BeginBorrowedSwordSlashChoice(borrowedSword, includeJijiang: false);
            return;
        }

        if (pending.IsQinglongCrescentBladeUse)
        {
            var qinglong = pending.QinglongCrescentBlade ??
                throw new InvalidOperationException("A Qinglong Crescent Blade Jijiang failure has no parent resolution.");
            PublishQinglongCrescentBladeChoice(qinglong, includeJijiang: false);
            return;
        }

        if (!pending.IsActiveUse)
        {
            PublishOwnerSlashDecision(pending);
            return;
        }

        var frameId = pending.ActiveSkillFrameId ??
            throw new InvalidOperationException("An active Jijiang failure has no active-skill frame.");
        var owner = _players[pending.OwnerSeat];
        if (!owner.IsHuman)
        {
            owner.AiJijiangFailedThisTurn = true;
        }
        ActiveActionExecutor.CompleteFactionRequest(RequireActiveAction(frameId), this);
        _status = EngineStatus.Running;
    }

    private void PublishOwnerSlashDecision(JijiangResolution failedRequest)
    {
        var owner = _players[failedRequest.OwnerSeat];
        var slashes = GetResponseCards(owner, CardKind.Slash);
        var incomingCard = failedRequest.Purpose switch
        {
            JijiangPurpose.DuelResponse => CardKind.Duel,
            JijiangPurpose.GroupResponse => _pendingGroupCard?.Card.Kind ?? CardKind.BarbarianAssault,
            _ => throw new InvalidOperationException("Only response Jijiang can restore an owner response prompt.")
        };
        var sourceSeat = failedRequest.Purpose == JijiangPurpose.DuelResponse
            ? _pendingDuel?.OpponentSeat
            : _pendingGroupCard?.SourceSeat;
        _pendingDecision = new PendingDecision(
            DecisionKind.RespondSlash,
            owner.Seat,
            "【激将】无人响应，是否由你自己打出【杀】？",
            slashes.Select(card => card.Id).ToArray(),
            [],
            sourceSeat,
            incomingCard)
        {
            PromptId = CreatePromptId(),
            RequiredCardKind = CardKind.Slash,
            Choices = CreateResponseChoices(
                slashes,
                CardKind.Slash,
                incomingCard,
                card => GetEffectiveResponseKind(owner, card, CardKind.Slash),
                includeJijiang: false,
                responder: owner)
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private void CompleteJijiangResponse(
        JijiangResolution pending,
        CharacterState provider,
        Card selectedSlash)
    {
        var attack = pending.ResponseAttack ??
            throw new InvalidOperationException("A response Jijiang has no attack continuation.");
        if (!ReferenceEquals(_pendingJijiang, pending) ||
            !ReferenceEquals(_pendingAttack, attack) ||
            provider.Seat != pending.CurrentCandidateSeat)
        {
            throw new InvalidOperationException("The completed Jijiang response is not current.");
        }

        var owner = _players[pending.OwnerSeat];
        var effectiveKind = GetEffectiveResponseKind(provider, selectedSlash, CardKind.Slash);
        var responseConversion = GetSelectedResponseConversion(provider, selectedSlash, effectiveKind);
        var responseFrom = FindOwnedCardLocation(provider, selectedSlash);
        var duel = pending.Purpose == JijiangPurpose.DuelResponse
            ? _pendingDuel ?? throw new InvalidOperationException("A Duel Jijiang response has no Duel continuation.")
            : null;
        var responseOpponentSeat = duel?.OpponentSeat ?? attack.SourceSeat;
        PopResponseWindow(attack.ResolutionId);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingJijiang = null;
        ClearPendingDecision();
        MoveCard(
            selectedSlash,
            responseFrom,
            CardLocation.Processing,
            CardMoveReasons.Respond);
        AddLog(
            "CardResponded",
            $"{provider.Name} 响应【激将】，替 {owner.Name} 打出【{CardCatalog.Get(effectiveKind).DisplayName}】。",
            provider.Seat,
            owner.Seat);
        QueueGameEvent(new JijiangResolvedEvent(
            pending.ResolutionId,
            owner.Seat,
            Succeeded: true,
            provider.Seat,
            selectedSlash.Id,
            effectiveKind,
            IsActiveUse: false));
        QueueGameEvent(new CardRespondedEvent(
            selectedSlash.Id,
            owner.Seat,
            responseOpponentSeat,
            effectiveKind));
        MarkSlashUsedOrPlayedDuringCurrentPlayPhase(owner.Seat, effectiveKind);

        if (pending.Purpose == JijiangPurpose.DuelResponse)
        {
            QueueGameEvent(new DuelResponseEvent(
                duel!.ResolutionId,
                owner.Seat,
                UsedSlash: true,
                SlashCardId: selectedSlash.Id,
                ResponseCardKind: effectiveKind));
            var responseCost = new CardActionCost(selectedSlash.Id, selectedSlash.Kind, responseFrom);
            if (TryBeginCardResponsePrograms(
                    attack,
                    owner,
                    provider,
                    requesterSeat: owner.Seat,
                    responseOpponentSeat,
                    effectiveKind,
                    [responseCost],
                    ProgramCardContinuation.JijiangDuelSlash,
                    responseConversion))
            {
                return;
            }
            MoveCard(
                selectedSlash,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.ResponseFinished);
            ContinueDuelAfterSuccessfulSlash(duel, owner.Seat);
            return;
        }

        var group = _pendingGroupCard ??
            throw new InvalidOperationException("A group Jijiang response has no group continuation.");
        QueueGameEvent(new GroupResponseEvent(
            group.ResolutionId,
            group.Card.Kind,
            CardKind.Slash,
            owner.Seat,
            UsedResponse: true,
            ResponseCardId: selectedSlash.Id,
            ResponseCardKind: effectiveKind));
        var groupResponseCost = new CardActionCost(selectedSlash.Id, selectedSlash.Kind, responseFrom);
        if (TryBeginCardResponsePrograms(
                attack,
                owner,
                provider,
                requesterSeat: owner.Seat,
                responseOpponentSeat,
                effectiveKind,
                [groupResponseCost],
                ProgramCardContinuation.JijiangGroupResponse,
                responseConversion))
        {
            return;
        }
        MoveCard(
            selectedSlash,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.ResponseFinished);
        CompleteAttack(attack);
    }

    private void BeginProvidedJijiangSlash(
        JijiangResolution pending,
        CharacterState provider,
        IReadOnlyList<Card> physicalCards,
        CardKind effectiveKind,
        bool usesZhuqueFan,
        CardConversionSource? conversionSource = null)
    {
        var selectedSlash = physicalCards.FirstOrDefault() ??
            throw new InvalidOperationException("An active Jijiang Slash must retain a physical card.");
        var owner = _players[pending.OwnerSeat];
        var target = _players[pending.TargetSeat ??
            throw new InvalidOperationException("An active Jijiang use has no target.")];
        if (!ReferenceEquals(_pendingJijiang, pending) ||
            !pending.IsActiveUse ||
            !CanUseProvidedSlashTarget(owner, target, effectiveKind))
        {
            throw new InvalidOperationException("The active Jijiang target is no longer legal.");
        }

        if (!CanSpendSlashUse(owner, target, ignoresCount: false, effectiveKind))
        {
            throw new InvalidOperationException("The Jijiang Slash limit has already been reached.");
        }

        pending.AwaitingProviders = false;
        var frameId = pending.ActiveSkillFrameId ??
            throw new InvalidOperationException("An active Jijiang use has no active-skill frame.");
        SetActiveSkillFrameStep(frameId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new JijiangResolvedEvent(
            frameId,
            owner.Seat,
            Succeeded: true,
            provider.Seat,
            selectedSlash.Id,
            effectiveKind,
            IsActiveUse: true,
            target.Seat));
        AddLog(
            "CardUsed",
            $"{provider.Name} 响应【激将】，由 {owner.Name} 对 {target.Name} 使用【{CardCatalog.Get(effectiveKind).DisplayName}】。",
            owner.Seat,
            target.Seat);
        ResolveSlashCore(
            owner,
            target,
            selectedSlash,
            effectiveKind,
            provider.Seat,
            pending,
            physicalCards: physicalCards,
            usesZhuqueFan: usesZhuqueFan,
            conversionSource: conversionSource);
    }

    private void BeginBorrowedSwordJijiangSlash(
        JijiangResolution pending,
        CharacterState provider,
        IReadOnlyList<Card> physicalCards,
        CardKind effectiveKind,
        bool usesZhuqueFan,
        CardConversionSource? conversionSource = null)
    {
        var selectedSlash = physicalCards.FirstOrDefault() ??
            throw new InvalidOperationException("A Borrowed Sword Jijiang Slash must retain a physical card.");
        var borrowedSword = pending.BorrowedSword ??
            throw new InvalidOperationException("A Borrowed Sword Jijiang use has no parent resolution.");
        var owner = _players[pending.OwnerSeat];
        var target = _players[pending.TargetSeat ??
            throw new InvalidOperationException("A Borrowed Sword Jijiang use has no target.")];
        if (!ReferenceEquals(_pendingJijiang, pending) ||
            !ReferenceEquals(_pendingBorrowedSword, borrowedSword) ||
            !pending.IsBorrowedSwordUse ||
            !IsLegalBorrowedSwordSlashTarget(owner, target, effectiveKind))
        {
            throw new InvalidOperationException("The Borrowed Sword Jijiang target is no longer legal.");
        }

        pending.AwaitingProviders = false;
        borrowedSword.AwaitingSlashChoice = false;
        borrowedSword.SlashCardId = selectedSlash.Id;
        borrowedSword.EffectiveSlashKind = effectiveKind;
        PopResponseWindow(borrowedSword.ResolutionId);
        SetCardUseStep(borrowedSword.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new JijiangResolvedEvent(
            borrowedSword.ResolutionId,
            owner.Seat,
            Succeeded: true,
            provider.Seat,
            selectedSlash.Id,
            effectiveKind,
            IsActiveUse: true,
            target.Seat));
        AddLog(
            "CardUsed",
            $"{provider.Name} 响应【激将】，由 {owner.Name} 按【借刀杀人】要求对 {target.Name} 使用【{CardCatalog.Get(effectiveKind).DisplayName}】。",
            owner.Seat,
            target.Seat);
        ResolveSlashCore(
            owner,
            target,
            selectedSlash,
            effectiveKind,
            provider.Seat,
            activeJijiang: pending,
            borrowedSword: borrowedSword,
            physicalCards: physicalCards,
            usesZhuqueFan: usesZhuqueFan,
            conversionSource: conversionSource);
    }

