    }

    private void ResolvePendingAiDuel()
    {
        var duel = _pendingDuel ??
            throw new InvalidOperationException("AI Duel continuation has no pending Duel.");
        var responder = _players[duel.ResponderSeat];
        if (_pendingDecision?.Choices.Any(choice =>
                choice.Parameters.GetValueOrDefault("response") == "jijiang-request") == true)
        {
            BeginJijiangResponseRequest(duel.Attack);
            PublishState();
            return;
        }
        var slashes = GetResponseCards(responder, CardKind.Slash);
        var zhangbaPair = GetZhangbaSlashPairs(responder).FirstOrDefault();
        var programSelection = GetProgramMultiCardViewAsSelections(
            responder, CardKind.Slash, forResponse: true).FirstOrDefault();
        PopResponseWindow(duel.ResolutionId);
        SetCardUseStep(duel.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingDecision = null;

        if (slashes.Count == 0 && zhangbaPair is null && programSelection is null)
        {
            ResolveDuelResponse(duel, responder, selectedSlash: null);
        }
        else
        {
            var view = CreateSnapshot(responder.Seat);
            var (useSlash, thought) = _aiBrains[responder.Seat].ChooseDuelResponse(
                view,
                duel.OpponentSeat,
                ++_thoughtSequence);
            AddThought(thought);
            if (useSlash && slashes.Count > 0)
            {
                ResolveDuelResponse(duel, responder, slashes[0]);
            }
            else if (useSlash && zhangbaPair is not null)
            {
                ResolveDuelZhangbaResponse(duel, responder, zhangbaPair);
            }
            else if (useSlash && programSelection is not null)
            {
                ResolveDuelProgramMultiCardResponse(duel, responder, programSelection);
            }
            else
            {
                ResolveDuelResponse(duel, responder, selectedSlash: null);
            }
        }

        PublishState();
    }

    private void ResolvePendingAiGroupAttack()
    {
        var group = _pendingGroupCard ??
            throw new InvalidOperationException("AI group response has no pending group attack.");
        var attack = group.CurrentAttack ??
            throw new InvalidOperationException("AI group response has no current target.");
        var responder = _players[attack.TargetSeat];
        if (_pendingDecision?.Choices.Any(choice =>
                choice.Parameters.GetValueOrDefault("response") == "jijiang-request") == true)
        {
            BeginJijiangResponseRequest(attack);
            PublishState();
            return;
        }
        if (_pendingDecision?.Choices.Any(choice =>
                choice.Parameters.GetValueOrDefault("response") == "hujia-request") == true)
        {
            BeginHujiaRequest(attack);
            PublishState();
            return;
        }

        var requiredCardKind = group.RequiredCardKind ??
            throw new InvalidOperationException("A group response attack must declare a required card kind.");
        var responseCards = GetResponseCards(responder, requiredCardKind);
        var zhangbaPair = requiredCardKind == CardKind.Slash
            ? GetZhangbaSlashPairs(responder).FirstOrDefault()
            : null;
        var programSelection = requiredCardKind == CardKind.Slash
            ? GetProgramMultiCardViewAsSelections(
                responder, CardKind.Slash, forResponse: true).FirstOrDefault()
            : null;
        var hasBagua = requiredCardKind == CardKind.Dodge &&
                       !attack.IgnoresArmor &&
                       HasBagua(responder);
        PopResponseWindow(group.ResolutionId);
        SetCardUseStep(group.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingDecision = null;

        if (responseCards.Count == 0 && zhangbaPair is null && programSelection is null && !hasBagua)
        {
            ResolveGroupResponse(group, responder, selectedResponse: null);
        }
        else if (requiredCardKind == CardKind.Dodge && hasBagua)
        {
            var view = CreateSnapshot(responder.Seat);
            var (useDodge, useBagua, thought) = _aiBrains[responder.Seat]
                .ChooseDodgeResponse(
                    view,
                    group.SourceSeat,
                    ++_thoughtSequence,
                    attack.IgnoresArmor,
                    legalDodgeAvailable: responseCards.Count > 0);
            AddThought(thought);
            if (useDodge)
            {
                ResolveGroupResponse(group, responder, responseCards.FirstOrDefault());
            }
            else if (useBagua)
            {
                var judgmentResult = ResolveBaguaJudgment(attack, responder);
                if (judgmentResult is { } succeeded)
                {
                    CompleteBaguaResponse(attack, succeeded);
                }
            }
            else
            {
                ResolveGroupResponse(group, responder, selectedResponse: null);
            }
        }
        else
        {
            var view = CreateSnapshot(responder.Seat);
            var (useResponse, thought) = _aiBrains[responder.Seat].ChooseGroupResponse(
                view,
                group.SourceSeat,
                group.Card.Kind,
                requiredCardKind,
                ++_thoughtSequence);
            AddThought(thought);
            if (useResponse && responseCards.Count > 0)
            {
                ResolveGroupResponse(group, responder, responseCards[0]);
            }
            else if (useResponse && zhangbaPair is not null)
            {
                ResolveGroupZhangbaResponse(group, responder, zhangbaPair);
            }
            else if (useResponse && programSelection is not null)
            {
                ResolveGroupProgramMultiCardResponse(group, responder, programSelection);
            }
            else
            {
                ResolveGroupResponse(group, responder, selectedResponse: null);
            }
        }

        PublishState();
    }

    private void ResolvePendingAiDodge()
    {
        var attack = _pendingAttack ??
            throw new InvalidOperationException("AI Dodge continuation has no pending Slash.");
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (_pendingDecision?.Choices.Any(choice =>
                choice.Parameters.GetValueOrDefault("response") == "hujia-request") == true)
        {
            BeginHujiaRequest(attack);
            PublishState();
            return;
        }

        PopResponseWindow(attack.ResolutionId);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingDecision = null;
        var dodges = GetResponseCards(target, CardKind.Dodge);
        var dodge = dodges.FirstOrDefault();
        var hasBagua = !attack.IgnoresArmor && HasBagua(target);

        if (!target.IsAlive || (dodge is null && !hasBagua))
        {
            if (!ApplyAttackDamage(attack))
            {
                CompleteAttack(attack);
            }
        }
        else
        {
            var view = CreateSnapshot(target.Seat);
            var (useDodge, useBagua, thought) = _aiBrains[target.Seat]
                .ChooseDodgeResponse(
                    view,
                    source.Seat,
                    ++_thoughtSequence,
                    attack.IgnoresArmor,
                    legalDodgeAvailable: dodge is not null);
            AddThought(thought);
            if (useDodge)
            {
                ResolveDodgeResponse(attack, target, dodge!);
            }
            else if (useBagua)
            {
                var judgmentResult = ResolveBaguaJudgment(attack, target);
                if (judgmentResult is { } succeeded)
                {
                    CompleteBaguaResponse(attack, succeeded);
                }
            }
            else
            {
                if (!ApplyAttackDamage(attack))
                {
                    CompleteAttack(attack);
                }
            }
        }

        PublishState();
    }

    private bool? ResolveBaguaJudgment(
        AttackResolution attack,
        CharacterState defender)
    {
        if (attack.IgnoresArmor)
        {
            throw new InvalidOperationException("The attacking weapon ignores armor, so Bagua cannot respond.");
        }

        if (!HasBagua(defender))
        {
            throw new InvalidOperationException("Bagua judgment requires Bagua equipment.");
        }

        return BeginJudgment(
            attack,
            defender.Seat,
            JudgmentReasons.BaguaDefense,
            attack.ResolutionId,
            attack.EffectiveCardKind,
            JudgmentContinuationKind.Bagua,
            damageSkill: null);
    }

    private void CompleteBaguaResponse(AttackResolution attack, bool succeeded)
    {
        if (_pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack } group &&
            ReferenceEquals(group.CurrentAttack, attack))
        {
            var requiredCardKind = group.RequiredCardKind ??
                throw new InvalidOperationException(
                    "A group response attack must declare a required card kind.");
            QueueGameEvent(new GroupResponseEvent(
                group.ResolutionId,
                group.Card.Kind,
                requiredCardKind,
                attack.TargetSeat,
                UsedResponse: succeeded,
                ResponseCardId: null,
                ResponseCardKind: succeeded ? CardKind.Dodge : null));
        }

        if (succeeded)
        {
            var continuation = _pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack } responseGroup &&
                               ReferenceEquals(responseGroup.CurrentAttack, attack)
                ? ProgramCardContinuation.GroupResponse
                : ProgramCardContinuation.Dodge;
            if (TryBeginCardResponsePrograms(
                    attack,
                    _players[attack.TargetSeat],
                    _players[attack.TargetSeat],
                    requesterSeat: null,
                    attack.SourceSeat,
                    CardKind.Dodge,
                    [],
                    continuation))
            {
                return;
            }
            CompleteSuccessfulDodgeResponse(attack);
        }
        else if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private bool? BeginJudgment(
        AttackResolution? attack,
        int targetSeat,
        string reason,
        long parentFrameId,
        CardKind? sourceCard,
        JudgmentContinuationKind continuation,
        DamageSkillResolution? damageSkill,
        Card? delayedCard = null,
        int? sourceSeat = null,
        string? programResultBind = null,
        SkillProgramCardSetVisibility? programResultVisibility = null)
    {
        if (_pendingJudgment is not null)
        {
            throw new InvalidOperationException("The engine cannot resolve two judgments at once.");
        }

        var frameId = ++_resolutionSequence;
        var frame = new JudgmentFrame(
            frameId,
            parentFrameId,
            targetSeat,
            reason,
            CardId: null,
            CardKind: null,
            Suit: null,
            Succeeded: null,
            ReplacementCandidateSeats: []);
        _resolutionStack.Add(frame);
        QueueGameEvent(new JudgmentRequestedEvent(
            frameId,
            parentFrameId,
            targetSeat,
            reason,
            sourceCard));

        if (!EnsureDrawPile())
        {
            frame = frame with
            {
                Succeeded = false,
                Step = ResolutionFrameStep.Completed
            };
            ReplaceJudgmentFrame(frame);
            QueueGameEvent(new JudgmentResolvedEvent(
                frameId,
                parentFrameId,
                targetSeat,
                reason,
                CardId: null,
                CardKind: null,
                Suit: null,
                Rank: null,
                Succeeded: false));
            AddLog(
                "Judgment",
                $"{_players[targetSeat].Name} 的判定因牌堆耗尽而失败。",
                targetSeat,
                sourceSeat ?? attack?.SourceSeat);
            PopResolutionFrame(frameId, ResolutionFrameKind.Judgment);
            if (IsDelayedJudgmentContinuation(continuation) ||
                continuation is JudgmentContinuationKind.Luoshen or JudgmentContinuationKind.Shuangxiong or
                    JudgmentContinuationKind.Leiji or JudgmentContinuationKind.ProgramSkill)
            {
                var exhaustedJudgment = new JudgmentResolution(
                    frameId,
                    parentFrameId,
                    attack,
                    sourceSeat ?? attack?.SourceSeat ?? targetSeat,
                    targetSeat,
                    reason,
                    continuation,
                    damageSkill,
                    [],
                    currentCard: null,
                    delayedCard,
                    programResultBind,
                    programResultVisibility);
                ResumeCompletedJudgment(exhaustedJudgment, succeeded: false);
            }

            return false;
        }

        var judgmentCard = _cardZones.CardsAt(CardLocation.DrawPile)[^1];
        frame = frame with
        {
            CardId = judgmentCard.Id,
            CardKind = judgmentCard.Kind,
            Suit = judgmentCard.Suit
        };
        ReplaceJudgmentFrame(frame);
        MoveCard(
            judgmentCard,
            CardLocation.DrawPile,
            CardLocation.Judgment(targetSeat),
            CardMoveReasons.JudgmentReveal);

        var candidates = CollectJudgmentReplacementCandidates(
            judgmentCard,
            targetSeat,
            reason);
        var orderedCandidates = candidates.ToArray();
        var orderedCandidateSeats = orderedCandidates
            .Select(candidate => candidate.OwnerSeat)
            .ToArray();
        frame = frame with
        {
            ReplacementCandidateSeats = Array.AsReadOnly(orderedCandidateSeats),
            ReplacementCandidateIndex = 0,
            Step = orderedCandidateSeats.Length == 0
                ? ResolutionFrameStep.ResolvingEffect
                : ResolutionFrameStep.AwaitingResponse
        };
        ReplaceJudgmentFrame(frame);

        var pending = new JudgmentResolution(
            frameId,
            parentFrameId,
            attack,
            sourceSeat ?? attack?.SourceSeat ?? targetSeat,
            targetSeat,
            reason,
            continuation,
            damageSkill,
            orderedCandidates,
            judgmentCard,
            delayedCard,
            programResultBind,
            programResultVisibility);
        if (orderedCandidateSeats.Length == 0)
        {
            var succeeded = FinalizeJudgment(pending);
            if (succeeded is { } completed &&
                (IsDelayedJudgmentContinuation(continuation) ||
                 continuation is JudgmentContinuationKind.Luoshen or JudgmentContinuationKind.Shuangxiong or
                     JudgmentContinuationKind.Leiji or JudgmentContinuationKind.ProgramSkill))
            {
                ResumeCompletedJudgment(pending, completed);
            }

            return succeeded;
        }

        _pendingJudgment = pending;
        BeginGuicaiChoice(pending);
        return null;
    }

    private IReadOnlyList<JudgmentTriggerCandidate> CollectJudgmentReplacementCandidates(
        Card judgmentCard,
        int targetSeat,
        string reason)
    {
        var candidates = new List<JudgmentTriggerCandidate>();
        foreach (var owner in _players.Where(player => player.IsAlive))
        {
            foreach (var skill in EnabledSkillRules(owner).Select(definition => definition.Judgment).OfType<IJudgmentSkillRule>())
            {
                var context = new JudgmentSkillContext(
                    CreateSkillContext(owner),
                    targetSeat,
                    reason,
                    judgmentCard.Id,
                    judgmentCard.Kind,
                    judgmentCard.Suit,
                    judgmentCard.Rank);
                if (!skill.CanTriggerBeforeJudgment(context) ||
                    !skill.OffersJudgmentCardChoice(context))
                {
                    continue;
                }

                candidates.Add(new JudgmentTriggerCandidate(
                    owner.Seat,
                    skill.Kind,
                    skill.JudgmentTriggerId,
                    skill.JudgmentTriggerPriority));
            }

            if (_contentRegistry is null)
            {
                continue;
            }

            foreach (var binding in EnabledUniqueProgramTriggers(
                         owner, SkillProgramTriggerWindow.JudgmentReplacing)
                     .OrderBy(item => item.SkillId, StringComparer.Ordinal)
                     .ThenBy(item => item.Trigger.Id, StringComparer.Ordinal))
            {
                var program = binding.Program;
                var trigger = binding.Trigger;
                if (!MatchesProgramJudgmentReplacement(owner, trigger, targetSeat, reason) ||
                    GetProgramJudgmentReplacementCards(owner, trigger, targetSeat, reason).Count == 0)
                {
                    continue;
                }

                candidates.Add(new JudgmentTriggerCandidate(
                    owner.Seat,
                    SkillKind.None,
                    $"program:{program.Id}:{trigger.Id}",
                    Priority: 0,
                    ProgramId: program.Id,
                    ProgramTriggerId: trigger.Id,
                    GameplayHash: program.GameplayHash));
            }
        }

        var orderingSeat = (_currentSeat );
        return JudgmentTriggerOrdering.Order(candidates, orderingSeat, _playerCount);
    }

    private void BeginGuicaiChoice(JudgmentResolution pending)
    {
        if (!ReferenceEquals(_pendingJudgment, pending) ||
            pending.CurrentCard is not { } judgmentCard)
        {
            throw new InvalidOperationException("The Guicai judgment is not the current resolution.");
        }

        if (pending.CandidateIndex >= pending.CandidateSeats.Count)
        {
            var succeeded = FinalizeJudgment(pending);
            if (succeeded is { } completed)
            {
                ResumeCompletedJudgment(pending, completed);
            }
            return;
        }

        var candidate = pending.CurrentCandidate ??
            throw new InvalidOperationException("The judgment replacement candidate cursor is invalid.");
        var owner = _players[candidate.OwnerSeat];
        if (candidate.IsProgram)
        {
            BeginProgramJudgmentReplacementChoice(pending, candidate);
            return;
        }
        var skill = EnabledSkillRules(owner).Select(definition => definition.Judgment).OfType<IJudgmentSkillRule>().Single(item => item.Kind == candidate.Skill);
        var context = new JudgmentSkillContext(
            CreateSkillContext(owner),
            pending.TargetSeat,
            pending.Reason,
            judgmentCard.Id,
            judgmentCard.Kind,
            judgmentCard.Suit,
            judgmentCard.Rank);
        if (!owner.IsAlive ||
            !skill.CanTriggerBeforeJudgment(context) ||
            !skill.OffersJudgmentCardChoice(context) ||
            GetJudgmentReplacementCards(
                owner, skill.Kind, pending.TargetSeat, pending.Reason).Count == 0)
        {
            AdvanceJudgmentCandidate(pending);
            return;
        }

        SetJudgmentFrameState(pending, ResolutionFrameStep.AwaitingResponse);
        QueueGameEvent(new JudgmentReplacementRequestedEvent(
            pending.FrameId,
            pending.FrameId,
            pending.TargetSeat,
            owner.Seat,
            pending.Reason,
            judgmentCard.Id,
            judgmentCard.Kind,
            judgmentCard.Suit));
        _pendingDecision = CreateGuicaiDecision(pending, owner, skill);
        _status = owner.IsHuman
            ? EngineStatus.AwaitingHumanResponse
            : EngineStatus.Running;
    }

    private PendingDecision CreateGuicaiDecision(
        JudgmentResolution pending,
        CharacterState owner,
        IJudgmentSkillRule skill)
    {
        var judgmentCard = pending.CurrentCard ??
            throw new InvalidOperationException("A Guicai prompt requires a public judgment card.");
        var target = _players[pending.TargetSeat];
        var replacementCards = GetJudgmentReplacementCards(
            owner, skill.Kind, pending.TargetSeat, pending.Reason);
        var choices = replacementCards
            .Select(card => new PromptChoice(
                new ChoiceId($"guicai.replace.frame-{pending.FrameId}.card-{card.Id}"),
                $"弃置【{card.DisplayName}】替换 {target.Name} 的判定牌。",
                [card.Id],
                [],
                new Dictionary<string, string>
                {
                    ["response"] = "guicai-replace",
                    ["action"] = "replace-judgment"
                }))
            .Append(new PromptChoice(
                new ChoiceId($"guicai.skip.frame-{pending.FrameId}.seat-{owner.Seat}"),
                $"不发动【{skill.Name}】，保留当前判定牌。",
                [],
                [],
                new Dictionary<string, string>
                {
                    ["response"] = "skip-guicai",
                    ["action"] = "skip-judgment-replacement"
                }))
            .ToArray();

        return new PendingDecision(
            skill.Kind == SkillKind.Guidao ? DecisionKind.Guidao : DecisionKind.Guicai,
            owner.Seat,
            $"{target.Name} 的【{judgmentCard.DisplayName}】（{judgmentCard.Suit}）即将判定，是否发动【{skill.Name}】替换？",
            replacementCards.Select(card => card.Id).ToArray(),
            [],
            SourceSeat: target.Seat,
            IncomingCard: judgmentCard.Kind)
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            RequiredCardKind = null,
            TargetSeat = target.Seat
        };
    }

    private IReadOnlyList<Card> GetJudgmentReplacementCards(
        CharacterState owner,
        SkillKind skill,
        int judgmentSubjectSeat,
        string judgmentReason) =>
        skill == SkillKind.Guidao
            ? GetHand(owner).Concat(GetEquipment(owner))
                .Where(card => !IsProtectedJudgmentSourceEquipment(
                    owner, card, judgmentSubjectSeat, judgmentReason))
                .Where(card => card.Suit is Suit.Spade or Suit.Club)
                .OrderBy(card => card.Id)
                .ToArray()
            : GetHand(owner).ToArray();

    private bool IsProtectedJudgmentSourceEquipment(
        CharacterState owner,
        Card card,
        int judgmentSubjectSeat,
        string judgmentReason) =>
        owner.Seat == judgmentSubjectSeat &&
        string.Equals(judgmentReason, JudgmentReasons.BaguaDefense, StringComparison.Ordinal) &&
        card.Kind == CardKind.BaguaFormation &&
        _cardZones.GetLocation(card.Id) == CardLocation.Equipment(owner.Seat);

    private void ResolveGuicaiChoice(
        JudgmentResolution pending,
        int? selectedCardId)
    {
        if (!ReferenceEquals(_pendingJudgment, pending) ||
            pending.CurrentCard is not { } oldJudgmentCard ||
            pending.CurrentCandidateSeat < 0)
        {
            throw new InvalidOperationException("The Guicai judgment is not the current resolution.");
        }

        var owner = _players[pending.CurrentCandidateSeat];
        if (selectedCardId is { } cardId)
        {
            var candidate = pending.CurrentCandidate ??
                throw new InvalidOperationException("The judgment replacement candidate cursor is invalid.");
            var skill = EnabledSkillRules(owner).Select(definition => definition.Judgment).OfType<IJudgmentSkillRule>().Single(item => item.Kind == candidate.Skill);
            var replacement = GetJudgmentReplacementCards(
                owner, skill.Kind, pending.TargetSeat, pending.Reason)
                .SingleOrDefault(card => card.Id == cardId) ??
                throw new InvalidOperationException("The selected judgment replacement card is no longer owned by the skill user.");
            if (_cardZones.GetLocation(oldJudgmentCard.Id) != CardLocation.Judgment(pending.TargetSeat))
            {
                throw new InvalidOperationException("The current judgment card is not in its judgment zone.");
            }

            MoveCard(
                oldJudgmentCard,
                CardLocation.Judgment(pending.TargetSeat),
                CardLocation.DiscardPile,
                CardMoveReasons.JudgmentFinish);
            var replacementFrom = _cardZones.GetLocation(replacement.Id);
            MoveCard(
                replacement,
                replacementFrom,
                CardLocation.Processing,
                skill.Kind == SkillKind.Guidao ? CardMoveReasons.GuidaoReplace : CardMoveReasons.GuicaiReplace);
            MoveCard(
                replacement,
                CardLocation.Processing,
                CardLocation.Judgment(pending.TargetSeat),
                skill.Kind == SkillKind.Guidao ? CardMoveReasons.GuidaoReplace : CardMoveReasons.GuicaiReplace);
            pending.CurrentCard = replacement;
            pending.WasReplaced = true;
            QueueGameEvent(new JudgmentReplacementResolvedEvent(
                pending.FrameId,
                pending.FrameId,
                pending.TargetSeat,
                owner.Seat,
                pending.Reason,
                Used: true,
                oldJudgmentCard.Id,
                replacement.Id,
                replacement.Kind,
                replacement.Suit,
                replacement.Rank));
            AddLog(
                "JudgmentReplaced",
                $"{owner.Name} 发动【{skill.Name}】替换了 {pending.Reason} 的判定牌。",
                owner.Seat,
                pending.TargetSeat);
        }
        else
        {
            var candidate = pending.CurrentCandidate ??
                throw new InvalidOperationException("The judgment replacement candidate cursor is invalid.");
            var skill = EnabledSkillRules(owner).Select(definition => definition.Judgment).OfType<IJudgmentSkillRule>().Single(item => item.Kind == candidate.Skill);
            QueueGameEvent(new JudgmentReplacementResolvedEvent(
                pending.FrameId,
                pending.FrameId,
                pending.TargetSeat,
                owner.Seat,
                pending.Reason,
                Used: false,
                oldJudgmentCard.Id,
                NewCardId: null,
                NewCardKind: null,
                NewSuit: null,
                NewRank: null));
            AddLog(
                "JudgmentReplacementSkipped",
                $"{owner.Name} 选择不发动【{skill.Name}】，保留当前判定牌。",
                owner.Seat,
                pending.TargetSeat);
        }

        AdvanceJudgmentCandidate(pending);
    }

    private void AdvanceJudgmentCandidate(JudgmentResolution pending)
    {
        if (!ReferenceEquals(_pendingJudgment, pending))
        {
            throw new InvalidOperationException("The Guicai judgment is not the current resolution.");
        }

        pending.CandidateIndex++;
        SetJudgmentFrameState(pending, pending.CandidateIndex >= pending.CandidateSeats.Count
            ? ResolutionFrameStep.ResolvingEffect
            : ResolutionFrameStep.AwaitingResponse);
        if (pending.CandidateIndex >= pending.CandidateSeats.Count)
        {
            var succeeded = FinalizeJudgment(pending);
            if (succeeded is { } completed)
            {
                ResumeCompletedJudgment(pending, completed);
            }
            return;
        }

        BeginGuicaiChoice(pending);
    }

    private bool? FinalizeJudgment(JudgmentResolution pending)
    {
        if (pending.CurrentCard is not { } judgmentCard)
        {
            throw new InvalidOperationException("A judgment cannot resolve without a card.");
        }

        var frame = GetJudgmentFrame(pending.FrameId);
        var judgmentSuit = EffectiveSuit(_players[pending.TargetSeat], judgmentCard);
        var succeeded = pending.Continuation switch
        {
            JudgmentContinuationKind.Lightning =>
                judgmentSuit == Suit.Spade && judgmentCard.Rank is >= 2 and <= 9,
            JudgmentContinuationKind.Ganglie when UsesClassicGanglieJudgment =>
                judgmentSuit != Suit.Heart,
            JudgmentContinuationKind.Indulgence =>
                judgmentSuit == Suit.Heart,                        JudgmentContinuationKind.SupplyShortage =>
                judgmentSuit == Suit.Club,                        JudgmentContinuationKind.Luoshen => !IsRedSuit(judgmentSuit),
            JudgmentContinuationKind.Shuangxiong => IsRedSuit(judgmentSuit),
            JudgmentContinuationKind.Leiji => judgmentSuit is Suit.Spade or Suit.Club,
            _ => IsRedSuit(judgmentSuit)
        };
        ReplaceJudgmentFrame(frame with
        {
            CardId = judgmentCard.Id,
            CardKind = judgmentCard.Kind,
            Suit = judgmentSuit,
            Succeeded = succeeded,
            ReplacementCandidateSeats = Array.AsReadOnly(pending.CandidateSeats.ToArray()),
            ReplacementCandidateIndex = pending.CandidateIndex,
            Step = ResolutionFrameStep.Completed
        });
        QueueGameEvent(new JudgmentResolvedEvent(
            pending.FrameId,
            frame.ParentFrameId,
            pending.TargetSeat,
            pending.Reason,
            judgmentCard.Id,
            judgmentCard.Kind,
            judgmentSuit,
            judgmentCard.Rank,
            succeeded));
        var abilityName = pending.Continuation switch
        {
            JudgmentContinuationKind.Bagua or JudgmentContinuationKind.HujiaBagua => "八卦阵",
            JudgmentContinuationKind.Ganglie => "刚烈",
            JudgmentContinuationKind.Indulgence => "乐不思蜀",
            JudgmentContinuationKind.SupplyShortage => "兵粮寸断",
            JudgmentContinuationKind.Lightning => "闪电",
            JudgmentContinuationKind.Luoshen => "洛神",
            JudgmentContinuationKind.Tieqi => "铁骑",
            JudgmentContinuationKind.Shuangxiong => "双雄",
            JudgmentContinuationKind.Leiji => "雷击",
            _ => pending.Reason
        };
        var judgmentResult = pending.Continuation == JudgmentContinuationKind.Lightning
            ? succeeded ? "命中" : "未命中"
            : succeeded ? "成功" : "失败";
        AddLog(
            "Judgment",
            $"{_players[pending.TargetSeat].Name} 发动【{abilityName}】判定：最终为【{judgmentCard.DisplayName}】（{judgmentCard.Suit} {judgmentCard.RankText}），判定{judgmentResult}。",
            pending.TargetSeat,
            pending.SourceSeat);
        pending.ResultSucceeded = succeeded;
        if (TryBeginProgramJudgmentWindow(pending, judgmentCard, judgmentSuit, succeeded))
        {
            return null;
        }

        return CompleteFinalizedJudgment(pending, judgmentCard, succeeded);
    }

    private bool? CompleteFinalizedJudgment(
        JudgmentResolution pending,
        Card judgmentCard,
        bool succeeded,
        bool allowPostJudgmentSkills = true)
    {
        if (allowPostJudgmentSkills &&
            pending.Continuation != JudgmentContinuationKind.Luoshen &&
            TryBeginTianduChoice(pending))
        {
            return null;
        }

        if (pending.Continuation == JudgmentContinuationKind.ProgramSkill)
        {
            FinishProgramSkillJudgment(pending, judgmentCard);
            return succeeded;
        }

        var claimedByLuoshen = pending.Continuation == JudgmentContinuationKind.Luoshen && succeeded;
        var claimedByShuangxiong = pending.Continuation == JudgmentContinuationKind.Shuangxiong;
        FinishResolvedJudgment(
            pending,
            claimedByLuoshen ? SkillKind.Luoshen : claimedByShuangxiong ? SkillKind.Shuangxiong : null);
        if (claimedByShuangxiong)
        {
            _shuangxiongJudgmentWasRed = IsRedSuit(judgmentCard.Suit);
            QueueGameEvent(new JudgmentCardClaimedEvent(pending.FrameId, pending.TargetSeat,
                SkillKind.Shuangxiong, true, judgmentCard.Id, judgmentCard.Kind));
        }
        if (pending.Continuation == JudgmentContinuationKind.Luoshen)
        {
            QueueGameEvent(new JudgmentCardClaimedEvent(
                pending.FrameId,
                pending.TargetSeat,
                SkillKind.Luoshen,
                claimedByLuoshen,
                judgmentCard.Id,
                judgmentCard.Kind));
            if (claimedByLuoshen)
            {
                AddLog(
                    "SkillTriggered",
                    $"{_players[pending.TargetSeat].Name} 的【洛神】判定为黑色，获得判定牌【{judgmentCard.DisplayName}】。",
                    pending.TargetSeat);
            }
        }
        return succeeded;
    }

    private bool TryBeginTianduChoice(JudgmentResolution pending)
    {
        if (!UsesFormalTiandu || pending.CurrentCard is not { } judgmentCard)
        {
            return false;
        }

        var owner = _players[pending.TargetSeat];
        var skill = EnabledSkillRules(owner).Select(definition => definition.Judgment).OfType<IJudgmentSkillRule>().FirstOrDefault(candidate => candidate.Kind == SkillKind.Tiandu);
        if (!owner.IsAlive || skill is null)
        {
            return false;
        }

        var context = new JudgmentSkillContext(
            CreateSkillContext(owner),
            pending.TargetSeat,
            pending.Reason,
            judgmentCard.Id,
            judgmentCard.Kind,
            judgmentCard.Suit,
            judgmentCard.Rank);
        if (!skill.CanClaimResolvedJudgment(context))
        {
            return false;
        }

        _pendingJudgment = pending;
        SetJudgmentFrameState(pending, ResolutionFrameStep.AwaitingResponse);
        _pendingDecision = new PendingDecision(
            DecisionKind.Tiandu,
            owner.Seat,
            $"【{judgmentCard.DisplayName}】已作为你的判定牌生效，是否发动【天妒】获得此牌？",
            [],
            [],
            SourceSeat: owner.Seat,
            IncomingCard: judgmentCard.Kind)
        {
            PromptId = CreatePromptId(),
            TargetSeat = owner.Seat,
            Choices =
            [
                new PromptChoice(
                    new ChoiceId($"tiandu.claim.frame-{pending.FrameId}"),
                    $"发动【天妒】，获得【{judgmentCard.DisplayName}】。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "tiandu-claim" }),
                new PromptChoice(
                    new ChoiceId($"tiandu.skip.frame-{pending.FrameId}"),
                    "不发动【天妒】，将判定牌置入弃牌堆。",
                    [],
                    [],
                    new Dictionary<string, string> { ["action"] = "tiandu-skip" })
            ]
        };
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private void ResolveTianduChoice(JudgmentResolution pending, bool useSkill)
    {
        if (!ReferenceEquals(_pendingJudgment, pending) ||
            pending.ResultSucceeded is not { } succeeded ||
            pending.CurrentCard is not { } judgmentCard ||
            _pendingDecision is not { Kind: DecisionKind.Tiandu, PlayerSeat: var ownerSeat } ||
            ownerSeat != pending.TargetSeat)
        {
            throw new InvalidOperationException("The Tiandu judgment is not the current resolution.");
        }

        ClearPendingDecision();
        FinishResolvedJudgment(pending, useSkill ? SkillKind.Tiandu : null);
        QueueGameEvent(new JudgmentCardClaimedEvent(
            pending.FrameId,
            ownerSeat,
            SkillKind.Tiandu,
            useSkill,
            judgmentCard.Id,
            judgmentCard.Kind));
        AddLog(
            useSkill ? "SkillTriggered" : "SkillSkipped",
            useSkill
                ? $"{_players[ownerSeat].Name} 发动【天妒】，获得判定牌【{judgmentCard.DisplayName}】。"
                : $"{_players[ownerSeat].Name} 未发动【天妒】。",
            ownerSeat);
        ResumeCompletedJudgment(pending, succeeded);
    }

    private void FinishResolvedJudgment(JudgmentResolution pending, SkillKind? claimingSkill)
    {
        var judgmentCard = pending.CurrentCard ??
            throw new InvalidOperationException("A resolved judgment must retain its card until disposition.");
        if (_cardZones.GetLocation(judgmentCard.Id) == CardLocation.Judgment(pending.TargetSeat))
        {
            MoveCard(
                judgmentCard,
                CardLocation.Judgment(pending.TargetSeat),
                claimingSkill is not null ? CardLocation.Hand(pending.TargetSeat) : CardLocation.DiscardPile,
                claimingSkill switch
                {
                    SkillKind.Tiandu => CardMoveReasons.TianduClaim,
                    SkillKind.Luoshen => CardMoveReasons.LuoshenClaim,
                    SkillKind.Shuangxiong => CardMoveReasons.ShuangxiongClaim,
                    _ => CardMoveReasons.JudgmentFinish
                });
        }

        SetJudgmentFrameState(pending, ResolutionFrameStep.Completed);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.Judgment);
        if (ReferenceEquals(_pendingJudgment, pending))
        {
            _pendingJudgment = null;
        }
    }

    private void FinishProgramSkillJudgment(JudgmentResolution pending, Card judgmentCard)
    {
        var location = _cardZones.GetLocation(judgmentCard.Id);
        if (location == CardLocation.Judgment(pending.TargetSeat))
        {
            MoveCard(
                judgmentCard,
                location,
                CardLocation.Processing,
                new CardMoveReason("skill-program.judgment.result"));
        }

        SetJudgmentFrameState(pending, ResolutionFrameStep.Completed);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.Judgment);
        if (ReferenceEquals(_pendingJudgment, pending))
        {
            _pendingJudgment = null;
        }
    }

    private void CompleteDelayedJudgment(
        JudgmentResolution pending,
        bool succeeded)
    {
        var delayedCard = pending.DelayedCard ??
            throw new InvalidOperationException("A delayed judgment has no delayed card.");
        var target = _players[pending.TargetSeat];
        var delayedLocation = _cardZones.GetLocation(delayedCard.Id);
        if (delayedLocation != CardLocation.Judgment(target.Seat))
        {
            throw new InvalidOperationException(
                "The resolved delayed card is not in its target's judgment zone.");
        }

        var effectiveCardKind = GetJudgmentEffectiveCardKind(delayedCard);
        var delayedEffectSucceeded = (!succeeded
);
        var delayedEffects = delayedEffectSucceeded
            ? GetDelayedTurnEffects(effectiveCardKind)
            : DelayedTurnEffects.None;
        _pendingTurnDelayedEffects |= delayedEffects;
        MoveCard(
            delayedCard,
            CardLocation.Judgment(target.Seat),
            CardLocation.DiscardPile,
            CardMoveReasons.DelayedCardFinish);
        QueueGameEvent(new DelayedCardResolvedEvent(
            pending.FrameId,
            delayedCard.Id,
            effectiveCardKind,
            target.Seat,
            pending.CurrentCard?.Id,
            succeeded,
            SkippedPlayPhase: delayedEffects.HasFlag(DelayedTurnEffects.SkipPlayPhase))
        {
            SkippedDrawPhase = delayedEffects.HasFlag(DelayedTurnEffects.SkipDrawPhase)
        });
        var phaseDescription = delayedEffects.HasFlag(DelayedTurnEffects.SkipDrawPhase) &&
                               delayedEffects.HasFlag(DelayedTurnEffects.SkipPlayPhase)
            ? "跳过摸牌和出牌阶段"
            : delayedEffects.HasFlag(DelayedTurnEffects.SkipDrawPhase)
                ? "跳过摸牌阶段"
                : delayedEffects.HasFlag(DelayedTurnEffects.SkipPlayPhase)
                    ? "跳过出牌阶段"
                    : "正常进入后续阶段";
        AddLog(
            "DelayedCardResolved",
            $"{target.Name} 的【{CardCatalog.Get(effectiveCardKind).DisplayName}】判定为{GetSuitDisplayName(pending.CurrentCard?.Suit)}，{phaseDescription}。",
            target.Seat);
        BeginDelayedJudgmentOrTurnStart(target);
    }

    private static string GetSuitDisplayName(Suit? suit) => suit switch
    {
        Suit.Spade => "黑桃",
        Suit.Heart => "红桃",
        Suit.Club => "梅花",
        Suit.Diamond => "方片",
        _ => "未知花色"
    };

    private void CompleteLightningJudgment(
        JudgmentResolution pending,
        bool hit)
    {
        var lightning = pending.DelayedCard ??
            throw new InvalidOperationException("A Lightning judgment has no delayed card.");
        var target = _players[pending.TargetSeat];
        var lightningLocation = _cardZones.GetLocation(lightning.Id);
        if (lightningLocation != CardLocation.Judgment(target.Seat))
        {
            throw new InvalidOperationException(
                "The resolved Lightning is not in its target's judgment zone.");
        }

        if (!hit)
        {
            var nextTargetSeat = FindNextAliveSeat(target.Seat);
            if (nextTargetSeat != target.Seat)
            {
                MoveCard(
                    lightning,
                    CardLocation.Judgment(target.Seat),
                    CardLocation.Judgment(nextTargetSeat),
                    CardMoveReasons.DelayedCardTransfer);
            }

            QueueGameEvent(new LightningResolvedEvent(
                pending.FrameId,
                lightning.Id,
                target.Seat,
                pending.CurrentCard?.Id,
                Hit: false,
                NextTargetSeat: nextTargetSeat,
                DamageAmount: 0));
            AddLog(
                "LightningResolved",
                nextTargetSeat == target.Seat
                    ? $"{target.Name} 的【闪电】未命中，因仅剩自己存活而留在其判定区。"
                    : $"{target.Name} 的【闪电】未命中，移至 {_players[nextTargetSeat].Name} 的判定区。",
                target.Seat,
                nextTargetSeat);
            BeginDelayedJudgmentOrTurnStart(
                target,
                excludedCardId: nextTargetSeat == target.Seat ? lightning.Id : null);
            return;
        }

        const int lightningDamage = 3;
        QueueGameEvent(new LightningResolvedEvent(
            pending.FrameId,
            lightning.Id,
            target.Seat,
            pending.CurrentCard?.Id,
            Hit: true,
            NextTargetSeat: null,
            DamageAmount: lightningDamage));
        AddLog(
            "LightningResolved",
            $"{target.Name} 的【闪电】命中，受到 {lightningDamage} 点雷电伤害。",
            target.Seat);

        var attack = new AttackResolution(
            pending.FrameId,
            target.Seat,
            target.Seat,
            lightning,
            damageAmount: lightningDamage,
            playedCardKind: CardKind.Lightning,
            isDelayedJudgmentDamage: true,
            delayedJudgmentSeat: target.Seat);
        _pendingAttack = attack;
        if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private void ResumeAfterLightningDamage(AttackResolution attack)
    {
        var current = _players[attack.DelayedJudgmentSeat ?? attack.SourceSeat];
        if (!current.IsAlive)
        {
            EndTurn();
            return;
        }

        BeginDelayedJudgmentOrTurnStart(current);
    }

    private void ResumeCompletedJudgment(JudgmentResolution pending, bool succeeded)
    {
        if (pending.Continuation == JudgmentContinuationKind.ProgramSkill)
        {
            var bind = pending.ProgramResultBind ??
                throw new InvalidOperationException("A program judgment lost its result binding.");
            var visibility = pending.ProgramResultVisibility ??
                throw new InvalidOperationException("A program judgment lost its result visibility.");
            var cardIds = pending.CurrentCard is { } resultCard
                ? new[] { resultCard.Id }
                : Array.Empty<int>();
            var locations = pending.CurrentCard is { } boundCard
                ? new[] { _cardZones.GetLocation(boundCard.Id) }
                : Array.Empty<CardLocation>();
            SetProgramCardSet(pending.ParentFrameId, bind, cardIds, visibility, locations);
            ContinueProgramSkill(pending.ParentFrameId);
            return;
        }


        if (pending.Continuation == JudgmentContinuationKind.Leiji)
        {
            CompleteLeijiJudgment(pending);
            return;
        }

        if (pending.Continuation == JudgmentContinuationKind.Shuangxiong)
        {
            var draw = _pendingShuangxiongDraw ?? throw new InvalidOperationException("A Shuangxiong judgment has no draw continuation.");
            _pendingShuangxiongDraw = null;
            CompleteTurnStartAfterDraw(_players[draw.PlayerSeat], draw.DelayedEffects);
            return;
        }
        if (pending.Continuation == JudgmentContinuationKind.Tieqi)
        {
            var attack = pending.Attack ??
                throw new InvalidOperationException("A Tieqi judgment has no Slash continuation.");
            CompleteTieqiJudgment(attack, succeeded);
            return;
        }

        if (pending.Continuation == JudgmentContinuationKind.Luoshen)
        {
            var current = _players[pending.TargetSeat];
            if (succeeded && current.IsAlive)
            {
                BeginLuoshenChoice(current, isRepeat: true);
            }
            else if (current.IsAlive)
            {
                BeginTurnStartAfterLuoshen(current);
            }
            else
            {
                EndTurn();
            }
            return;
        }

        if (pending.Continuation == JudgmentContinuationKind.Bagua)
        {
            var attack = pending.Attack ??
                throw new InvalidOperationException("A Bagua judgment has no attack continuation.");
            CompleteBaguaResponse(attack, succeeded);
            return;
        }

        if (pending.Continuation == JudgmentContinuationKind.HujiaBagua)
        {
            var attack = pending.Attack ??
                throw new InvalidOperationException("A Hujia Bagua judgment has no attack continuation.");
            CompleteHujiaBaguaResponse(attack, succeeded);
            return;
        }

        if (pending.Continuation == JudgmentContinuationKind.Lightning)
        {
            CompleteLightningJudgment(pending, succeeded);
            return;
        }

        if (IsDelayedJudgmentContinuation(pending.Continuation))
        {
            CompleteDelayedJudgment(pending, succeeded);
            return;
        }

        var damageSkill = pending.DamageSkill ??
            throw new InvalidOperationException("A Ganglie judgment has no damage-skill continuation.");
        damageSkill.GanglieJudgmentSucceeded = succeeded;
        if (_winner != Winner.None)
        {
            CompleteGanglieSkill(damageSkill, used: true);
            return;
        }
        var source = _players[damageSkill.SourceSeat];
        if (succeeded && source.IsAlive)
        {
            SetDamageSkillFrameStep(damageSkill.FrameId, ResolutionFrameStep.ResolvingEffect);
            _pendingDecision = CreateGangliePunishmentDecision(damageSkill, source);
            _status = source.IsHuman
                ? EngineStatus.AwaitingHumanResponse
                : EngineStatus.Running;
            return;
        }

        CompleteGanglieSkill(damageSkill, used: true);
    }

    private void CompleteLeijiJudgment(JudgmentResolution judgment)
    {
        var pending = _pendingLeiji ??
            throw new InvalidOperationException("A Leiji judgment has no Dodge continuation.");
        if (!ReferenceEquals(pending.OriginalAttack, judgment.Attack) ||
            pending.TargetSeat != judgment.TargetSeat)
        {
            throw new InvalidOperationException("The resolved Leiji judgment does not belong to the current trigger.");
        }

        var owner = _players[pending.OwnerSeat];
        var target = _players[pending.TargetSeat];
        var suit = judgment.CurrentCard is { } card ? EffectiveSuit(target, card) : (Suit?)null;
        var recovered = 0;
        var damage = suit switch
        {
            Suit.Spade => 2,
            Suit.Club => 1,
            _ => 0
        };
        if (suit == Suit.Club && owner.IsAlive && owner.Hp < owner.MaxHp)
        {
            var recoveryFrameId = BeginRecovery(pending.OriginalAttack.ResolutionId,
                pending.OwnerSeat, pending.OwnerSeat, 1);
            owner.Hp++;
            recovered = 1;
            QueueGameEvent(new RecoveryAppliedEvent(pending.OwnerSeat, pending.OwnerSeat, 1, owner.Hp));
            PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
        }

        QueueGameEvent(new LeijiResolvedEvent(
            judgment.FrameId,
            pending.OwnerSeat,
            pending.TargetSeat,
            judgment.CurrentCard?.Id,
            suit,
            recovered,
            damage,
            owner.Hp,
            Math.Max(0, target.Hp)));
        AddLog("SkillTriggered", damage switch
        {
            2 => $"{target.Name} 的【雷击】判定为黑桃，将受到 2 点雷电伤害。",
            1 => $"{target.Name} 的【雷击】判定为梅花，{owner.Name} 回复 {recovered} 点体力，{target.Name} 将受到 1 点雷电伤害。",
            _ => $"{target.Name} 的【雷击】判定未产生效果。"
        }, pending.OwnerSeat, pending.TargetSeat);

        if (damage == 0 || !target.IsAlive || !owner.IsAlive)
        {
            _pendingLeiji = null;
            FinishSuccessfulDodgeResponse(pending.OriginalAttack);
            return;
        }

        var leijiAttack = new AttackResolution(
            pending.OriginalAttack.ResolutionId,
            pending.OwnerSeat,
            pending.TargetSeat,
            card: null,
            damageAmount: damage,
            playedCardKind: null,
            isLeijiDamage: true,
            damageNatureOverride: DamageNature.Thunder);
        pending.DamageAttack = leijiAttack;
        _pendingAttack = leijiAttack;
        if (!ApplyAttackDamage(leijiAttack))
        {
            CompleteAttack(leijiAttack);
        }
    }

    private JudgmentFrame GetJudgmentFrame(long frameId)
    {
        var frame = _resolutionStack.LastOrDefault(candidate => candidate.Id == frameId) as JudgmentFrame;
        return frame ??
            throw new InvalidOperationException($"Resolution frame {frameId} is not a Judgment frame.");
    }

    private void SetJudgmentFrameState(
        JudgmentResolution pending,
        ResolutionFrameStep step)
    {
        var frame = GetJudgmentFrame(pending.FrameId);
        _resolutionStack[_resolutionStack.FindLastIndex(candidate => candidate.Id == pending.FrameId)] =
            frame with
            {
                ReplacementCandidateSeats = Array.AsReadOnly(pending.CandidateSeats.ToArray()),
                ReplacementCandidateIndex = pending.CandidateIndex,
                Step = step
            };
    }

    private void ReplaceJudgmentFrame(JudgmentFrame frame)
    {
        var index = _resolutionStack.FindLastIndex(candidate => candidate.Id == frame.Id);
        if (index < 0 || _resolutionStack[index] is not JudgmentFrame)
        {
            throw new InvalidOperationException($"Resolution frame {frame.Id} is not a Judgment frame.");
        }

        _resolutionStack[index] = frame;
    }

    private static bool IsRedSuit(Suit suit) =>
        suit is Suit.Heart or Suit.Diamond;

    private static bool IsLightningHit(Card card) =>
        card.Suit == Suit.Spade && card.Rank is >= 2 and <= 9;

    private void ResolveDodgeResponse(
        AttackResolution attack,
        CharacterState defender,
        Card responseCard)
    {
        var responseCardKind = GetEffectiveResponseKind(
            defender,
            responseCard,
            CardKind.Dodge);
        var responseConversion = GetSelectedResponseConversion(defender, responseCard, responseCardKind);
        var responseFrom = FindOwnedCardLocation(defender, responseCard);
        MoveCard(
            responseCard,
            responseFrom,
            CardLocation.Processing,
            CardMoveReasons.Respond);
        var incomingName = CardCatalog.Get(RequireAttackCardKind(attack)).DisplayName;
        var responseName = CardCatalog.Get(responseCardKind).DisplayName;
        var responseDescription = IsNativeResponseCard(responseCard, CardKind.Dodge)
            ? $"打出【{responseName}】"
            : $"将【{responseCard.DisplayName}】当作【{responseName}】";
        var completesResponse = attack.SuccessfulDodgeResponses + 1 >= attack.RequiredDodgeResponses;
        AddLog(
            "CardResponded",
            completesResponse
                ? $"{defender.Name} {responseDescription}，抵消了【{incomingName}】。"
                : $"{defender.Name} {responseDescription}响应【{incomingName}】；【无双】仍要求下一张【闪】。",
            defender.Seat,
            attack.SourceSeat);
        QueueGameEvent(new CardRespondedEvent(
            responseCard.Id,
            defender.Seat,
            attack.SourceSeat,
            responseCardKind));
        var responseCost = new CardActionCost(responseCard.Id, responseCard.Kind, responseFrom);
        if (TryBeginCardResponsePrograms(
                attack,
                defender,
                defender,
                requesterSeat: null,
                attack.SourceSeat,
                responseCardKind,
                [responseCost],
                ProgramCardContinuation.Dodge,
                responseConversion))
        {
            return;
        }
        MoveCard(
            responseCard,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.ResponseFinished);
        CompleteSuccessfulDodgeResponse(attack);
    }

    private void ContinueAcceptedCardResponse(
        AttackResolution attack,
        CardActionContext action,
        ProgramCardContinuation continuation)
    {
        var processing = _cardZones.CardsAt(CardLocation.Processing);
        foreach (var cost in action.PhysicalCards)
        {
            var card = processing.Single(item => item.Id == cost.CardId);
            MoveCard(
                card,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.ResponseFinished);
        }

        switch (continuation)
        {
            case ProgramCardContinuation.Dodge:
            case ProgramCardContinuation.HujiaDodge:
                CompleteSuccessfulDodgeResponse(attack);
                return;
            case ProgramCardContinuation.DuelSlash:
            case ProgramCardContinuation.JijiangDuelSlash:
                {
                    var duel = _pendingDuel ??
                        throw new InvalidOperationException("An accepted Duel response has no Duel continuation.");
                    ContinueDuelAfterSuccessfulSlash(duel, action.ActorSeat);
                    return;
                }
            case ProgramCardContinuation.GroupResponse:
            case ProgramCardContinuation.JijiangGroupResponse:
                CompleteAttack(attack);
                return;
            default:
                throw new InvalidOperationException(
                    $"Continuation {continuation} is not a card-response continuation.");
        }
    }

    private int GetIceSwordTargetCardCount(CharacterState target) =>
        GetHand(target).Count + GetEquipment(target).Count;

    private bool TryBeginIceSwordChoice(AttackResolution attack, int preventedDamageAmount)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!UsesFormalIceSword ||
            attack.IceSwordAttempted ||
            attack.IsChainPropagation ||
            attack.IsActiveSkillDamage ||
            attack.EffectiveCardKind is not (CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash) ||
            !source.IsAlive ||
            !target.IsAlive ||
            GetEquipment(source).All(card => card.Kind != CardKind.IceSword) ||
            GetIceSwordTargetCardCount(target) == 0)
        {
            return false;
        }

        if (_pendingIceSword is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Ice Sword choices at once.");
        }

        attack.MarkIceSwordAttempted();
        _pendingIceSword = new IceSwordResolution(attack, preventedDamageAmount);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        PublishIceSwordChoice(_pendingIceSword);
        return true;
    }

    private void PublishIceSwordChoice(IceSwordResolution pending)
    {
        if (!ReferenceEquals(_pendingIceSword, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack))
        {
            throw new InvalidOperationException("The Ice Sword choice has no current Slash continuation.");
        }

        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var hand = GetHand(target);
        var equipment = GetEquipment(target);
        if (hand.Count + equipment.Count == 0)
        {
            FinishIceSwordPrevention(pending);
            return;
        }

        var choices = new List<PromptChoice>();
        for (var slot = 0; slot < hand.Count; slot++)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"ice-sword.hand-slot-{slot}.resolution-{attack.ResolutionId}.pick-{pending.DiscardedCardIds.Count + 1}"),
                $"弃置 {target.Name} 的第 {slot + 1} 个暗手牌位。",
                [],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["action"] = "ice-sword-discard",
                    ["target-zone"] = "hand",
                    ["slot-index"] = slot.ToString(System.Globalization.CultureInfo.InvariantCulture),
                    ["pick-index"] = (pending.DiscardedCardIds.Count + 1).ToString(System.Globalization.CultureInfo.InvariantCulture)
                }));
        }
        foreach (var card in equipment)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"ice-sword.equipment-{card.Id}.resolution-{attack.ResolutionId}.pick-{pending.DiscardedCardIds.Count + 1}"),
                $"弃置 {target.Name} 装备区的【{card.DisplayName}】。",
                [card.Id],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["action"] = "ice-sword-discard",
                    ["target-zone"] = "equipment",
                    ["pick-index"] = (pending.DiscardedCardIds.Count + 1).ToString(System.Globalization.CultureInfo.InvariantCulture)
                }));
        }
        if (!pending.Activated)
        {
            choices.Add(new PromptChoice(
                new ChoiceId($"ice-sword.damage.resolution-{attack.ResolutionId}"),
                $"不发动【寒冰剑】，对 {target.Name} 造成 {pending.PreventedDamageAmount} 点伤害。",
                [],
                [],
                new Dictionary<string, string> { ["action"] = "ice-sword-damage" }));
        }

        _pendingDecision = new PendingDecision(
            DecisionKind.IceSword,
            source.Seat,
            pending.Activated
                ? $"【寒冰剑】已防止伤害，请继续弃置 {target.Name} 的第二张牌。"
                : $"你的【{CardCatalog.Get(RequireAttackCardKind(attack)).DisplayName}】将对 {target.Name} 造成 {pending.PreventedDamageAmount} 点伤害，是否发动【寒冰剑】？",
            equipment.Select(card => card.Id).ToArray(),
            [target.Seat],
            SourceSeat: source.Seat,
            IncomingCard: attack.EffectiveCardKind)
        {
            PromptId = source.IsHuman ? CreatePromptId() : default,
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices = choices
        };
        _status = source.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private void ResolveIceSwordChoice(PromptChoice selected)
    {
        var pending = _pendingIceSword ??
            throw new InvalidOperationException("There is no Ice Sword choice to resolve.");
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.IceSword } decision ||
            decision.PlayerSeat != attack.SourceSeat)
        {
            throw new InvalidOperationException("The Ice Sword choice is not the current Slash continuation.");
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var action = selected.Parameters.GetValueOrDefault("action");
        if (action == "ice-sword-damage")
        {
            if (pending.Activated || selected.Cards.Count != 0 || selected.Targets.Count != 0)
            {
                throw new InvalidOperationException("Ice Sword damage may only be retained before its first discard.");
            }

            _pendingIceSword = null;
            ClearPendingDecision();
            SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
            QueueGameEvent(new IceSwordResolvedEvent(
                attack.ResolutionId,
                source.Seat,
                target.Seat,
                Used: false,
                PreventedDamageAmount: 0,
                DiscardedCardIds: []));
            AddLog(
                "EquipmentSkipped",
                $"{source.Name} 未发动【寒冰剑】，{target.Name} 继续受到 {pending.PreventedDamageAmount} 点伤害。",
                source.Seat,
                target.Seat);
            if (!ApplyAttackDamage(attack))
            {
                CompleteAttack(attack);
            }
            return;
        }

        if (action != "ice-sword-discard" ||
            !selected.Targets.SequenceEqual([target.Seat]))
        {
            throw new InvalidOperationException("The Ice Sword discard choice is malformed.");
        }

        Card discarded;
        var targetZone = selected.Parameters.GetValueOrDefault("target-zone");
        if (targetZone == "hand" &&
            selected.Cards.Count == 0 &&
            selected.Parameters.TryGetValue("slot-index", out var slotText) &&
            int.TryParse(
                slotText,
                System.Globalization.NumberStyles.None,
                System.Globalization.CultureInfo.InvariantCulture,
                out var slot) &&
            slot >= 0 && slot < GetHand(target).Count)
        {
            discarded = GetHand(target)[slot];
        }
        else if (targetZone == "equipment" &&
                 selected.Cards.Count == 1 &&
                 GetEquipment(target).FirstOrDefault(card => card.Id == selected.Cards[0]) is { } equipment)
        {
            discarded = equipment;
        }
        else
        {
            throw new InvalidOperationException("The selected Ice Sword target card is no longer available.");
        }

        pending.Activated = true;
        ClearPendingDecision();
        MoveCard(
            discarded,
            FindOwnedCardLocation(target, discarded),
            CardLocation.DiscardPile,
            CardMoveReasons.IceSwordDiscard);
        pending.DiscardedCardIds.Add(discarded.Id);
        AddLog(
            "EquipmentEffect",
            $"{source.Name} 发动【寒冰剑】，弃置 {target.Name} 的【{discarded.DisplayName}】。",
            source.Seat,
            target.Seat);

        if (pending.DiscardedCardIds.Count < 2 && GetIceSwordTargetCardCount(target) > 0)
        {
            PublishIceSwordChoice(pending);
            return;
        }

        FinishIceSwordPrevention(pending);
    }

    private void FinishIceSwordPrevention(IceSwordResolution pending)
    {
        if (!ReferenceEquals(_pendingIceSword, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack) ||
            !pending.Activated ||
            pending.DiscardedCardIds.Count is < 1 or > 2)
        {
            throw new InvalidOperationException("The completed Ice Sword prevention is invalid.");
        }

        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        _pendingIceSword = null;
        ClearPendingDecision();
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new IceSwordResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            Used: true,
            pending.PreventedDamageAmount,
            Array.AsReadOnly(pending.DiscardedCardIds.ToArray())));
        AddLog(
            "DamagePrevented",
            $"{source.Name} 的【寒冰剑】防止了对 {target.Name} 的 {pending.PreventedDamageAmount} 点伤害，并依次弃置其 {pending.DiscardedCardIds.Count} 张牌。",
            source.Seat,
            target.Seat);
        CompleteAttack(attack);
    }

    private IReadOnlyList<Card> GetQilinBowTargetMounts(CharacterState target) =>
        GetEquipment(target)
            .Where(card => EquipmentCatalog.Get(card.Kind).Slot is
                EquipmentSlot.OffensiveHorse or EquipmentSlot.DefensiveHorse)
            .ToArray();

    private bool TryBeginQilinBowChoice(AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!UsesFormalQilinBow ||
            attack.QilinBowAttempted ||
            attack.IsChainPropagation ||
            attack.IsActiveSkillDamage ||
            attack.EffectiveCardKind is not (CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash) ||
            !source.IsAlive ||
            !target.IsAlive ||
            GetEquipment(source).All(card => card.Kind != CardKind.QilinBow) ||
            GetQilinBowTargetMounts(target).Count == 0)
        {
            return false;
        }

        if (_pendingQilinBow is not null)
        {
            throw new InvalidOperationException("The engine cannot open two Qilin Bow choices at once.");
        }

        attack.MarkQilinBowAttempted();
        _pendingQilinBow = new QilinBowResolution(attack);
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.AwaitingResponse);
        PublishQilinBowChoice(_pendingQilinBow);
        return true;
    }

    private void PublishQilinBowChoice(QilinBowResolution pending)
    {
        if (!ReferenceEquals(_pendingQilinBow, pending) ||
            !ReferenceEquals(_pendingAttack, pending.Attack))
        {
            throw new InvalidOperationException("The Qilin Bow choice has no current Slash continuation.");
        }

        var attack = pending.Attack;
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var mounts = GetQilinBowTargetMounts(target);
        if (mounts.Count == 0)
        {
            throw new InvalidOperationException("A Qilin Bow prompt requires at least one target mount.");
        }

        var choices = mounts.Select(card => new PromptChoice(
            new ChoiceId($"qilin-bow.mount-{card.Id}.resolution-{attack.ResolutionId}"),
            $"发动【麒麟弓】，弃置 {target.Name} 的【{card.DisplayName}】。",
            [card.Id],
            [target.Seat],
            new Dictionary<string, string>
            {
                ["action"] = "qilin-bow-discard",
                ["target-zone"] = "equipment"
            })).ToList();
        choices.Add(new PromptChoice(
            new ChoiceId($"qilin-bow.skip.resolution-{attack.ResolutionId}"),
            "不发动【麒麟弓】，继续结算此伤害。",
            [],
            [],
            new Dictionary<string, string> { ["action"] = "qilin-bow-skip" }));

        _pendingDecision = new PendingDecision(
            DecisionKind.QilinBow,
            source.Seat,
            $"你的【{CardCatalog.Get(RequireAttackCardKind(attack)).DisplayName}】将对 {target.Name} 造成伤害，是否发动【麒麟弓】弃置其一张坐骑？",
            mounts.Select(card => card.Id).ToArray(),
            [target.Seat],
            SourceSeat: source.Seat,
            IncomingCard: attack.EffectiveCardKind)
        {
            PromptId = source.IsHuman ? CreatePromptId() : default,
            IsPrivate = true,
            TargetSeat = target.Seat,
            Choices = choices
        };
        _status = source.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
    }

    private void ResolveQilinBowChoice(PromptChoice selected)
    {
        var pending = _pendingQilinBow ??
            throw new InvalidOperationException("There is no Qilin Bow choice to resolve.");
        var attack = pending.Attack;
        if (!ReferenceEquals(_pendingAttack, attack) ||
            _pendingDecision is not { Kind: DecisionKind.QilinBow } decision ||
            decision.PlayerSeat != attack.SourceSeat)
        {
            throw new InvalidOperationException("The Qilin Bow choice is not the current Slash continuation.");
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var action = selected.Parameters.GetValueOrDefault("action");
        Card? discardedMount = null;
        if (action == "qilin-bow-discard" &&
            selected.Targets.SequenceEqual([target.Seat]) &&
            selected.Cards.Count == 1)
        {
            discardedMount = GetQilinBowTargetMounts(target)
                .SingleOrDefault(card => card.Id == selected.Cards[0]) ??
                throw new InvalidOperationException("The selected Qilin Bow mount is no longer available.");
        }
        else if (action != "qilin-bow-skip" ||
                 selected.Cards.Count != 0 ||
                 selected.Targets.Count != 0)
        {
            throw new InvalidOperationException("The Qilin Bow choice is malformed.");
        }

        _pendingQilinBow = null;
        ClearPendingDecision();
        SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        if (discardedMount is not null)
        {
            MoveCard(
                discardedMount,
                FindOwnedCardLocation(target, discardedMount),
                CardLocation.DiscardPile,
                CardMoveReasons.QilinBowDiscard);
        }
        QueueGameEvent(new QilinBowResolvedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            Used: discardedMount is not null,
            DiscardedMountCardId: discardedMount?.Id));
        AddLog(
            discardedMount is null ? "EquipmentSkipped" : "EquipmentEffect",
            discardedMount is null
                ? $"{source.Name} 未发动【麒麟弓】，继续对 {target.Name} 结算伤害。"
                : $"{source.Name} 发动【麒麟弓】，弃置 {target.Name} 的【{discardedMount.DisplayName}】。",
            source.Seat,
            target.Seat);
        if (!ApplyAttackDamage(attack))
        {
            CompleteAttack(attack);
        }
    }

    private bool ApplyAttackDamage(AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!target.IsAlive)
        {
            return false;
        }

        if (!attack.IsChainPropagation && HasDirectedCardArmorBypass(attack.ResolutionId, target.Seat))
            attack.SetIgnoresArmor(true);
        var nature = GetDamageNature(attack);
        var amount = FinalizeAttackDamageAmount(attack);
        if (TryPreventWuyanDamage(attack, amount))
        {
            return false;
        }
        if (TryBeginBeforeDamageProgramWindowForAttack(attack, amount, nature))
        {
            return true;
        }
        if (TryBeginTianxiangChoice(attack, amount, nature))
        {
            return true;
        }
        if (TryBeginIceSwordChoice(attack, amount))
        {
            return true;
        }
        if (TryBeginQilinBowChoice(attack))
        {
            return true;
        }
        if (!attack.IsChainPropagation &&
            (nature is DamageNature.Fire or DamageNature.Thunder) &&
            target.IsChained)
        {
            var propagatedTargets = _players
                .Where(player =>
                    player.IsAlive &&
                    player.Seat != target.Seat &&
                    player.IsChained)
                .Select(player => player.Seat)
                .ToArray();
            var chainMembers = new[] { target.Seat }
                .Concat(propagatedTargets)
                .ToArray();
            attack.SetChainedTargets(propagatedTargets);
            foreach (var chainSeat in chainMembers)
            {
                _players[chainSeat].IsChained = false;
                QueueGameEvent(new IronChainStateChangedEvent(
                    attack.ResolutionId,
                    source.Seat,
                    chainSeat,
                    IsChained: false));
            }

            if (propagatedTargets.Length > 0)
            {
                AddLog(
                    "ChainDamage",
                    $"{target.Name} 受到{GetDamageNatureLabel(nature)}伤害，向 {propagatedTargets.Length} 名连环角色传导同量伤害。",
                    source.Seat,
                    target.Seat);
            }
        }
        var damageFrameId = BeginDamage(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            amount,
            nature);
        var awaitingDying = false;
        var awaitingDamageTrigger = false;
        try
        {
            QueueGameEvent(new DamageRequestedEvent(
                damageFrameId,
                source.Seat,
                target.Seat,
                amount,
                attack.EffectiveCardKind,
                nature));
            attack.CaptureDamageDistance(source.Seat == target.Seat
                ? 0
                : GetCombatDistance(source.Seat, target.Seat));
            target.Hp = Math.Max(0, target.Hp - amount);
            attack.MarkDamageApplied();
            var natureLabel = GetDamageNatureLabel(nature);
            AddLog("Damage", $"{target.Name} 受到 {source.Name} 造成的 {amount} 点{natureLabel}伤害，剩余 {Math.Max(0, target.Hp)} 点体力。", source.Seat, target.Seat);
            QueueGameEvent(new DamageAppliedEvent(
                source.Seat,
                target.Seat,
                amount,
                Math.Max(0, target.Hp),
                nature));
            ApplyHengyeGrowth(damageFrameId, source, target, amount);
            if (TryBeginDamageTriggerWindow(
                    attack, damageFrameId, SkillProgramTriggerWindow.DamageAppliedBeforeDying))
            {
                awaitingDamageTrigger = true;
            }
            else if (target.Hp <= 0)
            {
                BeginDying(attack, damageFrameId, target, source);
                // Buqu may finish this dying continuation synchronously.
                awaitingDying = true;
            }
            else
            {
                awaitingDamageTrigger = TryBeginDamageTriggerWindow(
                    attack, damageFrameId, SkillProgramTriggerWindow.AfterDamageApplied);
            }

            if (!awaitingDying && !awaitingDamageTrigger)
            {
                QueueGameEvent(new AfterDamageEvent(
                    damageFrameId,
                    source.Seat,
                    target.Seat,
                    amount,
                    Math.Max(0, target.Hp),
                    nature));
            }
        }
        finally
        {
            if (!awaitingDying && !awaitingDamageTrigger)
            {
                PopResolutionFrame(damageFrameId, ResolutionFrameKind.Damage);
            }
        }

        return awaitingDying || awaitingDamageTrigger;
    }

    private bool TryBeginTianxiangChoice(AttackResolution attack, int amount, DamageNature nature)
    {
        if (!UsesFormalXiaoQiao || attack.TianxiangResolved)
            return false;
        var owner = _players[attack.TargetSeat];
        attack.MarkTianxiangResolved();
        if (!HasRuntimeSkill(owner, SkillKind.Tianxiang))
            return false;
        var cards = GetHand(owner).Where(card => EffectiveSuit(owner, card) == Suit.Heart)
            .OrderBy(card => card.Id).ToArray();
        var targets = _players.Where(player => player.IsAlive && player.Seat != owner.Seat)
            .OrderBy(player => player.Seat).ToArray();
        if (cards.Length == 0 || targets.Length == 0)
            return false;
        var choices = cards.SelectMany(card => targets.Select(target => new PromptChoice(
                new ChoiceId($"tianxiang-{card.Id}-{target.Seat}"),
                $"弃置【{CardCatalog.Get(card.Kind).DisplayName}】，将 {amount} 点伤害转移给 {target.Name}",
                [card.Id], [target.Seat],
                new Dictionary<string, string> { ["action"] = "tianxiang-use" })))
            .Append(new PromptChoice(new ChoiceId("tianxiang-skip"), "不发动【天香】", [], [],
                new Dictionary<string, string> { ["action"] = "tianxiang-skip" }))
            .ToArray();
        _pendingTianxiang = new TianxiangResolution(attack, owner.Seat, amount, nature);
        _pendingDecision = new PendingDecision(
            DecisionKind.Tianxiang, owner.Seat, $"你即将受到 {amount} 点伤害，是否发动【天香】？",
            cards.Select(card => card.Id).ToArray(), targets.Select(player => player.Seat).ToArray(),
            attack.SourceSeat, attack.EffectiveCardKind)
        { PromptId = CreatePromptId(), Choices = choices };
        PushResponseWindow(
            attack.ResolutionId,
            attack.SourceSeat,
            owner.Seat,
            attack.EffectiveCardKind ?? CardKind.Slash,
            attack.EffectiveCardKind ?? CardKind.Slash);
        _status = owner.IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running;
        return true;
    }

    private Suit EffectiveSuit(CharacterState owner, Card card) =>
        UsesFormalXiaoQiao && HasRuntimeSkill(owner, SkillKind.Hongyan) && card.Suit == Suit.Spade
            ? Suit.Heart
            : card.Suit;

    private EngineRunResult ResolveTianxiangChoice(int? discardedCardId, int? targetSeat, bool advance)
    {
        var pending = _pendingTianxiang ?? throw new InvalidOperationException("天香结算不存在。");
        var attack = pending.Attack;
        var owner = _players[pending.OwnerSeat];
        PopResponseWindow(attack.ResolutionId);
        SetResponseParentStep(attack.ResolutionId, ResolutionFrameStep.ResolvingEffect);
        _pendingTianxiang = null;
        ClearPendingDecision();
        if (discardedCardId is { } cardId && targetSeat is { } redirectedSeat)
        {
            var card = GetHand(owner).Single(card => card.Id == cardId && EffectiveSuit(owner, card) == Suit.Heart);
            var target = _players.Single(player => player.Seat == redirectedSeat && player.IsAlive && player.Seat != owner.Seat);
            MoveCard(card, CardLocation.Hand(owner.Seat), CardLocation.Processing, CardMoveReasons.TianxiangDiscard);
            MoveCard(card, CardLocation.Processing, CardLocation.DiscardPile, CardMoveReasons.TianxiangDiscard);
            attack.RedirectFinalizedDamageTarget(target.Seat);
            attack.SetTianxiangDraw(owner.Seat, target.Seat);
            QueueGameEvent(new TianxiangTransferredEvent(attack.ResolutionId, owner.Seat, attack.SourceSeat,
                target.Seat, card.Id, pending.Amount, pending.Nature));
            AddLog("SkillTriggered", $"{owner.Name} 发动【天香】，将 {pending.Amount} 点伤害转移给 {target.Name}。", owner.Seat, target.Seat);
        }
        if (!ApplyAttackDamage(attack)) CompleteAttack(attack);
        PublishState();
        return advance ? AdvanceToHumanBoundary() : BuildResult();
    }

    private bool IsAiTianxiangPending() => _pendingDecision is { Kind: DecisionKind.Tianxiang, PlayerSeat: var seat } &&
        !_players[seat].IsHuman;

    private void ResolvePendingAiTianxiang()
    {
        var decision = _pendingDecision ?? throw new InvalidOperationException("AI 天香提示不存在。");
        var use = decision.Choices.FirstOrDefault(choice => choice.Parameters.GetValueOrDefault("action") == "tianxiang-use");
        ResolveTianxiangChoice(use?.Cards.SingleOrDefault(), use?.Targets.SingleOrDefault(), false);
    }

    private bool TryBeginDamageTriggerWindow(
        AttackResolution attack,
        long damageFrameId,
        SkillProgramTriggerWindow window)
    {
        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        var damageContext = new DamageSkillContext(
            CreateSkillContext(target),
            source.Seat,
            attack.EffectiveCardKind,
            SourceCardIsInProcessing:
                attack.Card is { } sourceCard &&
                _cardZones.GetLocation(sourceCard.Id) == CardLocation.Processing,
            Nature: GetDamageNature(attack),
            Amount: attack.DamageAmount,
            SourceCardId: attack.Card?.Id,
            SourceCardSuit: attack.Card?.Suit,
            TargetSeat: target.Seat,
            TargetHp: target.Hp,
            TargetMaxHp: target.MaxHp,
            SourceCardCount: GetHand(source).Count + GetEquipment(source).Count,
            SourceToTargetDistance: attack.SourceToTargetDistanceAtDamage);
        var triggerCandidates = DamageTriggerOrdering.Order(
            CollectDamageTriggerCandidates(damageContext, attack, window),
            source.Seat,
            _playerCount);
        if (triggerCandidates.Count == 0) return false;

        BeginDamageTriggerWindow(attack, damageFrameId, window, triggerCandidates);
        // Expose an optional trigger in the command that caused the damage.
        // Automatic candidates remain one deterministic engine step each.
        if (triggerCandidates[0].IsOptional)
        {
            RunOneDamageTriggerStep();
        }
        return true;
    }

    private void BeginDamageTriggerWindow(
        AttackResolution attack,
        long damageFrameId,
        SkillProgramTriggerWindow window,
        IReadOnlyList<DamageTriggerCandidate> candidates)
    {
        if (_pendingDamageTrigger is not null)
        {
            throw new InvalidOperationException("The engine cannot resolve two damage trigger windows at once.");
        }

        var frozenCandidates = Array.AsReadOnly(candidates.ToArray());
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new DamageTriggerWindowFrame(
            frameId,
            damageFrameId,
            attack.SourceSeat,
            attack.TargetSeat,
            attack.Card?.Id,
            attack.EffectiveCardKind,
            frozenCandidates));
        QueueGameEvent(new DamageTriggerWindowOpenedEvent(
            frameId,
            damageFrameId,
            attack.SourceSeat,
            attack.TargetSeat,
            attack.Card?.Id,
            attack.EffectiveCardKind,
            frozenCandidates));
        _pendingDamageTrigger = new DamageTriggerResolution(
            frameId,
            damageFrameId,
            attack,
            window,
            frozenCandidates);
    }

    private void RunOneDamageTriggerStep()
    {
        var window = _pendingDamageTrigger ??
            throw new InvalidOperationException("A damage trigger step has no pending window.");
        if (_pendingDamageSkill is not null || _pendingDecision is not null)
        {
            return;
        }

        if (window.CandidateIndex >= window.Candidates.Count)
        {
            CompleteDamageTriggerWindow(window);
            return;
        }

        var candidate = window.Candidates[window.CandidateIndex];
        var owner = _players[candidate.OwnerSeat];
        if (candidate.ToProgramCandidate() is { } programCandidate)
        {
            var programContext = CreateAfterDamageProgramContext(window, programCandidate);
            if (!CanRunProgramTrigger(programCandidate, programContext))
            {
                AdvanceDamageTriggerCandidate(window);
                return;
            }
            if (candidate.IsOptional)
            {
                ExposeProgramTriggerDecision(programCandidate, programContext);
                return;
            }
            BeginProgramBinding(programCandidate, programContext);
            return;
        }
        var context = CreateDamageSkillContext(window.Attack, owner);
        var skill = SkillRegistry.Get(candidate.Skill).Damage!;
        if (!owner.IsAlive ||
            !skill.CanTriggerAfterDamage(context) ||
            ResolveDamageSkillEffect(skill, context) != candidate.Effect)
        {
            AdvanceDamageTriggerCandidate(window);
            return;
        }

        if (candidate.IsOptional)
        {
            BeginDamageSkillChoice(window, candidate, owner, skill);
            return;
        }

        if (candidate.Effect == DamageSkillEffectKind.RecoverDamageSource)
        {
            RecoverDamageSourceThroughKuanggu(
                window.Attack,
                window.DamageFrameId,
                owner,
                skill,
                context);
        }

        AdvanceDamageTriggerCandidate(window);
    }

    private void AdvanceDamageTriggerCandidate(DamageTriggerResolution window)
    {
        if (!ReferenceEquals(_pendingDamageTrigger, window))
        {
            throw new InvalidOperationException("The completed damage trigger window is not current.");
        }

        window.CandidateIndex++;
        // A nested Ganglie death can determine the winner before the final
        // trigger candidate. Close this window now so the host never stops at
        // Winner != None with live frames, Processing cards or a new prompt.
        if (_winner != Winner.None) window.CandidateIndex = window.Candidates.Count;
        SetDamageTriggerWindowCursor(window.FrameId, window.CandidateIndex);
        QueueGameEvent(new DamageTriggerWindowAdvancedEvent(
            window.FrameId,
            window.CandidateIndex,
            window.CandidateIndex >= window.Candidates.Count));
        if (window.CandidateIndex >= window.Candidates.Count)
        {
            CompleteDamageTriggerWindow(window);
        }
    }

    private void CompleteDamageTriggerWindow(DamageTriggerResolution window)
    {
        if (!ReferenceEquals(_pendingDamageTrigger, window) ||
            _pendingDamageSkill is not null)
        {
            throw new InvalidOperationException("The damage trigger window is not ready to complete.");
        }

        SetDamageTriggerWindowStep(window.FrameId, ResolutionFrameStep.Completed);
        var target = _players[window.Attack.TargetSeat];
        PopResolutionFrame(window.FrameId, ResolutionFrameKind.DamageTriggerWindow);
        _pendingDamageTrigger = null;
        if (window.Window == SkillProgramTriggerWindow.DamageAppliedBeforeDying)
        {
            if (target.Hp <= 0 && target.IsAlive)
            {
                BeginDying(window.Attack, window.DamageFrameId, target,
                    _players[window.Attack.SourceSeat]);
                return;
            }
            if (TryBeginDamageTriggerWindow(window.Attack, window.DamageFrameId,
                    SkillProgramTriggerWindow.AfterDamageApplied))
            {
                return;
            }
        }
        if (target.Hp <= 0 && target.IsAlive &&
            !window.Attack.HasResolvedDyingForDamage(window.DamageFrameId))
        {
            BeginDying(window.Attack, window.DamageFrameId, target, _players[window.Attack.SourceSeat]);
            return;
        }

        QueueGameEvent(new AfterDamageEvent(
            window.DamageFrameId,
            window.Attack.SourceSeat,
            window.Attack.TargetSeat,
            window.Attack.DamageAmount,
            Math.Max(0, target.Hp),
            GetDamageNature(window.Attack)));

        PopResolutionFrame(window.DamageFrameId, ResolutionFrameKind.Damage);
        CompleteDamageAttack(window.Attack);
    }

    private void BeginDamageSkillChoice(
        DamageTriggerResolution window,
        DamageTriggerCandidate candidate,
        CharacterState owner,
        IDamageSkillRule skill)
    {
        var attack = window.Attack;
        var damageFrameId = window.DamageFrameId;
        SetDamageTriggerWindowStep(window.FrameId, ResolutionFrameStep.AwaitingResponse);
        if (_pendingDamageSkill is not null)
        {
            throw new InvalidOperationException("The engine cannot resolve two damage skills at once.");
        }

        var context = CreateDamageSkillContext(attack, owner);
        var effect = candidate.Effect == DamageSkillEffectKind.None
            ? skill.GetDamageSkillEffect(context)
            : candidate.Effect;
        if (effect == DamageSkillEffectKind.None)
        {
            throw new InvalidOperationException(
                $"Optional damage skill {skill.Kind} did not declare a resolvable effect.");
        }

        var effectCardIds = Array.Empty<int>();
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new DamageSkillFrame(
            frameId,
            window.FrameId,
            owner.Seat,
            attack.SourceSeat,
            attack.Card?.Id,
            attack.EffectiveCardKind,
            skill.Kind,
            CandidateId: candidate.CandidateId,
            Priority: candidate.Priority,
            Effect: effect,
            EffectCardIds: effectCardIds));
        _pendingDamageSkill = new DamageSkillResolution(
            frameId,
            window.FrameId,
            damageFrameId,
            attack,
            owner.Seat,
            skill.Kind,
            attack.EffectiveCardKind,
            candidate.CandidateId,
            candidate.Priority,
            effect,
            effectCardIds);
        QueueGameEvent(new DamageSkillRequestedEvent(
            damageFrameId,
            owner.Seat,
            attack.SourceSeat,
            attack.Card?.Id,
            attack.EffectiveCardKind,
            skill.Kind,
            candidate.CandidateId,
            candidate.Priority));

        _pendingDecision = effect switch
        {
            DamageSkillEffectKind.RecoverDamageTarget => CreateYuanhuDecision(
                owner,
                skill,
                attack),
            DamageSkillEffectKind.GanglieJudgment => CreateGanglieDecision(
                owner,
                skill,
                attack),
            DamageSkillEffectKind.BenefitDamageSource => CreateYaowuDecision(owner, skill, attack),
            _ => throw new InvalidOperationException($"Unsupported damage skill effect {effect}.")
        };
        _status = effect == DamageSkillEffectKind.BenefitDamageSource
            ? (_players[attack.SourceSeat].IsHuman ? EngineStatus.AwaitingHumanResponse : EngineStatus.Running)
            : owner.IsHuman
            ? EngineStatus.AwaitingHumanResponse
            : EngineStatus.Running;
    }

    private PendingDecision CreateYaowuDecision(CharacterState owner, IDamageSkillRule skill, AttackResolution attack)
    {
        var source = _players[attack.SourceSeat];
        var choices = new List<PromptChoice>();
        if (source.Hp < source.MaxHp)
            choices.Add(new PromptChoice(new ChoiceId("yaowu.recover"),
                $"因 {owner.Name} 的【{skill.Name}】回复1点体力。", [], [],
                new Dictionary<string, string> { ["action"] = "yaowu-recover" }));
        choices.Add(new PromptChoice(new ChoiceId("yaowu.draw"),
            $"因 {owner.Name} 的【{skill.Name}】摸一张牌。", [], [],
            new Dictionary<string, string> { ["action"] = "yaowu-draw" }));
        return new PendingDecision(DecisionKind.Yaowu, source.Seat,
            $"你使用红色【杀】对 {owner.Name} 造成伤害，选择【耀武】收益。", [], [])
        { PromptId = CreatePromptId(), IsPrivate = true, TargetSeat = owner.Seat, Choices = choices.AsReadOnly() };
    }

    private void ResolveYaowuChoice(bool recover)
    {
        var pending = _pendingDamageSkill ?? throw new InvalidOperationException("There is no Yaowu damage skill pending.");
        if (pending.Skill != SkillKind.Yaowu || pending.Effect != DamageSkillEffectKind.BenefitDamageSource ||
            _pendingDecision is not { Kind: DecisionKind.Yaowu })
            throw new InvalidOperationException("There is no Yaowu benefit choice to resolve.");
        var window = _pendingDamageTrigger ?? throw new InvalidOperationException("Yaowu has no damage trigger window.");
        var owner = _players[pending.OwnerSeat];
        var source = _players[pending.SourceSeat];
        if (recover && source.Hp >= source.MaxHp)
            throw new InvalidOperationException("A full-health Yaowu source cannot choose recovery.");
        ClearPendingDecision();
        if (recover)
        {
            var recoveryFrameId = BeginRecovery(pending.DamageFrameId, owner.Seat, source.Seat, 1);
            source.Hp = Math.Min(source.MaxHp, source.Hp + 1);
            QueueGameEvent(new RecoveryAppliedEvent(owner.Seat, source.Seat, 1, source.Hp));
            PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
        }
        else
        {
            DrawCards(source, 1, log: true, reason: CardMoveReasons.YaowuDraw);
        }
        QueueGameEvent(new YaowuResolvedEvent(pending.DamageFrameId, owner.Seat, source.Seat, recover, source.Hp));
        QueueGameEvent(new DamageSkillResolvedEvent(pending.DamageFrameId, owner.Seat, source.Seat,
            pending.Card?.Id, pending.EffectiveCardKind, SkillKind.Yaowu, true,
            pending.CandidateId, pending.Priority, source.Seat));
        AddLog("SkillTriggered", recover
            ? $"{owner.Name} 的【耀武】令 {source.Name} 回复1点体力。"
            : $"{owner.Name} 的【耀武】令 {source.Name} 摸一张牌。", owner.Seat, source.Seat);
        SetDamageSkillFrameStep(pending.FrameId, ResolutionFrameStep.ResolvingEffect);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.DamageSkill);
        _pendingDamageSkill = null;
        SetDamageTriggerWindowStep(window.FrameId, ResolutionFrameStep.ResolvingEffect);
        AdvanceDamageTriggerCandidate(window);
    }

    private PendingDecision CreateGanglieDecision(
        CharacterState owner,
        IDamageSkillRule skill,
        AttackResolution attack)
    {
        return new PendingDecision(
            DecisionKind.Ganglie,
            owner.Seat,
            $"{owner.Name} 受到伤害，是否发动【{skill.Name}】进行判定？",
            [],
            [],
            attack.SourceSeat,
            attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices =
            [
                new PromptChoice(
                    new ChoiceId("ganglie.use"),
                    $"发动【{skill.Name}】进行判定。",
                    [],
                    [],
                    new Dictionary<string, string>
                    {
                        ["response"] = "ganglie",
                        ["action"] = "judge-source"
                    }),
                new PromptChoice(
                    new ChoiceId("ganglie.skip"),
                    $"不发动【{skill.Name}】。",
                    [],
                    [],
                    new Dictionary<string, string>
                    {
                        ["response"] = "skip-ganglie",
                        ["action"] = "skip-damage-skill"
                    })
            ],
            RequiredCardKind = null,
            TargetSeat = owner.Seat
        };
    }

    private PendingDecision CreateYuanhuDecision(
        CharacterState owner,
        IDamageSkillRule skill,
        AttackResolution attack)
    {
        var target = _players[attack.TargetSeat];
        var choices = GetHand(owner)
            .Select(card => new PromptChoice(
                new ChoiceId($"yuanhu.discard.card-{card.Id}"),
                $"弃置【{card.DisplayName}】，令 {target.Name} 回复 1 点体力。",
                [card.Id],
                [target.Seat],
                new Dictionary<string, string>
                {
                    ["response"] = "yuanhu",
                    ["action"] = "recover-damage-target"
                }))
            .Append(new PromptChoice(
                new ChoiceId("yuanhu.skip"),
                $"不发动【{skill.Name}】。",
                [],
                [],
                new Dictionary<string, string>
                {
                    ["response"] = "yuanhu-skip",
                    ["action"] = "skip-damage-skill"
                }))
            .ToArray();

        return new PendingDecision(
            DecisionKind.Yuanhu,
            owner.Seat,
            $"{owner.Name} 可弃置一张手牌，令受伤的 {target.Name} 回复 1 点体力。",
            GetHand(owner).Select(card => card.Id).ToArray(),
            [target.Seat],
            attack.SourceSeat,
            attack.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            RequiredCardKind = null,
            TargetSeat = target.Seat
        };
    }

    private PendingDecision CreateGangliePunishmentDecision(
        DamageSkillResolution pending,
        CharacterState source)
    {
        var owner = _players[pending.OwnerSeat];
        var hand = GetHand(source).ToArray();
        var choices = new List<PromptChoice>();
        for (var first = 0; first < hand.Length - 1; first++)
        {
            for (var second = first + 1; second < hand.Length; second++)
            {
                var firstCard = hand[first];
                var secondCard = hand[second];
                choices.Add(new PromptChoice(
                    new ChoiceId($"ganglie.discard.card-{firstCard.Id}.card-{secondCard.Id}"),
                    $"弃置【{firstCard.DisplayName}】和【{secondCard.DisplayName}】，不承受伤害。",
                    [firstCard.Id, secondCard.Id],
                    [],
                    new Dictionary<string, string>
                    {
                        ["response"] = "ganglie-discard-two",
                        ["action"] = "punish-source-discard"
                    }));
            }
        }

        choices.Add(new PromptChoice(
            new ChoiceId("ganglie.lose-hp"),
            $"让 {source.Name} 承受 1 点伤害，不弃置手牌。",
            [],
            [],
            new Dictionary<string, string>
            {
                ["response"] = "ganglie-lose-hp",
                ["action"] = "punish-source-damage"
            }));

        return new PendingDecision(
            DecisionKind.GangliePunish,
            source.Seat,
            $"{owner.Name} 的【刚烈】判定为红色，请选择伤害来源的反制代价。",
            hand.Select(card => card.Id).ToArray(),
            [],
            owner.Seat,
            pending.EffectiveCardKind)
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            RequiredCardKind = null,
            TargetSeat = source.Seat
        };
    }

    private void ResolveGanglieChoice(DamageSkillResolution pending, bool useSkill)
    {
        if (!ReferenceEquals(_pendingDamageSkill, pending))
        {
            throw new InvalidOperationException("The completed Ganglie trigger is not current.");
        }

        if (!useSkill)
        {
            CompleteGanglieSkill(pending, used: false);
            return;
        }

        var source = _players[pending.SourceSeat];
        var judgment = ResolveGanglieJudgment(pending);
        if (judgment is null)
        {
            return;
        }

        pending.GanglieJudgmentSucceeded = judgment.Value;
        if (judgment.Value && source.IsAlive)
        {
            SetDamageSkillFrameStep(pending.FrameId, ResolutionFrameStep.ResolvingEffect);
            _pendingDecision = CreateGangliePunishmentDecision(pending, source);
            _status = source.IsHuman
                ? EngineStatus.AwaitingHumanResponse
                : EngineStatus.Running;
            return;
        }

        CompleteGanglieSkill(pending, used: true);
    }

    private bool? ResolveGanglieJudgment(DamageSkillResolution pending)
    {
        return BeginJudgment(
            pending.Attack,
            pending.OwnerSeat,
            JudgmentReasons.Ganglie,
            pending.FrameId,
            pending.EffectiveCardKind,
            JudgmentContinuationKind.Ganglie,
            pending);
    }

    private void ResolveGangliePunishmentChoice(
        DamageSkillResolution pending,
        GangliePunishmentKind punishment,
        IReadOnlyList<int> discardedCardIds)
    {
        if (!ReferenceEquals(_pendingDamageSkill, pending) ||
            !pending.GanglieJudgmentSucceeded ||
            _pendingDying is not null)
        {
            throw new InvalidOperationException("The Ganglie punishment is not a current red-judgment continuation.");
        }

        var source = _players[pending.SourceSeat];
        if (!source.IsAlive)
        {
            throw new InvalidOperationException("A dead damage source cannot take a Ganglie punishment.");
        }

        pending.GangliePunishment = punishment;
        pending.GangliePunishmentCardIds = Array.AsReadOnly(discardedCardIds.ToArray());
        if (punishment == GangliePunishmentKind.DiscardTwo)
        {
            if (discardedCardIds.Count != 2 ||
                discardedCardIds.Distinct().Count() != 2)
            {
                throw new InvalidOperationException("Ganglie discard punishment requires two distinct cards.");
            }

            var discarded = discardedCardIds
                .Select(cardId => GetHand(source).SingleOrDefault(card => card.Id == cardId) ??
                    throw new InvalidOperationException("A Ganglie punishment card is not in the source hand."))
                .ToArray();
            MoveCards(
                discarded,
                CardLocation.Hand(source.Seat),
                CardLocation.DiscardPile,
                CardMoveReasons.GanglieDiscard);
            CompleteGangliePunishment(pending);
            return;
        }

        if (discardedCardIds.Count != 0)
        {
            throw new InvalidOperationException("Ganglie damage punishment cannot select cards.");
        }

        if (TryBeginBeforeDamageProgramWindowForGanglie(pending))
        {
            return;
        }

        ApplyGangliePunishmentDamage(pending);
    }

    private void ApplyGangliePunishmentDamage(DamageSkillResolution pending)
    {
        if (!ReferenceEquals(_pendingDamageSkill, pending) ||
            pending.GangliePunishment != GangliePunishmentKind.LoseHp ||
            _pendingDying is not null)
        {
            throw new InvalidOperationException("The Ganglie damage punishment is not current.");
        }

        var source = _players[pending.SourceSeat];
        if (!source.IsAlive)
        {
            CompleteGangliePunishment(pending);
            return;
        }

        // The current registry-backed rules path records this skill damage as
        // a real nested frame. Older checkpoints keep their historical event
        // stream through the compatibility rules version, even when replayed
        // against the current registry.
        if (!UsesTypedGanglieDamageFrames)
        {
            source.Hp = Math.Max(0, source.Hp - 1);
            if (source.Hp <= 0)
            {
                BeginDying(
                    pending.Attack,
                    pending.DamageFrameId,
                    source,
                    _players[pending.Attack.SourceSeat],
                    parentFrameId: pending.FrameId,
                    resumesDamageSkill: true);
                return;
            }

            CompleteGangliePunishment(pending);
            return;
        }

        var damageFrameId = BeginDamage(
            pending.FrameId,
            pending.OwnerSeat,
            source.Seat,
            amount: 1,
            nature: DamageNature.Normal);
        pending.GanglieDamageFrameId = damageFrameId;
        QueueGameEvent(new DamageRequestedEvent(
            damageFrameId,
            pending.OwnerSeat,
            source.Seat,
            Amount: 1,
            SourceCard: null,
            Nature: DamageNature.Normal));
        var nestedAttack = new AttackResolution(
            pending.FrameId, pending.OwnerSeat, source.Seat, card: null, damageAmount: 1,
            damageNatureOverride: DamageNature.Normal);
        nestedAttack.CaptureDamageDistance(pending.OwnerSeat == source.Seat
            ? 0
            : GetCombatDistance(pending.OwnerSeat, source.Seat));
        source.Hp = Math.Max(0, source.Hp - 1);
        nestedAttack.MarkDamageApplied();
        QueueGameEvent(new DamageAppliedEvent(
            pending.OwnerSeat,
            source.Seat,
            Amount: 1,
            RemainingHp: Math.Max(0, source.Hp),
            Nature: DamageNature.Normal));
        ApplyHengyeGrowth(
            damageFrameId,
            _players[pending.OwnerSeat],
            source,
            amount: 1);
        if (_pendingDamageTrigger is not { } outerTrigger)
        {
            throw new InvalidOperationException("Nested Ganglie damage lost its outer trigger window.");
        }
        _pendingNestedGanglieDamage = new NestedGanglieDamageResolution(
            nestedAttack, pending, outerTrigger, _pendingNestedGanglieDamage);
        _pendingDamageSkill = null;
        _pendingDamageTrigger = null;
        if (TryBeginDamageTriggerWindow(
                nestedAttack, damageFrameId, SkillProgramTriggerWindow.DamageAppliedBeforeDying))
            return;
        if (source.Hp <= 0)
        {
            BeginDying(nestedAttack, damageFrameId, source, _players[pending.OwnerSeat]);
            return;
        }
        if (TryBeginDamageTriggerWindow(
                nestedAttack, damageFrameId, SkillProgramTriggerWindow.AfterDamageApplied))
            return;
        QueueGameEvent(new AfterDamageEvent(
            damageFrameId, pending.OwnerSeat, source.Seat, 1,
            Math.Max(0, source.Hp), DamageNature.Normal));
        PopResolutionFrame(damageFrameId, ResolutionFrameKind.Damage);
        CompleteDamageAttack(nestedAttack);
    }

    private void CompleteGanglieDamage(DamageSkillResolution pending)
    {
        var damageFrameId = pending.GanglieDamageFrameId ??
            throw new InvalidOperationException("Ganglie damage has no active damage frame.");
        var source = _players[pending.SourceSeat];
        QueueGameEvent(new AfterDamageEvent(
            damageFrameId,
            pending.OwnerSeat,
            source.Seat,
            Amount: 1,
            RemainingHp: Math.Max(0, source.Hp),
            Nature: DamageNature.Normal));
        PopResolutionFrame(damageFrameId, ResolutionFrameKind.Damage);
        CompleteGangliePunishment(pending);
    }

    private void CompleteGangliePunishment(DamageSkillResolution pending)
    {
        var source = _players[pending.SourceSeat];
        QueueGameEvent(new GangliePunishmentResolvedEvent(
            pending.GanglieDamageFrameId ?? pending.DamageFrameId,
            pending.OwnerSeat,
            pending.SourceSeat,
            pending.GangliePunishment ??
                throw new InvalidOperationException("Ganglie punishment was not selected."),
            pending.GangliePunishmentCardIds,
            Math.Max(0, source.Hp),
            source.IsAlive));
        AddLog(
            "GangliePunishment",
            pending.GangliePunishment == GangliePunishmentKind.DiscardTwo
                ? $"{source.Name} 因【刚烈】弃置两张手牌。"
                : $"{source.Name} 因【刚烈】承受 1 点伤害，剩余 {Math.Max(0, source.Hp)} 点体力。",
            pending.SourceSeat,
            pending.OwnerSeat);
        CompleteGanglieSkill(pending, used: true);
    }

    private void CompleteGanglieSkill(DamageSkillResolution pending, bool used)
    {
        if (!ReferenceEquals(_pendingDamageSkill, pending))
        {
            throw new InvalidOperationException("The completed Ganglie skill is not current.");
        }

        var window = _pendingDamageTrigger ??
            throw new InvalidOperationException("A Ganglie skill must belong to a damage trigger window.");
        if (window.FrameId != pending.TriggerFrameId || window.DamageFrameId != pending.DamageFrameId)
        {
            throw new InvalidOperationException("The Ganglie skill does not belong to the current trigger window.");
        }

        var owner = _players[pending.OwnerSeat];
        var source = _players[pending.SourceSeat];
        SetDamageSkillFrameStep(pending.FrameId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new DamageSkillResolvedEvent(
            pending.DamageFrameId,
            pending.OwnerSeat,
            pending.SourceSeat,
            pending.Card?.Id,
            pending.EffectiveCardKind,
            pending.Skill,
            used,
            pending.CandidateId,
            pending.Priority,
            pending.GangliePunishment is null ? null : source.Seat));
        AddLog(
            "SkillTriggered",
            !used
                ? $"{owner.Name} 选择不发动【刚烈】。"
                : pending.GangliePunishment is { } punishment
                    ? punishment == GangliePunishmentKind.DiscardTwo
                        ? $"{owner.Name} 发动【刚烈】并令 {source.Name} 弃置两张手牌。"
                        : $"{owner.Name} 发动【刚烈】并令 {source.Name} 承受 1 点伤害。"
                    : pending.GanglieJudgmentSucceeded
                        ? $"{owner.Name} 发动【刚烈】，伤害来源已不再可受罚。"
                        : $"{owner.Name} 发动【刚烈】，判定未成功。",
            owner.Seat,
            source.Seat);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.DamageSkill);
        _pendingDamageSkill = null;
        SetDamageTriggerWindowStep(window.FrameId, ResolutionFrameStep.ResolvingEffect);
        AdvanceDamageTriggerCandidate(window);
    }

    private void ResolveDamageSkillChoice(
        DamageSkillResolution pending,
        bool useSkill,
        int? selectedCardId = null,
        int? selectedTargetSeat = null)
    {
        if (!ReferenceEquals(_pendingDamageSkill, pending))
        {
            throw new InvalidOperationException("The completed damage skill is not current.");
        }

        var window = _pendingDamageTrigger ??
            throw new InvalidOperationException("A damage skill must belong to a damage trigger window.");
        if (window.FrameId != pending.TriggerFrameId || window.DamageFrameId != pending.DamageFrameId)
        {
            throw new InvalidOperationException("The damage skill does not belong to the current trigger window.");
        }

        if (pending.Effect == DamageSkillEffectKind.GanglieJudgment)
        {
            ResolveGanglieChoice(pending, useSkill);
            return;
        }

        var owner = _players[pending.OwnerSeat];
        var source = _players[pending.SourceSeat];
        var skill = SkillRegistry.Get(pending.Skill).Damage!;
        var damageContext = CreateDamageSkillContext(pending.Attack, owner);
        Card? yuanhuDiscardedCard = null;
        CharacterState? yuanhuRecoveredTarget = null;
        var yuanhuRecoveryAmount = 0;
        if (useSkill)
        {
            switch (pending.Effect)
            {
                case DamageSkillEffectKind.RecoverDamageTarget:
                    if (selectedCardId is not { } yuanhuCardId ||
                        selectedTargetSeat is not { } yuanhuTargetSeat ||
                        yuanhuTargetSeat != pending.Attack.TargetSeat ||
                        !IsValidPlayerSeat(yuanhuTargetSeat) ||
                        !GetHand(owner).Any(card => card.Id == yuanhuCardId))
                    {
                        throw new InvalidOperationException("The selected Yuanhu card or target is not legal.");
                    }

                    yuanhuRecoveredTarget = _players[yuanhuTargetSeat];
                    if (!yuanhuRecoveredTarget.IsAlive ||
                        yuanhuRecoveredTarget.Hp <= 0 ||
                        yuanhuRecoveredTarget.Hp >= yuanhuRecoveredTarget.MaxHp ||
                        !skill.CanTriggerAfterDamage(damageContext) ||
                        !skill.OffersDamageCardChoice(damageContext))
                    {
                        throw new InvalidOperationException("The Yuanhu target is no longer recoverable.");
                    }

                    yuanhuDiscardedCard = GetHand(owner).Single(card => card.Id == yuanhuCardId);
                    MoveCard(
                        yuanhuDiscardedCard,
                        CardLocation.Hand(owner.Seat),
                        CardLocation.DiscardPile,
                        CardMoveReasons.YuanhuDiscard);
                    QueueGameEvent(new DamageSkillCardDiscardedEvent(
                        pending.DamageFrameId,
                        owner.Seat,
                        yuanhuDiscardedCard.Id,
                        yuanhuDiscardedCard.Kind,
                        pending.Skill));

                    var recoveryFrameId = BeginRecovery(
                        pending.DamageFrameId,
                        owner.Seat,
                        yuanhuRecoveredTarget.Seat,
                        1);
                    try
                    {
                        yuanhuRecoveredTarget.Hp = Math.Min(
                            yuanhuRecoveredTarget.MaxHp,
                            yuanhuRecoveredTarget.Hp + 1);
                        yuanhuRecoveryAmount = 1;
                        AddLog(
                            "Recovered",
                            $"{owner.Name} 因【{skill.Name}】使 {yuanhuRecoveredTarget.Name} 回复至 {yuanhuRecoveredTarget.Hp}/{yuanhuRecoveredTarget.MaxHp} 点体力。",
                            owner.Seat,
                            yuanhuRecoveredTarget.Seat);
                        QueueGameEvent(new RecoveryAppliedEvent(
                            owner.Seat,
                            yuanhuRecoveredTarget.Seat,
                            yuanhuRecoveryAmount,
                            yuanhuRecoveredTarget.Hp));
                    }
                    finally
                    {
                        PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
                    }

                    break;
                default:
                    throw new InvalidOperationException(
                        $"Skill {pending.Skill} has no supported damage effect.");
            }
        }

        SetDamageSkillFrameStep(pending.FrameId, ResolutionFrameStep.ResolvingEffect);
        QueueGameEvent(new DamageSkillResolvedEvent(
            pending.DamageFrameId,
            pending.OwnerSeat,
            pending.SourceSeat,
            pending.Card?.Id,
            pending.EffectiveCardKind,
            pending.Skill,
            useSkill,
            pending.CandidateId,
            pending.Priority,
            yuanhuRecoveredTarget?.Seat));
        AddLog(
            "SkillTriggered",
            useSkill
                ? pending.Effect switch
                {
                    DamageSkillEffectKind.RecoverDamageTarget =>
                        $"{owner.Name} 触发【{skill.Name}】，弃置【{yuanhuDiscardedCard!.DisplayName}】令 {yuanhuRecoveredTarget!.Name} 回复 1 点体力。",
                    _ => $"{owner.Name} 触发【{skill.Name}】。"
                }
                : pending.Effect switch
                {
                    DamageSkillEffectKind.RecoverDamageTarget =>
                        $"{owner.Name} 选择不发动【{skill.Name}】。",
                    _ => $"{owner.Name} 选择不发动【{skill.Name}】，伤害牌将进入弃牌堆。"
                },
            owner.Seat,
            source.Seat);
        PopResolutionFrame(pending.FrameId, ResolutionFrameKind.DamageSkill);
        _pendingDamageSkill = null;
        SetDamageTriggerWindowStep(window.FrameId, ResolutionFrameStep.ResolvingEffect);
        AdvanceDamageTriggerCandidate(window);
    }

    private IReadOnlyList<DamageTriggerCandidate> CollectDamageTriggerCandidates(
        DamageSkillContext context,
        AttackResolution attack,
        SkillProgramTriggerWindow window)
    {
        var candidates = new List<DamageTriggerCandidate>();
        if (window == SkillProgramTriggerWindow.AfterDamageApplied)
        {
        foreach (var owner in _players.Where(player => player.IsAlive))
            foreach (var skill in EnabledSkillRules(owner).Select(definition => definition.Damage).OfType<IDamageSkillRule>())
            {
                var ownerContext = context with
                {
                    Owner = CreateSkillContext(owner)
                };
                if (!skill.CanTriggerAfterDamage(ownerContext))
                {
                    continue;
                }

                var effect = ResolveDamageSkillEffect(skill, ownerContext);
                if (effect == DamageSkillEffectKind.None)
                {
                    continue;
                }

                var offersChoice = skill.OffersDamageCardChoice(ownerContext) ||
                                   skill.Kind == SkillKind.Yaowu && UsesFormalHuaXiong;

                candidates.Add(new DamageTriggerCandidate(
                    owner.Seat,
                    skill.Kind,
                    skill.DamageTriggerId,
                    skill.DamageTriggerPriority,
                    IsOptional: offersChoice,
                    Effect: effect));
            }
        }

        foreach (var programOwnerSeat in new[] { context.TargetSeat, context.SourceSeat }
                     .OfType<int>().Distinct())
        foreach (var candidate in CollectProgramTriggerCandidates(
                     _players[programOwnerSeat], window))
        {
            var trigger = _contentRegistry!.GetSkill(candidate.SkillId).Program!.Triggers
                .Single(item => item.Id == candidate.BindingId);
            var ownsTiming = trigger.Subject switch
            {
                SkillProgramTriggerSubject.Owner => programOwnerSeat == context.TargetSeat,
                SkillProgramTriggerSubject.Source => programOwnerSeat == context.SourceSeat &&
                    MatchesAfterDamageProgramSource(attack, trigger),
                SkillProgramTriggerSubject.DamageSource => programOwnerSeat == context.SourceSeat,
            _ => false
            };
            if (!ownsTiming) continue;
            var occurrenceIndexes = trigger.DamageOccurrence switch
            {
                null or SkillProgramDamageOccurrence.PerDamage => [0],
                SkillProgramDamageOccurrence.PerDamagePoint =>
                    Enumerable.Range(0, Math.Max(0, context.Amount)).ToArray(),
                _ => throw new InvalidOperationException(
                    "An after-damage trigger lost its occurrence policy.")
            };
            foreach (var occurrenceIndex in occurrenceIndexes)
            {
                candidates.Add(new DamageTriggerCandidate(
                    candidate.OwnerSeat,
                    SkillKind.None,
                    $"program:{candidate.SkillId}:{candidate.BindingId}:{candidate.SkillInstanceId}:occurrence-{occurrenceIndex}",
                    candidate.Priority,
                    IsOptional: trigger.Optional,
                    ProgramId: candidate.SkillId,
                    ProgramTriggerId: candidate.BindingId,
                    SkillInstanceId: candidate.SkillInstanceId,
                    GameplayHash: candidate.GameplayHash,
                    OccurrenceIndex: occurrenceIndex));
            }
        }

        return candidates;
    }

    private static bool MatchesAfterDamageProgramSource(
        AttackResolution attack,
        SkillProgramTrigger trigger) =>
        attack.ConversionSource is { } source &&
        string.Equals(source.SkillId, trigger.SourceSkillId, StringComparison.Ordinal) &&
        (trigger.SourceViewAsId is null ||
         string.Equals(source.BindingId, trigger.SourceViewAsId, StringComparison.Ordinal));

    private DamageSkillEffectKind ResolveDamageSkillEffect(
        IDamageSkillRule skill,
        DamageSkillContext context)
    {
        if (skill.Kind == SkillKind.Kuanggu)
        {
            return UsesFormalKuanggu
                ? skill.GetDamageSkillEffect(context)
                : DamageSkillEffectKind.None;
        }

        return skill.GetDamageSkillEffect(context);
    }

    private DamageSkillContext CreateDamageSkillContext(
        AttackResolution attack,
        CharacterState owner)
    {
        var target = _players[attack.TargetSeat];
        return new(
            CreateSkillContext(owner),
            attack.SourceSeat,
            attack.EffectiveCardKind,
            SourceCardIsInProcessing:
                attack.Card is { } sourceCard &&
                _cardZones.GetLocation(sourceCard.Id) == CardLocation.Processing,
            Nature: GetDamageNature(attack),
            Amount: attack.DamageAmount,
            SourceCardId: attack.Card?.Id,
            SourceCardSuit: attack.Card?.Suit,
            TargetSeat: attack.TargetSeat,
            TargetHp: target.Hp,
            TargetMaxHp: target.MaxHp,
            SourceCardCount: GetHand(_players[attack.SourceSeat]).Count +
                             GetEquipment(_players[attack.SourceSeat]).Count,
            SourceToTargetDistance: attack.SourceToTargetDistanceAtDamage);
    }

    private void RecoverDamageSourceThroughKuanggu(
        AttackResolution attack,
        long damageFrameId,
        CharacterState owner,
        IDamageSkillRule skill,
        DamageSkillContext context)
    {
        if (skill.Kind != SkillKind.Kuanggu ||
            owner.Seat != attack.SourceSeat ||
            ResolveDamageSkillEffect(skill, context) != DamageSkillEffectKind.RecoverDamageSource)
        {
            throw new InvalidOperationException("Kuanggu can only recover the eligible current damage source.");
        }

        var recoveryAmount = Math.Min(context.Amount, owner.MaxHp - owner.Hp);
        if (recoveryAmount <= 0)
        {
            throw new InvalidOperationException("Kuanggu recovery requires a wounded damage source.");
        }

        var recoveryFrameId = BeginRecovery(
            damageFrameId,
            owner.Seat,
            owner.Seat,
            recoveryAmount);
        try
        {
            owner.Hp += recoveryAmount;
            QueueGameEvent(new RecoveryAppliedEvent(
                owner.Seat,
                owner.Seat,
                recoveryAmount,
                owner.Hp));
            QueueGameEvent(new KuangguRecoveredEvent(
                damageFrameId,
                owner.Seat,
                attack.TargetSeat,
                context.Amount,
                recoveryAmount,
                owner.Hp));
            AddLog(
                "SkillTriggered",
                $"{owner.Name} 触发【{skill.Name}】，因对 {_players[attack.TargetSeat].Name} 造成 {context.Amount} 点伤害回复 {recoveryAmount} 点体力。",
                owner.Seat,
                attack.TargetSeat);
        }
        finally
        {
            PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
        }
    }

    private void BeginDying(
        AttackResolution attack,
        long damageFrameId,
        CharacterState victim,
        CharacterState killer,
        long? parentFrameId = null,
        bool resumesDamageSkill = false)
    {
        if (_pendingDying is not null)
        {
            throw new InvalidOperationException("The engine cannot resolve two dying players at once.");
        }

        var responderSeats = Array.AsReadOnly(BuildDyingResponderSeats(victim.Seat).ToArray());
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new DyingFrame(
            frameId,
            parentFrameId ?? damageFrameId,
            victim.Seat,
            killer.Seat,
            responderSeats,
            ResponderIndex: 0));
        _pendingDying = new DyingResolution(
            frameId,
            damageFrameId,
            attack,
            victim.Seat,
            killer.Seat,
            responderSeats,
            parentFrameId ?? damageFrameId,
            resumesDamageSkill
                ? DyingContinuation.DamageSkill
                : DyingContinuation.Damage);
        QueueGameEvent(new PlayerDyingEvent(frameId, victim.Seat, killer.Seat));
        _status = EngineStatus.Running;
        if (TryResolveBuqu(_pendingDying))
        {
            return;
        }
        ExposeHumanDyingPrompt();
    }

    private void BeginActiveSkillDying(long activeSkillFrameId, CharacterState victim)
    {
        if (_pendingDying is not null)
        {
            throw new InvalidOperationException("The engine cannot resolve two dying players at once.");
        }

        if (_resolutionStack.LastOrDefault() is not ActiveSkillFrame activeSkill ||
            activeSkill.Id != activeSkillFrameId ||
            activeSkill.SourceSeat != victim.Seat)
        {
            throw new InvalidOperationException(
                "An active-skill dying continuation must retain its owner's active-skill frame.");
        }

        var responderSeats = Array.AsReadOnly(BuildDyingResponderSeats(victim.Seat).ToArray());
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new DyingFrame(
            frameId,
            activeSkillFrameId,
            victim.Seat,
            null,
            responderSeats,
            0));
        _pendingDying = new DyingResolution(
            frameId,
            null,
            null,
            victim.Seat,
            null,
            responderSeats,
            activeSkillFrameId,
            DyingContinuation.ActiveSkill);
        QueueGameEvent(new PlayerDyingEvent(frameId, victim.Seat, null));
        _status = EngineStatus.Running;
        if (TryResolveBuqu(_pendingDying))
        {
            return;
        }
        ExposeHumanDyingPrompt();
    }

    private void BeginGanglieDying(DamageSkillResolution pending)
    {
        var source = _players[pending.SourceSeat];
        var owner = _players[pending.OwnerSeat];
        var damageFrameId = pending.GanglieDamageFrameId ??
            throw new InvalidOperationException("Ganglie dying has no active damage frame.");
        BeginDying(
            pending.Attack,
            damageFrameId,
            source,
            owner,
            parentFrameId: pending.FrameId,
            resumesDamageSkill: true);
    }

    private IReadOnlyList<int> BuildDyingResponderSeats(int victimSeat)
    {
        var seats = new List<int>(_playerCount);
        for (var offset = 0; offset < _playerCount; offset++)
        {
            var seat = (victimSeat + offset) % _playerCount;
            if (_players[seat].IsAlive)
            {
                seats.Add(seat);
            }
        }

        return seats;
    }

    private bool TryResolveBuqu(DyingResolution? dying)
    {
        if (!UsesFormalZhouTai || dying is null)
            return false;
        var victim = _players[dying.VictimSeat];
        if (!victim.IsAlive || !HasRuntimeSkill(victim, SkillKind.Buqu) || !EnsureDrawPile())
            return false;
        var card = _cardZones.CardsAt(CardLocation.DrawPile)[^1];
        var unique = GetBuquWounds(victim).All(wound => wound.Rank != card.Rank);
        if (unique)
        {
            MoveCard(card, CardLocation.DrawPile, CardLocation.BuquWound(victim.Seat), CardMoveReasons.BuquReveal);
            victim.Hp = 1;
        }
        else
        {
            MoveCard(card, CardLocation.DrawPile, CardLocation.DiscardPile, CardMoveReasons.BuquDuplicate);
        }
        var wounds = GetBuquWounds(victim).Select(wound => wound.Id).ToArray();
        QueueGameEvent(new BuquResolvedEvent(
            dying.FrameId, victim.Seat, card.Id, card.Rank, unique, Array.AsReadOnly(wounds)));
        AddLog("SkillTriggered", unique
            ? $"{victim.Name} 的【不屈】亮出点数 {card.Rank}，与已有“创”不同，回复至 1 点体力。"
            : $"{victim.Name} 的【不屈】亮出重复点数 {card.Rank}，该牌置入弃牌堆并继续濒死结算。",
            victim.Seat);
        if (unique)
            CompleteDying(dying, survived: true);
        return unique;
    }

    private Card[] GetDyingPeaches(CharacterState responder)
    {
        var context = CreateSkillContext(responder);
        var passiveSkills = ConversionRules(responder).ToArray();
        var handCandidates = GetPlayableCards(responder)
            .Where(card => !IsTurnHandCardRestricted(responder, card))
            .Where(card => !HasProgramCardIdentity(responder, card))
            .Where(card => card.Kind == CardKind.Peach || passiveSkills.Any(skill =>
                skill is JijiuSkill && (!IsClassicIdentityMode)
                    ? card.Kind != CardKind.Peach && card.Suit is Suit.Heart or Suit.Diamond
                    : skill.CanUseAsDyingRescue(context, card)))
            .ToArray();

        if (!UsesFormalJijiuEquipment)
        {
            return handCandidates;
        }

        return handCandidates
            .Concat(GetEquipment(responder).Where(card => passiveSkills.Any(skill =>
                skill is JijiuSkill && skill.CanUseAsDyingRescue(context, card))))
            .ToArray();
    }

    private Card[] GetDyingAlcohols(CharacterState responder, int victimSeat) =>
        responder.Seat == victimSeat
            ? GetHand(responder)
                .Where(card => card.Kind == CardKind.Alcohol &&
                               !HasProgramCardIdentity(responder, card))
                .ToArray()
            : [];

    private bool CanUseNiepan(CharacterState responder, DyingResolution dying)
    {
        if (!UsesFormalPangTong || responder.Seat != dying.VictimSeat || !responder.IsAlive ||
            !HasRuntimeSkill(responder, SkillKind.Niepan))
            return false;

        var contentMetadata = GetEnabledContentSkill(responder, SkillKind.Niepan);
        var legacyMetadata = responder.General.Skills.FirstOrDefault(skill => skill.Kind == SkillKind.Niepan);
        var skillId = contentMetadata?.Id ?? legacyMetadata?.ContentId;
        var tags = contentMetadata?.Tags ?? legacyMetadata?.Tags ?? SkillTag.None;
        return skillId is not null &&
               tags.HasFlag(SkillTag.Limited)
            ? _skillRuntimeState.GetUsage(
                responder.Seat, skillId, "activation", SkillUsageScope.Game) == 0
            : !responder.UsedLimitedSkillKinds.Contains(SkillKind.Niepan);
    }

    private void RunOneDyingStep()
    {
        var dying = _pendingDying ??
            throw new InvalidOperationException("A dying step requires a pending dying resolution.");
        if (_pendingDecision is not null)
        {
            return;
        }

        if (dying.ResponderIndex >= dying.ResponderSeats.Count)
        {
            CompleteDying(dying, survived: false);
            PublishState();
            return;
        }

        var responder = _players[dying.ResponderSeat];
        var peaches = GetDyingPeaches(responder);
        var alcohols = GetDyingAlcohols(responder, dying.VictimSeat);
        var programCandidates = GetDyingProgramCandidates(responder, dying);
        if (responder.IsHuman)
        {
            if (peaches.Length > 0 || alcohols.Length > 0 || CanUseNiepan(responder, dying) ||
                programCandidates.Count > 0)
            {
                RequestHumanDyingResponse(responder, peaches, alcohols);
                return;
            }

            ApplyDyingResponse(
                responder,
                usePeach: false,
                peachCardId: null,
                useAlcohol: false,
                alcoholCardId: null);
            PublishState();
            return;
        }

        if (programCandidates.FirstOrDefault(item =>
                GetProgramTrigger(item).Window == SkillProgramTriggerWindow.SelfDyingResponse) is
            { } programCandidate)
        {
            BeginDyingProgramBinding(programCandidate, dying);
            PublishState();
            return;
        }

        foreach (var rescueCandidate in programCandidates.Where(item =>
            GetProgramTrigger(item).Window == SkillProgramTriggerWindow.DyingResponse))
        {
            var (useRescue, rescueThought) = _aiBrains[responder.Seat].ChooseProgramDyingRescue(
                CreateSnapshot(responder.Seat), dying.VictimSeat,
                _contentRegistry!.GetSkill(rescueCandidate.SkillId).Name, ++_thoughtSequence);
            AddThought(rescueThought);
            if (!useRescue) continue;
            BeginDyingProgramBinding(rescueCandidate, dying);
            PublishState();
            return;
        }

        if (CanUseNiepan(responder, dying))
        {
            ResolveNiepan();
            PublishState();
            return;
        }

        var view = CreateSnapshot(responder.Seat);
        var (usePeach, peachCardId, useAlcohol, alcoholCardId, thought) = _aiBrains[responder.Seat].ChooseDyingResponseWithAlcohol(
            view,
            dying.VictimSeat,
            peaches,
            alcohols,
            ++_thoughtSequence,
            false);
        AddThought(thought);
        ApplyDyingResponse(
            responder,
            usePeach,
            peachCardId,
            useAlcohol,
            alcoholCardId);
        PublishState();
    }

    private void ExposeHumanDyingPrompt()
    {
        var dying = _pendingDying;
        if (dying is null || _pendingDecision is not null ||
            dying.ResponderIndex >= dying.ResponderSeats.Count)
        {
            return;
        }

        var responder = _players[dying.ResponderSeat];
        if (!responder.IsHuman)
        {
            return;
        }

        var peaches = GetDyingPeaches(responder);
        var alcohols = GetDyingAlcohols(responder, dying.VictimSeat);
        var programCandidates = GetDyingProgramCandidates(responder, dying);
        if (peaches.Length > 0 || alcohols.Length > 0 || CanUseNiepan(responder, dying) ||
            programCandidates.Count > 0)
        {
            RequestHumanDyingResponse(responder, peaches, alcohols);
        }
    }

    private void RequestHumanDyingResponse(
        CharacterState responder,
        IReadOnlyList<Card> peaches,
        IReadOnlyList<Card> alcohols)
    {
        var dying = _pendingDying ??
            throw new InvalidOperationException("There is no dying resolution for the prompt.");
        var victim = _players[dying.VictimSeat];
        var choices = peaches.Select(peach => new PromptChoice(
            new ChoiceId($"dying.peach.card-{peach.Id}"),
            peach.Kind == CardKind.Peach
                ? $"使用【桃】救援 {victim.Name}。"
                : $"将【{peach.DisplayName}】当作【桃】救援 {victim.Name}。",
            [peach.Id],
            [],
            new Dictionary<string, string>
            {
                ["response"] = "peach",
                ["physical-card-kind"] = peach.Kind.ToString(),
                ["target-seat"] = victim.Seat.ToString(System.Globalization.CultureInfo.InvariantCulture)
            })).ToList();
        choices.AddRange(alcohols.Select(alcohol => new PromptChoice(
            new ChoiceId($"dying.alcohol.card-{alcohol.Id}"),
            responder.Seat == victim.Seat
                ? $"使用【酒】自救，使 {victim.Name} 回复 1 点体力。"
                : $"使用【酒】救援 {victim.Name}，使其回复 1 点体力。",
            [alcohol.Id],
            [],
            new Dictionary<string, string>
            {
                ["response"] = "alcohol",
                ["target-seat"] = victim.Seat.ToString(System.Globalization.CultureInfo.InvariantCulture)
            })));
        if (CanUseNiepan(responder, dying))
        {
            choices.Add(new PromptChoice(
                new ChoiceId("dying.niepan"),
                "发动限定技【涅槃】：弃置区域内所有牌，解除连环，摸三张牌并将体力回复至 3 点。",
                [], [],
                new Dictionary<string, string>
                {
                    ["response"] = "niepan",
                    ["target-seat"] = victim.Seat.ToString(System.Globalization.CultureInfo.InvariantCulture)
                }));
        }
        var programCandidates = GetDyingProgramCandidates(responder, dying);
        foreach (var candidate in programCandidates)
        {
            var skill = _contentRegistry!.GetSkill(candidate.SkillId);
            choices.Add(new PromptChoice(
                new ChoiceId($"dying.program.{candidate.SkillId}.{candidate.BindingId}.{candidate.SkillInstanceId}"),
                GetProgramTrigger(candidate).Window == SkillProgramTriggerWindow.DyingResponse
                    ? $"发动【{skill.Name}】救援 {victim.Name}。"
                    : $"发动【{skill.Name}】：{skill.Description}",
                [], [],
                new Dictionary<string, string>
                {
                    ["response"] = "program-trigger",
                    ["skill-id"] = candidate.SkillId,
                    ["binding-id"] = candidate.BindingId,
                    ["skill-instance-id"] = candidate.SkillInstanceId,
                    ["target-seat"] = victim.Seat.ToString(System.Globalization.CultureInfo.InvariantCulture),
                }));
        }
        var rescueCardIds = peaches
            .Select(card => card.Id)
            .Concat(alcohols.Select(card => card.Id))
            .ToArray();
        var rescueNameParts = new List<string>();
        if (peaches.Count > 0) rescueNameParts.Add("桃");
        if (alcohols.Count > 0) rescueNameParts.Add("酒");
        if (CanUseNiepan(responder, dying)) rescueNameParts.Add("涅槃");
        rescueNameParts.AddRange(programCandidates.Select(candidate =>
            _contentRegistry!.GetSkill(candidate.SkillId).Name));
        var rescueNames = string.Join("】或【", rescueNameParts);
        choices.Add(new PromptChoice(
            new ChoiceId("dying.let-die"),
            $"不使用【{rescueNames}】，让 {victim.Name} 阵亡。",
            [],
            [],
            new Dictionary<string, string>
            {
                ["response"] = "let-die",
                ["target-seat"] = victim.Seat.ToString(System.Globalization.CultureInfo.InvariantCulture)
            }));

        _pendingDecision = new PendingDecision(
            DecisionKind.RescueDying,
            responder.Seat,
            $"{victim.Name} 进入濒死状态，是否使用【{rescueNames}】救援？",
            rescueCardIds,
            [],
            SourceSeat: victim.Seat)
        {
            PromptId = CreatePromptId(),
            Choices = choices,
            TargetSeat = victim.Seat
        };
        _status = EngineStatus.AwaitingHumanDying;
        PublishState();
    }

    private void ResolveNiepan()
    {
        var dying = _pendingDying ?? throw new InvalidOperationException("There is no dying resolution for Niepan.");
        var victim = _players[dying.VictimSeat];
        if (!CanUseNiepan(victim, dying) ||
            _pendingDecision is { } decision &&
            (decision.Kind != DecisionKind.RescueDying || decision.PlayerSeat != victim.Seat))
        {
            throw new InvalidOperationException("Niepan is not legal in the current dying window.");
        }

        ClearPendingDecision();
        var contentMetadata = GetEnabledContentSkill(victim, SkillKind.Niepan);
        var legacyMetadata = victim.General.Skills.FirstOrDefault(skill => skill.Kind == SkillKind.Niepan);
        var skillId = contentMetadata?.Id ?? legacyMetadata?.ContentId;
        var tags = contentMetadata?.Tags ?? legacyMetadata?.Tags ?? SkillTag.None;
        if (skillId is not null &&
            tags.HasFlag(SkillTag.Limited))
        {
            if (!_skillRuntimeState.TryConsumeUsage(
                    victim.Seat, skillId, "activation", SkillUsageScope.Game, limit: 1))
                throw new InvalidOperationException("Niepan has already been used in this game.");
        }
        else
        {
            victim.UsedLimitedSkillKinds.Add(SkillKind.Niepan);
        }
        var discarded = 0;
        foreach (var card in GetHand(victim).ToArray())
        {
            MoveCard(card, CardLocation.Hand(victim.Seat), CardLocation.DiscardPile, CardMoveReasons.NiepanDiscard);
            discarded++;
        }
        foreach (var card in GetEquipment(victim).ToArray())
        {
            MoveCard(card, CardLocation.Equipment(victim.Seat), CardLocation.DiscardPile, CardMoveReasons.NiepanDiscard);
            discarded++;
        }
        foreach (var card in GetJudgment(victim).ToArray())
        {
            MoveCard(card, CardLocation.Judgment(victim.Seat), CardLocation.DiscardPile, CardMoveReasons.NiepanDiscard);
            discarded++;
        }
        victim.IsChained = false;
        victim.Hp = Math.Min(3, victim.MaxHp);
        var drawn = DrawCards(victim, 3, log: false, reason: CardMoveReasons.NiepanDraw);
        QueueGameEvent(new NiepanResolvedEvent(dying.FrameId, victim.Seat, discarded, drawn.Count, victim.Hp));
        AddLog("SkillTriggered", $"{victim.Name} 发动限定技【涅槃】，弃置 {discarded} 张区域牌，摸 {drawn.Count} 张牌并回复至 {victim.Hp} 点体力。", victim.Seat);
        CompleteDying(dying, survived: true);
    }

    private void ApplyDyingResponse(
        CharacterState responder,
        bool usePeach,
        int? peachCardId,
        bool useAlcohol,
        int? alcoholCardId)
    {
        var dying = _pendingDying ??
            throw new InvalidOperationException("There is no dying response to apply.");
        if (responder.Seat != dying.ResponderSeat)
        {
            throw new InvalidOperationException("The response does not belong to the current dying responder.");
        }

        var victim = _players[dying.VictimSeat];
        SetDyingFrameStep(dying.FrameId, ResolutionFrameStep.ResolvingEffect);
        int? usedPeachCardId = null;
        CardKind? usedPeachPhysicalCardKind = null;
        int? usedAlcoholCardId = null;
        if (usePeach && useAlcohol)
        {
            throw new InvalidOperationException("A dying response can use only one rescue source.");
        }
        if (usePeach)
        {
            var peach = GetDyingPeaches(responder).FirstOrDefault(card =>
                (!peachCardId.HasValue || card.Id == peachCardId.Value));
            if (peach is null)
            {
                throw new InvalidOperationException("The requested Peach is not in the responder's playable zones.");
            }

            usedPeachCardId = peach.Id;
            usedPeachPhysicalCardKind = peach.Kind == CardKind.Peach ? null : peach.Kind;
            ResolvePeach(responder, victim, peach, allowDying: true);
        }
        if (useAlcohol)
        {
            if (responder.Seat != victim.Seat)
            {
                throw new InvalidOperationException("Alcohol can only rescue its dying holder.");
            }
            var alcohol = GetHand(responder).FirstOrDefault(card =>
                card.Kind == CardKind.Alcohol &&
                !HasProgramCardIdentity(responder, card) &&
                (!alcoholCardId.HasValue || card.Id == alcoholCardId.Value));
            if (alcohol is null)
            {
                throw new InvalidOperationException("The requested Alcohol is not in the responder's hand.");
            }
            usedAlcoholCardId = alcohol.Id;
            ResolveDyingAlcohol(responder, victim, alcohol);
        }
        QueueGameEvent(new DyingResponseEvent(
            dying.FrameId,
            responder.Seat,
            usePeach,
            usedPeachCardId,
            useAlcohol,
            usedAlcoholCardId)
        {
            UsedPeachPhysicalCardKind = usedPeachPhysicalCardKind
        });
        dying.ResponderIndex++;

        if (victim.Hp > 0)
        {
            CompleteDying(dying, survived: true);
            return;
        }

        if (dying.ResponderIndex >= dying.ResponderSeats.Count)
        {
            CompleteDying(dying, survived: false);
            return;
        }

        SetDyingFrameStep(dying.FrameId, ResolutionFrameStep.AwaitingResponse);
        _status = EngineStatus.Running;
        ExposeHumanDyingPrompt();
    }

    private void CompleteDying(DyingResolution dying, bool survived)
    {
        if (!ReferenceEquals(_pendingDying, dying))
        {
            throw new InvalidOperationException("The completed dying resolution is not current.");
        }

        SetDyingFrameStep(dying.FrameId, ResolutionFrameStep.ResolvingEffect);
        if (!survived)
        {
            FinalizePlayerDeath(dying);
            return;
        }

        CompleteDyingAfterDeath(dying, survived);
    }

    private void CompleteDyingAfterDeath(DyingResolution dying, bool survived)
    {
        if (!ReferenceEquals(_pendingDying, dying))
        {
            throw new InvalidOperationException("The completed dying continuation is not current.");
        }
        QueueGameEvent(new DyingResolvedEvent(dying.FrameId, dying.VictimSeat, survived));
        PopResolutionFrame(dying.FrameId, ResolutionFrameKind.Dying);
        _pendingDying = null;
        if (dying.ResumesProgramSkill)
        {
            CompleteProgramSkillAfterDying(dying);
            return;
        }
        if (dying.ResumesActiveSkill)
        {
            CompleteActiveSkillAfterDying(dying, survived);
            return;
        }

        if (dying.ResumesDamageSkill)
        {
            var pending = _pendingDamageSkill ??
                throw new InvalidOperationException("Ganglie dying completed without its damage-skill continuation.");
            if (pending.SourceSeat != dying.VictimSeat)
            {
                throw new InvalidOperationException("Ganglie dying completed for the wrong player.");
            }

            if (pending.GanglieDamageFrameId is null)
            {
                CompleteGangliePunishment(pending);
            }
            else
            {
                CompleteGanglieDamage(pending);
            }
            return;
        }

        CompleteDamageAfterDying(dying);
    }

    private void CompleteActiveSkillAfterDying(DyingResolution dying, bool survived)
    {
        var actor = _players[dying.VictimSeat];
        if (_resolutionStack.LastOrDefault() is not ActiveSkillFrame activeSkill ||
            activeSkill.Id != dying.ParentFrameId ||
            activeSkill.SourceSeat != actor.Seat)
        {
            throw new InvalidOperationException(
                "An active-skill dying continuation must return to its active-skill frame.");
        }

        if (activeSkill.Effect == ActiveSkillEffectKind.PayHpOrDiscardWeaponAndDamage)
        {
            var action = RequireActiveAction(activeSkill.Id);
            if (survived)
            {
                if (!((IActiveActionEffectHost)this).BeginSkillDamage(action,
                        action.TargetSeats.Single(), card: null))
                    ActiveActionExecutor.CompleteDamage(action, dealtDamage: false, this);
                return;
            }

            ActiveActionExecutor.CompleteDamage(action, dealtDamage: false, this);
            if (_winner != Winner.None && _status != EngineStatus.Completed)
            {
                CompleteGame();
            }
            return;
        }

        if (activeSkill.Effect != ActiveSkillEffectKind.LoseHpAndDraw)
        {
            throw new InvalidOperationException(
                "The active-skill dying continuation has an unsupported effect.");
        }

        IReadOnlyList<int> drawn = [];
        if (survived)
        {
            drawn = DrawCards(
                actor,
                activeSkill.DrawCount,
                log: true,
                reason: CardMoveReasons.KujinDraw);
            QueueGameEvent(new SkillCardsDrawnEvent(
                activeSkill.Id,
                actor.Seat,
                activeSkill.Skill,
                drawn));
        }

        SetActiveSkillFrameStep(activeSkill.Id, ResolutionFrameStep.Completed);
        QueueGameEvent(new ActiveSkillResolvedEvent(
            activeSkill.Id,
            actor.Seat,
            activeSkill.Skill,
            activeSkill.Effect));
        PopResolutionFrame(activeSkill.Id, ResolutionFrameKind.ActiveSkill);
        AddLog(
            "ActiveSkill",
            survived
                ? $"{actor.Name} 发动【苦肉】，失去 {activeSkill.HpCost} 点体力并摸了 {drawn.Count} 张牌。"
                : $"{actor.Name} 发动【苦肉】后未能脱离濒死。",
            actor.Seat);

        if (!survived && _winner != Winner.None && _status != EngineStatus.Completed)
        {
            CompleteGame();
        }
    }

    private void CompleteDamageAfterDying(DyingResolution dying)
    {
        var victim = _players[dying.VictimSeat];
        var attack = dying.Attack ??
            throw new InvalidOperationException("A damage dying continuation has no attack.");
        var damageFrameId = dying.DamageFrameId ??
            throw new InvalidOperationException("A damage dying continuation has no damage frame.");
        attack.MarkDyingResolvedForDamage(damageFrameId);
        if (_winner == Winner.None &&
            TryBeginDamageTriggerWindow(attack, damageFrameId,
                SkillProgramTriggerWindow.AfterDamageApplied))
        {
            return;
        }
        QueueGameEvent(new AfterDamageEvent(
            damageFrameId,
            attack.SourceSeat,
            dying.VictimSeat,
            attack.DamageAmount,
            Math.Max(0, victim.Hp),
            GetDamageNature(attack)));
        PopResolutionFrame(damageFrameId, ResolutionFrameKind.Damage);
        CompleteDamageAttack(attack);
    }

    private void CompleteDamageAttack(AttackResolution attack)
    {
        if (_pendingNestedGanglieDamage is not { } nested ||
            !ReferenceEquals(nested.Attack, attack))
        {
            CompleteAttack(attack);
            return;
        }

        _pendingNestedGanglieDamage = nested.Parent;
        _pendingDamageTrigger = nested.OuterTrigger;
        _pendingDamageSkill = nested.OuterSkill;
        CompleteGangliePunishment(nested.OuterSkill);
    }

    private bool FinishAttack(AttackResolution attack, bool allowYingboGift = true)
    {
        if (attack.IsProgramSkillDamage)
        {
            if (attack.Card is not null || attack.ProgramSkillFrameId != attack.ResolutionId)
                throw new InvalidOperationException(
                    "Configured active-program damage must retain its program frame and no physical card.");
            return false;
        }

        if (attack.IsProgramJudgmentDamage)
        {
            if (attack.Card is not null || attack.ProgramJudgmentFrameId is null)
            {
                throw new InvalidOperationException(
                    "Configured judgment damage must retain its program frame and no physical card.");
            }
            return false;
        }

        if (attack.IsLeijiDamage)
        {
            if (attack.Card is not null)
            {
                throw new InvalidOperationException("Leiji damage cannot carry a physical card.");
            }
            if (_winner != Winner.None && _status != EngineStatus.Completed)
            {
                CompleteGame();
            }
            return false;
        }

        if (attack.Card is null && attack.EffectiveCardKind == CardKind.Slash && _pendingShensuStage is 1 or 2)
        {
            SetCardUseStep(attack.ResolutionId, ResolutionFrameStep.Completed);
            PopResolutionFrame(attack.ResolutionId, ResolutionFrameKind.CardUse);
            if (_winner != Winner.None)
            {
                if (_status != EngineStatus.Completed) CompleteGame();
            }
            ClearYingboCardUse(attack.ResolutionId);
            return false;
        }

        if (attack.IsActiveSkillDamage)
        {
            if (attack.SourceSkill == SkillKind.Lijian)
            {
                if (attack.Card is not null || attack.EffectiveCardKind != CardKind.Duel)
                {
                    throw new InvalidOperationException("Lijian Duel cannot carry a physical Duel card.");
                }

                SetActiveSkillFrameStep(attack.ResolutionId, ResolutionFrameStep.Completed);
                var frame = _resolutionStack.OfType<ActiveSkillFrame>()
                    .Single(candidate => candidate.Id == attack.ResolutionId);
                QueueGameEvent(new ActiveSkillResolvedEvent(
                    frame.Id,
                    frame.SourceSeat,
                    frame.Skill,
                    frame.Effect));
                PopResolutionFrame(frame.Id, ResolutionFrameKind.ActiveSkill);
                if (_winner != Winner.None && _status != EngineStatus.Completed)
                {
                    CompleteGame();
                }
                return false;
            }

            if (_resolutionStack.OfType<ActiveSkillFrame>().LastOrDefault(frame =>
                    frame.Id == attack.ResolutionId && frame.Skill == attack.SourceSkill) is
                { Effect: ActiveSkillEffectKind.PayHpOrDiscardWeaponAndDamage } damageAction)
            {
                if (attack.Card is not null)
                {
                    throw new InvalidOperationException("A direct active-action damage cannot carry a physical card.");
                }

                ActiveActionExecutor.CompleteDamage(RequireActiveAction(damageAction.Id),
                    dealtDamage: true, this);
                if (_winner != Winner.None && _status != EngineStatus.Completed)
                {
                    CompleteGame();
                }
                return false;
            }

            var activeSkillCard = RequireAttackCard(attack);
            var activeSkillLocation = _cardZones.GetLocation(activeSkillCard.Id);
            if (activeSkillLocation.Zone is not (CardZoneKind.Hand or CardZoneKind.DrawPile or CardZoneKind.DiscardPile))
            {
                throw new InvalidOperationException(
                    $"A resolved active-skill damage card has an unsupported destination: {activeSkillLocation}.");
            }

            if (_resolutionStack.OfType<ActiveSkillFrame>().LastOrDefault(frame =>
                    frame.Id == attack.ResolutionId && frame.Skill == attack.SourceSkill) is not
                { Effect: ActiveSkillEffectKind.RevealGiftAndDamage } giftAction)
            {
                throw new InvalidOperationException(
                    $"Unsupported active-skill damage source: {attack.SourceSkill}.");
            }

            ActiveActionExecutor.CompleteDamage(RequireActiveAction(giftAction.Id),
                dealtDamage: true, this);
            if (_winner != Winner.None && _status != EngineStatus.Completed)
            {
                CompleteGame();
            }

            return false;
        }

        var attackCard = RequireAttackCard(attack);
        var cardLocation = _cardZones.GetLocation(attackCard.Id);

        if (attack.IsDelayedJudgmentDamage)
        {
            if (cardLocation == CardLocation.Judgment(attack.DelayedJudgmentSeat ?? attack.SourceSeat))
            {
                MoveCard(
                    attackCard,
                    cardLocation,
                    CardLocation.DiscardPile,
                    CardMoveReasons.DelayedCardFinish);
            }
            else if (cardLocation != CardLocation.DiscardPile)
            {
                throw new InvalidOperationException(
                    $"A resolved Lightning left its judgment zone through an unsupported destination: {cardLocation}.");
            }

            if (_winner != Winner.None && _status != EngineStatus.Completed)
            {
                CompleteGame();
            }

            return false;
        }

        if (allowYingboGift &&
            TryBeginYingboGift(
                attack.ResolutionId,
                attack.CardUserSeat,
                attackCard,
                RequireAttackCardKind(attack),
                attack.PhysicalCards,
                YingboGiftContinuation.Attack,
                attack: attack))
        {
            return true;
        }

        foreach (var physicalCard in attack.PhysicalCards)
        {
            var physicalLocation = _cardZones.GetLocation(physicalCard.Id);
            if (physicalLocation == CardLocation.Processing)
            {
                MoveCard(
                    physicalCard,
                    CardLocation.Processing,
                    CardLocation.DiscardPile,
                    CardMoveReasons.UseFinished);
            }
            else if (physicalLocation.Zone is not (CardZoneKind.Hand or CardZoneKind.DrawPile or CardZoneKind.DiscardPile))
            {
                throw new InvalidOperationException(
                    $"A resolved {attack.EffectiveCardKind} physical card left Processing through an unsupported destination: {physicalLocation}.");
            }
        }

        var completedAction = _resolutionStack.OfType<CardUseFrame>()
            .Single(frame => frame.Id == attack.ResolutionId).Action;
        QueueCardUseFinishedWithoutPop(attack.ResolutionId, attackCard, RequireAttackCardKind(attack));
        if (_winner == Winner.None && completedAction is not null &&
            TryBeginProgramCardWindow(attack, completedAction,
                SkillProgramTriggerWindow.CardUseCompleted, completedAction.TargetSeats,
                ProgramCardContinuation.CompletedSlash,
                cardUseCausedDamage: attack.CardUseCausedDamage))
            return true;
        PopFinishedCardUse(attack.ResolutionId);
        CompleteFinishedAttackCardUse(attack);
        return false;
    }

    private void CompleteFinishedAttackCardUse(AttackResolution attack)
    {
        if (_pendingJijiang is { IsActiveUse: true, AwaitingProviders: false } jijiang &&
            ReferenceEquals(jijiang.ActiveAttack, attack))
        {
            CompleteActiveFactionRequest(jijiang);
        }
        else if (_pendingJijiang is { IsQinglongCrescentBladeUse: true, AwaitingProviders: false } qinglongJijiang &&
                 ReferenceEquals(qinglongJijiang.ActiveAttack, attack))
        {
            CompleteQinglongCrescentBladeJijiang(qinglongJijiang);
        }

        if (_winner != Winner.None &&
            _status != EngineStatus.Completed &&
            (_pendingBorrowedSword?.ActiveAttack is not { } borrowedAttack ||
             !ReferenceEquals(borrowedAttack, attack)))
        {
            CompleteGame();
        }
    }

    private void CompleteAttack(AttackResolution attack)
    {
        if (_pendingDying is not null)
        {
            throw new InvalidOperationException("A card cannot finish while its dying resolution is pending.");
        }


        if (attack.TryConsumeTianxiangDraw(out var tianxiangOwnerSeat, out var tianxiangTargetSeat))
        {
            var target = _players[tianxiangTargetSeat];
            var drawCount = target.IsAlive ? Math.Max(0, target.MaxHp - target.Hp) : 0;
            if (drawCount > 0)
                DrawCards(target, drawCount, log: true, reason: CardMoveReasons.TianxiangDraw);
            QueueGameEvent(new TianxiangCardsDrawnEvent(
                attack.ResolutionId, tianxiangOwnerSeat, tianxiangTargetSeat, drawCount));
        }

        if (!attack.IsLeijiDamage && !attack.IsProgramJudgmentDamage &&
            _pendingGroupCard is { Effect: GroupCardEffect.ResponseAttack } group)
        {
            if (!ReferenceEquals(group.CurrentAttack, attack))
            {
                throw new InvalidOperationException(
                    "The completed attack does not belong to the current group target.");
            }

            group.CurrentAttack = null;
            _pendingAttack = null;
            _pendingDuel = null;
            _pendingDecision = null;
            group.TargetIndex++;
            SetCardUseTargetIndex(group.ResolutionId, group.TargetIndex);
            BeginGroupAttackResponse(group);
            return;
        }

        if (_winner == Winner.None &&
            attack.TryAdvanceChainedTarget(
                seat => _players[seat].IsAlive,
                UsesFormalTengjia || UsesFormalSilverLion,
                out var fromSeat))
        {
            QueueGameEvent(new ChainedDamagePropagatedEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                fromSeat,
                attack.TargetSeat,
                attack.DamageAmount,
                GetDamageNature(attack)));
            AddLog(
                "ChainDamage",
                $"连环伤害从 {_players[fromSeat].Name} 传导至 {_players[attack.TargetSeat].Name}。",
                attack.SourceSeat,
                attack.TargetSeat);
            if (!ApplyAttackDamage(attack))
            {
                CompleteAttack(attack);
            }

            return;
        }

        if (_pendingFangtianHalberd is { } fangtian &&
            ReferenceEquals(fangtian.CurrentAttack, attack))
        {
            fangtian.DamageWasApplied |= attack.DamageWasApplied;
            fangtian.CurrentAttack = null;
            fangtian.TargetIndex++;
            while (fangtian.TargetIndex < fangtian.TargetSeats.Count &&
                   !_players[GetFangtianEffectiveTarget(fangtian, fangtian.TargetIndex)].IsAlive)
            {
                fangtian.TargetIndex++;
            }

            if (_winner == Winner.None && fangtian.TargetIndex < fangtian.TargetSeats.Count)
            {
                _pendingAttack = null;
                _pendingDuel = null;
                _pendingDecision = null;
                BeginNextFangtianHalberdTarget(fangtian);
                return;
            }

            SetCardUseTargetIndex(fangtian.ResolutionId, fangtian.TargetSeats.Count);
            attack.SetCardUseCausedDamage(fangtian.DamageWasApplied);
            _pendingFangtianHalberd = null;
        }

        if (!attack.CardUseCausedDamage)
            attack.SetCardUseCausedDamage(attack.DamageWasApplied);

        if (FinishAttack(attack))
        {
            return;
        }
        CompleteAttackAfterCardResolution(attack);
    }

    private void CompleteAttackAfterCardResolution(AttackResolution attack)
    {
        var borrowedSword = _pendingBorrowedSword is { ActiveAttack: { } borrowedAttack } pendingBorrowedSword &&
                            ReferenceEquals(borrowedAttack, attack)
            ? pendingBorrowedSword
            : null;
        var resumesDelayedTurn = attack.IsDelayedJudgmentDamage;
        var resumesLeiji = attack.IsLeijiDamage;
        var resumesProgramJudgment = attack.IsProgramJudgmentDamage;
        var resumesProgramSkill = attack.IsProgramSkillDamage;
        var shensuStage = attack.Card is null && attack.EffectiveCardKind == CardKind.Slash &&
                          !resumesProgramSkill && !resumesProgramJudgment && !resumesLeiji
            ? _pendingShensuStage : 0;
        _pendingAttack = null;
        _pendingDuel = null;
        _pendingDecision = null;
        if (shensuStage is 1 or 2)
        {
            // Resume only after releasing the old attack. The continuation can open
            // a second Shensu prompt, which must survive this attack's cleanup.
            _pendingShensuStage = 0;
            if (_winner == Winner.None && _status != EngineStatus.Completed)
            {
                if (shensuStage == 1)
                    CompleteTurnStartAfterDraw(_players[attack.SourceSeat], DelayedTurnEffects.None);
                else
                    BeginDiscardPhase();
            }
            return;
        }
        if (borrowedSword is not null)
        {
            CompleteBorrowedSwordAfterSlash(borrowedSword);
            return;
        }
        if (resumesProgramSkill)
        {
            if (attack.ProgramSkillFrameId is not { } frameId ||
                _resolutionStack.LastOrDefault() is not ProgramSkillFrame frame || frame.Id != frameId)
                throw new InvalidOperationException("Configured active-program damage lost its parent frame.");
            if (resumesProgramJudgment)
                _pendingAttack = _pendingJudgment?.Attack;
            ContinueProgramSkill(frameId);
        }
        else if (resumesProgramJudgment && _status != EngineStatus.Completed)
        {
            ResumeAfterProgramJudgmentDamage(attack);
        }
        else if (resumesDelayedTurn && _winner == Winner.None && _status != EngineStatus.Completed)
        {
            ResumeAfterLightningDamage(attack);
        }
        else if (resumesLeiji)
        {
            ResumeAfterLeijiDamage(attack);
        }
    }

    private void ResumeAfterLeijiDamage(AttackResolution attack)
    {
        var pending = _pendingLeiji ??
            throw new InvalidOperationException("Leiji damage has no Dodge continuation.");
        if (!ReferenceEquals(pending.DamageAttack, attack))
        {
            throw new InvalidOperationException("The completed damage does not belong to the current Leiji trigger.");
        }

        var originalAttack = pending.OriginalAttack;
        _pendingLeiji = null;
        _pendingAttack = originalAttack;
        if (_winner != Winner.None || _status == EngineStatus.Completed)
        {
            // The result is settled: finish the interrupted physical use without opening
            // another Dodge follow-up, card-use trigger or optional card gift.
            if (FinishAttack(originalAttack, allowYingboGift: false))
                throw new InvalidOperationException("A completed game cannot suspend the interrupted card use.");
            CompleteAttackAfterCardResolution(originalAttack);
            return;
        }
        FinishSuccessfulDodgeResponse(originalAttack);
    }

    private void ResumeAfterProgramJudgmentDamage(AttackResolution attack)
    {
        if (attack.ProgramJudgmentFrameId is not { } frameId ||
            _resolutionStack.LastOrDefault() is not ProgramJudgmentTriggerWindowFrame frame ||
            frame.Id != frameId ||
            _pendingJudgment is null)
        {
            throw new InvalidOperationException(
                "Configured judgment damage did not return to its trigger window.");
        }
        _pendingAttack = _pendingJudgment.Attack;
        ContinueProgramJudgmentWindow();
    }

    private void FinishGroupAttack(GroupCardResolution group, bool allowYingboGift = true)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) || group.Effect != GroupCardEffect.ResponseAttack)
        {
            throw new InvalidOperationException("The group attack is not the current card resolution.");
        }

        if (_pendingDying is not null || _pendingAttack is not null)
        {
            throw new InvalidOperationException(
                "A group card cannot finish while a target continuation is pending.");
        }

        if (allowYingboGift &&
            TryBeginYingboGift(
                group.ResolutionId,
                group.SourceSeat,
                group.Card,
                group.Card.Kind,
                group.PhysicalCards,
                YingboGiftContinuation.GroupAttack,
                group: group))
        {
            return;
        }

        foreach (var physicalCard in group.PhysicalCards)
        {
            var cardLocation = _cardZones.GetLocation(physicalCard.Id);
            if (cardLocation == CardLocation.Processing)
            {
                MoveCard(
                    physicalCard,
                    CardLocation.Processing,
                    CardLocation.DiscardPile,
                    CardMoveReasons.UseFinished);
            }
            else if (!IsResolvedGroupPhysicalCardDestinationAllowed(
                         cardLocation,
                         group.DamageClaimedPhysicalCardIds.Contains(physicalCard.Id),
                         group.TargetSeats))
            {
                throw new InvalidOperationException(
                    $"A resolved {group.Card.Kind} left Processing through an unsupported destination: {cardLocation}.");
            }
        }

        if (UsesFormalZhuRong && group.Card.Kind == CardKind.BarbarianAssault &&
            _players.FirstOrDefault(player => player.IsAlive && HasRuntimeSkill(player, SkillKind.Juxiang)) is { } zhuRong &&
            group.SourceSeat != zhuRong.Seat)
        {
            var claimable = group.PhysicalCards.Where(card =>
                _cardZones.GetLocation(card.Id) == CardLocation.DiscardPile).ToArray();
            foreach (var card in claimable)
                MoveCard(card, CardLocation.DiscardPile, CardLocation.Hand(zhuRong.Seat), CardMoveReasons.JuxiangGain);
            if (claimable.Length > 0)
            {
                QueueGameEvent(new JuxiangCardClaimedEvent(group.ResolutionId, zhuRong.Seat,
                    claimable.Select(card => card.Id).ToArray()));
                AddLog("SkillTriggered", $"{zhuRong.Name} 的【巨象】获得了结算完毕的【南蛮入侵】。", zhuRong.Seat);
            }
        }

        SetCardUseTargetIndex(group.ResolutionId, group.TargetSeats.Count);
        FinishCardUse(group.ResolutionId, group.Card);
        _pendingGroupCard = null;
        _pendingAttack = null;
        _pendingDuel = null;
        _pendingDecision = null;

        if (_winner != Winner.None && _status != EngineStatus.Completed)
        {
            CompleteGame();
        }
    }

    private void FinishGroupRecovery(GroupCardResolution group)
    {
        if (!ReferenceEquals(_pendingGroupCard, group) || group.Effect != GroupCardEffect.Recovery)
        {
            throw new InvalidOperationException("The group recovery is not the current card resolution.");
        }

        if (_pendingDying is not null || _pendingAttack is not null)
        {
            throw new InvalidOperationException(
                "A group recovery cannot finish while another continuation is pending.");
        }

        var cardLocation = _cardZones.GetLocation(group.Card.Id);
        if (cardLocation == CardLocation.Processing)
        {
            MoveCard(
                group.Card,
                CardLocation.Processing,
                CardLocation.DiscardPile,
                CardMoveReasons.UseFinished);
        }
        else if (cardLocation != CardLocation.DiscardPile)
        {
            throw new InvalidOperationException(
                $"A resolved {group.Card.Kind} left Processing through an unsupported destination: {cardLocation}.");
        }

        SetCardUseTargetIndex(group.ResolutionId, group.TargetSeats.Count);
        FinishCardUse(group.ResolutionId, group.Card);
        _pendingGroupCard = null;
        _pendingAttack = null;
        _pendingDuel = null;
        _pendingDecision = null;

        if (_winner != Winner.None && _status != EngineStatus.Completed)
        {
            CompleteGame();
        }
    }

    private void ResolvePeach(CharacterState player, Card peach)
    {
        ResolvePeach(player, player, peach, allowDying: false);
    }

    private void ResolvePeach(
        CharacterState source,
        CharacterState target,
        Card peach,
        bool allowDying)
    {
        if ((!allowDying && source.Hp >= source.MaxHp) ||
            (allowDying && target.Hp > 0) ||
            !target.IsAlive)
        {
            throw new InvalidOperationException("This Peach target cannot currently be recovered.");
        }


        var usesJiuyuan = allowDying &&
                          UsesFormalJiuyuan &&
                          target.Role == Role.Lord &&
                          HasRuntimeSkill(target, SkillKind.Jiuyuan) &&
                          source.Seat != target.Seat &&
                          string.Equals(GetEffectiveFactionId(source), "wu", StringComparison.Ordinal);
        ResolveRecoveryCard(
            source,
            target,
            peach,
            "桃",
            playedCardKind: CardKind.Peach,
            recoveryAmount: usesJiuyuan ? 2 : 1,
            jiuyuanOwnerSeat: usesJiuyuan ? target.Seat : null);
    }

    private void ResolveDyingAlcohol(
        CharacterState source,
        CharacterState target,
        Card alcohol)
    {
        if ((source.Seat != target.Seat) ||
            target.Hp > 0 ||
            !target.IsAlive)
        {
            throw new InvalidOperationException("Alcohol can only rescue a living dying player.");
        }

        ResolveRecoveryCard(source, target, alcohol, "酒");
    }

    private void ResolveRecoveryCard(
        CharacterState source,
        CharacterState target,
        Card card,
        string cardName,
        CardKind? playedCardKind = null,
        int recoveryAmount = 1,
        int? jiuyuanOwnerSeat = null)
    {
        var resolutionId = BeginCardUse(
            card,
            source.Seat,
            [target.Seat],
            playedCardKind: playedCardKind);
        MoveCard(
            card,
            FindOwnedCardLocation(source, card),
            CardLocation.Processing,
            CardMoveReasons.Use);
        SetCardUseStep(resolutionId, ResolutionFrameStep.ResolvingEffect);
        var recoveryFrameId = BeginRecovery(resolutionId, source.Seat, target.Seat, recoveryAmount);
        try
        {
            target.Hp = Math.Min(target.MaxHp, target.Hp + recoveryAmount);
            if (jiuyuanOwnerSeat is { } ownerSeat)
            {
                QueueGameEvent(new JiuyuanAppliedEvent(
                    resolutionId,
                    ownerSeat,
                    source.Seat,
                    card.Id,
                    recoveryAmount));
            }
            AddLog(
                "Recovered",
                $"{source.Name} 使用【{cardName}】使 {target.Name} 回复 {recoveryAmount} 点体力，至 {target.Hp}/{target.MaxHp}。",
                source.Seat,
                target.Seat);
            QueueGameEvent(new RecoveryAppliedEvent(
                source.Seat,
                target.Seat,
                recoveryAmount,
                target.Hp));
        }
        finally
        {
            PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
        }

        MoveCard(
            card,
            CardLocation.Processing,
            CardLocation.DiscardPile,
            CardMoveReasons.UseFinished);
        FinishCardUse(resolutionId, card, playedCardKind);
    }
    private long BeginCardUse(
        Card card,
        int sourceSeat,
        IReadOnlyList<int> targetSeats,
        CardKind? playedCardKind = null,
        bool ignoresArmor = false,
        IReadOnlyList<int>? physicalCardIds = null,
        CardConversionSource? conversionSource = null,
        IReadOnlyList<CardConversionSource>? additionalConversionSources = null,
        SkillKind? cardKindModifierSkill = null,
        IReadOnlyList<int>? designatedTargetSeats = null)
    {
        var resolutionId = ++_resolutionSequence;
        var targets = Array.AsReadOnly(targetSeats.ToArray());
        var designated = (Array.AsReadOnly((designatedTargetSeats ?? targets)
                .Where(seat => IsValidPlayerSeat(seat) && _players[seat].IsAlive)
                .Distinct().ToArray())
);
        var effectiveCardKind = playedCardKind ?? card.Kind;
        var physicalIds = Array.AsReadOnly((physicalCardIds ?? [card.Id]).ToArray());
        var actionContext = CaptureCardUseAction(
            card,
            sourceSeat,
            targets,
            effectiveCardKind,
            physicalIds,
            conversionSource,
            additionalConversionSources,
            cardKindModifierSkill,
            designated);
        _resolutionStack.Add(new CardUseFrame(
            resolutionId,
            sourceSeat,
            card.Id,
            effectiveCardKind,
            targets,
            IgnoresArmor: ignoresArmor,
            PhysicalCardIds: physicalIds)
        { Action = actionContext });
        QueueGameEvent(new CardUseDeclaredEvent(
            resolutionId,
            card.Id,
            effectiveCardKind,
            sourceSeat,
            IgnoresArmor: ignoresArmor));
        QueueGameEvent(new TargetsConfirmedEvent(resolutionId, targets));
        RecordYingboCardUse(resolutionId, sourceSeat, effectiveCardKind);
        return resolutionId;
    }

    private void PushResponseWindow(
        long parentFrameId,
        int sourceSeat,
        int responderSeat,
        CardKind incomingCard,
        CardKind requiredCardKind)
    {
        SetResponseParentStep(parentFrameId, ResolutionFrameStep.AwaitingResponse);
        _resolutionStack.Add(new ResponseWindowFrame(
            ++_resolutionSequence,
            parentFrameId,
            sourceSeat,
            responderSeat,
            incomingCard,
            RequiredCardKind: requiredCardKind));
    }

    private void SetResponseParentStep(long frameId, ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not
            (CardUseFrame or ActiveSkillFrame or ProgramSkillFrame or JudgmentFrame or ProgramJudgmentTriggerWindowFrame))
        {
            throw new InvalidOperationException(
                $"Resolution frame {frameId} cannot own a response window.");
        }

        _resolutionStack[index] = _resolutionStack[index] with { Step = step };
    }

    private long BeginDamage(
        long parentFrameId,
        int sourceSeat,
        int targetSeat,
        int amount,
        DamageNature nature = DamageNature.Normal)
    {
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new DamageFrame(
            frameId,
            parentFrameId,
            sourceSeat,
            targetSeat,
            amount,
            Nature: nature));
        return frameId;
    }

    private long BeginRecovery(
        long parentFrameId,
        int sourceSeat,
        int targetSeat,
        int amount)
    {
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new RecoveryFrame(
            frameId,
            parentFrameId,
            sourceSeat,
            targetSeat,
            amount));
        return frameId;
    }

    private long BeginDeath(long parentFrameId, int victimSeat, int? killerSeat)
    {
        var frameId = ++_resolutionSequence;
        _resolutionStack.Add(new DeathFrame(frameId, parentFrameId, victimSeat, killerSeat));
        return frameId;
    }

    private void SetDyingFrameStep(long frameId, ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not DyingFrame dying)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a Dying frame.");
        }

        var pendingDying = _pendingDying;
        var responderIndex = pendingDying is { FrameId: var pendingFrameId } && pendingFrameId == frameId
            ? pendingDying.ResponderIndex
            : dying.ResponderIndex;
        _resolutionStack[index] = dying with
        {
            ResponderIndex = responderIndex,
            Step = step
        };
    }

    private void SetDamageSkillFrameStep(long frameId, ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not DamageSkillFrame damageSkill)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a DamageSkill frame.");
        }

        _resolutionStack[index] = damageSkill with { Step = step };
    }

    private void SetDamageTriggerWindowStep(long frameId, ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not DamageTriggerWindowFrame triggerWindow)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a damage trigger window.");
        }

        _resolutionStack[index] = triggerWindow with { Step = step };
    }

    private void SetDamageTriggerWindowCursor(long frameId, int candidateIndex)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not DamageTriggerWindowFrame triggerWindow)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a damage trigger window.");
        }

        if (candidateIndex < 0 || candidateIndex > triggerWindow.Candidates.Count)
        {
            throw new ArgumentOutOfRangeException(nameof(candidateIndex));
        }

        _resolutionStack[index] = triggerWindow with { CandidateIndex = candidateIndex };
    }

    private void PopResponseWindow(long parentFrameId)
    {
        if (_resolutionStack.Count == 0 ||
            _resolutionStack[^1] is not ResponseWindowFrame response ||
            response.ParentFrameId != parentFrameId)
        {
            throw new InvalidOperationException(
                $"Resolution stack does not have a response window for frame {parentFrameId}.");
        }

        PopResolutionFrame(response.Id, ResolutionFrameKind.ResponseWindow);
    }

    private void SetCardUseStep(long frameId, ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index >= 0 && _resolutionStack[index] is ActiveSkillFrame
            {
                Skill: SkillKind.Lijian,
                Effect: ActiveSkillEffectKind.DiscardAndStartDuel
            } activeSkill)
        {
            _resolutionStack[index] = activeSkill with { Step = step };
            return;
        }

        if (index < 0 || _resolutionStack[index] is not CardUseFrame cardUse)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a CardUse frame.");
        }

        _resolutionStack[index] = cardUse with { Step = step };
    }

    private void RedirectCardUseTarget(long frameId, int originalTargetSeat, int redirectedTargetSeat)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not CardUseFrame cardUse)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a CardUse frame.");
        }

        var targetSeats = cardUse.TargetSeats.ToArray();
        var targetIndex = Array.IndexOf(targetSeats, originalTargetSeat);
        if (targetIndex < 0)
        {
            throw new InvalidOperationException("The redirected Slash target is absent from its CardUse frame.");
        }

        targetSeats[targetIndex] = redirectedTargetSeat;
        _resolutionStack[index] = cardUse with { TargetSeats = targetSeats };
    }

    private void SetActiveSkillFrameStep(long frameId, ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not ActiveSkillFrame activeSkill)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not an ActiveSkill frame.");
        }

        _resolutionStack[index] = activeSkill with { Step = step };
    }

    private void UpdateNullificationWindowFrame(
        NullificationResolution pending,
        ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == pending.FrameId);
        if (index < 0 || _resolutionStack[index] is not NullificationWindowFrame frame)
        {
            throw new InvalidOperationException(
                $"Resolution frame {pending.FrameId} is not a Nullification window.");
        }

        _resolutionStack[index] = frame with
        {
            CandidateSeats = Array.AsReadOnly(pending.CandidateSeats.ToArray()),
            CandidateIndex = pending.CandidateIndex,
            ChainDepth = pending.ChainDepth,
            EffectNullified = pending.EffectNullified,
            Step = step
        };
    }

    private void UpdateTargetCardSelectionFrame(
        TargetCardSelectionResolution pending,
        ResolutionFrameStep step)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == pending.FrameId);
        if (index < 0 || _resolutionStack[index] is not TargetCardSelectionFrame frame)
        {
            throw new InvalidOperationException(
                $"Resolution frame {pending.FrameId} is not a hidden target-card selection.");
        }

        _resolutionStack[index] = frame with { Step = step };
    }

    private void SetCardUseTargetIndex(long frameId, int targetIndex)
    {
        var index = _resolutionStack.FindLastIndex(frame => frame.Id == frameId);
        if (index < 0 || _resolutionStack[index] is not CardUseFrame cardUse)
        {
            throw new InvalidOperationException($"Resolution frame {frameId} is not a CardUse frame.");
        }

        if (targetIndex < 0 || targetIndex > cardUse.TargetSeats.Count)
        {
            throw new ArgumentOutOfRangeException(nameof(targetIndex));
        }

        _resolutionStack[index] = cardUse with { TargetIndex = targetIndex };
    }

    private void FinishCardUse(
        long frameId,
        Card card,
        CardKind? playedCardKind = null)
    {
        if (_resolutionStack.OfType<CardUseFrame>().SingleOrDefault(frame => frame.Id == frameId) is { } pendingUse)
        {
            foreach (var physicalCardId in pendingUse.PhysicalCardIds ?? [pendingUse.CardId])
            {
                if (_cardZones.GetLocation(physicalCardId) == CardLocation.Processing)
                {
                    var physicalCard = _cardZones.CardsAt(CardLocation.Processing)
                        .Single(candidate => candidate.Id == physicalCardId);
                    MoveCard(
                        physicalCard,
                        CardLocation.Processing,
                        CardLocation.DiscardPile,
                        CardMoveReasons.UseFinished);
                }
            }
        }
        QueueCardUseFinishedWithoutPop(frameId, card, playedCardKind);
        PopFinishedCardUse(frameId);
    }

    private void QueueCardUseFinishedWithoutPop(long frameId, Card card, CardKind? playedCardKind)
    {
        SetCardUseStep(frameId, ResolutionFrameStep.Completed);
        if (_resolutionStack.Count == 0 ||
            _resolutionStack[^1] is not CardUseFrame cardUse ||
            cardUse.Id != frameId)
        {
            throw new InvalidOperationException(
                $"Resolution frame {frameId} has unfinished child frames.");
        }

        QueueGameEvent(new CardUseFinishedEvent(
            frameId,
            card.Id,
            playedCardKind ?? card.Kind));
    }

    private void PopFinishedCardUse(long frameId)
    {
        PopResolutionFrame(frameId, ResolutionFrameKind.CardUse);
        _acceptedProgramUses.Remove(frameId);
        _committedProgramUses.Remove(frameId);
        _preparedProgramTargets.Remove(frameId);
        ClearYingboCardUse(frameId);
        ContinueProgramAfterSelectedCardUse();
    }

    private void PopResolutionFrame(long frameId, ResolutionFrameKind expectedKind)
    {
        if (_resolutionStack.Count == 0)
        {
            throw new InvalidOperationException(
                $"Resolution frame {frameId} is not the top {expectedKind} frame.");
        }

        var top = _resolutionStack[^1];
        if (top.Id != frameId || top.Kind != expectedKind)
        {
            throw new InvalidOperationException(
                $"Resolution frame {frameId} is not the top {expectedKind} frame.");
        }

        _resolutionStack.RemoveAt(_resolutionStack.Count - 1);
    }

    private bool CanUseSlashTarget(
        CharacterState source,
        CharacterState target,
        Card slashCard,
        CardConversionSource? conversionSource = null,
        CardKind effectiveKind = CardKind.Slash) =>
        !IsCardUseForbidden(source.Seat, effectiveKind, CardActionType.Use) &&
        target.IsAlive &&
        target.Seat != source.Seat &&
        (HasCardDistanceExemption(source, target, effectiveKind) ||
         IgnoresProgramSlashDistance(source, conversionSource) ||
         IgnoresSpGuanYuWushengDistance(source, slashCard) ||
         HasUnlimitedTurnRuleModifier(source.Seat, SkillRuleQuery.SlashDistanceLimit) ||
         GetCombatDistance(source.Seat, target.Seat) <= GetAttackRange(source.Seat)) &&
        !IsDirectedCardTargetProhibited(source.Seat, target.Seat, effectiveKind) &&
        !IsSlashProhibited(source, target, slashCard);

    private bool CanUseVirtualSlashTarget(
        CharacterState source,
        CharacterState target,
        CardKind effectiveKind = CardKind.Slash) =>
        !IsCardUseForbidden(source.Seat, effectiveKind, CardActionType.Use) &&
        target.IsAlive &&
        target.Seat != source.Seat &&
        CanSpendSlashUse(source, target, ignoresCount: false, effectiveKind) &&
        (HasCardDistanceExemption(source, target, effectiveKind) ||
         HasUnlimitedTurnRuleModifier(source.Seat, SkillRuleQuery.SlashDistanceLimit) ||
         GetCombatDistance(source.Seat, target.Seat) <= GetAttackRange(source.Seat)) &&
        !IsSlashProhibited(target);

    private bool CanUseZhangbaSerpentSpear(CharacterState actor) =>
        SlashKinds.Any(kind => !IsCardUseForbidden(actor.Seat, kind, CardActionType.Use)) &&
        UsesFormalZhangbaSerpentSpear &&
        GetEquipment(actor).Any(card => card.Kind == CardKind.ZhangbaSerpentSpear) &&
        GetPlayableCards(actor).Count(card => !IsTurnHandCardRestricted(actor, card)) >= 2;

    private bool HasZhuqueFan(CharacterState actor) =>
        UsesFormalZhuqueFan &&
        GetEquipment(actor).Any(card => card.Kind == CardKind.ZhuqueFan);

    private IReadOnlyList<CardKind> GetSlashUseKinds(
        CharacterState actor,
        CardKind baseEffectiveKind) =>
        GetSlashUseVariants(actor, baseEffectiveKind)
            .Select(variant => variant.EffectiveKind)
            .Distinct()
            .ToArray();

    private bool IsZhuqueFanConversion(
        CharacterState actor,
        CardKind baseEffectiveKind,
        CardKind requestedEffectiveKind) =>
        baseEffectiveKind == CardKind.Slash &&
        requestedEffectiveKind == CardKind.FireSlash &&
        HasZhuqueFan(actor);

    private IReadOnlyList<LegalAction> BuildNationalRevealActions(CharacterState actor)
    {
        var actions = new List<LegalAction>();
        if (!IsNationalWarMode || !actor.IsAlive)
        {
            return actions;
        }

        if (actor.GeneralSelected && !actor.GeneralRevealed)
        {
            actions.Add(new LegalAction(
                LegalActionKind.RevealGeneral,
                null,
                null,
                $"明置【{actor.General.Name}】",
                Skill: actor.General.Skill)
            {
                GeneralSlot = GeneralSelectionSlot.Primary
            });
        }

        if (actor.SecondaryGeneralSelected &&
            !actor.SecondaryGeneralRevealed &&
            actor.SecondaryGeneral is not null)
        {
            actions.Add(new LegalAction(
                LegalActionKind.RevealGeneral,
                null,
                null,
                $"明置【{actor.SecondaryGeneral.Name}】",
                Skill: actor.SecondaryGeneral.Skill)
            {
                GeneralSlot = GeneralSelectionSlot.Secondary
            });
        }

        return actions;
    }

    private IReadOnlyList<LegalAction> BuildLegalActions(CharacterState actor)
    {
        var actions = new List<LegalAction>();
        if (!actor.IsAlive || _phase != TurnPhase.Play || actor.Seat != _currentSeat)
        {
            return actions;
        }

        if (IsNationalWarMode)
        {
            actions.AddRange(BuildNationalRevealActions(actor));
        }

        var allPhysicalPlayableCards = GetPlayableCards(actor);
        var physicalPlayableCards = allPhysicalPlayableCards
            .Where(card => !IsTurnHandCardRestricted(actor, card))
            .ToArray();
        var playableCards = physicalPlayableCards
            .Where(card => !HasProgramCardIdentity(actor, card))
            .ToArray();
        var conversionRules = ConversionRules(actor).ToArray();
        var cardUseRules = CardUseRules(actor).ToArray();
        var skillContext = CreateSkillContext(actor);
        var slashLimit = GetSlashUseLimit(actor);
        if (SlashKinds.Any(kind => !IsCardUseForbidden(actor.Seat, kind, CardActionType.Use)) &&
            (_slashCountThisTurn < slashLimit || HasSlashAllowanceForAnyTarget(actor)))
        {
            foreach (var transformed in physicalPlayableCards
                         .SelectMany(card => GetProgramCardIdentityMatches(actor, card)
                             .Where(match => match.Identity.OutputKind == CardKind.Slash)
                             .Select(match => (Card: card, Match: match))))
            {
                var card = transformed.Card;
                var conversionSource = transformed.Match.Source;
                foreach (var variant in GetSlashUseVariants(
                             actor, card, CardKind.Slash, conversionSource))
                {
                    var effectiveKind = variant.EffectiveKind;
                    IReadOnlyList<CardConversionSource>? additionalConversions =
                        variant.AdditionalConversionSource is { } additional ? [additional] : null;
                    var targets = GetFangtianOrderedSlashTargets(
                        actor, card, conversionSource, effectiveKind: effectiveKind);
                    var physicalName = CardCatalog.Get(card.Kind).DisplayName;
                    var effectiveName = CardCatalog.Get(effectiveKind).DisplayName;
                    foreach (var target in targets)
                    {
                        actions.Add(new LegalAction(
                            LegalActionKind.Slash,
                            card.Id,
                            target.Seat,
                            DescribeConversion(conversionSource,
                                variant.AdditionalConversionSource is { } chained
                                    ? $"将【{physicalName}】视为【杀】，再发动【{DescribeAdditionalConversion(chained)}】改为【火杀】对 {target.Name} 使用"
                                    : variant.UsesZhuqueFan
                                    ? $"将【{physicalName}】视为【杀】，再以【朱雀羽扇】改为【火杀】对 {target.Name} 使用"
                                    : $"将【{physicalName}】视为【{effectiveName}】对 {target.Name} 使用"),
                            PlayedCardKind: effectiveKind)
                        {
                            ConversionSource = conversionSource,
                            AdditionalConversionSources = additionalConversions
                        });
                    }

                    AddFangtianHalberdSlashActions(
                        actions, actor, card, targets, effectiveName, effectiveKind, conversionSource,
                        additionalConversions);
                    AddProgramTargetCountSlashActions(
                        actions, actor, card, targets, effectiveName, effectiveKind, conversionSource,
                        additionalConversions);
                }
            }

            foreach (var slash in playableCards.Where(card => IsSlashCard(card.Kind)))
            {
                foreach (var variant in GetSlashUseVariants(actor, slash.Kind))
                {
                    var effectiveKind = variant.EffectiveKind;
                    var targets = GetFangtianOrderedSlashTargets(actor, slash, effectiveKind: effectiveKind);
                    var slashName = CardCatalog.Get(effectiveKind).DisplayName;
                    CardKind? playedCardKind = effectiveKind == slash.Kind
                        ? null
                        : effectiveKind;
                    foreach (var target in targets)
                    {
                        actions.Add(new LegalAction(
                            LegalActionKind.Slash,
                            slash.Id,
                            target.Seat,
                            variant.UsesZhuqueFan
                                ? $"发动【朱雀羽扇】，将【杀】改为【火杀】对 {target.Name} 使用"
                                : $"对 {target.Name} 使用【{slashName}】",
                            PlayedCardKind: playedCardKind));
                    }

                    AddFangtianHalberdSlashActions(
                        actions,
                        actor,
                        slash,
                        targets,
                        slashName,
                        playedCardKind);
                    AddProgramTargetCountSlashActions(
                        actions, actor, slash, targets, slashName, playedCardKind);
                }
            }

            foreach (var slash in playableCards.Where(card => card.Kind == CardKind.Slash))
            foreach (var conversionSource in GetProgramViewAsConversions(
                         actor, slash, CardKind.FireSlash, forResponse: false))
            {
                var targets = GetFangtianOrderedSlashTargets(
                    actor, slash, conversionSource, effectiveKind: CardKind.FireSlash);
                foreach (var target in targets)
                {
                    actions.Add(new LegalAction(
                        LegalActionKind.Slash,
                        slash.Id,
                        target.Seat,
                        DescribeConversion(conversionSource,
                            $"将【杀】改为【火杀】对 {target.Name} 使用"),
                        PlayedCardKind: CardKind.FireSlash)
                    {
                        ConversionSource = conversionSource
                    });
                }
                AddFangtianHalberdSlashActions(actions, actor, slash, targets,
                    "火杀", CardKind.FireSlash, conversionSource);
                AddProgramTargetCountSlashActions(actions, actor, slash, targets,
                    "火杀", CardKind.FireSlash, conversionSource);
            }

            foreach (var converted in playableCards)
            {
                var programSources = GetProgramViewAsConversions(
                    actor, converted, CardKind.Slash, forResponse: false);
                var legacySources = GetLegacyViewAsConversions(
                    actor, converted, CardKind.Slash, forResponse: false);
                if (legacySources.Count == 0 && programSources.Count == 0) continue;
                var physicalName = CardCatalog.Get(converted.Kind).DisplayName;
                var sources = new List<CardConversionSource?>();
                sources.AddRange(legacySources);
                sources.AddRange(programSources);
                foreach (var conversionSource in sources)
                {
                    foreach (var variant in GetSlashUseVariants(
                                 actor, converted, CardKind.Slash, conversionSource))
                    {
                        IReadOnlyList<CardConversionSource>? additionalConversions =
                            variant.AdditionalConversionSource is { } additional ? [additional] : null;
                        var targets = GetFangtianOrderedSlashTargets(
                            actor, converted, conversionSource, effectiveKind: variant.EffectiveKind);
                        var effectiveName = CardCatalog.Get(variant.EffectiveKind).DisplayName;
                        foreach (var target in targets)
                        {
                            var description = variant.AdditionalConversionSource is { } chained
                                ? $"将【{physicalName}】当作【杀】，再发动【{DescribeAdditionalConversion(chained)}】改为【火杀】对 {target.Name} 使用"
                                : variant.UsesZhuqueFan
                                    ? $"将【{physicalName}】当作【杀】，再以【朱雀羽扇】改为【火杀】对 {target.Name} 使用"
                                    : $"将【{physicalName}】当作【杀】对 {target.Name} 使用";
                            actions.Add(new LegalAction(
                                LegalActionKind.Slash,
                                converted.Id,
                                target.Seat,
                                DescribeConversion(conversionSource, description),
                                PlayedCardKind: variant.EffectiveKind)
                            {
                                ConversionSource = conversionSource,
                                AdditionalConversionSources = additionalConversions
                            });
                        }

                        AddFangtianHalberdSlashActions(
                            actions, actor, converted, targets, effectiveName,
                            variant.EffectiveKind, conversionSource, additionalConversions);
                        AddProgramTargetCountSlashActions(
                            actions, actor, converted, targets, effectiveName,
                            variant.EffectiveKind, conversionSource, additionalConversions);
                    }
                }
            }

            if (UsesFormalWushengEquipment)
            {
                foreach (var converted in GetEquipment(actor).Where(card =>
                             CanUseAsFormalWushengSlash(actor, card)))
                {
                    var physicalName = CardCatalog.Get(converted.Kind).DisplayName;
                    var sources = GetLegacyViewAsConversions(
                            actor, converted, CardKind.Slash, forResponse: false)
                        .Concat(GetProgramViewAsConversions(
                            actor, converted, CardKind.Slash, forResponse: false));
                    foreach (var conversionSource in sources)
                    {
                        foreach (var variant in GetSlashUseVariants(
                                     actor, converted, CardKind.Slash, conversionSource))
                        {
                            IReadOnlyList<CardConversionSource>? additionalConversions =
                                variant.AdditionalConversionSource is { } additional ? [additional] : null;
                            var targets = GetFangtianOrderedSlashTargets(
                                actor, converted, conversionSource, effectiveKind: variant.EffectiveKind);
                            var effectiveName = CardCatalog.Get(variant.EffectiveKind).DisplayName;
                            foreach (var target in targets)
                            {
                                var description = variant.AdditionalConversionSource is { } chained
                                    ? $"将装备区【{physicalName}】当作【杀】，再发动【{DescribeAdditionalConversion(chained)}】改为【火杀】对 {target.Name} 使用"
                                    : variant.UsesZhuqueFan
                                        ? $"将装备区【{physicalName}】当作【杀】，再以【朱雀羽扇】改为【火杀】对 {target.Name} 使用"
                                        : $"将装备区【{physicalName}】当作【杀】对 {target.Name} 使用";
                                actions.Add(new LegalAction(
                                    LegalActionKind.Slash,
                                    converted.Id,
                                    target.Seat,
                                    DescribeConversion(conversionSource, description),
                                    PlayedCardKind: variant.EffectiveKind)
                                {
                                    ConversionSource = conversionSource,
                                    AdditionalConversionSources = additionalConversions
                                });
                            }
                            AddProgramTargetCountSlashActions(
                                actions, actor, converted, targets, effectiveName,
                                variant.EffectiveKind, conversionSource, additionalConversions);
                        }
                    }
                }
            }

            if (CanUseZhangbaSerpentSpear(actor))
            {
                var targets = SlashKinds
                    .SelectMany(kind => _players.Where(target => CanUseVirtualSlashTarget(actor, target, kind)))
                    .Select(target => target.Seat)
                    .Distinct()
                    .Order()
                    .ToArray();
                if (targets.Length > 0)
                {
                    actions.Add(new LegalAction(
                        LegalActionKind.UseEquipmentEffect,
                        null,
                        null,
                        "发动【丈八蛇矛】，将两张手牌当【杀】使用",
                        MinCardCount: 2,
                        MaxCardCount: 2,
                        MinTargetCount: 1,
                        MaxTargetCount: 1,
                        EquipmentKind: CardKind.ZhangbaSerpentSpear)
                    {
                        SelectableCardIds = physicalPlayableCards.Select(card => card.Id).Order().ToArray(),
                        SelectableTargetSeats = targets
                    });
                }
            }
        }
        else if (SlashKinds.Any(kind => !IsCardUseForbidden(actor.Seat, kind, CardActionType.Use)))
        {
            AddNuzhanUnlimitedTrickSlashActions(actions, actor, playableCards);
        }

        if (actor.Hp < actor.MaxHp)
        {
            foreach (var peach in playableCards.Where(card => card.Kind == CardKind.Peach))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.Peach,
                    peach.Id,
                    actor.Seat,
                    "对自己使用【桃】"));
            }
        }

        foreach (var duel in playableCards.Where(card => card.Kind == CardKind.Duel))
        {
            foreach (var target in _players.Where(player =>
                         player.IsAlive &&
                         player.Seat != actor.Seat &&
                         (!UsesFormalKongchengTargeting ||
                          !IsCardTargetProhibited(player, CardKind.Duel))))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.Duel,
                    duel.Id,
                    target.Seat,
                    $"对 {target.Name} 使用【决斗】"));
            }
        }

        foreach (var converted in playableCards.Where(card => card.Kind != CardKind.Duel))
        {
            foreach (var conversionSource in GetProgramViewAsConversions(
                         actor, converted, CardKind.Duel, forResponse: false))
            {
                foreach (var target in _players.Where(player =>
                             player.IsAlive &&
                             player.Seat != actor.Seat &&
                             (!UsesFormalKongchengTargeting ||
                              !IsCardTargetProhibited(player, CardKind.Duel))))
                {
                    actions.Add(new LegalAction(
                        LegalActionKind.Duel,
                        converted.Id,
                        target.Seat,
                        DescribeConversion(conversionSource,
                            $"将【{converted.DisplayName}】当作【决斗】对 {target.Name} 使用"),
                        PlayedCardKind: CardKind.Duel)
                    {
                        ConversionSource = conversionSource
                    });
                }
            }
        }

        if (UsesFormalShuangxiong && HasRuntimeSkill(actor, SkillKind.Shuangxiong) &&
            _shuangxiongJudgmentWasRed is { } judgmentWasRed)
        {
            foreach (var converted in playableCards.Where(card => IsRedSuit(card.Suit) != judgmentWasRed))
            {
                foreach (var target in _players.Where(player => player.IsAlive && player.Seat != actor.Seat &&
                             (!UsesFormalKongchengTargeting || !IsCardTargetProhibited(player, CardKind.Duel))))
                {
                    actions.Add(new LegalAction(LegalActionKind.Duel, converted.Id, target.Seat,
                        $"发动【双雄】，将【{converted.DisplayName}】当作【决斗】对 {target.Name} 使用",
                        PlayedCardKind: CardKind.Duel));
                }
            }
        }

        foreach (var drawTwo in playableCards.Where(card => card.Kind == CardKind.DrawTwo))
        {
            actions.Add(new LegalAction(
                LegalActionKind.DrawTwo,
                drawTwo.Id,
                null,
                "使用【无中生有】摸两张牌"));
        }

        foreach (var assault in playableCards.Where(card => card.Kind == CardKind.BarbarianAssault))
        {
            if (CanUseGlobalCard(actor, CardKind.BarbarianAssault))
                actions.Add(new LegalAction(
                    LegalActionKind.BarbarianAssault,
                    assault.Id,
                    null,
                    "使用【南蛮入侵】"));
        }

        foreach (var arrowBarrage in playableCards.Where(card => card.Kind == CardKind.ArrowBarrage))
        {
            if (CanUseGlobalCard(actor, CardKind.ArrowBarrage))
                actions.Add(new LegalAction(
                    LegalActionKind.ArrowBarrage,
                    arrowBarrage.Id,
                    null,
                    "使用【万箭齐发】"));
        }

        foreach (var peachGarden in playableCards.Where(card => card.Kind == CardKind.PeachGarden))
        {
            if (CanUseGlobalCard(actor, CardKind.PeachGarden))
                actions.Add(new LegalAction(
                    LegalActionKind.PeachGarden,
                    peachGarden.Id,
                    null,
                    "使用【桃园结义】"));
        }

        foreach (var fiveGrains in playableCards.Where(card => card.Kind == CardKind.FiveGrains))
        {
            if (CanUseGlobalCard(actor, CardKind.FiveGrains))
                actions.Add(new LegalAction(
                    LegalActionKind.FiveGrains,
                    fiveGrains.Id,
                    null,
                    "使用【五谷丰登】"));
        }

        foreach (var indulgence in playableCards.Where(card => card.Kind == CardKind.Indulgence))
        {
            foreach (var target in _players.Where(player =>
                         player.IsAlive &&
                         player.Seat != actor.Seat &&
                         !HasJudgmentEffectiveCard(player, CardKind.Indulgence)))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.Indulgence,
                    indulgence.Id,
                    target.Seat,
                    $"对 {target.Name} 使用【乐不思蜀】"));
            }
        }

        if (UsesFormalDaQiao)
        {
            foreach (var converted in GetHand(actor)
                         .Concat(GetEquipment(actor))
                         .Where(card => !IsTurnHandCardRestricted(actor, card))
                         .Where(card => !HasProgramCardIdentity(actor, card))
                         .Where(card => conversionRules.Any(rule => rule.CanUseAsIndulgence(skillContext, card))))
            {
                var physicalName = CardCatalog.Get(converted.Kind).DisplayName;
                foreach (var target in _players.Where(player =>
                             player.IsAlive &&
                             player.Seat != actor.Seat &&
                             !HasJudgmentEffectiveCard(player, CardKind.Indulgence)))
                {
                    actions.Add(new LegalAction(
                        LegalActionKind.Indulgence,
                        converted.Id,
                        target.Seat,
                        $"发动【国色】，将【{physicalName}】当作【乐不思蜀】对 {target.Name} 使用",
                        PlayedCardKind: CardKind.Indulgence));
                }
            }
        }

        foreach (var supplyShortage in playableCards.Where(card => card.Kind == CardKind.SupplyShortage))
        {
            var ignoresDistance = cardUseRules.Any(rule => rule.IgnoresTrickDistance(skillContext, CardKind.SupplyShortage));
            var distanceLimit = UsesFormalDuanliang
                ? GetSupplyShortageDistanceLimit(actor, skillContext)
                : 1;
            foreach (var target in _players.Where(player =>
                         player.IsAlive &&
                         player.Seat != actor.Seat &&
                         ((HasCardDistanceExemption(actor, player, CardKind.SupplyShortage) ||
                               ignoresDistance ||
                               GetCombatDistance(actor.Seat, player.Seat) <= distanceLimit
)) &&
                         !IsDirectedCardTargetProhibited(actor.Seat, player.Seat, CardKind.SupplyShortage) &&
                         !HasJudgmentEffectiveCard(player, CardKind.SupplyShortage)))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.SupplyShortage,
                    supplyShortage.Id,
                    target.Seat,
                    $"对 {target.Name} 使用【兵粮寸断】"));
            }
        }

        if (UsesFormalDuanliang)
        {
            var distanceLimit = GetSupplyShortageDistanceLimit(actor, skillContext);
            var convertedCards = GetHand(actor)
                .Concat(GetEquipment(actor))
                .Where(card => !IsTurnHandCardRestricted(actor, card))
                .Where(card => !HasProgramCardIdentity(actor, card))
                .Where(card => conversionRules.Any(rule => rule.CanUseAsSupplyShortage(skillContext, card)));
            foreach (var converted in convertedCards)
            {
                var physicalName = CardCatalog.Get(converted.Kind).DisplayName;
                foreach (var target in _players.Where(player =>
                             player.IsAlive &&
                             player.Seat != actor.Seat &&
                             (HasCardDistanceExemption(actor, player, CardKind.SupplyShortage) ||
                              GetCombatDistance(actor.Seat, player.Seat) <= distanceLimit) &&
                             !IsDirectedCardTargetProhibited(actor.Seat, player.Seat, CardKind.SupplyShortage) &&
                             !HasJudgmentEffectiveCard(player, CardKind.SupplyShortage)))
                {
                    actions.Add(new LegalAction(
                        LegalActionKind.SupplyShortage,
                        converted.Id,
                        target.Seat,
                        $"将【{physicalName}】当作【兵粮寸断】对 {target.Name} 使用",
                        PlayedCardKind: CardKind.SupplyShortage));
                }
            }
        }

        foreach (var lightning in playableCards.Where(card => card.Kind == CardKind.Lightning))
        {
            if (!HasJudgmentEffectiveCard(actor, CardKind.Lightning))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.Lightning,
                    lightning.Id,
                    actor.Seat,
                    "对自己使用【闪电】"));
            }
        }

        var ironChainTargets = _players
            .Where(player => player.IsAlive)
            .OrderBy(player => player.Seat)
            .ToArray();
        {
            foreach (var ironChain in allPhysicalPlayableCards.Where(card =>
                         !HasProgramCardIdentity(actor, card) &&
                         card.Kind == CardKind.IronChain))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.Recast,
                    ironChain.Id,
                    null,
                    "重铸【铁索连环】，摸一张牌"));
            }
        }

        foreach (var ironChain in playableCards.Where(card => card.Kind == CardKind.IronChain))
        {
            foreach (var target in ironChainTargets)
            {
                actions.Add(new LegalAction(
                    LegalActionKind.IronChain,
                    ironChain.Id,
                    target.Seat,
                    $"对 {target.Name} 使用【铁索连环】"));
            }

            for (var firstIndex = 0; firstIndex < ironChainTargets.Length - 1; firstIndex++)
            {
                for (var secondIndex = firstIndex + 1; secondIndex < ironChainTargets.Length; secondIndex++)
                {
                    var first = ironChainTargets[firstIndex];
                    var second = ironChainTargets[secondIndex];
                    actions.Add(new LegalAction(
                        LegalActionKind.IronChain,
                        ironChain.Id,
                        null,
                        $"对 {first.Name}、{second.Name} 使用【铁索连环】",
                        TargetSeats: [first.Seat, second.Seat]));
                }
            }
        }

        if (UsesFormalPangTong && HasRuntimeSkill(actor, SkillKind.Lianhuan))
        {
            foreach (var converted in GetHand(actor).Where(card =>
                         !HasProgramCardIdentity(actor, card) &&
                         card.Kind != CardKind.IronChain && card.Suit == Suit.Club))
            {
                actions.Add(new LegalAction(LegalActionKind.Recast, converted.Id, null,
                    $"发动【连环】，将【{converted.DisplayName}】当【铁索连环】重铸并摸一张牌",
                    PlayedCardKind: CardKind.IronChain));
                if (IsTurnHandCardRestricted(actor, converted))
                {
                    continue;
                }
                foreach (var target in ironChainTargets)
                {
                    actions.Add(new LegalAction(LegalActionKind.IronChain, converted.Id, target.Seat,
                        $"发动【连环】，将【{converted.DisplayName}】当【铁索连环】对 {target.Name} 使用",
                        PlayedCardKind: CardKind.IronChain));
                }
                for (var firstIndex = 0; firstIndex < ironChainTargets.Length - 1; firstIndex++)
                {
                    for (var secondIndex = firstIndex + 1; secondIndex < ironChainTargets.Length; secondIndex++)
                    {
                        var first = ironChainTargets[firstIndex];
                        var second = ironChainTargets[secondIndex];
                        actions.Add(new LegalAction(LegalActionKind.IronChain, converted.Id, null,
                            $"发动【连环】，将【{converted.DisplayName}】当【铁索连环】对 {first.Name}、{second.Name} 使用",
                            PlayedCardKind: CardKind.IronChain,
                            TargetSeats: [first.Seat, second.Seat]));
                    }
                }
            }
        }

        if (!actor.HasAlcoholEffect &&
            (!actor.UsedPlayPhaseAlcoholThisTurn))
        {
            foreach (var alcohol in playableCards.Where(card => card.Kind == CardKind.Alcohol))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.Alcohol,
                    alcohol.Id,
                    null,
                    "使用【酒】，本回合下一张杀伤害+1"));
            }
        }

        foreach (var equipment in playableCards.Where(card => EquipmentCatalog.IsEquipment(card.Kind)))
        {
            var definition = EquipmentCatalog.Get(equipment.Kind);
            actions.Add(new LegalAction(
                LegalActionKind.Equip,
                equipment.Id,
                null,
                $"装备【{definition.DisplayName}】至{EquipmentCatalog.GetSlotName(definition.Slot)}槽"));
        }

        foreach (var dismantlement in playableCards.Where(card => card.Kind == CardKind.Dismantlement))
        {
            foreach (var target in _players.Where(player =>
                         player.IsAlive &&
                         player.Seat != actor.Seat &&
                         HasTargetCard(player)))
            {
                AddTargetCardActions(
                    actions,
                    LegalActionKind.Dismantlement,
                    dismantlement,
                    target,
                    "过河拆桥");
            }
        }

        if (UsesFormalQixi)
        {
            var qixiCards = GetHand(actor)
                .Concat(GetEquipment(actor))
                .Where(card => !IsTurnHandCardRestricted(actor, card))
                .Where(card => !HasProgramCardIdentity(actor, card))
                .Where(card => conversionRules.Any(rule => rule.CanUseAsDismantlement(skillContext, card)));
            foreach (var converted in qixiCards)
            {
                foreach (var target in _players.Where(player =>
                             player.IsAlive &&
                             player.Seat != actor.Seat &&
                             HasTargetCard(player)))
                {
                    AddTargetCardActions(
                        actions,
                        LegalActionKind.Dismantlement,
                        converted,
                        target,
                        "过河拆桥",
                        CardKind.Dismantlement);
                }
            }
        }

        foreach (var snatch in playableCards.Where(card => card.Kind == CardKind.Snatch))
        {
            var ignoresDistance = cardUseRules.Any(rule => rule.IgnoresTrickDistance(skillContext, CardKind.Snatch));
            foreach (var target in _players.Where(player =>
                         player.IsAlive &&
                         player.Seat != actor.Seat &&
                         (HasCardDistanceExemption(actor, player, CardKind.Snatch) ||
                          ignoresDistance ||
                          GetCombatDistance(actor.Seat, player.Seat) == 1) &&
                         !IsDirectedCardTargetProhibited(actor.Seat, player.Seat, CardKind.Snatch) &&
                         HasTargetCard(player)))
            {
                AddTargetCardActions(
                    actions,
                    LegalActionKind.Snatch,
                    snatch,
                    target,
                    "顺手牵羊");
            }
        }

        if (UsesFormalBorrowedSword)
        {
            foreach (var borrowedSword in playableCards.Where(card => card.Kind == CardKind.BorrowedSword))
            {
                foreach (var weaponOwner in _players.Where(player =>
                             player.IsAlive &&
                             player.Seat != actor.Seat &&
                             !IsDirectedCardTargetProhibited(actor.Seat, player.Seat, CardKind.BorrowedSword) &&
                             GetWeapon(player) is not null))
                {
                    foreach (var slashTarget in _players.Where(player =>
                                 IsLegalBorrowedSwordSlashTarget(weaponOwner, player)))
                    {
                        actions.Add(new LegalAction(
                            LegalActionKind.BorrowedSword,
                            borrowedSword.Id,
                            null,
                            $"令 {weaponOwner.Name} 对 {slashTarget.Name} 使用【杀】，否则获得其武器",
                            TargetSeats: [weaponOwner.Seat, slashTarget.Seat]));
                    }
                }
            }
        }

        foreach (var fireAttack in playableCards.Where(card => card.Kind == CardKind.FireAttack))
        {
            foreach (var target in _players.Where(player =>
                         player.IsAlive &&
                         GetHand(player).Any(card => player.Seat != actor.Seat || card.Id != fireAttack.Id)))
            {
                actions.Add(new LegalAction(
                    LegalActionKind.FireAttack,
                    fireAttack.Id,
                    target.Seat,
                    $"对 {target.Name} 使用【火攻】"));
            }
        }

        if (UsesFormalWolong && HasRuntimeSkill(actor, SkillKind.Huoji))
        {
            foreach (var converted in GetHand(actor).Where(card =>
                         !IsTurnHandCardRestricted(actor, card) &&
                         !HasProgramCardIdentity(actor, card) &&
                         card.Kind != CardKind.FireAttack && IsRedSuit(card.Suit)))
            {
                foreach (var target in _players.Where(player => player.IsAlive &&
                             GetHand(player).Any(card => player.Seat != actor.Seat || card.Id != converted.Id)))
                {
                    actions.Add(new LegalAction(LegalActionKind.FireAttack, converted.Id, target.Seat,
                        $"发动【火计】，将【{converted.DisplayName}】当作【火攻】对 {target.Name} 使用",
                        PlayedCardKind: CardKind.FireAttack));
                }
            }
        }

        foreach (var activeSkill in EnabledSkillRules(actor)
                     .Select(skillRule => ActiveActionCatalog.Find(skillRule.Kind))
                     .Where(candidate => candidate is not null)
                     .Cast<ActiveActionRule>())
        {
            var selection = ActiveActionCatalog.Selection(activeSkill.Kind);
            if (!IsActiveActionAvailable(actor, selection))
            {
                continue;
            }

            var activeSkillTargets = GetActiveSkillValidTargetSeats(actor, activeSkill.Kind);
            var activeSkillContext = CreateActiveSkillContext(actor, activeSkill.Kind);
            if (!activeSkill.CanUse(activeSkillContext)) continue;
            var activeEffect = activeSkill.GetEffect(activeSkillContext);
            if (activeEffect.MinTargetCount <= activeSkillTargets.Count)
            {
                actions.Add(new LegalAction(
                    LegalActionKind.UseSkill,
                    null,
                    null,
                    $"发动【{activeSkill.Name}】",
                    Skill: activeSkill.Kind,
                    MinCardCount: activeEffect.MinCardCount,
                    MaxCardCount: activeEffect.MaxCardCount,
                    MinTargetCount: activeEffect.MinTargetCount,
                    MaxTargetCount: activeEffect.MaxTargetCount)
                {
                    SelectableCardIds = activeEffect.MaxCardCount > 0
                        ? GetActiveSkillValidCardIds(actor, activeSkill.Kind).Order().ToArray()
                        : [],
                    SelectableTargetSeats = activeEffect.MaxTargetCount > 0
                        ? activeSkillTargets.Order().ToArray()
                        : []
                });
            }
        }

        if (UsesFormalWoodenOx &&
            !_woodenOxUsedThisTurn &&
            GetHand(actor).Count > 0 &&
            GetEquipment(actor).Any(card => card.Kind == CardKind.WoodenOx))
        {
            actions.Add(new LegalAction(
                LegalActionKind.UseEquipmentEffect,
                null,
                null,
                "发动【木牛流马】，将一张手牌扣置为“粮”，并可移动此装备",
                MinCardCount: 1,
                MaxCardCount: 1,
                MinTargetCount: 0,
                MaxTargetCount: 1,
                EquipmentKind: CardKind.WoodenOx)
            {
                SelectableCardIds = GetHand(actor).Select(card => card.Id).Order().ToArray(),
                SelectableTargetSeats = _players
                    .Where(player => player.IsAlive &&
                                     player.Seat != actor.Seat &&
                                     GetEquipment(player).All(card =>
                                         EquipmentCatalog.Get(card.Kind).Slot != EquipmentSlot.Treasure))
                    .Select(player => player.Seat)
                    .Order()
                    .ToArray()
            });
        }

        actions.AddRange(BuildProgramActions(actor));
        actions.Add(new LegalAction(LegalActionKind.EndPlay, null, null, "结束出牌"));
        var physicalKinds = allPhysicalPlayableCards.ToDictionary(card => card.Id, card => card.Kind);
        var permittedActions = actions.Where(action =>
        {
            var effectiveKind = action.PlayedCardKind ??
                (action.CardId is { } cardId && physicalKinds.TryGetValue(cardId, out var physicalKind)
                    ? physicalKind
                    : (CardKind?)null);
            if (effectiveKind is null) return true;
            var targets = action.TargetSeats.Count > 0
                ? action.TargetSeats
                : action.TargetSeat is { } targetSeat ? [targetSeat] : [];
            return GetDeclaredCardTargets(actor, action.Kind, targets).All(target =>
                !IsDirectedCardTargetProhibited(actor.Seat, target, effectiveKind.Value));
        });
        return FilterTurnCardUseRestrictions(actor, permittedActions);
    }

    private IReadOnlyList<CharacterState> GetFangtianOrderedSlashTargets(
        CharacterState actor,
        Card slash,
        CardConversionSource? conversionSource = null,
        bool ignoresSlashLimit = false,
        CardKind effectiveKind = CardKind.Slash)
    {
        if (IsCardUseForbidden(actor.Seat, effectiveKind, CardActionType.Use))
        {
            return [];
        }

        return _players
            .Where(player =>
                CanSpendSlashUse(actor, player, ignoresSlashLimit, effectiveKind) &&
                CanUseSlashTarget(actor, player, slash, conversionSource, effectiveKind))
            .ToArray();
    }

    private void AddFangtianHalberdSlashActions(
        ICollection<LegalAction> actions,
        CharacterState actor,
        Card physicalCard,
        IReadOnlyList<CharacterState> legalTargets,
        string slashName,
        CardKind? playedCardKind,
        CardConversionSource? conversionSource = null,
        IReadOnlyList<CardConversionSource>? additionalConversionSources = null,
        SkillKind? cardKindModifierSkill = null)
    {
        if (!UsesFormalFangtianHalberd ||
            GetHand(actor).Count != 1 ||
            GetHand(actor)[0].Id != physicalCard.Id ||
            GetEquipment(actor).All(card => card.Kind != CardKind.FangtianHalberd) ||
            legalTargets.Count < 2)
        {
            return;
        }

        var orderedTargets = legalTargets
            .OrderBy(player => (player.Seat - actor.Seat + _playerCount) % _playerCount)
            .ToArray();
        var maximumTargets = Math.Min(3, orderedTargets.Length);
        for (var targetCount = 2; targetCount <= maximumTargets; targetCount++)
        {
            AddCombinations(0, []);

            void AddCombinations(int startIndex, IReadOnlyList<CharacterState> selected)
            {
                if (selected.Count == targetCount)
                {
                    AddFangtianHalberdSlashAction(
                        actions,
                        physicalCard,
                        slashName,
                        playedCardKind,
                        selected,
                        conversionSource,
                        additionalConversionSources,
                        cardKindModifierSkill);
                    return;
                }

                for (var index = startIndex;
                     index <= orderedTargets.Length - (targetCount - selected.Count);
                     index++)
                {
                    AddCombinations(index + 1, [.. selected, orderedTargets[index]]);
                }
            }
        }
    }

    private void AddFangtianHalberdSlashAction(
        ICollection<LegalAction> actions,
        Card physicalCard,
        string slashName,
        CardKind? playedCardKind,
        IReadOnlyList<CharacterState> targets,
        CardConversionSource? conversionSource,
        IReadOnlyList<CardConversionSource>? additionalConversionSources,
        SkillKind? cardKindModifierSkill)
    {
        var targetSeats = Array.AsReadOnly(targets.Select(target => target.Seat).ToArray());
        actions.Add(new LegalAction(
            LegalActionKind.Slash,
            physicalCard.Id,
            targetSeats[0],
            DescribeConversion(conversionSource, $"发动【方天画戟】，对 {string.Join("、", targets.Select(target => target.Name))} 使用【{slashName}】"),
            PlayedCardKind: playedCardKind,
            TargetSeats: targetSeats)
        {
            ConversionSource = conversionSource,
            AdditionalConversionSources = additionalConversionSources,
            CardKindModifierSkill = cardKindModifierSkill
        });
    }

    private void AddTargetCardActions(
        ICollection<LegalAction> actions,
        LegalActionKind actionKind,
        Card effectCard,
        CharacterState target,
        string effectName,
        CardKind? playedCardKind = null)
    {
        var useDescription = playedCardKind is null
            ? $"对 {target.Name} 使用【{effectName}】"
            : $"将【{effectCard.DisplayName}】当作【{effectName}】对 {target.Name} 使用";
        if (GetHand(target).Count > 0)
        {
            actions.Add(new LegalAction(
                actionKind,
                effectCard.Id,
                target.Seat,
                useDescription,
                PlayedCardKind: playedCardKind));
        }

        foreach (var equipment in GetEquipment(target))
        {
            actions.Add(new LegalAction(
                actionKind,
                effectCard.Id,
                target.Seat,
                $"{useDescription}，选择其装备【{equipment.DisplayName}】",
                PlayedCardKind: playedCardKind,
                TargetCardId: equipment.Id));
        }

        foreach (var judgment in GetJudgment(target))
        {
            actions.Add(new LegalAction(
                actionKind,
                effectCard.Id,
                target.Seat,
                $"{useDescription}，选择其判定区【{judgment.DisplayName}】",
                PlayedCardKind: playedCardKind,
                TargetCardId: judgment.Id));
        }
    }

    private Card? FindOwnedPlayableCard(CharacterState actor, int? cardId)
    {
        if (cardId is not { } requestedCardId)
        {
            return null;
        }

        return GetHand(actor).SingleOrDefault(card => card.Id == requestedCardId) ??
               GetWoodenOxGrain(actor).SingleOrDefault(card => card.Id == requestedCardId) ??
               GetEquipment(actor).SingleOrDefault(card => card.Id == requestedCardId);
    }

    private static bool IsOwnedPlayableLocation(CharacterState actor, CardLocation location) =>
        location.OwnerSeat == actor.Seat &&
        location.Zone is CardZoneKind.Hand or CardZoneKind.WoodenOxGrain;

    private CardLocation FindOwnedCardLocation(CharacterState actor, Card card)
    {
        if (GetHand(actor).Any(candidate => candidate.Id == card.Id))
        {
            return CardLocation.Hand(actor.Seat);
        }

        if (GetEquipment(actor).Any(candidate => candidate.Id == card.Id))
        {
            return CardLocation.Equipment(actor.Seat);
        }

        if (GetWoodenOxGrain(actor).Any(candidate => candidate.Id == card.Id))
        {
            return CardLocation.WoodenOxGrain(actor.Seat);
        }

        throw new InvalidOperationException("The chosen card is no longer in the actor's playable zones.");
    }

    private static bool IsPublicTargetZone(CardZoneKind zone) =>
        zone is CardZoneKind.Equipment or CardZoneKind.Judgment;

    private static CardMoveReason GetTargetCardMoveReason(
        LegalActionKind actionKind,
        CardZoneKind sourceZone) =>
        (actionKind, sourceZone) switch
        {
            (LegalActionKind.Dismantlement, CardZoneKind.Hand) => CardMoveReasons.Dismantlement,
            (LegalActionKind.Dismantlement, CardZoneKind.Equipment) => CardMoveReasons.Dismantlement,
            (LegalActionKind.Dismantlement, CardZoneKind.Judgment) => CardMoveReasons.DismantlementJudgment,
            (LegalActionKind.Snatch, CardZoneKind.Hand) => CardMoveReasons.Snatch,
            (LegalActionKind.Snatch, CardZoneKind.Equipment) => CardMoveReasons.Snatch,
            (LegalActionKind.Snatch, CardZoneKind.Judgment) => CardMoveReasons.SnatchJudgment,
            _ => throw new InvalidOperationException(
                $"{actionKind} cannot move a target card from {sourceZone}.")
        };

    private static CardMoveReason GetTargetCardFinishedMoveReason(
        LegalActionKind actionKind,
        CardZoneKind sourceZone) =>
        (actionKind, sourceZone) switch
        {
            (LegalActionKind.Dismantlement, CardZoneKind.Hand) => CardMoveReasons.DismantlementFinished,
            (LegalActionKind.Dismantlement, CardZoneKind.Equipment) => CardMoveReasons.DismantlementFinished,
            (LegalActionKind.Dismantlement, CardZoneKind.Judgment) => CardMoveReasons.DismantlementJudgmentFinished,
            (LegalActionKind.Snatch, CardZoneKind.Hand) => CardMoveReasons.SnatchFinished,
            (LegalActionKind.Snatch, CardZoneKind.Equipment) => CardMoveReasons.SnatchFinished,
            (LegalActionKind.Snatch, CardZoneKind.Judgment) => CardMoveReasons.SnatchJudgmentFinished,
            _ => throw new InvalidOperationException(
                $"{actionKind} cannot finish a target card from {sourceZone}.")
        };

    private static LegalAction? SelectPlayAction(
        IReadOnlyList<LegalAction> legalActions,
        Card card,
        IReadOnlyList<int> targets,
        CardKind? playedCardKind,
        int? targetCardId,
        CardConversionSource? conversionSource,
        IReadOnlyList<CardConversionSource>? additionalConversionSources,
        SkillKind? cardKindModifierSkill,
        SkillKind? targetCountModifierSkill)
    {
        var matching = legalActions
            .Where(candidate => candidate.Kind != LegalActionKind.Recast)
            .Where(candidate => candidate.TargetSeats.SequenceEqual(targets))
            .Where(candidate => targetCardId is null || candidate.TargetCardId == targetCardId)
            .ToArray();
        if (conversionSource is { } requestedSource)
        {
            return matching.FirstOrDefault(candidate =>
                (candidate.PlayedCardKind ?? card.Kind) == (playedCardKind ?? card.Kind) &&
                candidate.ConversionSource == requestedSource &&
                ConversionSourcesEqual(candidate.AdditionalConversionSources, additionalConversionSources) &&
                candidate.CardKindModifierSkill == cardKindModifierSkill &&
                candidate.TargetCountModifierSkill == targetCountModifierSkill);
        }
        if (cardKindModifierSkill is not null || targetCountModifierSkill is not null)
        {
            return matching.FirstOrDefault(candidate =>
                (candidate.PlayedCardKind ?? card.Kind) == (playedCardKind ?? card.Kind) &&
                ConversionSourcesEqual(candidate.AdditionalConversionSources, additionalConversionSources) &&
                candidate.CardKindModifierSkill == cardKindModifierSkill &&
                candidate.TargetCountModifierSkill == targetCountModifierSkill);
        }
        if (playedCardKind is { } requestedKind)
        {
            var kindMatches = matching.Where(candidate =>
                (candidate.PlayedCardKind ?? card.Kind) == requestedKind).ToArray();
            var nativeOrEquipmentMatches = kindMatches.Where(candidate =>
                candidate.ConversionSource is null &&
                (candidate.AdditionalConversionSources is null || candidate.AdditionalConversionSources.Count == 0) &&
                candidate.CardKindModifierSkill is null &&
                candidate.TargetCountModifierSkill is null).ToArray();
            if (nativeOrEquipmentMatches.Length == 1)
            {
                return nativeOrEquipmentMatches[0];
            }
            if (kindMatches.Any(candidate =>
                    candidate.AdditionalConversionSources is { Count: > 0 } ||
                    candidate.CardKindModifierSkill is not null ||
                    candidate.TargetCountModifierSkill is not null))
            {
                return null;
            }
            return kindMatches.Select(candidate => (
                    candidate.ConversionSource,
                    AdditionalConversions: candidate.AdditionalConversionSources is null
                        ? null
                        : string.Join("\u001f", candidate.AdditionalConversionSources),
                    candidate.CardKindModifierSkill,
                    candidate.TargetCountModifierSkill)).Distinct().Count() > 1
                ? null
                : kindMatches.FirstOrDefault();
        }

        // Compatibility callers do not carry an action discriminator. Prefer a
        // native use of the physical card when one exists, then fall back to a
        // conversion such as Wusheng's red-card Slash.
        var selected = matching.FirstOrDefault(candidate =>
                   candidate.PlayedCardKind is null && candidate.TargetCardId is null) ??
               matching.FirstOrDefault(candidate => candidate.PlayedCardKind is null) ??
               matching.FirstOrDefault();
        if (selected is not null &&
            (selected.ConversionSource is not null ||
             selected.AdditionalConversionSources is { Count: > 0 } ||
             selected.CardKindModifierSkill is not null ||
             selected.TargetCountModifierSkill is not null) &&
            matching.Count(candidate =>
                (candidate.PlayedCardKind ?? card.Kind) == (selected.PlayedCardKind ?? card.Kind)) > 1)
        {
            return null;
        }
        return selected;
    }

    private static bool ConversionSourcesEqual(
        IReadOnlyList<CardConversionSource>? left,
        IReadOnlyList<CardConversionSource>? right) =>
        (left is null || left.Count == 0) && (right is null || right.Count == 0) ||
        left is not null && right is not null && left.SequenceEqual(right);

    private static bool IsSlashCard(CardKind kind) =>
        kind is CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash;

    private void MarkSlashUsedOrPlayedDuringCurrentPlayPhase(int actorSeat, CardKind effectiveCardKind)
    {
        if (_phase == TurnPhase.Play &&
            actorSeat == _currentSeat &&
            IsSlashCard(effectiveCardKind))
        {
            _usedOrPlayedSlashDuringPlayPhase = true;
        }
    }

    private IReadOnlyList<Card> GetResponseCards(
        CharacterState responder,
        CardKind requiredCardKind)
    {
        if (requiredCardKind == CardKind.Slash &&
            IsCardUseForbidden(responder.Seat, CardKind.Slash, CardActionType.Response))
        {
            return [];
        }

        var cards = GetPlayableCards(responder)
            .Where(card => !IsTurnHandCardRestricted(responder, card))
            .Where(card => CanUseCardAsResponse(responder, card, requiredCardKind));
        if (UsesFormalWushengEquipment && requiredCardKind == CardKind.Slash)
        {
            cards = cards.Concat(GetEquipment(responder).Where(card =>
                CanUseAsFormalWushengResponse(responder, card)));
        }

        return cards.ToArray();
    }

    private IReadOnlyList<IReadOnlyList<Card>> GetZhangbaSlashPairs(CharacterState responder)
    {
        if (!CanUseZhangbaSerpentSpear(responder))
        {
            return [];
        }

        var hand = GetPlayableCards(responder)
            .Where(card => !IsTurnHandCardRestricted(responder, card))
            .OrderBy(card => card.Id)
            .ToArray();
        var pairs = new List<IReadOnlyList<Card>>();
        for (var first = 0; first < hand.Length - 1; first++)
        {
            for (var second = first + 1; second < hand.Length; second++)
            {
                pairs.Add(Array.AsReadOnly(new[] { hand[first], hand[second] }));
            }
        }

        return pairs;
    }

    private IReadOnlyList<Card>? FindZhangbaSlashPair(
        CharacterState responder,
        IReadOnlyList<int> requestedCardIds)
    {
        if (requestedCardIds.Count != 2 || requestedCardIds.Distinct().Count() != 2)
        {
            return null;
        }

        var requested = requestedCardIds.Order().ToArray();
        return GetZhangbaSlashPairs(responder).FirstOrDefault(pair =>
            pair.Select(card => card.Id).Order().SequenceEqual(requested));
    }

    private bool CanUseAsFormalWushengSlash(CharacterState responder, Card card)
    {
        if (!UsesFormalWushengEquipment)
        {
            return false;
        }

        var context = CreateSkillContext(responder);
        return GetProgramViewAsConversions(responder, card, CardKind.Slash, forResponse: false)
                   .Any(source => source.SkillId == "classic:wusheng") ||
               EnabledSkillRules(responder).Any(skill =>
                   skill.Kind == SkillKind.Wusheng && skill.Conversion?.CanUseAsSlash(context, card) == true);
    }

    private bool CanUseAsFormalWushengResponse(CharacterState responder, Card card)
    {
        if (!UsesFormalWushengEquipment)
        {
            return false;
        }

        var context = CreateSkillContext(responder);
        return GetProgramViewAsConversions(responder, card, CardKind.Slash, forResponse: true)
                   .Any(source => source.SkillId == "classic:wusheng") ||
               EnabledSkillRules(responder).Any(skill =>
                   skill.Kind == SkillKind.Wusheng &&
                   skill.Conversion?.CanUseAsResponse(context, card, CardKind.Slash) == true);
    }

    private bool CanConvertResponse(CharacterState responder, Card card, CardKind requiredCardKind)
    {
        var identities = GetProgramCardIdentityMatches(responder, card);
        if (identities.Count != 0)
            return identities.Any(match =>
                MatchesRequiredCard(match.Identity.OutputKind, requiredCardKind));
        var context = CreateSkillContext(responder);
        return new SkillProgramRules(
                EnabledViewAsPrograms(responder),
                GetHand(responder).Select(item => item.Id).ToHashSet(),
                GetEquipment(responder).Select(item => item.Id).ToHashSet())
            .CanUseAsResponse(context, card, requiredCardKind) || EnabledSkillRules(responder).Any(skill =>
            (UsesFormalLuoshenAndQingguo || skill.Kind != SkillKind.Qingguo) &&
            skill.Conversion?.CanUseAsResponse(context, card, requiredCardKind) == true);
    }

    private CardKind GetEffectiveResponseKind(
        CharacterState responder,
        Card responseCard,
        CardKind requiredCardKind)
    {
        var identities = GetProgramCardIdentityMatches(responder, responseCard);
        if (identities.Count != 0)
        {
            return identities.Any(match =>
                    MatchesRequiredCard(match.Identity.OutputKind, requiredCardKind))
                ? requiredCardKind
                : throw new InvalidOperationException(
                    $"The mandatory identity of response card {responseCard.Id} cannot satisfy {requiredCardKind}.");
        }

        if (MatchesRequiredCard(responseCard.Kind, requiredCardKind))
        {
            return requiredCardKind;
        }

        return CanConvertResponse(responder, responseCard, requiredCardKind)
            ? requiredCardKind
            : throw new InvalidOperationException(
                $"The response card {responseCard.Id} cannot be used as {requiredCardKind}.");
    }

    private static bool IsNativeResponseCard(Card responseCard, CardKind requiredCardKind) =>
        MatchesRequiredCard(responseCard.Kind, requiredCardKind);

    private bool CanUseCardAsResponse(
        CharacterState responder,
        Card card,
        CardKind requiredCardKind)
    {
        var identities = GetProgramCardIdentityMatches(responder, card);
        return identities.Count != 0
            ? identities.Any(match => MatchesRequiredCard(match.Identity.OutputKind, requiredCardKind))
            : MatchesRequiredCard(card.Kind, requiredCardKind) ||
              CanConvertResponse(responder, card, requiredCardKind);
    }

    private static CardKind? ReadResponseCardKind(PromptChoice choice) =>
        choice.Parameters.TryGetValue("response-card-kind", out var value) &&
        Enum.TryParse<CardKind>(value, ignoreCase: false, out var kind)
            ? kind
            : null;

    private static bool MatchesRequiredCard(CardKind actual, CardKind required) =>
        required == CardKind.Slash ? IsSlashCard(actual) : actual == required;

    private static DamageNature GetDamageNature(CardKind kind) => kind switch
    {
        CardKind.FireSlash or CardKind.FireAttack => DamageNature.Fire,
        CardKind.ThunderSlash or CardKind.Lightning => DamageNature.Thunder,
        _ => DamageNature.Normal
    };

    private DamageNature GetDamageNature(AttackResolution attack) =>
        IsYingboRepeated(attack.ResolutionId)
            ? DamageNature.Fire
            : attack.DamageNatureOverride ?? GetDamageNature(RequireAttackCardKind(attack));

    private static Card RequireAttackCard(AttackResolution attack) =>
        attack.Card ?? throw new InvalidOperationException(
            "This card-resolution path requires a physical source card.");

    private static CardKind RequireAttackCardKind(AttackResolution attack) =>
        attack.EffectiveCardKind ?? throw new InvalidOperationException(
            "This card-resolution path requires an effective source card kind.");

    private int FinalizeAttackDamageAmount(AttackResolution attack)
    {
        if (attack.DamageAmountFinalized)
        {
            return attack.DamageAmount;
        }

        var baseAmount = attack.DamageAmount;
        var turnDamageModifiers = attack.EffectiveCardKind is { } effectiveKind
            ? _turnCardUseEffects.GetDamageModifiers(
                _turnNumber,
                _currentSeat,
                attack.SourceSeat,
                attack.CardUserSeat,
                effectiveKind,
                attack.IsChainPropagation)
            : [];
        var programDamageModifiers = turnDamageModifiers
            .Select(modifier => (modifier.Source, modifier.Amount))
            .Concat(GetPassiveProgramDamageModifiers(attack))
            .ToArray();
        var programDamageBonus = programDamageModifiers.Sum(modifier => modifier.Amount);
        var receivesGudingBladeBonus = UsesFormalGudingBlade &&
            !attack.IsChainPropagation &&
            !attack.IsActiveSkillDamage &&
            attack.CardUserSeat == attack.SourceSeat &&
            attack.EffectiveCardKind is CardKind.Slash or CardKind.FireSlash or CardKind.ThunderSlash &&
            GetHand(_players[attack.TargetSeat]).Count == 0 &&
            GetEquipment(_players[attack.SourceSeat]).Any(card => card.Kind == CardKind.GudingBlade);
        var receivesYingboBonus = IsYingboRepeated(attack.ResolutionId);
        var receivesTengjiaBonus = UsesFormalTengjia &&
            GetDamageNature(attack) == DamageNature.Fire &&
            HasTengjia(_players[attack.TargetSeat]) &&
            (attack.IsChainPropagation || !attack.IgnoresArmor);
        var silverLionCapsDamage = UsesFormalSilverLion &&
            baseAmount + programDamageBonus +
            (receivesGudingBladeBonus ? 1 : 0) +
            (receivesYingboBonus ? 1 : 0) +
            (receivesTengjiaBonus ? 1 : 0) > 1 &&
            HasSilverLion(_players[attack.TargetSeat]) &&
            (attack.IsChainPropagation || !attack.IgnoresArmor);
        var damageBonus = programDamageBonus +
                          (receivesGudingBladeBonus ? 1 : 0) +
                          (receivesYingboBonus ? 1 : 0) +
                          (receivesTengjiaBonus ? 1 : 0);
        attack.FinalizeDamageAmount(damageBonus, silverLionCapsDamage ? 1 : null);
        var runningAmount = baseAmount;
        foreach (var modifier in programDamageModifiers)
        {
            var modifiedAmount = checked(runningAmount + modifier.Amount);
            QueueGameEvent(new ProgramCardDamageModifiedEvent(
                attack.ResolutionId,
                modifier.Source,
                attack.TargetSeat,
                RequireAttackCardKind(attack),
                runningAmount,
                modifiedAmount));
            AddLog(
                "SkillTriggered",
                $"{_players[attack.SourceSeat].Name} 的【{_contentRegistry!.GetSkill(modifier.Source.SkillId).Name}】令本次【{CardCatalog.Get(RequireAttackCardKind(attack)).DisplayName}】伤害 +{modifier.Amount}。",
                attack.SourceSeat,
                attack.TargetSeat);
            runningAmount = modifiedAmount;
        }
        if (receivesGudingBladeBonus)
        {
            var modifiedAmount = checked(runningAmount + 1);
            QueueGameEvent(new GudingBladeDamageIncreasedEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                attack.TargetSeat,
                RequireAttackCardKind(attack),
                runningAmount,
                modifiedAmount));
            AddLog(
                "EquipmentEffect",
                $"{_players[attack.SourceSeat].Name} 的【古锭刀】对空手的 {_players[attack.TargetSeat].Name} 生效，本次伤害 +1。",
                attack.SourceSeat,
                attack.TargetSeat);
            runningAmount = modifiedAmount;
        }
        if (receivesYingboBonus)
        {
            var modifiedAmount = checked(runningAmount + 1);
            QueueGameEvent(new YingboDamageIncreasedEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                attack.TargetSeat,
                RequireAttackCardKind(attack),
                runningAmount,
                modifiedAmount));
            AddLog(
                "SkillTriggered",
                $"{_players[attack.SourceSeat].Name} 的【英博】令本次伤害 +1。",
                attack.SourceSeat,
                attack.TargetSeat);
            runningAmount = modifiedAmount;
        }
        if (receivesTengjiaBonus)
        {
            var modifiedAmount = checked(runningAmount + 1);
            QueueGameEvent(new TengjiaFireDamageIncreasedEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                attack.TargetSeat,
                attack.EffectiveCardKind,
                runningAmount,
                modifiedAmount));
            AddLog("EquipmentEffect", $"{_players[attack.TargetSeat].Name} 的【藤甲】令本次火焰伤害 +1。", attack.TargetSeat, attack.SourceSeat);
            runningAmount = modifiedAmount;
        }
        if (silverLionCapsDamage)
        {
            QueueGameEvent(new SilverLionDamageCappedEvent(
                attack.ResolutionId,
                attack.SourceSeat,
                attack.TargetSeat,
                attack.EffectiveCardKind,
                runningAmount,
                1));
            AddLog("EquipmentEffect", $"{_players[attack.TargetSeat].Name} 的【白银狮子】将本次伤害改为 1 点。", attack.TargetSeat, attack.SourceSeat);
        }

        return attack.DamageAmount;
    }

    private IReadOnlyList<(CardUseEffectSource Source, int Amount)> GetPassiveProgramDamageModifiers(
        AttackResolution attack)
    {
        if (_contentRegistry is null || attack.IsChainPropagation ||
            attack.IsActiveSkillDamage || attack.IsDelayedJudgmentDamage || attack.IsLeijiDamage ||
            attack.IsProgramJudgmentDamage || attack.CardUserSeat != attack.SourceSeat ||
            attack.EffectiveCardKind is not { } effectiveKind ||
            !IsValidPlayerSeat(attack.SourceSeat) || !IsValidPlayerSeat(attack.TargetSeat) ||
            !_players[attack.SourceSeat].IsAlive || !_players[attack.TargetSeat].IsAlive)
            return [];

        return (GetSkillBindingShard(_players[attack.SourceSeat])?.ProgramInstances ?? [])
            .SelectMany(instance => instance.Program.DamageModifiers.Select(modifier =>
                (instance, modifier)))
            .Where(item => item.modifier.CardKinds.Contains(effectiveKind) &&
                (item.modifier.Condition switch
                {
                    SkillProgramDamageModifierCondition.Always => true,
                    SkillProgramDamageModifierCondition.SourceOutsideTargetAttackRange =>
                        GetCombatDistance(attack.TargetSeat, attack.SourceSeat) >
                        GetAttackRange(attack.TargetSeat),
            _ => false
                }))
            .Select(item => (new CardUseEffectSource(item.instance.SkillId, item.modifier.Id,
                attack.SourceSeat, item.instance.SkillInstanceId), item.modifier.Amount))
            .ToArray();
    }

    private static string GetSuitName(Suit suit) => suit switch
    {
        Suit.Spade => "黑桃",
        Suit.Heart => "红桃",
        Suit.Club => "梅花",
        Suit.Diamond => "方块",
        _ => suit.ToString()
    };

    private static string GetDamageNatureLabel(DamageNature nature) => nature switch
    {
        DamageNature.Fire => "火焰",
        DamageNature.Thunder => "雷电",
        _ => string.Empty
    };

