    private bool HasBagua(CharacterState player) =>
        GetEquipment(player).Any(card => card.Kind == CardKind.BaguaFormation) ||
        UsesFormalWolong && HasRuntimeSkill(player, SkillKind.Bazhen) &&
        !GetEquipment(player).Any(card => EquipmentCatalog.Get(card.Kind).Slot == EquipmentSlot.Armor);

    private bool HasTengjia(CharacterState player) =>
        GetEquipment(player).Any(card => card.Kind == CardKind.Tengjia);

    private bool HasSilverLion(CharacterState player) =>
        GetEquipment(player).Any(card => card.Kind == CardKind.SilverLion);

    private bool CanRequestHujia(CharacterState owner, AttackResolution attack) =>
        UsesFormalHujia &&
        !attack.HujiaAttempted &&
        owner.IsAlive &&
        owner.Role == Role.Lord &&
        HasRuntimeSkill(owner, SkillKind.Hujia) &&
        GetHujiaCandidateSeats(owner.Seat).Count > 0;

    private int GetRequiredResponseCount(
        CharacterState skillOwner,
        int sourceSeat,
        int responderSeat,
        CardKind incomingCard,
        CardKind requiredCardKind)
    {
        if (!UsesFormalWushuang || !HasRuntimeSkill(skillOwner, SkillKind.Wushuang))
        {
            return 1;
        }

        return CardUseRules(skillOwner).Aggregate(1, (count, rule) => rule.ModifyRequiredResponseCount(
            new ResponseCountSkillContext(
                CreateSkillContext(skillOwner),
                sourceSeat,
                responderSeat,
                incomingCard,
                requiredCardKind),
            count));
    }

    private IReadOnlyList<int> GetHujiaCandidateSeats(int ownerSeat) =>
        Enumerable.Range(0, _playerCount)
            .Select(offset => (_currentSeat + offset) % _playerCount)
            .Where(seat => seat != ownerSeat &&
                           _players[seat].IsAlive &&
                           string.Equals(GetEffectiveFactionId(_players[seat]), "wei", StringComparison.Ordinal))
            .ToArray();

    private bool CanRequestJijiangResponse(CharacterState owner, AttackResolution attack)
    {
        if (!UsesFormalJijiang ||
            IsCardUseForbidden(owner.Seat, CardKind.Slash, CardActionType.Response) ||
            !owner.IsAlive ||
            owner.Role != Role.Lord ||
            !HasRuntimeSkill(owner, SkillKind.Jijiang) ||
            GetJijiangCandidateSeats(owner.Seat).Count == 0)
        {
            return false;
        }

        if (_pendingDuel is { } duel && ReferenceEquals(duel.Attack, attack))
        {
            return duel.ResponderSeat == owner.Seat && !duel.JijiangAttempted;
        }

        return !attack.JijiangAttempted;
    }

    private bool CanUseFactionSlashRequest(CharacterState owner, string providerFactionId)
    {
        if (SlashKinds.All(kind => IsCardUseForbidden(owner.Seat, kind, CardActionType.Use)) ||
            !owner.IsAlive ||
            owner.Role != Role.Lord ||
            (!owner.IsHuman && owner.AiJijiangFailedThisTurn) ||
            GetFactionProviderSeats(owner.Seat, providerFactionId).Count == 0)
        {
            return false;
        }

        return _players.Any(target => CanUseProvidedSlashTarget(owner, target));
    }

    private bool CanUseProvidedSlashTarget(
        CharacterState owner,
        CharacterState target,
        CardKind? effectiveKind = null) =>
        effectiveKind is { } kind
            ? target.IsAlive && target.Seat != owner.Seat &&
              CanSpendSlashUse(owner, target, ignoresCount: false, kind) &&
              (HasCardDistanceExemption(owner, target, kind) ||
               HasUnlimitedTurnRuleModifier(owner.Seat, SkillRuleQuery.SlashDistanceLimit) ||
               GetCombatDistance(owner.Seat, target.Seat) <= GetAttackRange(owner.Seat)) &&
              !IsSlashProhibited(target)
            : SlashKinds.Any(candidate => CanUseProvidedSlashTarget(owner, target, candidate));

    private IReadOnlyList<int> GetFactionProviderSeats(int ownerSeat, string factionId) =>
        Enumerable.Range(0, _playerCount)
            .Select(offset => (_currentSeat + offset) % _playerCount)
            .Where(seat => seat != ownerSeat &&
                            _players[seat].IsAlive &&
                            string.Equals(GetEffectiveFactionId(_players[seat]), factionId, StringComparison.Ordinal))
            .ToArray();

    private IReadOnlyList<int> GetJijiangCandidateSeats(int ownerSeat) =>
        GetFactionProviderSeats(ownerSeat, "shu");

    private bool HasBlackSlashBarrier(CharacterState player) =>
        GetEquipment(player).Any(card => EquipmentCatalog.Get(card.Kind).BlocksBlackSlash);

    private bool HasArmor(CharacterState player) =>
        GetEquipment(player).Any(card => EquipmentCatalog.Get(card.Kind).Slot == EquipmentSlot.Armor);

    internal static bool IsBlackCardUse(IReadOnlyList<Card> physicalCards) =>
        physicalCards.Count > 0 &&
        physicalCards.All(card => card.Suit is Suit.Spade or Suit.Club);

    internal static bool CanYizhongNullify(IReadOnlyList<Card> physicalCards, bool hasArmor) =>
        !hasArmor && IsBlackCardUse(physicalCards);

    internal static bool IsTrickCardDamage(CardKind kind) =>
        CardCatalog.Get(kind).CategoryName == "锦囊牌";

    internal static bool CanWuyanPreventDamage(
        bool isClassicIdentityMode,
        CardKind kind,
        bool sourceHasWuyan,
        bool targetHasWuyan) =>
        isClassicIdentityMode &&
        IsTrickCardDamage(kind) &&
        (sourceHasWuyan || targetHasWuyan);

    private bool TryPreventWuyanDamage(AttackResolution attack, int amount)
    {
        if (attack.EffectiveCardKind is not { } cardKind)
        {
            return false;
        }

        var source = _players[attack.SourceSeat];
        var target = _players[attack.TargetSeat];
        if (!CanWuyanPreventDamage(
                IsClassicIdentityMode,
                cardKind,
                HasRuntimeSkill(source, SkillKind.Wuyan),
                HasRuntimeSkill(target, SkillKind.Wuyan)))
        {
            return false;
        }
        var skillOwner = HasRuntimeSkill(source, SkillKind.Wuyan)
            ? source
            : HasRuntimeSkill(target, SkillKind.Wuyan)
                ? target
                : null;
        if (skillOwner is null)
        {
            return false;
        }

        AddLog(
            "DamagePrevented",
            $"{skillOwner.Name} 的【无言】防止了【{CardCatalog.Get(cardKind).DisplayName}】造成的 {amount} 点伤害。",
            skillOwner.Seat,
            skillOwner.Seat == source.Seat ? target.Seat : source.Seat);
        QueueGameEvent(new WuyanDamagePreventedEvent(
            attack.ResolutionId,
            source.Seat,
            target.Seat,
            cardKind,
            amount,
            skillOwner.Seat));
        return true;
    }

    private bool HasArmorBypass(CharacterState player) =>
        GetEquipment(player).Any(card => EquipmentCatalog.Get(card.Kind).IgnoresArmor);

    private PlayerSkillContext CreateSkillContext(CharacterState player) =>
        new(
            player.Seat,
            player.Hp,
            player.MaxHp,
            GetHand(player).Count,
            _phase,
            player.UsedActiveSkillKinds,
            player.Seat == _currentSeat,
            player.IsFaceDown,
            player.IsChained);

    private ActiveSkillContext CreateActiveSkillContext(
        CharacterState actor,
        SkillKind skill,
        int selectedCardCount = 0,
        int selectedTargetCount = 0)
    {
        var selection = ActiveActionCatalog.Selection(skill);
        return new ActiveSkillContext(
            CreateSkillContext(actor),
            selectedCardCount,
            selectedTargetCount,
            AdditionalSelectableCardCount:
                selection.Cards == ActiveCardSelector.HandAndEquipmentInClassic && IsClassicIdentityMode
                    ? GetEquipment(actor).Count
                    : 0,
            EnforceOncePerTurn: selection.OncePerTurn);
    }

    private bool IsActiveActionAvailable(CharacterState actor, ActiveActionSelection selection)
    {
        var gate = selection.Gate;
        return (!gate.HasFlag(ActiveActionGate.ClassicIdentity) || IsClassicIdentityMode) &&
               (!gate.HasFlag(ActiveActionGate.GlobalArrowBarragePlayable) ||
                CanUseGlobalCard(actor, CardKind.ArrowBarrage)) &&
               (!gate.HasFlag(ActiveActionGate.TwoSameSuitHandCards) ||
                GetHand(actor).GroupBy(card => card.Suit).Any(group => group.Count() >= 2)) &&
               (!gate.HasFlag(ActiveActionGate.FactionSlashRequestAvailable) ||
                 CanUseFactionSlashRequest(actor, selection.ProviderFactionId ??
                     throw new InvalidOperationException("A faction request needs a provider faction.")));
    }

    private IReadOnlySet<int> GetActiveSkillValidCardIds(
        CharacterState actor,
        SkillKind skill)
    {
        var selection = ActiveActionCatalog.Selection(skill);
        var hand = GetHand(actor);
        var equipment = GetEquipment(actor);
        return selection.Cards switch
        {
            ActiveCardSelector.WeaponFromHandOrEquipment => hand.Concat(equipment)
                .Where(card => EquipmentCatalog.IsEquipment(card.Kind) &&
                    EquipmentCatalog.Get(card.Kind).Slot == EquipmentSlot.Weapon)
                .Select(card => card.Id).ToHashSet(),            ActiveCardSelector.SameSuitPair => hand.GroupBy(card => card.Suit)
                .Where(group => group.Count() >= 2)
                .SelectMany(group => group).Select(card => card.Id).ToHashSet(),            ActiveCardSelector.HandAndEquipmentInClassic when IsClassicIdentityMode =>
                hand.Concat(equipment).Select(card => card.Id).ToHashSet(),            _ => hand.Select(card => card.Id).ToHashSet()
        };
    }

    private IReadOnlySet<int> GetActiveSkillValidTargetSeats(
        CharacterState actor,
        SkillKind skill)
    {
        var selection = ActiveActionCatalog.Selection(skill);
        var requirements = selection.Targets;
        if (selection.RequireClassicIdentityForTarget && !IsClassicIdentityMode)
        {
            return new HashSet<int>();
        }

        return _players.Where(player =>
                requirements.HasFlag(ActiveTargetSelector.Alive) && player.IsAlive &&
                (!requirements.HasFlag(ActiveTargetSelector.Other) || player.Seat != actor.Seat) &&
                (!requirements.HasFlag(ActiveTargetSelector.Wounded) || player.Hp < player.MaxHp) &&
                (!requirements.HasFlag(ActiveTargetSelector.Male) || player.Gender == GeneralGender.Male) &&
                (!requirements.HasFlag(ActiveTargetSelector.HasHand) || GetHand(player).Count > 0) &&
                (!requirements.HasFlag(ActiveTargetSelector.MoreHpThanOwner) || player.Hp > actor.Hp) &&
                (!requirements.HasFlag(ActiveTargetSelector.WithinAttackRange) ||
                    GetCombatDistance(actor.Seat, player.Seat) <= GetAttackRange(actor.Seat)) &&
                (!requirements.HasFlag(ActiveTargetSelector.FactionSlashRequestTarget) ||
                    CanUseProvidedSlashTarget(actor, player)))
            .Select(player => player.Seat).ToHashSet();
    }

    private void MoveCard(
        Card card,
        CardLocation from,
        CardLocation to,
        CardMoveReason reason)
    {
        var batch = BeginCardMovementBatch([from]);
        var movements = new List<CardMovementRecord>(1);
        var committed = false;
        try
        {
            _cardZones.Move(card.Id, from, to);
            movements.Add(RecordMovement(card, from, to, reason));
            ClearJudgmentEffectiveKindAfterMove(card, from, to);
            ResolveSilverLionRemoval(card, from, reason);
            ResolveWoodenOxMove(card, from, to);
            committed = true;
        }
        finally
        {
            CompleteCardMovementBatch(batch, movements, committed);
        }
    }

    private void MoveCards(
        IReadOnlyList<Card> cards,
        CardLocation from,
        CardLocation to,
        CardMoveReason reason)
    {
        var batch = BeginCardMovementBatch([from]);
        var movements = new List<CardMovementRecord>(cards.Count);
        var committed = false;
        try
        {
            var moved = _cardZones.MoveMany(cards.Select(card => card.Id), from, to);
            foreach (var card in moved)
            {
                movements.Add(RecordMovement(card, from, to, reason));
                ClearJudgmentEffectiveKindAfterMove(card, from, to);
                ResolveSilverLionRemoval(card, from, reason);
                ResolveWoodenOxMove(card, from, to);
            }
            committed = true;
        }
        finally
        {
            CompleteCardMovementBatch(batch, movements, committed);
        }
    }

    private void MoveAllCards(
        CardLocation from,
        CardLocation to,
        CardMoveReason reason)
    {
        var batch = BeginCardMovementBatch([from]);
        var movements = new List<CardMovementRecord>();
        var committed = false;
        try
        {
            var cards = _cardZones.MoveAll(from, to);
            foreach (var card in cards)
            {
                movements.Add(RecordMovement(card, from, to, reason));
                ClearJudgmentEffectiveKindAfterMove(card, from, to);
                ResolveSilverLionRemoval(card, from, reason);
                ResolveWoodenOxMove(card, from, to);
            }
            committed = true;
        }
        finally
        {
            CompleteCardMovementBatch(batch, movements, committed);
        }
    }

    private void ResolveWoodenOx(CharacterState actor, int storedCardId, int targetSeat)
    {
        var storedCard = GetHand(actor).Single(card => card.Id == storedCardId);
        MoveCard(storedCard, CardLocation.Hand(actor.Seat), CardLocation.WoodenOxGrain(actor.Seat), CardMoveReasons.WoodenOxStore);
        _woodenOxUsedThisTurn = true;
        AddLog("EquipmentEffect", $"{actor.Name} 将一张手牌扣置于【木牛流马】下。", actor.Seat);

        if (targetSeat < 0)
        {
            return;
        }

        var woodenOx = GetEquipment(actor).Single(card => card.Kind == CardKind.WoodenOx);
        MoveCard(woodenOx, CardLocation.Equipment(actor.Seat), CardLocation.Equipment(targetSeat), CardMoveReasons.WoodenOxTransfer);
        AddLog("EquipmentEffect", $"{actor.Name} 将【木牛流马】移动给 {_players[targetSeat].Name}。", actor.Seat);
    }

    private void ResolveWoodenOxMove(Card card, CardLocation from, CardLocation to)
    {
        if (!UsesFormalWoodenOx || card.Kind != CardKind.WoodenOx ||
            from is not { Zone: CardZoneKind.Equipment, OwnerSeat: { } ownerSeat })
        {
            return;
        }

        var grainFrom = CardLocation.WoodenOxGrain(ownerSeat);
        if (_cardZones.Count(grainFrom) == 0)
        {
            return;
        }

        if (to is { Zone: CardZoneKind.Equipment, OwnerSeat: { } targetSeat })
        {
            MoveAllCards(grainFrom, CardLocation.WoodenOxGrain(targetSeat), CardMoveReasons.WoodenOxTransfer);
        }
        else
        {
            MoveAllCards(grainFrom, CardLocation.DiscardPile, CardMoveReasons.WoodenOxGrainDiscard);
        }
    }

    private void ResolveSilverLionRemoval(Card card, CardLocation from, CardMoveReason reason)
    {
        if (!UsesFormalSilverLion ||
            card.Kind != CardKind.SilverLion ||
            from is not { Zone: CardZoneKind.Equipment, OwnerSeat: { } ownerSeat })
        {
            return;
        }

        var owner = _players[ownerSeat];
        if (!owner.IsAlive || owner.Hp >= owner.MaxHp)
        {
            return;
        }

        var parentFrameId = _resolutionStack.LastOrDefault()?.Id ?? 0;
        var recoveryFrameId = BeginRecovery(parentFrameId, ownerSeat, ownerSeat, 1);
        try
        {
            owner.Hp++;
            QueueGameEvent(new RecoveryAppliedEvent(ownerSeat, ownerSeat, 1, owner.Hp));
            QueueGameEvent(new SilverLionRemovedRecoveryEvent(
                recoveryFrameId, ownerSeat, reason, 1, owner.Hp));
            AddLog("EquipmentEffect", $"{owner.Name} 失去【白银狮子】，回复 1 点体力。", ownerSeat);
        }
        finally
        {
            PopResolutionFrame(recoveryFrameId, ResolutionFrameKind.Recovery);
        }
    }

    private void ClearJudgmentEffectiveKindAfterMove(
        Card card,
        CardLocation from,
        CardLocation to)
    {
        if (from.Zone == CardZoneKind.Judgment && to.Zone != CardZoneKind.Judgment)
        {
            _judgmentEffectiveCardKinds.Remove(card.Id);
        }
    }

    private CardMovementRecord RecordMovement(
        Card card,
        CardLocation from,
        CardLocation to,
        CardMoveReason reason)
    {
        var movement = new CardMovementRecord(
            ++_movementSequence,
            _turnNumber,
            card.Id,
            card.Kind,
            from,
            to,
            reason);
        _cardMovements.Add(movement);
        if (_started)
        {
            _pendingNotifications.Enqueue(new CardMovedNotification(movement));
            QueueGameEvent(new CardMovedEvent(card.Id, card.Kind, from, to, reason));
        }
        return movement;
    }

    private bool IsPendingDamageProgramDying()
    {
        if (_pendingDamageTrigger is not { } trigger ||
            _pendingDying is not { ResumesProgramSkill: true } dying ||
            _resolutionStack.OfType<ProgramSkillFrame>().LastOrDefault(frame =>
                frame.Id == dying.ParentFrameId) is not { } program ||
            program.WindowContext is not
            {
                Window: SkillProgramTriggerWindow.AfterDamageApplied,
                ParentFrameId: var parentFrameId
            } || parentFrameId != trigger.FrameId ||
            _resolutionStack.OfType<DyingFrame>().LastOrDefault(frame =>
                frame.Id == dying.FrameId) is not { } dyingFrame ||
            dyingFrame.ParentFrameId != program.Id)
            return false;

        return _resolutionStack.LastOrDefault() is DyingFrame topDying &&
                   topDying.Id == dying.FrameId ||
               _resolutionStack.LastOrDefault() is ProgramSkillFrame responseProgram &&
                   responseProgram.WindowContext is
                   {
                       Window: SkillProgramTriggerWindow.DyingResponse or
                           SkillProgramTriggerWindow.SelfDyingResponse,
                       ParentFrameId: var dyingParentId
                   } && dyingParentId == dying.FrameId;
    }

    private void AssertCoreInvariants()
    {
        var damageProgramDying = IsPendingDamageProgramDying();
        _turnCardUseEffects.AssertInvariants();
        AssertPindianInvariant();
        AssertProgramCardWindowState();
        AssertProgramJudgmentWindowState();
        AssertDiscardPromptInvariant();
        AssertYingboInvariant();
        _cardZones.AssertInvariants(_initialCardCount);

        foreach (var player in _players)
        {
            var equipment = GetEquipment(player);
            if (equipment.Any(card => !EquipmentCatalog.IsEquipment(card.Kind)))
            {
                throw new InvalidOperationException(
                    $"Player {player.Seat} equipment zone contains a non-equipment card.");
            }

            if (equipment
                .Select(card => EquipmentCatalog.Get(card.Kind).Slot)
                .Distinct()
                .Count() != equipment.Count)
            {
                throw new InvalidOperationException(
                    $"Player {player.Seat} has more than one card in an equipment slot.");
            }
        }

        foreach (var (cardId, effectiveKind) in _judgmentEffectiveCardKinds)
        {
            if (_cardZones.GetLocation(cardId).Zone != CardZoneKind.Judgment ||
                !IsDelayedCard(effectiveKind))
            {
                throw new InvalidOperationException(
                    $"Judgment effective card {cardId}/{effectiveKind} is outside a delayed judgment zone.");
            }
        }

        if (_pendingDeath is not null)
        {
            AssertOwnerDiedProgramInvariant();
            return;
        }

        var processing = _cardZones.CardsAt(CardLocation.Processing);
        var hasActiveCardResolution = _pendingAttack is not null ||
            _pendingBorrowedSword is not null ||
            _pendingGroupCard is not null ||
            _pendingFireAttack is not null ||
            _pendingNullification is not null ||
            _pendingJizhi is not null ||
            _pendingTieqi is not null ||
            _pendingLiegong is not null ||
            _pendingYingboGift is not null ||
            _pendingTargetCardSelection is not null ||
            _pendingJudgment is not null ||
            _resolutionStack.Any(frame => frame is ActiveSkillFrame or ProgramSkillFrame or ProgramCardTriggerWindowFrame or PindianFrame);
        if (!hasActiveCardResolution && processing.Count != 0)
        {
            throw new InvalidOperationException("Processing contains cards without an active resolution.");
        }

        if (_pendingAttack is { } attack &&
            !IsActiveAttackCardConsistent(attack, processing))
        {
            throw new InvalidOperationException(
                $"The active card resolution and Processing zone are inconsistent " +
                $"(attack={attack.ResolutionId}/{attack.EffectiveCardKind}, physical=[{string.Join(',', attack.PhysicalCards.Select(card => card.Id))}], " +
                $"processing=[{string.Join(',', processing.Select(card => card.Id))}]).");
        }

        if (_pendingBorrowedSword is { } borrowedSword)
        {
            var parentFrame = _resolutionStack.OfType<CardUseFrame>()
                .FirstOrDefault(frame => frame.Id == borrowedSword.ResolutionId);
            var parentCardInProcessing = processing.Any(card => card.Id == borrowedSword.Card.Id);
            var responseWindow = _resolutionStack.OfType<ResponseWindowFrame>().LastOrDefault(frame =>
                frame.ParentFrameId == borrowedSword.ResolutionId);
            var awaitingOwnerChoice = borrowedSword.AwaitingSlashChoice &&
                _pendingDecision is { Kind: DecisionKind.RespondSlash } borrowedDecision &&
                borrowedDecision.PlayerSeat == borrowedSword.WeaponOwnerSeat &&
                responseWindow is not null &&
                responseWindow.ResponderSeat == borrowedSword.WeaponOwnerSeat;
            var awaitingJijiang = _pendingJijiang is { IsBorrowedSwordUse: true } borrowedJijiang &&
                (borrowedJijiang.AwaitingProviders || borrowedJijiang.AwaitingZhuqueFanChoice) &&
                ReferenceEquals(borrowedJijiang.BorrowedSword, borrowedSword);
            var resolvingSlash = borrowedSword.ActiveAttack is { } borrowedAttack &&
                ReferenceEquals(_pendingAttack, borrowedAttack);
            if (parentFrame is null ||
                parentFrame.CardKind != CardKind.BorrowedSword ||
                !parentCardInProcessing ||
                (awaitingOwnerChoice ? 1 : 0) + (awaitingJijiang ? 1 : 0) + (resolvingSlash ? 1 : 0) != 1)
            {
                throw new InvalidOperationException(
                    "A Borrowed Sword continuation must retain its parent card and exactly one response or Slash continuation.");
            }
        }

        if (_pendingGroupCard is { Effect: GroupCardEffect.Recovery } recoveryGroup &&
            (processing.Count != 1 || processing[0].Id != recoveryGroup.Card.Id))
        {
            throw new InvalidOperationException(
                "The active group recovery and Processing zone are inconsistent.");
        }

        if (_pendingGroupCard is { Effect: GroupCardEffect.PublicDraft } publicDraft &&
            (processing.Count != 1 + publicDraft.RevealedCardIds.Count ||
             processing.All(card => card.Id != publicDraft.Card.Id) ||
             publicDraft.RevealedCardIds.Any(cardId => processing.All(card => card.Id != cardId))))
        {
            throw new InvalidOperationException(
                "The active FiveGrains draft and Processing zone are inconsistent.");
        }

        if (_pendingFireAttack is { } fireAttack)
        {
            const int expectedProcessingCount = 1;
            if (processing.Count != expectedProcessingCount ||
                processing.All(card => card.Id != fireAttack.Card.Id) ||
