                    jijiang.TargetSeat != parentAttack?.TargetSeat ||
                    (!awaitingProviderMatches && !activeAttackMatches))
                {
                    throw new InvalidOperationException(
                        "A Qinglong Crescent Blade Jijiang continuation must retain its parent choice or nested Slash.");
                }
            }
            else if (jijiang.IsActiveUse)
            {
                var activeFrame = jijiang.ActiveSkillFrameId is { } activeFrameId
                    ? _resolutionStack.OfType<ActiveSkillFrame>().LastOrDefault(frame => frame.Id == activeFrameId)
                    : null;
                var activeAttackMatches = !jijiang.AwaitingProviders &&
                                          !jijiang.AwaitingZhuqueFanChoice &&
                                          jijiang.ActiveAttack is { } activeAttack &&
                                          ReferenceEquals(_pendingAttack, activeAttack);
                if (activeFrame is null ||
                    (jijiang.AwaitingProviders
                        ? !providerPromptMatches
                        : jijiang.AwaitingZhuqueFanChoice
                            ? !zhuquePromptMatches
                            : !activeAttackMatches))
                {
                    throw new InvalidOperationException(
                        "An active Jijiang continuation must retain either one provider prompt or its Slash attack.");
                }
            }
            else
            {
                var responseWindow = _resolutionStack.OfType<ResponseWindowFrame>().LastOrDefault();
                if (!jijiang.AwaitingProviders ||
                    jijiang.ResponseAttack is not { } responseAttack ||
                    !ReferenceEquals(_pendingAttack, responseAttack) ||
                    responseWindow is null ||
                    responseWindow.ParentFrameId != responseAttack.ResolutionId ||
                    responseWindow.ResponderSeat != jijiang.OwnerSeat ||
                    !providerPromptMatches)
                {
                    throw new InvalidOperationException(
                        "A response Jijiang continuation must retain its attack, response window and one private provider prompt.");
                }
            }
        }

        if (_pendingGroupCard is { Effect: GroupCardEffect.Recovery } recovery &&
            (_pendingAttack is not null || recovery.CurrentAttack is not null))
        {
            throw new InvalidOperationException(
                "A group recovery cannot retain an attack continuation.");
        }

        if (_pendingGroupCard is { Effect: GroupCardEffect.PublicDraft } draft)
        {
            if (_pendingAttack is not null || draft.CurrentAttack is not null)
            {
                throw new InvalidOperationException(
                    "A FiveGrains draft cannot retain an attack continuation.");
            }

            if (draft.TargetIndex >= draft.TargetSeats.Count)
            {
                throw new InvalidOperationException(
                    "A FiveGrains draft must finish before its target cursor reaches the end.");
            }

            var expectedPicker = draft.TargetSeats[draft.TargetIndex];
            if (_pendingDecision is not { Kind: DecisionKind.SelectHarvestCard } harvestDecision ||
                harvestDecision.PlayerSeat != expectedPicker ||
                !harvestDecision.ValidCardIds.SequenceEqual(draft.RevealedCardIds))
            {
                throw new InvalidOperationException(
                    "A FiveGrains draft must retain a prompt for its current picker.");
            }

            var expectedStatus = _players[expectedPicker].IsHuman
                ? EngineStatus.AwaitingHumanCardSelection
                : EngineStatus.Running;
            if (_status != expectedStatus)
            {
                throw new InvalidOperationException(
                    "A FiveGrains draft status does not match its current picker.");
            }
        }

        if (_pendingDecision?.Kind == DecisionKind.SelectHarvestCard &&
            _pendingGroupCard is not { Effect: GroupCardEffect.PublicDraft })
        {
            throw new InvalidOperationException(
                "A harvest selection cannot exist without a public draft.");
        }

        if (_pendingDecision?.Kind is DecisionKind.FireAttackReveal or DecisionKind.FireAttackDiscard &&
            _pendingFireAttack is null)
        {
            throw new InvalidOperationException(
                "A FireAttack selection cannot exist without a FireAttack resolution.");
        }

        if (_pendingDecision?.Kind is DecisionKind.Guicai or DecisionKind.Guidao &&
            _pendingJudgment is null)
        {
            throw new InvalidOperationException(
                "A Guicai prompt cannot exist without a judgment continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.ProgramJudgmentReplacement &&
            _pendingJudgment is null)
        {
            throw new InvalidOperationException(
                "A configured replacement prompt cannot exist without a judgment continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.StoneAxe &&
            _pendingStoneAxe is null)
        {
            throw new InvalidOperationException(
                "A Stone Axe prompt cannot exist without its Slash continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.CixiongDoubleSwords &&
            _pendingCixiongDoubleSwords is null)
        {
            throw new InvalidOperationException(
                "A Cixiong Double Swords prompt cannot exist without its Slash continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.QinglongCrescentBlade &&
            _pendingQinglongCrescentBlade is null)
        {
            throw new InvalidOperationException(
                "A Qinglong Crescent Blade prompt cannot exist without its Slash continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.IceSword &&
            _pendingIceSword is null)
        {
            throw new InvalidOperationException(
                "An Ice Sword prompt cannot exist without its Slash continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.QilinBow &&
            _pendingQilinBow is null)
        {
            throw new InvalidOperationException(
                "A Qilin Bow prompt cannot exist without its Slash continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.Mengjin &&
            _pendingMengjin is null)
        {
            throw new InvalidOperationException(
                "A Mengjin prompt cannot exist without its Slash continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.Yingbo && _pendingYingboGift is null)
        {
            throw new InvalidOperationException(
                "A Yingbo prompt cannot exist without its card continuation.");
        }

        if (_pendingDecision?.Kind == DecisionKind.ZhuqueFan &&
            _pendingJijiang is not { AwaitingZhuqueFanChoice: true })
        {
            throw new InvalidOperationException(
                "A Zhuque Fan prompt cannot exist without its Jijiang continuation.");
        }

        if (_pendingDecision?.Kind is DecisionKind.Yuanhu or
            DecisionKind.Yaowu or
            DecisionKind.Ganglie or
            DecisionKind.GangliePunish &&
            _pendingDamageSkill is null)
        {
            throw new InvalidOperationException(
                "A damage-skill prompt cannot exist without a damage-skill continuation.");
        }

        var hasCardProgramPrompt = _pendingDecision is { Kind: DecisionKind.ProgramTrigger } &&
            _resolutionStack.OfType<ProgramCardTriggerWindowFrame>().Any();
        var hasBeforeDamageProgramPrompt = _pendingDecision is { Kind: DecisionKind.ProgramTrigger } &&
            _resolutionStack.OfType<BeforeDamageProgramWindowFrame>().Any();
        var awaitingHumanResponse =
            (_pendingDecision?.Kind is DecisionKind.RespondDodge or
                DecisionKind.RespondSlash or
                DecisionKind.Liuli or
                DecisionKind.Tianxiang or
                DecisionKind.Yuanhu or
                DecisionKind.Yaowu or
                DecisionKind.Ganglie or
                DecisionKind.GangliePunish or
                DecisionKind.Guicai or
                DecisionKind.Guidao or
                DecisionKind.Leiji or
                DecisionKind.Tieqi or
                DecisionKind.Liegong or
                DecisionKind.StoneAxe or
                DecisionKind.CixiongDoubleSwords or
                DecisionKind.QinglongCrescentBlade or
                DecisionKind.IceSword or
                DecisionKind.QilinBow or
                DecisionKind.Mengjin or
                DecisionKind.ZhuqueFan or
                DecisionKind.ProgramJudgmentTrigger or
                DecisionKind.ProgramJudgmentReplacement || hasCardProgramPrompt || hasBeforeDamageProgramPrompt) &&
             _status == EngineStatus.AwaitingHumanResponse;
        var awaitingHumanNullification =
            _pendingDecision?.Kind == DecisionKind.Nullification &&
            _status == EngineStatus.AwaitingHumanResponse;
        var awaitingHumanJizhi =
            _pendingDecision?.Kind == DecisionKind.Jizhi &&
            _status == EngineStatus.AwaitingHumanResponse;
        var awaitingHumanDying =
            _pendingDecision?.Kind == DecisionKind.RescueDying &&
            _status == EngineStatus.AwaitingHumanDying;
        var awaitingAiResponse = IsAiResponsePending() || IsAiTieqiPending() || IsAiLiegongPending() ||
                                              IsAiTianxiangPending() ||
                                  (_pendingDecision is { } programDecision &&
                                   (hasCardProgramPrompt || hasBeforeDamageProgramPrompt) &&
                                   !_players[programDecision.PlayerSeat].IsHuman) ||
                                 IsAiProgramJudgmentReplacementPending() ||
                                 IsAiProgramJudgmentPending();
        var awaitingAiNullification = IsAiNullificationPending();
        var awaitingAiJizhi = IsAiJizhiPending();
        var awaitingAiDamageSkill = IsAiDamageSkillPending();
        var awaitingAiJudgment = IsAiJudgmentPending();
        if (_pendingAttack is null &&
            _pendingNullification is null &&
            _pendingJudgment is null &&
            _resolutionStack.OfType<ProgramCardTriggerWindowFrame>()
                .All(frame => frame.Continuation is not
                    (ProgramCardContinuation.DelayedCard or ProgramCardContinuation.BeforeTrickTargetEffects)) &&
            _pendingJijiang?.IsActiveUse != true &&
            _pendingJijiang?.IsBorrowedSwordUse != true &&
            _pendingBorrowedSword is null &&
            _pendingDying?.ResumesActiveSkill != true &&
            _pendingDying?.ResumesProgramSkill != true &&
            (awaitingHumanResponse || awaitingHumanDying || awaitingAiResponse || awaitingAiDamageSkill || awaitingAiJudgment))
        {
            throw new InvalidOperationException("A response continuation exists without an active Slash.");
        }

        if (_pendingNullification is not null &&
            (awaitingHumanResponse || awaitingHumanDying || awaitingAiResponse || awaitingAiDamageSkill || awaitingAiJudgment))
        {
            throw new InvalidOperationException(
                "A Nullification window cannot retain a non-Nullification prompt.");
        }

        if (_pendingNullification is not null &&
            !awaitingHumanNullification &&
            !awaitingAiNullification &&
            !awaitingHumanJizhi &&
            !awaitingAiJizhi)
        {
            throw new InvalidOperationException(
                "An active Nullification window must retain exactly one response continuation.");
        }

        if (_pendingDying is null &&
            _pendingDamageTrigger is null &&
            _pendingDamageSkill is null &&
            _pendingJudgment is null &&
            _pendingYingboGift is null &&
            _pendingAttack is not null &&
            awaitingHumanResponse == awaitingAiResponse)
        {
            throw new InvalidOperationException("An active card resolution must have exactly one response continuation.");
        }

        if (_status == EngineStatus.Completed &&
            (_pendingDecision is not null ||
             _pendingAttack is not null ||
             _pendingDuel is not null ||
             _pendingGroupCard is not null ||
             _pendingFireAttack is not null ||
             _pendingNullification is not null ||
             _pendingTargetCardSelection is not null ||
             _pendingDying is not null ||
             _pendingDamageTrigger is not null ||
             _pendingDamageSkill is not null ||
              _pendingJudgment is not null ||
             _pendingLeiji is not null ||
             _pendingLuoshen is not null ||
             _pendingJizhi is not null ||
             _pendingTieqi is not null ||
             _pendingLiegong is not null ||
             _pendingYingboGift is not null ||
             _pendingHujia is not null ||
             _pendingJijiang is not null ||
             _pendingBorrowedSword is not null ||
             _pendingStoneAxe is not null ||
             _pendingCixiongDoubleSwords is not null ||
             _pendingQinglongCrescentBlade is not null ||
             _pendingIceSword is not null ||
             _pendingQilinBow is not null ||
             _pendingTianxiang is not null ||
             _pendingMengjin is not null ||
             _pendingFangtianHalberd is not null ||
             processing.Count != 0))
        {
            throw new InvalidOperationException("A completed game cannot retain pending resolution state.");
        }
    }

    private bool IsActiveAttackCardConsistent(
        AttackResolution attack,
        IReadOnlyList<Card> processing)
    {
        if (_resolutionStack.LastOrDefault() is PindianFrame { Result: { } contest } pindian)
        {
            var contestIds = new[] { contest.SourceCardId, contest.OpponentCardId };
            if (contestIds.Any(id => (pindian.ParentProcessingCardIds ?? []).Contains(id))) return false;
            processing = processing.Where(card => !contestIds.Contains(card.Id)).ToArray();
        }
        if (HasPendingProgramBoundCards)
        {
            return IsProgramProcessingConsistent(attack, processing);
        }

        if (_resolutionStack.OfType<ProgramCardTriggerWindowFrame>().LastOrDefault() is { } programFrame &&
            programFrame.Action.Type == CardActionType.Response)
        {
            var responseIds = programFrame.Action.PhysicalCards.Select(cost => cost.CardId).ToHashSet();
            if (responseIds.Any(id => processing.All(card => card.Id != id))) return false;
            processing = processing.Where(card => !responseIds.Contains(card.Id)).ToArray();
        }
        if (attack.IsLeijiDamage)
        {
            return attack.Card is null &&
                   _pendingLeiji is { } leiji &&
                   ReferenceEquals(leiji.DamageAttack, attack) &&
                   processing.Select(card => card.Id).Order().SequenceEqual(
                       leiji.OriginalAttack.PhysicalCards
                           .Where(card => _cardZones.GetLocation(card.Id) == CardLocation.Processing)
                           .Select(card => card.Id)
                           .Order());
        }

        if (attack.IsProgramJudgmentDamage)
        {
            var retainedParentCardIds = _pendingJudgment?.Attack?.PhysicalCards
                .Where(card => _cardZones.GetLocation(card.Id) == CardLocation.Processing)
                .Select(card => card.Id)
                .Order()
                .ToArray() ?? [];
            return attack.Card is null &&
                   processing.Select(card => card.Id).Order().SequenceEqual(retainedParentCardIds) &&
                   attack.ProgramJudgmentFrameId is { } frameId &&
                   _resolutionStack.OfType<ProgramJudgmentTriggerWindowFrame>()
                       .Any(frame => frame.Id == frameId);
        }

        if (attack.IsProgramSkillDamage)
        {
            return attack.Card is null && processing.Count == 0 &&
                   attack.ProgramSkillFrameId is { } frameId &&
                   _resolutionStack.OfType<ProgramSkillFrame>().Any(frame => frame.Id == frameId);
        }

        if (attack.Card is null && attack.EffectiveCardKind == CardKind.Slash && _pendingShensuStage is 1 or 2)
        {
            return processing.Count == 0 && _resolutionStack.OfType<CardUseFrame>().Any(frame =>
                frame.Id == attack.ResolutionId && frame.CardId == 0 && frame.PhysicalCardIds?.Count is 0);
        }

        if (attack.IsActiveSkillDamage && attack.SourceSkill == SkillKind.Qiangxi)
        {
            return attack.Card is null && processing.Count == 0;
        }

        if (attack.IsActiveSkillDamage && attack.SourceSkill == SkillKind.Lijian)
        {
            return attack.Card is null &&
                   attack.EffectiveCardKind == CardKind.Duel &&
                   processing.Count == 0;
        }

        var attackCard = attack.Card;
        if (attackCard is null)
        {
            return false;
        }

        if (attack.IsDelayedJudgmentDamage)
        {
            var delayedLocation = _cardZones.GetLocation(attackCard.Id);
            return delayedLocation.Zone is CardZoneKind.Judgment or
                CardZoneKind.Hand or
                CardZoneKind.DiscardPile;
        }

        if (attack.IsActiveSkillDamage)
        {
            var activeSkillLocation = _cardZones.GetLocation(attackCard.Id);
            return activeSkillLocation.Zone is CardZoneKind.DrawPile or
                CardZoneKind.Hand or
                CardZoneKind.DiscardPile;
        }

        if (_pendingBorrowedSword is { ActiveAttack: { } borrowedAttack } borrowedSword &&
            ReferenceEquals(borrowedAttack, attack))
        {
            if (processing.All(card => card.Id != borrowedSword.Card.Id))
            {
                return false;
            }

            var allowedIds = attack.PhysicalCards.Select(card => card.Id)
                .Append(borrowedSword.Card.Id)
                .ToHashSet();
            var allAttackCardsInProcessing = attack.PhysicalCards.All(card =>
                _cardZones.GetLocation(card.Id) == CardLocation.Processing);
            if (allAttackCardsInProcessing)
            {
                return processing.Count == attack.PhysicalCards.Count + 1 &&
                       processing.All(card => allowedIds.Contains(card.Id));
            }

            return _pendingDamageTrigger is not null &&
                   processing.All(card => allowedIds.Contains(card.Id)) &&
                   attack.PhysicalCards.All(card =>
                       _cardZones.GetLocation(card.Id).Zone is CardZoneKind.Processing or
                           CardZoneKind.DrawPile or CardZoneKind.Hand or CardZoneKind.DiscardPile);
        }

        if (_pendingFangtianHalberd is { CurrentAttack: { } fangtianAttack } fangtian &&
            ReferenceEquals(fangtianAttack, attack))
        {
            var fangtianCardLocation = _cardZones.GetLocation(fangtian.Card.Id);
            return attack.ResolutionId == fangtian.ResolutionId &&
                   attack.SourceSeat == fangtian.SourceSeat &&
                   attack.EffectiveCardKind == fangtian.EffectiveCardKind &&
                   attack.PhysicalCards.Count == 1 &&
                   attack.PhysicalCards[0].Id == fangtian.Card.Id &&
                   fangtianCardLocation.Zone is CardZoneKind.Processing or CardZoneKind.Hand or
                       CardZoneKind.DrawPile or CardZoneKind.DiscardPile &&
                   processing.All(card => card.Id == fangtian.Card.Id);
        }

        var attackCardIds = attack.PhysicalCards.Select(card => card.Id).ToHashSet();
        if (_resolutionStack.OfType<ProgramCardTriggerWindowFrame>().LastOrDefault() is
            { Continuation: ProgramCardContinuation.CompletedSlash, Action.ActionId: var completedActionId } &&
            _resolutionStack.OfType<CardUseFrame>().LastOrDefault(frame => frame.Id == attack.ResolutionId)?.Action?.ActionId == completedActionId)
        {
            return processing.Count == 0 && attack.PhysicalCards.All(card =>
                _cardZones.GetLocation(card.Id).Zone is CardZoneKind.DiscardPile or
                    CardZoneKind.Hand or CardZoneKind.DrawPile);
        }
        if (processing.Count == attack.PhysicalCards.Count &&
            processing.All(card => attackCardIds.Contains(card.Id)))
        {
            return true;
        }

        if (_pendingDamageTrigger is not null)
        {
            return processing.All(card => attackCardIds.Contains(card.Id)) &&
                   attack.PhysicalCards.All(card =>
                       _cardZones.GetLocation(card.Id).Zone is CardZoneKind.Processing or
                           CardZoneKind.DrawPile or CardZoneKind.Hand or CardZoneKind.DiscardPile);
        }

        if (attack.IsChainPropagation)
        {
            var propagatedLocation = _cardZones.GetLocation(attackCard.Id);
            return propagatedLocation.Zone is CardZoneKind.DrawPile or
                CardZoneKind.Hand or
                CardZoneKind.DiscardPile;
        }

        if (_pendingDying is not null)
        {
            var dyingLocation = _cardZones.GetLocation(attackCard.Id);
            return dyingLocation.Zone is CardZoneKind.DrawPile or
                CardZoneKind.Hand or
                CardZoneKind.DiscardPile;
        }

        if (_pendingGroupCard is not { Effect: GroupCardEffect.ResponseAttack } group ||
            processing.Count != 0)
        {
            return false;
        }

        var location = _cardZones.GetLocation(attackCard.Id);
        // The effect continues after a target claims its physical card. That target can
        // subsequently die, discard it, or move it again before the next target responds.
        return group.DamageClaimedPhysicalCardIds.Contains(attackCard.Id) && location.Zone is
            CardZoneKind.Hand or CardZoneKind.DiscardPile or CardZoneKind.DrawPile;
    }

    internal static bool IsResolvedGroupPhysicalCardDestinationAllowed(
        CardLocation location,
        bool damageCardClaimed,
        IReadOnlyList<int> targetSeats) =>
        location == CardLocation.DiscardPile ||
        damageCardClaimed && location.Zone == CardZoneKind.DrawPile ||
        location is { Zone: CardZoneKind.Hand, OwnerSeat: { } ownerSeat } &&
        targetSeats.Contains(ownerSeat);

    internal static bool RecordClaimedGroupPhysicalCard(
        ISet<int> claimedCardIds,
        long groupResolutionId,
        IReadOnlyList<Card> groupPhysicalCards,
        long attackResolutionId,
        int claimedCardId)
    {
        ArgumentNullException.ThrowIfNull(claimedCardIds);
        ArgumentNullException.ThrowIfNull(groupPhysicalCards);
        if (groupResolutionId != attackResolutionId ||
            !groupPhysicalCards.Any(card => card.Id == claimedCardId))
            return false;
        return claimedCardIds.Add(claimedCardId);
    }

    private bool IsHumanDecisionPending() =>
        _pendingDecision is { } decision && decision.PlayerSeat == _options.HumanSeat;

    private bool IsAiResponsePending() =>
        ((_pendingDecision?.Kind is DecisionKind.RespondDodge or
            DecisionKind.RespondSlash or
            DecisionKind.Leiji or
            DecisionKind.Liuli or
            DecisionKind.StoneAxe or
            DecisionKind.CixiongDoubleSwords or
            DecisionKind.QinglongCrescentBlade or
            DecisionKind.IceSword or
            DecisionKind.QilinBow or
            DecisionKind.Mengjin or
            DecisionKind.ZhuqueFan)) &&
        _pendingDecision.PlayerSeat != _options.HumanSeat;

    private bool IsAiNullificationPending() =>
        _pendingNullification is { } pending &&
        _pendingDecision is { Kind: DecisionKind.Nullification } decision &&
        pending.CandidateIndex < pending.CandidateSeats.Count &&
        decision.PlayerSeat == pending.CandidateSeats[pending.CandidateIndex] &&
        !_players[decision.PlayerSeat].IsHuman;

    private bool IsAiDamageSkillPending() =>
        _pendingJudgment is null &&
        _pendingDamageSkill is { } damageSkill &&
        _pendingDecision is { } damageSkillDecision &&
        (damageSkillDecision.Kind is DecisionKind.Yuanhu or
            DecisionKind.Yaowu or
            DecisionKind.Ganglie or
            DecisionKind.GangliePunish) &&
        damageSkillDecision.PlayerSeat ==
            (damageSkillDecision.Kind == DecisionKind.GangliePunish
                ? damageSkill.SourceSeat
                : damageSkillDecision.Kind == DecisionKind.Yaowu
                ? damageSkill.SourceSeat
                : damageSkill.OwnerSeat) &&
        !_players[damageSkillDecision.PlayerSeat].IsHuman;

    private bool IsAiJudgmentPending() =>
        _pendingJudgment is { } judgment &&
        _pendingDecision is { Kind: DecisionKind.Guicai or DecisionKind.Guidao } decision &&
        judgment.CurrentCandidateSeat == decision.PlayerSeat &&
        !_players[decision.PlayerSeat].IsHuman;

    private bool IsAiHarvestPending() =>
        _pendingGroupCard is { Effect: GroupCardEffect.PublicDraft } &&
        _pendingDecision?.Kind == DecisionKind.SelectHarvestCard &&
        _pendingDecision.PlayerSeat != _options.HumanSeat;

    private bool IsAiTargetCardSelectionPending() =>
        _pendingTargetCardSelection is { } pending &&
        _pendingDecision is
        {
            Kind: DecisionKind.SelectTargetCard,
            PlayerSeat: var playerSeat
        } decision &&
        decision.PlayerSeat == pending.SourceSeat &&
        !_players[playerSeat].IsHuman;

    private bool IsAiFireAttackPending() =>
        _pendingFireAttack is not null &&
        _pendingDecision is
        {
            Kind: DecisionKind.FireAttackReveal or DecisionKind.FireAttackDiscard,
            PlayerSeat: var playerSeat
        } &&
        playerSeat != _options.HumanSeat;

    private bool IsAiGuanxingPending() =>
        _pendingGuanxing is { PlayerSeat: var playerSeat } &&
        _pendingDecision is { Kind: DecisionKind.Guanxing, PlayerSeat: var decisionSeat } &&
        playerSeat == decisionSeat &&
        !_players[playerSeat].IsHuman;

    private void ResolvePendingAiGuanxing()
    {
        if (!IsAiGuanxingPending())
        {
            throw new InvalidOperationException("There is no AI Guanxing choice to resolve.");
        }

        var decision = _pendingDecision!;
        var actor = _players[decision.PlayerSeat];
        var (choiceId, thought) = _aiBrains[actor.Seat].ChooseGuanxing(
            CreateSnapshot(actor.Seat),
            decision.Choices,
            _thoughtSequence++);
        var choice = decision.Choices.Single(candidate => candidate.Id == choiceId);
        AddThought(thought);
        ResolveGuanxingChoice(choice);
        PublishState();
    }

    private bool IsAiShuangxiongPending() =>
        _pendingShuangxiongDraw is { PlayerSeat: var playerSeat } &&
        _pendingDecision is { Kind: DecisionKind.Shuangxiong, PlayerSeat: var decisionSeat } &&
        playerSeat == decisionSeat && !_players[playerSeat].IsHuman;

    private void ResolvePendingAiShuangxiong()
    {
        if (!IsAiShuangxiongPending()) throw new InvalidOperationException("There is no AI Shuangxiong choice.");
        ResolveShuangxiongDrawChoice(useSkill: true);
        PublishState();
    }

    private bool IsAiLuoshenPending() =>
        _pendingLuoshen is { PlayerSeat: var playerSeat } &&
        _pendingDecision is { Kind: DecisionKind.Luoshen, PlayerSeat: var decisionSeat } &&
        playerSeat == decisionSeat &&
        !_players[playerSeat].IsHuman;

    private void ResolvePendingAiLuoshen()
    {
        if (!IsAiLuoshenPending())
        {
            throw new InvalidOperationException("There is no AI Luoshen choice to resolve.");
        }

        ResolveLuoshenChoice(useSkill: true);
        PublishState();
    }

    private bool IsAiJizhiPending() =>
        _pendingJizhi is { PlayerSeat: var playerSeat } &&
        _pendingDecision is { Kind: DecisionKind.Jizhi, PlayerSeat: var decisionSeat } &&
        playerSeat == decisionSeat &&
        !_players[playerSeat].IsHuman;

    private void ResolvePendingAiJizhi()
    {
        if (!IsAiJizhiPending())
        {
            throw new InvalidOperationException("There is no AI Jizhi choice to resolve.");
        }

        ResolveJizhiChoice(useSkill: true);
        PublishState();
    }

    private bool IsAiTieqiPending() =>
        _pendingTieqi is { Attack.SourceSeat: var sourceSeat } &&
        _pendingDecision is { Kind: DecisionKind.Tieqi, PlayerSeat: var decisionSeat } &&
        sourceSeat == decisionSeat &&
        !_players[sourceSeat].IsHuman;

    private void ResolvePendingAiTieqi()
    {
        if (!IsAiTieqiPending())
        {
            throw new InvalidOperationException("There is no AI Tieqi choice to resolve.");
        }

        ResolveTieqiChoice(useSkill: true);
        PublishState();
    }

    private bool IsAiLiegongPending() =>
        _pendingLiegong is { Attack.SourceSeat: var sourceSeat } &&
        _pendingDecision is { Kind: DecisionKind.Liegong, PlayerSeat: var decisionSeat } &&
        sourceSeat == decisionSeat &&
        !_players[sourceSeat].IsHuman;

    private void ResolvePendingAiLiegong()
    {
        if (!IsAiLiegongPending())
        {
            throw new InvalidOperationException("There is no AI Liegong choice to resolve.");
        }

        ResolveLiegongChoice(useSkill: true);
        PublishState();
    }

    private bool IsAiKejiPending() =>
        _pendingDecision is { Kind: DecisionKind.Keji, PlayerSeat: var playerSeat } &&
        playerSeat == _currentSeat &&
        !_players[playerSeat].IsHuman;

    private void ResolvePendingAiKeji()
    {
        if (!IsAiKejiPending())
        {
            throw new InvalidOperationException("There is no AI Keji choice to resolve.");
        }

        ResolveKejiChoice(useSkill: true);
        PublishState();
    }

    private bool IsAiShensuPending() =>
        _pendingDecision is { Kind: DecisionKind.Shensu, PlayerSeat: var playerSeat } &&
        playerSeat == _currentSeat && !_players[playerSeat].IsHuman;

    private void ResolvePendingAiShensu()
    {
        if (!IsAiShensuPending()) throw new InvalidOperationException("There is no AI Shensu choice to resolve.");
        var use = _pendingDecision!.Choices.FirstOrDefault(choice =>
            choice.Parameters.GetValueOrDefault("action") == "shensu-use");
        ResolveShensuChoice(
            use?.Cards.Count > 0 ? use.Cards[0] : null,
            use?.Targets.Count > 0 ? use.Targets[0] : null);
        PublishState();
    }

    private bool IsAiYaowuPending() =>
        _pendingDecision is { Kind: DecisionKind.Yaowu, PlayerSeat: var playerSeat } &&
        !_players[playerSeat].IsHuman;

    private void ResolvePendingAiYaowu()
    {
        if (!IsAiYaowuPending()) throw new InvalidOperationException("There is no AI Yaowu choice to resolve.");
        var source = _players[_pendingDecision!.PlayerSeat];
        ResolveYaowuChoice(recover: source.Hp < source.MaxHp);
        PublishState();
    }

    private bool IsAiTianduPending() =>
        _pendingJudgment is { ResultSucceeded: not null, TargetSeat: var targetSeat } &&
        _pendingDecision is { Kind: DecisionKind.Tiandu, PlayerSeat: var decisionSeat } &&
        targetSeat == decisionSeat &&
        !_players[targetSeat].IsHuman;

    private void ResolvePendingAiTiandu()
    {
        if (!IsAiTianduPending())
        {
            throw new InvalidOperationException("There is no AI Tiandu choice to resolve.");
        }

        ResolveTianduChoice(_pendingJudgment!, useSkill: true);
        PublishState();
    }

    private bool IsAiFanjianPending() =>
        _pendingDecision is { Kind: DecisionKind.Fanjian, PlayerSeat: var playerSeat } &&
        !_players[playerSeat].IsHuman;

    private void ResolvePendingAiFanjian()
    {
        if (!IsAiFanjianPending())
        {
            throw new InvalidOperationException("There is no AI Fanjian suit choice to resolve.");
        }

        // Every suit is intentionally equivalent without access to Zhou Yu's
        // private hand. A fixed public tie-break keeps the choice replayable.
        ResolveActiveSuitChoice(Suit.Diamond);
        PublishState();
    }

    private void ResolveActiveSuitChoice(Suit chosenSuit)
    {
        if (_pendingDecision is not { Kind: DecisionKind.Fanjian } decision ||
            _resolutionStack.LastOrDefault() is not ActiveSkillFrame frame ||
            frame.Effect != ActiveSkillEffectKind.RevealGiftAndDamage ||
            frame.TargetSeats is not { Count: 1 } targets ||
            decision.PlayerSeat != targets[0])
            throw new InvalidOperationException("The active suit choice is not the current resolution.");

        ActiveActionExecutor.ResolveSuitChoice(RequireActiveAction(frame.Id), chosenSuit, this);
    }

    private bool IsAiDyingResponsePending() =>
        _pendingDying is { } dying &&
        _pendingDecision is null &&
        dying.ResponderIndex < dying.ResponderSeats.Count &&
        !_players[dying.ResponderSeat].IsHuman;

    private void RequireHumanDecision(DecisionKind expected)
    {
        EnsureStarted();
        if (_pendingDecision?.Kind != expected ||
            _pendingDecision.PlayerSeat != _options.HumanSeat)
        {
            throw new InvalidOperationException($"The engine is not waiting for human decision {expected}.");
        }
    }

    private void ClearPendingDecision()
    {
        _pendingDecision = null;
        _status = _winner == Winner.None ? EngineStatus.Running : EngineStatus.Completed;
    }

    private void EnsureStarted()
    {
        if (!_started)
        {
            throw new InvalidOperationException("Call Start before advancing the game.");
        }
    }

    private EngineRunResult ExecuteExclusive(Func<EngineRunResult> operation)
    {
        if (_isExecutingPublicOperation)
        {
            throw new InvalidOperationException(
                "GameEngine cannot be advanced reentrantly from a synchronous event handler.");
        }

        _isExecutingPublicOperation = true;
        try
        {
            operation();
            AssertCoreInvariants();
            _revision++;
            RefreshPendingDecisionRevision();
            if (_pendingStateSnapshot is not null)
            {
                _pendingStateSnapshot = State;
            }

            CommitPendingEvents();
            FlushNotifications();
            return BuildResult();
        }
        catch
        {
            _pendingNotifications.Clear();
            _pendingEvents.Clear();
            _pendingStateSnapshot = null;
            throw;
        }
        finally
        {
            _isExecutingPublicOperation = false;
        }
    }

    private EngineRunResult BuildResult()
    {
        var state = State;
        return new EngineRunResult(_status, _winner, state, state.PendingDecision, _revision)
        {
            WinnerTeamId = IsTeamMode ? _winnerTeamId : null,
            WinnerFactionId = IsNationalWarMode ? _winnerFactionId : null
        };
    }

    private void RefreshPendingDecisionRevision()
    {
        if (_pendingDecision is { } pending)
        {
            _pendingDecision = pending with { Revision = _revision };
        }
    }

    private void PublishState()
    {
        TryBeginCardsMovedProgramWindow();
        _pendingStateSnapshot = State;
    }

    private void AddLog(string type, string message, int? actor = null, int? target = null)
    {
        var entry = new GameLogEntry(++_logSequence, _turnNumber, type, message, actor, target);
        _log.Add(entry);
        _pendingNotifications.Enqueue(new LogNotification(entry));
    }

    private void AddThought(AiThoughtRecord thought)
    {
        _aiThoughts.Add(thought);
        _pendingNotifications.Enqueue(new AiThoughtNotification(thought));
    }

    private void AddGeneralThought(AiGeneralThought thought)
    {
        _aiGeneralThoughts.Add(thought);
        _pendingNotifications.Enqueue(new AiGeneralThoughtNotification(thought));
    }

    private void QueueGameEvent(IGameEvent payload)
    {
        if (_started)
        {
            _pendingEvents.Add(payload);
        }
    }

    private void CommitPendingEvents()
    {
        foreach (var payload in _pendingEvents)
        {
            var envelope = new EventEnvelope(
                new EventId(++_eventSequence),
                ParentId: null,
                _eventSequence,
                _revision,
                $"revision-{_revision}",
                payload);
            _events.Add(envelope);
            _pendingNotifications.Enqueue(new EventNotification(envelope));
        }

        _pendingEvents.Clear();
    }

    private void FlushNotifications()
    {
        while (_pendingNotifications.TryDequeue(out var notification))
        {
            switch (notification)
            {
                case LogNotification log:
                    InvokeObservers(LogAdded, log.Entry, nameof(LogAdded));
                    break;
                case AiThoughtNotification thought:
                    InvokeObservers(AiThoughtAdded, thought.Thought, nameof(AiThoughtAdded));
                    break;
                case AiGeneralThoughtNotification generalThought:
                    InvokeObservers(
                        AiGeneralThoughtAdded,
                        generalThought.Thought,
                        nameof(AiGeneralThoughtAdded));
                    break;
                case CardMovedNotification movement:
                    InvokeObservers(CardMoved, movement.Movement, nameof(CardMoved));
                    break;
                case EventNotification typedEvent:
                    InvokeObservers(EventCommitted, typedEvent.Event, nameof(EventCommitted));
                    break;
                default:
                    throw new InvalidOperationException($"Unknown engine notification {notification.GetType().Name}.");
            }
        }

        if (_pendingStateSnapshot is { } snapshot)
        {
            _pendingStateSnapshot = null;
            InvokeObservers(StateChanged, snapshot, nameof(StateChanged));
        }
    }

    private void InvokeObservers<T>(Action<T>? observers, T payload, string notificationType)
    {
        if (observers is null)
        {
            return;
        }

        foreach (Action<T> observer in observers.GetInvocationList())
        {
            try
            {
                observer(payload);
            }
            catch (Exception exception)
            {
                RecordObserverFailure(notificationType, exception);
            }
        }
    }

    private void RecordObserverFailure(string notificationType, Exception exception)
    {
        const int failureLimit = 128;
        if (_observerFailures.Count == failureLimit)
        {
            _observerFailures.RemoveAt(0);
        }

        _observerFailures.Add(new ObserverFailure(
            ++_observerFailureSequence,
            notificationType,
            exception.GetType().FullName ?? exception.GetType().Name,
            exception.Message));
    }

    private static CardSnapshot ToSnapshot(Card card) =>
        new(card.Id, card.Kind, card.Suit, card.Rank, card.DisplayName, card.RankText);

    private CardSnapshot ToJudgmentSnapshot(Card card)
    {
        var effectiveKind = GetJudgmentEffectiveCardKind(card);
        return new CardSnapshot(
            card.Id,
